是=哺乳類、動物
吃=魚、烏賊
會=游泳、跳出水面、用回聲定位找食物
住=海洋，少數住在河裡
壽命=大約 20 到 40 年
說明=海豚和鯨魚一樣是哺乳類，不是魚
特點=海豚睡覺時一半的大腦休息、一半醒著，才記得浮上去呼吸
@鯊魚|鯊|動物
