是=哺乳類、草食動物、動物
吃=樹葉，特別是金合歡樹的葉子
住=非洲的草原
壽命=野外大約 25 年
腳=4 隻
特點=長頸鹿的脖子雖然長，但和人一樣只有 7 節頸椎
因:脖子/脖子長/脖子那麼長=長脖子讓牠們吃得到別的動物搆不到的高處樹葉，雄長頸鹿也會用脖子互相打架爭奪伴侶；比較能生存、找到伴侶的長脖子個體留下比較多後代，脖子就一代代變長了。牠們的脖子雖然很長，但跟人一樣只有 7 節頸椎
高度=公長頸鹿可以高到 5 到 6 公尺，是陸地上最高的動物
