因:叮人=只有母蚊要吸血，血裡的蛋白質是牠產卵需要的；牠是靠人呼出的二氧化碳、體溫和汗味找到人的
因:叮了會癢/會癢/癢/叮會癢=蚊子叮人時會注入唾液防止血液凝固，身體對唾液起過敏反應、釋放組織胺，所以會腫、會癢
因:喜歡咬/咬我/叮我/愛咬/特別喜歡/被咬=蚊子靠二氧化碳、體溫、汗味和皮膚的氣味找人：呼出比較多二氧化碳（體型大、剛運動完、孕婦）、體溫比較高、流汗、喝了酒的人比較容易被叮；穿深色衣服也比較顯眼；每個人皮膚上的細菌產生的氣味不同，所以有人特別招蚊子。血型的影響，研究結果還不一致
