說明=低層的需求滿足了，人才比較會去追求高層的需求；後來的研究認為需求不一定嚴格照順序
@煤氣燈效應|煤氣燈操縱|科學
簡介=一種心理操控：對方不斷否認你的記憶和感受（「你想太多了」「我從來沒說過」），讓你懷疑自己的判斷、越來越依賴他
說明=名稱來自電影《煤氣燈下》；如果在關係裡常常覺得「是不是我有問題」，可以找信任的朋友或專業的人聊聊，確認自己的感受
@情緒勒索|情緒勒索|科學
