@斷捨離|斷捨離觀念|概念
簡介=日本作家山下英子提出的整理觀念：「斷」掉不需要的東西進來、「捨」去家裡沒用的東西、「離」開對物品的執著
說明=重點不是丟東西，而是只留下真正需要、會讓你開心的東西，讓生活和心情變輕鬆
@香蕉放冰箱|香蕉可以放冰箱,香蕉能放冰箱,香蕉要放冰箱,香蕉能不能放冰箱,香蕉可不可以放冰箱|常識
簡介=可以，但香蕉皮會變黑；黃了之後再放冰箱，果肉還是好的，可以多放幾天。還沒熟（偏綠）的香蕉不要放冰箱，低溫會讓它熟不了，放在室溫陰涼處就好
@雞蛋放冰箱|雞蛋要放冰箱,雞蛋要不要放冰箱,雞蛋可以放冰箱,雞蛋需要冰,雞蛋要冰嗎,蛋要放冰箱|常識
簡介=建議放冰箱。台灣和美國的雞蛋大多洗過，表面保護膜沒了，冷藏比較不容易壞、也比較能抑制沙門氏菌；放的時候尖端朝下，不要放在冰箱門（溫度變化大），買回來一兩週內吃完最好
@隔夜菜|隔夜菜可以吃,隔夜菜能吃,隔夜菜能不能吃,隔夜飯菜,剩菜可以吃,隔夜菜會致癌嗎,隔夜菜會不會致癌,隔夜菜致癌|常識
簡介=大多可以吃，重點是保存方式：煮好放涼後兩小時內蓋好放冰箱，隔天吃之前徹底加熱；葉菜類最好當餐吃完（放久亞硝酸鹽會變多），魚和海鮮也容易壞；放室溫一整晚的、聞起來怪怪的就不要吃
@空腹喝咖啡|空腹可以喝咖啡,空腹喝咖啡可以,早上空腹喝咖啡,空腹能喝咖啡|常識
簡介=大部分健康的人空腹喝咖啡沒什麼大問題；但胃比較敏感、有胃食道逆流或胃潰瘍的人，空腹喝容易胃痛、胃酸逆流、心悸，最好先吃點東西再喝。一天咖啡因建議不超過 300 到 400 毫克（大約兩三杯）
@每天喝水量|每天要喝多少水,一天要喝多少水,一天喝多少水,每天喝多少水,每天該喝多少水,一天該喝多少水,一天要喝幾杯水,每天應該喝多少水,一天喝幾杯水,喝水一天要喝多少,每天要喝幾公升的水,每天喝多少水才夠,一天要喝幾公升水,一天喝多少水才夠,每天要喝幾杯水|常識
簡介=一般建議大約是「體重（公斤）× 30 毫升」，例如 60 公斤的人一天大約 1,800 毫升，差不多 7 到 8 杯；天氣熱、運動流汗要再多喝。小口分次喝比一次灌很多好，尿液是淡黃色就代表水喝得差不多
@早上運動還是晚上運動|早上運動還是晚上運動,早上運動好還是晚上運動好,晨跑還是夜跑,什麼時候運動最好,幾點運動最好,晚上運動好嗎,晚上可以運動嗎,早上運動好嗎,晚上運動好不好|常識
簡介=都可以，最好的時間是「你最能持續的時間」。早上運動比較容易養成習慣、讓一整天有精神；傍晚身體比較暖、肌力和柔軟度比較好，比較不容易受傷。只要避開睡前一兩小時做太激烈的運動（會睡不著）就好
@複利|複利效應,複利是什麼,什麼是複利|經濟
簡介=利息也會再生利息的算法：第一年賺到的利息加進本金，第二年連同利息一起再算利息，時間越久，錢滾得越快
說明=例如 10 萬元、年報酬 6%，單利 10 年是 16 萬；複利 10 年大約 17.9 萬，30 年會變成大約 57 萬。所以愛因斯坦（傳說）稱它是「世界第八大奇蹟」，越早開始存錢投資越有利
@NFT|非同質化代幣|科技
簡介=非同質化代幣（Non-Fungible Token），記錄在區塊鏈上、獨一無二的數位憑證，常用來證明某張數位圖片、音樂或遊戲道具「屬於誰」
說明=2021 年很熱門，有作品賣到幾千萬美元，後來熱潮退燒、很多價格大跌；要注意它是高風險的投機商品
@ChatGPT|chatgpt,Chat GPT|科技
簡介=美國公司 OpenAI 在 2022 年 11 月推出的 AI 聊天機器人，用大型語言模型回答問題、寫文章、寫程式
說明=它讓生成式 AI 一下子紅遍全世界；類似的還有 Google 的 Gemini、Anthropic 的 Claude。這類 AI 很好用，但有時會講錯，重要的事要再查證
@世界上的國家數量|世界上有幾個國家,全世界有幾個國家,世界上有多少國家,全世界有多少國家,世界有幾個國家|常識
簡介=一般的說法是大約 195 個：193 個聯合國會員國，加上梵蒂岡和巴勒斯坦兩個聯合國觀察員國；台灣、科索沃等有實際治理但國際承認不一的地方，算法不同時數字會有差
@中國的省|中國有幾個省,中國有多少省,中國有幾個省份,中國的省份|常識
簡介=中國官方的行政區劃是 34 個省級行政區：23 個省（包含台灣，這是中華人民共和國的主張，台灣實際上由中華民國治理）、5 個自治區、4 個直轄市（北京、上海、天津、重慶）、2 個特別行政區（香港、澳門）
@清朝最後一個皇帝|清朝最後的皇帝,末代皇帝,清朝末代皇帝,清朝最後一位皇帝|常識
簡介=清朝最後一個皇帝是溥儀（宣統帝），3 歲登基，1912 年辛亥革命後退位，清朝結束；後來當過日本扶植的滿洲國皇帝，晚年在北京當平民，1967 年過世。電影《末代皇帝》就是講他的故事
@奧運起源|奧運從哪裡開始,奧運的起源,奧林匹克的起源,奧運發源地,奧運怎麼來的|常識
簡介=古代奧運起源於古希臘的奧林匹亞，傳說從西元前 776 年開始，每四年一次，祭祀宙斯；現代奧運由法國的古柏坦推動，1896 年在希臘雅典舉行第一屆
@法國國花|法國的國花|常識
簡介=法國的國花一般說是鳶尾花（香根鳶尾），它是法國王室的象徵；也有人說是虞美人（麗春花）
@台灣國鳥|台灣的國鳥,台灣國鳥是什麼|常識
簡介=台灣沒有法定的國鳥，2007 年網路票選最多人選的是台灣特有種「台灣藍鵲」，一般也把牠當作台灣的代表鳥；另外帝雉（黑長尾雉）也曾被印在千元鈔票上
@台灣國花|台灣的國花,中華民國國花|常識
簡介=中華民國的國花是梅花，1964 年行政院正式核定；梅花在寒冬開花，象徵堅忍不拔
@台灣國家公園|台灣有幾個國家公園,台灣的國家公園,台灣國家公園有哪些|常識
簡介=台灣有 9 座國家公園：墾丁、玉山、陽明山、太魯閣、雪霸、金門、東沙環礁、台江、澎湖南方四島；另外還有高雄的壽山國家自然公園
@台灣總統|台灣的總統,台灣總統是誰,中華民國總統,現任總統|常識
簡介=中華民國（台灣）現任總統是賴清德，2024 年 5 月 20 日就任，任期四年；副總統是蕭美琴
@二二八事件|228事件,二二八|事件
簡介=1947 年 2 月 28 日起在台灣發生的衝突：台北查緝私菸打傷人引發民眾抗議，國民政府派軍隊鎮壓，造成大量死傷，之後長期戒嚴、白色恐怖；2 月 28 日現在是和平紀念日
年份=1947 年 2 月 28 日
@健保卡|全民健保卡,健保IC卡,健保卡可以做什麼,健保卡有什麼用,健保卡的用途|常識
簡介=台灣全民健康保險的身分卡：看病、拿藥、住院時要出示，看診只要付部分負擔；也可以用來申辦健保快易通 App、網路報稅、領政府補助等
@悠遊卡|悠遊卡可以在哪裡用,悠遊卡哪裡可以用,悠遊卡怎麼用,悠遊卡要怎麼用,悠遊卡的用法|常識
簡介=悠遊卡是台灣的電子票證：可以搭捷運、公車、台鐵、YouBike，也能在便利商店、部分店家和停車場付款；可以設定自動加值，綁定後遺失可以掛失
@統一發票|發票怎麼對獎,統一發票怎麼對獎,發票對獎,統一發票幾月開獎,發票幾號開獎,發票什麼時候開獎,統一發票什麼時候開獎,發票開獎|常識
簡介=統一發票每兩個月一期，在單數月的 25 日開獎（1、3、5、7、9、11 月），開獎後可以在財政部網站或 App 查
說明=對獎方法：特別獎（1,000 萬）、特獎（200 萬）要 8 碼全中；頭獎 8 碼全中 20 萬，末 7 碼 4 萬、末 6 碼 1 萬、末 5 碼 4,000、末 4 碼 1,000、末 3 碼 200 元。用載具存發票可以自動對獎、中獎直接匯款
@報稅|報稅是幾月,什麼時候報稅,綜所稅申報,綜合所得稅申報時間,報稅時間,所得稅申報,綜所稅怎麼報|常識
簡介=台灣的綜合所得稅每年 5 月 1 日到 5 月 31 日申報上一年度的所得，可以用手機報稅、網路報稅或到國稅局臨櫃；遇到假日可能會順延
@勞保|勞工保險,勞保是什麼|經濟
簡介=台灣的勞工保險，有工作的人由雇主幫忙投保，保費由勞工、雇主和政府一起分擔
說明=保障包括生育、傷病、失能、老年和死亡給付，退休時可以領勞保老年年金；另外還有勞工退休金（勞退），是雇主每月提撥 6% 到你的個人帳戶
@血壓|正常血壓,血壓多少算正常,血壓正常值,高血壓標準,血壓多少算高|健康常識
簡介=理想血壓是收縮壓低於 120、舒張壓低於 80（mmHg）；台灣 2022 年的標準是 130/80 以上就算高血壓，建議在家量血壓、固定時間量
@血糖|血糖多少算正常,正常血糖,血糖正常值,空腹血糖|健康常識
簡介=空腹血糖 70 到 99 mg/dL 是正常；100 到 125 是糖尿病前期；126 以上（兩次以上）就可能是糖尿病。飯後兩小時血糖正常應該低於 140
@BMI|BMI怎麼算,身體質量指數,bmi怎麼算|健康常識
簡介=BMI（身體質量指數）＝體重（公斤）÷ 身高（公尺）的平方，例如 60 公斤、160 公分：60 ÷ 1.6² ≈ 23.4
說明=台灣的標準：18.5 以下過輕、18.5 到 24 正常、24 到 27 過重、27 以上肥胖；肌肉多的人 BMI 會偏高，要一起看腰圍和體脂
@每天走路步數|一天要走幾步,每天要走幾步,一天走多少步,每天走多少步,一天要走多少步|常識
簡介=常聽到的「一天一萬步」是很好的目標，但研究發現每天走 7,000 到 8,000 步，健康好處就很明顯了；平常走很少的人，先從每天多走 2,000 步開始就好
@維他命C功效|維他命C有什麼用,維生素C有什麼用,維他命C的功效|健康常識
簡介=人體自己不能製造、要從食物攝取的營養素，幫助製造膠原蛋白、傷口癒合、吸收鐵質，也是抗氧化物
說明=芭樂、奇異果、柑橘、甜椒、花椰菜都很多；成人每天大約需要 100 毫克，一般吃夠蔬果就夠，吃再多也不會預防感冒
@吃太多糖的壞處|吃太多糖有什麼壞處,吃糖的壞處,糖吃太多,吃太多糖會怎樣|常識
簡介=吃太多糖容易變胖、蛀牙、血糖不穩定，長期會增加糖尿病、脂肪肝和心血管疾病的風險，也可能讓皮膚狀況變差；建議每天添加糖不超過總熱量的 10%（大約 50 公克，一杯全糖手搖飲就可能超過）
@抽菸的壞處|抽菸有什麼壞處,吸菸的壞處,抽煙的壞處,抽菸會怎樣|常識
簡介=抽菸會大幅增加肺癌、口腔癌、心臟病、中風、慢性阻塞性肺病的風險，也會讓皮膚老化、牙齒變黃；二手菸、三手菸也會傷害身邊的人。戒菸任何時候都不嫌晚，可以打戒菸專線 0800-636363
@喝酒的壞處|喝酒有什麼壞處,喝酒的壞處,喝酒會怎樣,酒喝太多|常識
簡介=喝太多酒會傷肝（脂肪肝、肝硬化）、增加多種癌症和高血壓的風險，也會影響睡眠、判斷力和情緒；喝酒臉紅的人代謝酒精的能力比較差，風險更高。喝酒不開車，開車不喝酒
@藍牙|Bluetooth|科技
簡介=短距離的無線連線技術，讓手機和耳機、喇叭、手錶、鍵盤等裝置不用接線就能傳資料，距離大約 10 公尺內
@演算法|算法|科技
簡介=解決問題的一步一步的方法，像食譜一樣：照著固定的步驟做，就能得到答案
說明=電腦的搜尋、推薦影片、導航找路線都靠演算法；社群平台的「演算法」通常是指決定你會看到哪些內容的推薦系統
@程式設計|寫程式,coding,程式語言|科技
簡介=用電腦看得懂的語言（程式語言）寫下指令，讓電腦照著做事，例如做 App、網站、遊戲或自動處理資料
說明=常見的程式語言有 Python、JavaScript、Java、C、Swift；新手最常從 Python 開始
@Python|python,Python語言|科技
簡介=一種很受歡迎的程式語言，語法簡單好讀，適合新手入門
說明=常用在資料分析、人工智慧、網站後端和自動化；名字來自英國喜劇團體「蒙提·派森」，不是蟒蛇
@釣魚網站|釣魚網站是什麼,網路釣魚,釣魚簡訊|科技
簡介=假裝成銀行、購物網站、物流或政府機關的假網站，騙你輸入帳號、密碼或信用卡資料
說明=分辨方法：看清楚網址拼字、不要點簡訊和信件裡的可疑連結、銀行不會用簡訊要你登入；不小心輸入了，馬上改密碼、打給銀行，有疑問打 165 反詐騙專線
@信用分數|信用分數是什麼,信用評分,聯徵分數|經濟
簡介=銀行用來判斷你借錢會不會準時還的分數；台灣是聯合徵信中心（聯徵）的信用評分，大約 200 到 800 分
說明=想維持好的信用：信用卡準時全額繳款、不要一直只繳最低、不要短時間申請很多張卡或貸款；完全沒用過信用卡、沒有貸款紀錄的人，反而可能被說是「信用小白」
@定期定額|定期定額是什麼,定期定額投資|經濟
簡介=每個月固定一天、投入固定金額買同一檔基金或股票（例如 ETF），不管漲跌都買
說明=好處是不用猜時機、自動平均成本（便宜時買得多、貴時買得少），適合上班族長期投資；缺點是市場長期下跌還是會賠，要選好標的、放得夠久
@保險|保險是什麼|經濟
簡介=大家每個月付一點錢（保費）湊在一起，誰發生意外、生病、身故等風險，就從這筆錢拿出理賠，把個人負擔不了的大損失分散掉
說明=買保險的順序一般建議：先買保障型（意外險、醫療險、重大傷病、定期壽險），再考慮儲蓄、投資型；保費建議不要超過年收入的 10%
@儲蓄險|儲蓄險是什麼,儲蓄保險|經濟
簡介=結合保險和存錢的保單：定期繳保費，期滿或解約時可以領回本金加一點利息，同時有一些身故保障
說明=好處是強迫儲蓄；缺點是報酬率通常不高、提早解約會虧本金，保障也比純保障型保險少，要看清楚 IRR（內部報酬率）和綁約年限
@通貨緊縮|通縮|經濟
簡介=物價持續下跌的現象，跟通貨膨脹相反
說明=聽起來東西變便宜很好，但大家會等更便宜才買，公司賺不到錢、減薪裁員，經濟就會變差；日本在 1990 年代後經歷過很長的通縮
例子=東西一直變便宜，大家就想「再等等會更便宜」而不買，公司賣不出去只好減薪、裁員，大家更不敢花錢；日本從 1990 年代後期開始就長期被通縮困擾
@房貸|房屋貸款,房貸是什麼|經濟
簡介=買房子時跟銀行借的錢，用房子當擔保品，分 20 到 40 年慢慢還本金加利息
說明=通常要先準備兩到三成的頭期款；每月房貸最好不要超過家庭收入的三分之一。寬限期只繳利息、不還本金，期滿後月付金會變很多
@被動收入|被動收入是什麼|經濟
簡介=不需要每天花時間工作也能持續進來的收入，例如股票股利、ETF 配息、房租、版稅、數位商品、線上課程
說明=被動收入通常一開始要投入很多時間或資金；網路上「輕鬆躺著賺」的說法很多是詐騙，要小心
@台北高雄交通|台北到高雄要多久,從台北到高雄要多久,台北到高雄多遠,台北到高雄多久,高鐵台北到高雄,台北到高雄高鐵,台北到高雄要坐多久,台北到高雄高鐵要多久|常識
簡介=台北到高雄大約 350 公里：高鐵大約 1.5 到 2 小時；台鐵自強號大約 4 到 5 小時；開車走高速公路大約 4 到 5 小時；飛機現在已經沒有直飛的航班
@日本簽證|日本要簽證嗎,去日本要簽證嗎,日本需要簽證嗎,日本免簽嗎|常識
簡介=拿台灣護照去日本觀光，停留 90 天內不用簽證（免簽），護照效期要涵蓋停留期間；出發前可以先填 Visit Japan Web 加快入境。各國規定可能會變，出發前最好到外交部領事事務局網站確認
@時差|時差怎麼調,怎麼調時差,調時差,時差怎麼辦|常識
簡介=調時差可以這樣做：出發前幾天提早或延後一點睡覺時間；在飛機上就把手錶調成目的地時間；到了以後白天多曬太陽、盡量撐到當地晚上再睡；白天想睡只小睡 20 到 30 分鐘；少喝酒和咖啡
@飛機上帶水|飛機上可以帶水嗎,可以帶水上飛機嗎,飛機可以帶水嗎,登機可以帶水嗎|常識
簡介=國際線的手提行李，液體每瓶不能超過 100 毫升，全部裝在一個 1 公升的透明夾鏈袋裡，所以一般整瓶水不能帶過安檢；可以帶空水壺過安檢後再裝水，或在登機門附近買
說明=國內線和部分機場規定不同，出發前看航空公司的說明最準
@行動電源托運|行動電源可以托運嗎,行動電源能托運嗎,行動電源可以帶上飛機嗎,鋰電池可以托運嗎,飛機上可以帶行動電源,行動電源可以帶上飛機,搭飛機可以帶行動電源,行動電源能帶上飛機,行李箱可以帶行動電源嗎,行李箱可以放行動電源嗎,行動電源可以放行李箱嗎,托運行李可以放行動電源嗎,行動電源可以放托運行李嗎,行動電源可以帶嗎,行動電源能帶嗎,可以帶行動電源嗎,行動電源要放哪裡|常識
簡介=行動電源和備用鋰電池不能托運，只能放在隨身手提行李；一般 100Wh（大約 27,000 mAh）以下可以帶，100 到 160Wh 要航空公司同意，超過 160Wh 不能帶上飛機；很多航空公司也禁止在機上使用或充電
@MBTI|MBTI是什麼,mbti,MBTI人格測驗|心理
簡介=把人格分成 16 種類型的測驗，用四個面向組合：外向 E／內向 I、實感 S／直覺 N、思考 T／情感 F、判斷 J／感知 P，例如 INFP、ESTJ
說明=它很適合用來認識自己、聊天，但心理學界認為它的科學可信度有限，同一個人重測也常常變，不要拿來給人貼標籤
@INFP|infp,INFP是什麼|心理
