@韓國簽證|韓國要簽證嗎,去韓國要簽證嗎,韓國需要簽證嗎,韓國免簽嗎|常識
簡介=拿台灣護照去韓國觀光，停留 90 天內免簽；韓國有電子旅行許可（K-ETA）制度，台灣旅客有一段時間被暫時免除，規定常常調整，出發前請到外交部領事事務局或韓國官方網站確認
@美國簽證|美國要簽證嗎,去美國要簽證嗎,美國需要簽證嗎,美國免簽嗎|常識
簡介=台灣是美國免簽證計畫（VWP）的成員，拿台灣護照（要有身分證字號的晶片護照）觀光或商務停留 90 天內不用簽證，但出發前要上網申請 ESTA 電子旅行授權並付費；留學、工作要另外辦簽證
@勞基法工時|勞基法一天工作幾小時,一天工作幾小時,法定工時,正常工時,一週工作幾小時|常識
簡介=台灣勞基法規定正常工時每天不超過 8 小時、每週不超過 40 小時；加上加班，一天總工時不能超過 12 小時，一個月加班不能超過 46 小時（經勞資會議同意最多 54 小時、三個月不超過 138 小時）；每週有一天例假、一天休息日
@加班費|加班費怎麼算,加班費計算,平日加班費,加班費多少|常識
簡介=台灣勞基法的加班費：平日延長工時，前 2 小時是時薪的 1.34 倍（加給 1/3）、第 3 到 4 小時是 1.67 倍（加給 2/3）；休息日上班，前 2 小時 1.34 倍、第 3 到 8 小時 1.67 倍、第 9 到 12 小時 2.67 倍；國定假日上班要加倍給工資
說明=時薪通常用「月薪 ÷ 30 ÷ 8」計算；也可以勞資雙方同意換成補休
@特休|年假有幾天,特休有幾天,特休怎麼算,特別休假,年假幾天|常識
簡介=台灣勞基法的特休：工作滿 6 個月 3 天、滿 1 年 7 天、滿 2 年 10 天、滿 3 年 14 天、滿 5 年 15 天，滿 10 年以後每多一年加 1 天，最多 30 天；沒休完的特休，年度結束或離職時公司要折算成工資
@離職預告|離職要提前多久說,離職要提早多久,離職預告期,辭職要提前多久|常識
簡介=依台灣勞基法，不定期契約的勞工要離職，要照年資提前告知：做滿 3 個月未滿 1 年，10 天前；1 年以上未滿 3 年，20 天前；3 年以上，30 天前
說明=離職前記得：確認特休折現、最後一筆薪水、勞健保退保日期，拿離職證明；工作交接清楚，好聚好散
@婚禮紅包|婚禮紅包要包多少,結婚紅包包多少,喜酒紅包多少,紅包要包多少|常識
簡介=台灣婚禮紅包常見的金額是 1,200、1,600、2,000、2,200、3,600、6,600；一般同事、普通朋友大約 1,600 到 2,000，好朋友 2,000 到 3,600，親戚或很親近的人會更多；也會看喜宴餐廳的價位
說明=包雙數比較吉利，避開有 4 的數字；人沒到只送紅包的話，可以包少一點
@健康檢查|健康檢查要做哪些,健檢要做哪些,健康檢查要檢查什麼,健康檢查項目,成人健檢,免費健康檢查|健康常識
簡介=台灣的免費成人預防保健：40 到 64 歲每 3 年一次、65 歲以上每年一次，包括身高體重、血壓、血液（血糖、血脂、肝腎功能）、尿液檢查
說明=另外有免費癌症篩檢：子宮頸抹片、乳房攝影（45 到 69 歲女性）、糞便潛血檢查（大腸癌）、口腔黏膜檢查（嚼檳榔或抽菸的人），年齡和間隔以國健署最新公告為準；有家族病史的人可以跟醫生討論加做其他項目
@出國換錢|出國要換多少錢,出國要帶多少現金,出國帶多少錢|常識
簡介=現在很多國家都能刷卡或用行動支付，一般建議帶大約旅費三到五成的當地現金就夠，例如去日本一週可以換 3 到 5 萬日圓，再帶一兩張海外回饋高的信用卡；可以在台灣的銀行先換，或用外幣提款卡在當地領
@時間旅行|時間旅行可能嗎,可以時間旅行嗎,時光旅行,回到過去|科學
簡介=依照愛因斯坦的相對論，「到未來」在理論上是可以的：跑得接近光速或待在強重力的地方，時間會變慢，回來時地球已經過了比較久（太空人在國際太空站待半年，會比地面上的人年輕幾毫秒）
說明=「回到過去」就困難得多，會遇到「祖父悖論」這類矛盾，目前沒有任何可行的方法，也沒有證據證明做得到
@人死後|人死後會去哪裡,死後的世界,人死了會去哪,死後會怎樣|常識
簡介=這是人類想了幾千年的問題，沒有標準答案：佛教說會輪迴轉世，基督教說會上天堂或下地獄，道教和民間信仰有陰間的說法；科學上來說，死亡是身體和大腦停止運作，意識是不是還存在，目前沒有證據
說明=我覺得重要的是：人會一直被記得，留在愛他的人心裡
@地球毀滅|地球會毀滅嗎,地球什麼時候毀滅,世界會毀滅嗎|常識
簡介=很久很久以後會：大約 50 億年後，太陽會膨脹成紅巨星，可能把地球吞掉；在那之前大約 10 億年後，太陽變亮會讓海洋蒸發，地球就不適合生物住了。近期內比較需要擔心的是氣候變遷、核戰和小行星撞擊，這些人類可以努力預防
@宇宙大小|宇宙有多大,宇宙多大,宇宙有邊界嗎|常識
簡介=我們看得到的宇宙（可觀測宇宙）直徑大約 930 億光年，裡面有大約兩兆個星系；整個宇宙可能比這還大很多，甚至可能是無限大，目前還不知道
說明=光一秒可以繞地球七圈半，卻要走上百億年才能跨過可觀測宇宙
@最長壽的人|最長壽的人活了幾歲,世界上最長壽的人,最老的人活多久|常識
簡介=有可靠紀錄的最長壽的人是法國的珍妮·卡爾門，活了 122 歲又 164 天（1875 年到 1997 年）
@最快樂的國家|哪個國家最快樂,最幸福的國家,世界最快樂的國家|常識
簡介=聯合國的《世界幸福報告》裡，芬蘭連續好幾年排第一，丹麥、冰島、瑞典、荷蘭也常在前幾名；台灣常是亞洲排名最前面的國家之一。排名主要看收入、健康壽命、社會支持、自由、信任和慷慨
@鳥為什麼會飛|為什麼鳥會飛,鳥為什麼會飛,鳥怎麼飛,鳥為什麼能飛|常識
簡介=鳥會飛靠的是幾個特別的構造：翅膀拍下去時把空氣往下推，空氣就把鳥往上推（升力）；骨頭是中空的、很輕；有強壯的胸肌拍動翅膀；羽毛輕又能擋風；還有效率很高的肺和氣囊，能提供飛行需要的大量氧氣
@下雪的原因|為什麼會下雪,下雪的原因,雪是怎麼來的,雪怎麼形成|常識
簡介=雲裡的溫度在 0°C 以下時，水氣直接凝結在小灰塵上變成冰晶，冰晶互相黏在一起越長越大、變重就掉下來；如果一路上空氣都夠冷沒有融化，落到地面就是雪。雪花大多是六角形，因為水分子結冰時就是排成六角形
@喝水的原因|人為什麼要喝水,為什麼要喝水,為什麼要多喝水|常識
簡介=人體大約 60% 是水：血液要靠水運送養分和氧氣、流汗要靠水散熱、腎臟要靠水把廢物排出、關節和眼睛也要水來潤滑。人不吃東西可以撐好幾週，不喝水通常只能撐 3 到 5 天
@過敏|過敏是什麼,什麼是過敏,過敏反應|健康常識
簡介=過敏是免疫系統太敏感，把本來無害的東西（花粉、塵蟎、貓狗皮屑、某些食物）當成敵人，產生打噴嚏、流鼻水、皮膚癢、起疹子等反應
說明=嚴重的過敏（全身起疹子、嘴唇腫、呼吸困難）叫做「過敏性休克」，要馬上打 119
@碳水化合物|醣類,澱粉類|健康常識
簡介=碳水化合物（醣類）是身體最主要的能量來源，像米飯、麵、麵包、地瓜、水果、糖都是
說明=全穀類、地瓜這種「複合碳水化合物」消化比較慢、比較有飽足感；含糖飲料、甜點這種「精緻糖」血糖升得快，少吃比較好
@卡路里|大卡,熱量|健康常識
簡介=卡路里是熱量的單位，食物標示的「大卡」（千卡）就是 1,000 卡路里；一般成人一天大約需要 1,500 到 2,500 大卡，看性別、體型和活動量
說明=吃進去的熱量比消耗的多，多的就會變成脂肪存起來；大約 7,700 大卡等於 1 公斤脂肪
@膽固醇|壞膽固醇,好膽固醇|健康常識
簡介=膽固醇是身體製造細胞膜和荷爾蒙需要的脂質；「壞膽固醇」（LDL）太高會堆在血管壁，增加心臟病和中風風險；「好膽固醇」（HDL）會把多的膽固醇帶回肝臟
說明=少吃油炸、加工肉品和甜食，多吃蔬菜、魚、堅果，規律運動，都能改善膽固醇
@糖尿病|糖尿病是什麼|健康常識
簡介=糖尿病是血糖長期太高的慢性病：身體不能製造足夠的胰島素（第一型），或胰島素作用變差（第二型，最常見，和肥胖、少運動、遺傳有關）
說明=常見症狀是吃多、喝多、尿多、體重減輕；長期血糖太高會傷害眼睛、腎臟、神經和血管。控制飲食、運動、按時吃藥或打胰島素，可以控制得很好
@高血壓|高血壓是什麼|健康常識
簡介=血壓長期太高（台灣的標準是 130/80 以上），心臟和血管一直承受太大的壓力，時間久了會增加中風、心臟病、腎臟病的風險；很多人沒有症狀，所以被叫做「沉默的殺手」
說明=少吃鹽、控制體重、規律運動、少喝酒、不抽菸，按時量血壓，需要的話照醫生指示吃藥
@憂鬱症|憂鬱症是什麼|健康常識
簡介=憂鬱症是一種疾病，不是心情不好或想太多：連續兩週以上幾乎每天心情低落、對以前喜歡的事失去興趣，還可能睡不好、吃不下或吃太多、很累、覺得自己沒價值、很難專心，甚至想到死
說明=憂鬱症可以治療：看身心科、心理諮商、藥物都很有效。如果你或身邊的人有這樣的狀況，可以打 1925（依舊愛我）安心專線，24 小時都有人接
@焦慮症|焦慮症是什麼,廣泛性焦慮症|健康常識
簡介=焦慮症是擔心、緊張的感覺太強、太久，強到影響生活：常常控制不住地擔心、心跳快、呼吸急、肌肉緊繃、睡不好；恐慌症、社交焦慮症都屬於焦慮症
說明=焦慮症很常見，也可以治療：心理治療（像認知行為治療）和藥物都有效，看身心科或找心理師就可以
@失智症|失智症是什麼,老人痴呆,阿茲海默症|健康常識
簡介=失智症是大腦功能慢慢退化的疾病，不只是記性變差，還會影響判斷、語言、方向感和個性；最常見的是阿茲海默症
說明=早期發現可以延緩惡化；多動腦、多運動、多社交、控制三高，可以降低風險。家人懷疑時可以帶去看神經內科或精神科的記憶門診
@自閉症|自閉症是什麼,自閉症類群障礙,泛自閉症|健康常識
簡介=自閉症（自閉症類群障礙）是大腦發展的差異，不是疾病也不是教養造成的：常見在社交溝通上比較困難、有固定的興趣或重複的行為、對聲音光線等感覺特別敏感或遲鈍；每個人的狀況差很多
說明=越早接受早期療育越好；很多自閉症的人有自己特別擅長的事，理解和接納最重要
@ADHD|注意力不足過動症,過動症,adhd|健康常識
簡介=ADHD（注意力不足過動症）是大腦發展的差異：很難專心、容易分心、衝動、坐不住；不是不認真或沒教好，大人也可能有
說明=可以透過行為治療、環境調整和藥物改善；找兒童心智科或身心科評估
@抗生素|抗生素是什麼|健康常識
簡介=抗生素是用來殺死或抑制「細菌」的藥，像盤尼西林；它對病毒（感冒、流感大多是病毒）沒有用
說明=醫生開了抗生素就要照指示吃完，不要自己停藥或亂吃，不然細菌容易產生抗藥性
@漢朝多久|漢朝有多久,漢朝多少年,漢朝存在多久|常識
簡介=漢朝從西元前 202 年到西元 220 年，大約 400 年（分成西漢和東漢，中間有王莽的新朝），是中國歷史上很長、很強盛的朝代
@唐朝首都|唐朝的首都,唐朝首都在哪,唐朝的首都在哪|常識
簡介=唐朝的首都是長安（現在的陝西西安），當時是世界上最大、最國際化的城市之一；洛陽是東都
@宋朝發明|宋朝有什麼發明,宋朝的發明|常識
簡介=中國四大發明裡有三項在宋朝成熟或普及：畢昇發明活字印刷、指南針用在航海、火藥用在武器；宋朝也發行了世界最早的紙幣「交子」
@清朝結束|清朝是哪一年結束的,清朝哪一年結束,清朝什麼時候結束,清朝滅亡,清朝什麼時候滅亡,清朝哪一年滅亡,清朝是什麼時候滅亡的|常識
簡介=清朝在 1912 年結束：1911 年辛亥革命爆發，1912 年 2 月 12 日宣統皇帝溥儀退位，中華民國成立
@工業革命|第一次工業革命|事件
簡介=18 世紀中期從英國開始，用機器和蒸汽機取代手工生產，工廠、鐵路、火車大量出現，改變了人類的生活和工作方式
年份=大約 1760 年到 1840 年
@美國獨立|美國什麼時候獨立,美國獨立戰爭,美國獨立宣言|事件
簡介=北美 13 個殖民地脫離英國，1776 年 7 月 4 日發表《獨立宣言》，這天是美國的國慶日；獨立戰爭打到 1783 年英國正式承認
年份=1776 年 7 月 4 日
@一戰的原因|第一次世界大戰為什麼開始,一戰為什麼爆發,第一次世界大戰的原因|常識
簡介=直接的導火線是 1914 年 6 月奧匈帝國的皇儲斐迪南大公在塞拉耶佛被刺殺；背後的原因是歐洲列強之間的軍備競賽、搶殖民地、民族主義，還有兩大同盟（同盟國和協約國）互相綁在一起，一國開戰就拖進一大群國家
@冷戰|冷戰是什麼|事件
簡介=第二次世界大戰後，以美國為首的資本主義陣營和以蘇聯為首的共產主義陣營長期對抗，雙方沒有直接開打，而是比軍備、太空競賽、代理戰爭（韓戰、越戰）
年份=大約 1947 年到 1991 年蘇聯解體
@柏林圍牆|柏林牆|地標
簡介=1961 年東德蓋的圍牆，把柏林分成東西兩半，阻止東德人逃到西方，是冷戰的象徵；1989 年 11 月 9 日開放、之後被拆除，隔年東西德統一
位置=德國柏林
@南極洲有人住|南極洲有人住嗎,南極有人住嗎,南極有住人嗎|常識
簡介=南極洲沒有原住民、也沒有永久居民，只有各國科學研究站的研究人員輪流住，夏天大約 4,000 到 5,000 人、冬天大約 1,000 人；依照《南極條約》，南極只能用在和平和科學研究
@北極有企鵝|北極有企鵝嗎,北極有沒有企鵝|常識
簡介=北極沒有企鵝！野生企鵝幾乎都住在南半球（南極、南美洲、非洲南部、澳洲、紐西蘭），只有加拉巴哥企鵝住在赤道附近；北極有的是北極熊、北極狐和海豹，所以北極熊和企鵝其實不會碰面
@世界上的語言|世界上有幾種語言,全世界有幾種語言,世界上有多少種語言|常識
簡介=全世界大約有 7,000 種語言，其中很多只有很少人說、正在消失；說的人最多的是英語（算上第二語言）和中文（以母語來算）
@英文字母|英文有幾個字母,英文字母有幾個,英文字母有多少個|常識
簡介=英文有 26 個字母，其中 5 個母音字母（A、E、I、O、U），21 個子音字母
@注音符號|注音符號有幾個,注音有幾個|常識
簡介=注音符號一共有 37 個：21 個聲母、16 個韻母（介音ㄧㄨㄩ也算在韻母裡），再加上四個聲調符號和輕聲
@中文字數|中文有多少字,中文有幾個字,漢字有多少個|常識
簡介=《康熙字典》收了大約 4.7 萬個字，現代的大字典收到 8 萬到 10 萬個；但日常生活常用的只有大約 3,000 到 4,000 個，認得 2,500 個常用字就能看懂大部分的報紙
@日文的文字|日文有幾種文字,日文的文字,日文有哪些文字|常識
簡介=日文主要用三種文字：平假名（寫助詞和日本固有的詞）、片假名（寫外來語，例如コーヒー咖啡）、漢字；另外也會用羅馬字和數字
@韓文的由來|韓文是誰發明的,韓文的由來,誰發明韓文|常識
簡介=韓文（訓民正音）是朝鮮王朝的世宗大王在 1443 年創造、1446 年公布的，讓一般老百姓也能讀寫；字母的形狀模仿發音時嘴巴和舌頭的樣子，被認為是很科學的文字
@圓的面積公式|圓面積公式,圓的面積怎麼算,圓面積怎麼算,圓的周長公式,圓周長怎麼算|常識
簡介=圓的面積 = 圓周率 × 半徑 × 半徑（πr²）；圓的周長 = 2 × 圓周率 × 半徑（2πr），也就是直徑 × π。例如半徑 10 公分的圓，面積大約 314 平方公分、周長大約 62.8 公分
@平均數|平均數怎麼算,平均怎麼算,算平均,平均值怎麼算|常識
簡介=平均數 = 所有數字加起來 ÷ 數字的個數。例如 80、90、70 三個分數，平均是 (80 + 90 + 70) ÷ 3 = 80。另外「中位數」是排好順序後中間的那個數，比較不會被特別大或特別小的數影響
@一打|一打是幾個,一打幾個|常識
簡介=一打是 12 個；一籮是 12 打（144 個）
@一刻鐘|一刻鐘是幾分鐘,一刻是幾分鐘|常識
簡介=一刻鐘是 15 分鐘，一個小時有四刻；古代一天分成一百刻，一刻大約 14.4 分鐘
@一甲子|一甲子是幾年,甲子是幾年|常識
簡介=一甲子是 60 年：天干（10 個）和地支（12 個）依序配對，60 年循環一次，所以 60 歲叫「花甲之年」
@長頸鹿的脖子|長頸鹿的脖子有幾節,長頸鹿脖子幾節,長頸鹿的頸椎|常識
簡介=長頸鹿的脖子只有 7 節頸椎，跟人類一樣多！差別是牠每一節都很長，一節可以超過 25 公分；幾乎所有哺乳類都是 7 節頸椎
@世界盃冠軍|世界盃冠軍最多的國家,世界盃最多冠軍,世足冠軍最多,拿最多世界盃冠軍|常識
簡介=拿過最多次男子足球世界盃冠軍的是巴西，一共 5 次（1958、1962、1970、1994、2002）；德國和義大利各 4 次，阿根廷 3 次（最近一次是 2022 年卡達世界盃，梅西領軍）
@足球比賽時間|足球比賽多久,足球一場多久,足球比賽幾分鐘|常識
簡介=一場足球比賽是 90 分鐘，分上下半場各 45 分鐘，中場休息 15 分鐘，再加上裁判給的傷停補時；淘汰賽平手的話，會打 30 分鐘延長賽，還是平手就 PK 罰球
@籃球比賽時間|籃球比賽幾節,籃球比賽多久,籃球一場多久|常識
簡介=籃球比賽分 4 節：NBA 每節 12 分鐘（共 48 分鐘），國際籃總（FIBA）和奧運每節 10 分鐘（共 40 分鐘）；平手的話打 5 分鐘的延長賽
@網球計分|網球怎麼計分,網球計分方式,網球規則|常識
簡介=網球的分數是 0（Love）、15、30、40，再贏一球就拿下這一局；40 比 40 叫「平分（Deuce）」，要連贏兩球才算拿下。先拿到 6 局（且領先 2 局）贏一盤，6 比 6 打搶七；一般比賽三盤兩勝，大滿貫男子是五盤三勝
@羽球計分|羽球怎麼計分,羽毛球怎麼計分,羽球規則|常識
簡介=羽球採每球得分制，先拿到 21 分贏一局，三局兩勝；20 比 20 時要領先 2 分才贏，最多打到 30 分（29 比 29 時先得 30 分的贏）
@桌球計分|桌球怎麼計分,乒乓球怎麼計分,桌球規則|常識
簡介=桌球每球得分，先拿到 11 分贏一局，10 比 10 之後要領先 2 分；每 2 分換發球（10 比 10 之後每 1 分換）；比賽通常是五局三勝或七局四勝
@螞蟻的力氣|螞蟻可以舉起多重,螞蟻力氣多大,螞蟻可以搬多重|常識
簡介=螞蟻可以舉起自己體重的 10 到 50 倍，有研究測到某些螞蟻的脖子可以承受體重好幾千倍的拉力；因為牠們很小，肌肉相對身體的比例很大，所以看起來力氣特別大
@高鐵搭乘|怎麼搭高鐵,高鐵怎麼搭,搭高鐵,高鐵怎麼買票,高鐵票在哪裡買,高鐵票哪裡買,高鐵票要在哪買,高鐵票怎麼買,高鐵票要怎麼買|常識
簡介=搭高鐵可以用高鐵 App（T Express）、官網或便利商店訂票，也可以在車站售票機或櫃台買；有對號座和自由座（自由座比較便宜但不一定有位子）。到站後走票閘口，掃 App 的 QR code 或插車票進站，看月台和車廂號碼上車；悠遊卡、一卡通也可以直接刷自由座
@悠遊卡加值|悠遊卡怎麼加值,悠遊卡加值,儲值悠遊卡,悠遊卡沒錢了,悠遊卡沒錢,悠遊卡餘額不足,悠遊卡不夠錢|常識
簡介=悠遊卡可以在捷運站的加值機或詢問處、便利商店（7-11、全家、萊爾富、OK）結帳櫃台加值，每次 100 元為單位；也可以申請「自動加值」綁信用卡，餘額不夠時自動加值
@叫計程車|怎麼叫計程車,叫計程車,叫車|常識
簡介=可以在路邊看到空車（車頂燈亮、前面顯示「空車」）招手；或打車隊電話（像台灣大車隊 55688）；用 App 叫車（55688 App、Uber、LINE TAXI）最方便，可以先看到預估車資和司機資訊
@YouBike|YouBike怎麼借,Ubike怎麼借,微笑單車,公共腳踏車|常識
簡介=YouBike 用悠遊卡、一卡通或信用卡就能借：先在 YouBike App 或站點的機台註冊（綁手機號碼），到車柱刷卡、聽到提示聲就能把車拉出來；還車時推回空的車柱、刷卡確認。台北市前 30 分鐘是 5 元（費率依縣市和政策不同）
@台鐵和高鐵|台鐵和高鐵差在哪,台鐵和高鐵的差別,高鐵和台鐵差在哪,台鐵跟高鐵差在哪|常識
簡介=高鐵快很多（台北到高雄約 1.5 到 2 小時）但比較貴，車站多在市區外圍；台鐵比較慢（自強號約 4 到 5 小時）但便宜、站很多，很多車站就在市中心，也能到東部（花蓮、台東），高鐵到不了東部
@網購注意|網購要注意什麼,網路購物要注意什麼,網購注意事項|常識
簡介=網購要注意：選有評價、有實體客服的平台和賣家；價格低得太誇張要小心；不要私下轉帳、不要點陌生連結付款；收到貨開箱時錄影，有問題比較好處理；台灣網購大多有 7 天鑑賞期可以退貨。接到「設定錯誤、要你去 ATM 操作」的電話一定是詐騙，打 165
@退貨|退貨怎麼辦,怎麼退貨,網購退貨,東西要退貨|常識
簡介=台灣網購通常有 7 天鑑賞期，不用理由都能退貨（拆封試用過、個人化商品等例外）：先到購物平台的訂單裡按「申請退貨」，照說明把商品和配件、發票放回原包裝，等物流來收或拿去超商寄；退款通常幾天到兩週會退回原付款方式。實體店退貨要看店家的規定，記得留發票
@發票載具|發票載具是什麼,載具是什麼,手機條碼載具,手機載具,雲端發票怎麼用,雲端發票是什麼,雲端發票,載具怎麼用|常識
簡介=發票載具就是把電子發票存在手機或卡片裡，不用拿紙本發票。最常用的是「手機條碼」：在財政部電子發票 App 申請一組條碼，結帳時給店員掃，發票就存進你的帳戶，開獎時會自動對獎、中獎直接匯款到帳戶
@信用卡和金融卡|信用卡和金融卡差在哪,信用卡跟金融卡差別,金融卡和信用卡的差別|常識
簡介=金融卡（簽帳金融卡）是用你帳戶裡的錢，刷多少扣多少，沒錢就刷不過；信用卡是銀行先幫你付，下個月再繳帳單，準時全額繳清不用利息，只繳最低就會有很高的循環利息（大約 5% 到 15%）。信用卡通常回饋比較多，但要小心不要花超過自己付得起的
@行動支付|行動支付是什麼,手機支付,Apple Pay是什麼,LINE Pay是什麼|常識
簡介=行動支付就是用手機付錢，不用拿現金或卡片：Apple Pay、Google Pay 是把信用卡綁進手機，感應付款；LINE Pay、街口支付、全支付是掃 QR code 付款。好處是方便、常有回饋，手機要設好密碼或臉部辨識，不見時記得停用
@過期的牛奶|過期的牛奶可以喝嗎,過期牛奶可以喝嗎,牛奶過期可以喝嗎,過期的牛奶能喝嗎|常識
簡介=不建議喝。鮮奶過了保存期限就可能有細菌滋生，喝了容易拉肚子、腸胃炎；如果已經有酸味、結塊、顏色或味道怪怪的，一定要丟掉。保久乳沒開封、只過期一點點的風險比較低，但開封後也要冷藏、盡快喝完
@狗吃水果|狗可以吃蘋果嗎,狗可以吃香蕉嗎,狗可以吃什麼水果,狗狗可以吃水果嗎,狗可以吃西瓜嗎|常識
簡介=可以少量吃：蘋果（去籽、去核，籽有微量氰化物）、香蕉、西瓜（去籽去皮）、藍莓、芭樂都可以當小點心；不能吃葡萄和葡萄乾（可能造成急性腎衰竭）、酪梨、櫻桃核、柑橘大量吃也容易拉肚子。水果只能當零食，一天不要超過總熱量的 10%
@貓吃魚|貓可以吃魚嗎,貓咪可以吃魚嗎,貓可以吃生魚嗎|常識
簡介=可以偶爾吃煮熟、去刺的魚，但不要天天當主食：長期只吃魚可能缺乏營養（像維生素 E、B1），生魚還有寄生蟲和破壞維生素 B1 的酵素；鮪魚罐頭（人吃的）鹽分太高，最好選貓專用的罐頭
@孕婦喝咖啡|孕婦可以喝咖啡嗎,懷孕可以喝咖啡嗎,懷孕能喝咖啡嗎|常識
簡介=可以，但要限量：懷孕期間咖啡因每天不超過 200 毫克，大約是一杯中杯美式咖啡；茶、可樂、巧克力也有咖啡因，要一起算。喝太多可能增加流產和胎兒體重過輕的風險
@孕婦吃生魚片|孕婦可以吃生魚片嗎,懷孕可以吃生魚片嗎,懷孕能吃生魚片嗎,孕婦可以吃生食嗎|常識
簡介=建議不要。生魚片、生蠔這類生食可能有李斯特菌、寄生蟲，孕婦感染後可能影響胎兒；大型魚（鯊魚、旗魚、鮪魚大腹）汞含量比較高，也要少吃。想吃壽司可以選熟的（玉子燒、熟蝦、烤鰻魚、鮭魚炙燒）
@小孩喝咖啡|小孩可以喝咖啡嗎,小朋友可以喝咖啡嗎,國中生可以喝咖啡嗎|常識
簡介=不建議，特別是 12 歲以下。小孩對咖啡因比較敏感，容易心跳快、睡不好、焦慮；青少年如果要喝，一天咖啡因最好不超過 100 毫克（大約一小杯），而且不要晚上喝。很多手搖飲的茶和能量飲料也有很多咖啡因
@生雞蛋|生雞蛋可以吃嗎,生蛋可以吃嗎,雞蛋可以生吃嗎|常識
簡介=有風險：生雞蛋可能有沙門氏菌，吃了可能上吐下瀉、發燒，小孩、孕婦、老人和免疫力差的人最好不要吃。想吃半熟蛋或生蛋拌飯，選標示「洗選蛋」或「殺菌蛋」比較安全，而且要新鮮、冷藏保存
@發芽的馬鈴薯|發芽的馬鈴薯可以吃嗎,馬鈴薯發芽可以吃嗎,發芽馬鈴薯能吃嗎,馬鈴薯變綠|常識
簡介=小心！馬鈴薯發芽或表皮變綠的地方會產生龍葵鹼（茄鹼），吃多了會噁心、嘔吐、腹瀉、頭暈。只有一點點芽的話，可以把芽眼和周圍、綠色的部分挖掉一大塊再煮；發很多芽、整顆變綠或變軟皺，就直接丟掉。高溫煮也破壞不了龍葵鹼
@吃宵夜會胖嗎|吃宵夜會胖嗎,宵夜會胖嗎,晚上吃東西會胖嗎|常識
簡介=會不會胖主要看一天吃進去的總熱量，不是幾點吃。但宵夜常常是額外多吃的（鹽酥雞、泡麵、手搖飲），熱量很容易超過；太晚吃也可能影響睡眠、胃食道逆流。真的餓了可以選清淡的：無糖豆漿、茶葉蛋、水果、無糖優格
@飯後運動|吃飯後可以馬上運動嗎,飯後可以運動嗎,吃飽可以運動嗎,飯後多久可以運動|常識
簡介=飯後散步慢走是可以的，對血糖也有幫助；但跑步、游泳、重訓這種比較激烈的運動，最好等 1 到 2 小時（吃得多就等久一點），不然容易肚子痛、想吐、胃不舒服
@咖啡脫水|喝咖啡會脫水嗎,咖啡會脫水嗎,咖啡利尿|常識
簡介=一般不會。咖啡因有一點利尿作用，但咖啡本身大部分是水；研究發現常喝咖啡的人，適量喝（一天三到四杯以內）不會造成脫水，也可以算進每天的喝水量。不過還是建議主要喝白開水
@吃辣好不好|吃辣對身體好嗎,吃辣好嗎,吃辣的好處,吃辣的壞處|常識
簡介=適量吃辣有一些好處：辣椒素可能讓代謝稍微變快、促進食慾；但吃太辣容易胃痛、胃食道逆流、拉肚子，有胃潰瘍、痔瘡、正在長痘痘的人要少吃。能不能吃辣因人而異，身體不舒服就減量
@喝紅酒|喝紅酒對身體好嗎,紅酒對身體好嗎,喝紅酒好嗎,每天喝紅酒|常識
簡介=現在的研究認為沒有「對健康有益」的飲酒量：以前說紅酒能保護心臟，證據其實不夠強，而酒精會增加多種癌症和肝病的風險。紅酒裡的多酚，從葡萄、莓果、茶也吃得到。不喝最好；要喝就少量、不要天天喝
@一天吃幾顆蛋|蛋一天可以吃幾顆,一天可以吃幾顆蛋,雞蛋一天吃幾顆,一天吃幾顆蛋|常識
簡介=健康的人一天吃 1 到 2 顆蛋通常沒問題，雞蛋是很好的蛋白質來源；現在的研究認為食物裡的膽固醇對血液膽固醇影響沒有以前想的大。有高血脂、糖尿病或心血管疾病的人，可以問醫生或營養師建議的量
@每天蔬果量|一天要吃多少蔬菜,每天要吃多少蔬菜,一天要吃多少水果,蔬菜要吃多少|常識
簡介=台灣的每日飲食指南建議：成人每天蔬菜 3 到 5 份（1 份大約是煮熟後半碗），水果 2 到 4 份（1 份大約是一個拳頭大）；簡單記法是「每餐蔬菜比水果多、蔬菜吃半盤」
@蛋白質食物|什麼食物有蛋白質,哪些食物有蛋白質,蛋白質多的食物,高蛋白食物|常識
簡介=蛋白質多的食物：豆類和豆製品（豆腐、豆漿、毛豆）、魚和海鮮、雞蛋、雞胸肉和瘦肉、牛奶和優格、堅果。建議優先選豆類和魚，少吃加工肉品（香腸、培根）
@鈣質食物|什麼食物有鈣,哪些食物有鈣,鈣多的食物,補鈣吃什麼,怎麼補鈣,補鈣,要怎麼補鈣,補鈣要吃什麼|常識
簡介=鈣多的食物：牛奶、優格、起司、傳統豆腐（加了石膏凝固）、豆干、小魚乾、黑芝麻、深綠色蔬菜（芥藍、地瓜葉）。成人每天大約需要 1,000 毫克，喝兩杯牛奶大約就有一半；也要曬太陽、補充維生素 D 幫助吸收
@維他命C水果|什麼水果維他命C最多,維他命C最多的水果,哪個水果維他命C多,維生素C多的水果|常識
簡介=常見水果裡，芭樂的維他命 C 特別多（一顆就超過一天的需要量），其他像奇異果、木瓜、草莓、柑橘、柳丁、龍眼也很多；甜椒、青花菜這些蔬菜也很多
@香蕉的營養|香蕉有什麼營養,香蕉的營養,吃香蕉的好處|常識
簡介=香蕉有很多鉀（幫助調節血壓、預防抽筋）、碳水化合物（快速補充能量，運動前後很適合）、膳食纖維和維生素 B6；一根大約 90 到 120 大卡。腎臟病需要限鉀的人要少吃
@月亮上的水|月亮上有水嗎,月球上有水嗎,月球有水嗎|常識
簡介=有，但很少，而且大多是冰：科學家在月球南北極永遠照不到太陽的隕石坑裡發現水冰，月球表面的土壤裡也有微量的水分子。月亮上沒有河流和海，看起來像「海」的黑色區域其實是古代熔岩凝固的平原
@火星住人|火星可以住人嗎,人類可以住在火星嗎,火星能住人嗎,移民火星|常識
簡介=現在還不行：火星的空氣非常稀薄、大部分是二氧化碳，平均溫度大約零下 60°C，又有很強的宇宙輻射，人要住在密封的基地裡、穿太空衣才能出門。NASA 和 SpaceX 都在計畫載人登陸火星，但真正長期住人還需要很多年
@第一個上太空的人|第一個上太空的人是誰,誰是第一個上太空的人,第一個太空人|常識
簡介=第一個上太空的人是蘇聯的尤里·加加林，1961 年 4 月 12 日搭東方一號繞地球一圈，大約 108 分鐘；第一個登陸月球的人是美國的阿姆斯壯（1969 年）
@最近的恆星|最近的星星是哪一顆,離地球最近的恆星,最近的恆星|常識
簡介=離地球最近的恆星其實是太陽！太陽以外最近的是比鄰星（半人馬座比鄰星），大約 4.2 光年遠，用現在最快的太空船也要飛好幾千年
@流星|流星是什麼,為什麼會有流星|天體
簡介=太空中的小石頭或塵埃（流星體）高速衝進地球的大氣層，跟空氣摩擦燒起來發出的光，大部分在掉到地面前就燒完了；沒燒完掉到地上的叫隕石
說明=每年固定時候會有流星雨，像 8 月的英仙座流星雨、12 月的雙子座流星雨
@彗星|彗星是什麼,掃把星|天體
簡介=由冰、塵埃和岩石組成的小天體，繞著太陽轉；靠近太陽時冰會蒸發，形成長長的尾巴，所以俗稱「掃把星」
說明=最有名的哈雷彗星大約每 76 年回來一次，下一次大約在 2061 年
@極光|極光是怎麼來的,極光是什麼,為什麼會有極光,北極光|常識
簡介=太陽噴出的帶電粒子（太陽風）飛到地球，被地球的磁場引導到南北極附近，撞上高空大氣中的氧和氮，發出綠色、紅色、紫色的光，就是極光。最常在挪威、冰島、芬蘭、加拿大、阿拉斯加這些高緯度地方看到
@海嘯|海嘯是什麼,為什麼會有海嘯|常識
簡介=海底發生大地震、火山爆發或山崩，讓大量海水突然被推動，形成速度很快、到岸邊會變得很高的巨浪。在大海中海嘯可能只有幾十公分高，但靠近海岸會變成好幾公尺甚至十幾公尺
說明=在海邊感覺到強烈地震，或看到海水突然大退潮，要馬上往高處跑，不要等警報
@臭氧層|臭氧層是什麼,臭氧層破洞|常識
簡介=臭氧層是大氣中大約 15 到 35 公里高的一層，有比較多的臭氧，能擋掉大部分太陽的有害紫外線，保護地球上的生物
說明=以前冰箱、冷氣用的氟氯碳化物（CFCs）會破壞臭氧層，在南極上空造成破洞；1987 年各國簽了《蒙特婁議定書》禁用之後，臭氧層正在慢慢恢復
@酸雨|酸雨是什麼,為什麼會有酸雨|常識
簡介=工廠、汽機車燒煤和石油排放的二氧化硫、氮氧化物，在空氣中和水氣變成硫酸、硝酸，再隨著雨落下來，就是酸雨（酸鹼值低於 5.6）；會傷害森林、湖泊裡的生物，也會腐蝕建築和古蹟
@PM2.5|PM2.5是什麼,pm2.5,細懸浮微粒|常識
簡介=PM2.5 是直徑小於 2.5 微米的細懸浮微粒（大約頭髮的 1/30），來源有汽機車排氣、工廠、燃燒、沙塵等；因為很小，能深入肺部甚至進入血液，增加呼吸道和心血管疾病的風險
說明=空氣品質不好時（AQI 橘色以上），減少戶外運動、外出戴口罩、家裡關窗開空氣清淨機；可以用環境部的空氣品質 App 查
@空氣汙染|空氣汙染怎麼辦,空汙很嚴重怎麼辦,空氣不好怎麼辦,空汙|常識
簡介=空氣不好的時候：先查空氣品質（AQI），橘色以上就減少戶外活動、不要在戶外運動；出門戴口罩（N95 或醫療口罩比布口罩好）；回家洗手洗臉，關窗、開空氣清淨機；平常可以多搭大眾運輸、少開車，一起減少空汙
@資源回收|怎麼做資源回收,資源回收怎麼分,垃圾分類,回收怎麼分類,垃圾怎麼分類,垃圾要怎麼分類,回收要怎麼分|常識
簡介=台灣的資源回收大致分成：紙類（紙箱、報紙，攤平綁好）、塑膠類（寶特瓶、塑膠瓶罐，倒乾淨壓扁）、鐵鋁罐、玻璃瓶、乾電池、日光燈管、舊衣；回收前先把食物殘渣沖乾淨。廚餘另外分，沾了油汙的紙餐盒、衛生紙通常是一般垃圾
說明=各縣市的分類規定有些不一樣，可以看清潔隊公告或環保局網站
@塑膠吸管|塑膠吸管為什麼不好,為什麼不要用塑膠吸管,塑膠吸管的壞處,減塑|常識
簡介=塑膠吸管又小又輕，很難回收，常常流進海裡，幾百年都不會分解，會碎成微塑膠，海龜、海鳥可能誤食或被卡住；台灣從 2019 年起限制內用飲料提供一次性塑膠吸管。可以改用不鏽鋼、玻璃、竹子吸管，或直接就口喝
@減少碳排放|怎麼減少碳排放,怎麼減碳,如何減碳,減少碳足跡|常識
簡介=生活中減碳可以這樣做：多搭大眾運輸、騎腳踏車或走路，少開車；冷氣設 26 到 28°C、隨手關燈；少買不需要的東西、用環保杯和購物袋；少吃一點紅肉，多吃蔬菜和在地當季食物；搭飛機的次數減少一點；選有節能標章的電器
@火鍋|麻辣鍋,涮涮鍋|食物
簡介=把肉片、海鮮、蔬菜、豆腐等食材放進滾燙的湯底裡邊煮邊吃的料理，台灣常見的有麻辣鍋、涮涮鍋、薑母鴨、羊肉爐
說明=吃火鍋小提醒：湯頭越煮越鹹、普林越高，痛風的人少喝湯；加工火鍋料（餃類、丸子）熱量和鈉都高，多吃蔬菜和原型食物比較健康
@認知失調|認知失調是什麼|心理學
簡介=當一個人的想法和行為互相矛盾時，心裡會覺得不舒服，於是改變想法或找理由來合理化，好讓自己好過一點
說明=例如明知道抽菸傷身還在抽，就告訴自己「我爺爺抽一輩子也活到九十歲」；這是心理學家費斯汀格在 1957 年提出的
@冒牌者症候群|冒名頂替症候群,冒牌者現象|心理學
簡介=明明很有能力、也有成果，卻總覺得自己是靠運氣、不配得到現在的位置，很怕哪天被別人「拆穿」
說明=很多成功的人都有這種感覺，不是病；可以試著把自己的成果寫下來、跟信任的人聊聊，提醒自己成功不全是運氣
@墨菲定律|莫非定律|心理學
簡介=「凡是可能出錯的事，就一定會出錯」，像是越趕時間越容易遇到紅燈、帶傘不下雨不帶就下
說明=它本來的意思是提醒工程師：設計時要預先想到可能出錯的地方，做好防範
@達克效應|鄧寧-克魯格效應,達克效應是什麼|心理學
簡介=能力不足的人，常常高估自己的能力，因為他們連「自己哪裡不懂」都看不出來；真正厲害的人反而容易低估自己
說明=由心理學家鄧寧和克魯格在 1999 年提出；提醒我們保持謙虛、多聽別人的回饋
@存在主義|存在主義是什麼|哲學
簡介=一種哲學思想，認為人生沒有天生注定的意義，人是先存在、再透過自己的選擇決定自己是什麼樣的人，所以要為自己的選擇負責
說明=代表人物有沙特、卡繆、齊克果；沙特的名言是「存在先於本質」
@機器學習|機器學習是什麼,Machine Learning|科技
簡介=人工智慧的一種方法：不是由人一條一條寫規則，而是給電腦大量的資料，讓它自己從資料裡找出規律，用來預測或判斷
說明=像垃圾信件過濾、推薦影片、人臉辨識、語音助理都是用機器學習；深度學習是其中一種用多層神經網路的方法
@量子糾纏|量子糾纏是什麼|科學
簡介=兩個粒子「糾纏」在一起之後，不管離多遠，測量其中一個的狀態，另一個的狀態也會立刻確定，好像彼此相連
說明=愛因斯坦曾稱它是「鬼魅般的超距作用」；它是量子電腦和量子通訊的基礎，但不能用來傳送比光還快的訊息
@共享經濟|共享經濟是什麼|經濟
簡介=把自己閒置的東西或時間，透過網路平台分享給別人使用並收費，例如 Airbnb 分享房間、Uber 分享車子和開車時間、共享單車
說明=好處是讓資源用得更有效率；也有勞工保障、安全和法規管理的問題
@極簡主義|極簡主義是什麼,極簡生活|生活
簡介=一種生活態度：只留下真正需要、真正喜歡的東西，減少多餘的物品和欲望，把時間和精力放在重要的事情上
說明=跟斷捨離很像；重點不是東西越少越好，而是讓自己活得更輕鬆、更自由
@沉沒成本|沉沒成本是什麼,沉沒成本謬誤|經濟
簡介=已經花掉、收不回來的時間、金錢或心力，像已經買了的電影票
說明=「沉沒成本謬誤」是因為捨不得已經付出的，而繼續做不划算的事：電影很難看，卻因為票錢付了硬撐看完。做決定時應該看未來的好處，不是過去花了多少
@碳中和|淨零排放,碳中和是什麼,淨零|科學
簡介=把排放出去的二氧化碳等溫室氣體，用減少排放、種樹、碳捕捉等方式抵銷，讓淨排放量變成零
說明=台灣和很多國家都定了 2050 年淨零排放的目標
@基因編輯|基因編輯是什麼,CRISPR|科學
簡介=像用剪刀和修正液一樣，精準地修改生物 DNA 裡的特定片段；最有名的工具是 CRISPR，發明者在 2020 年得到諾貝爾化學獎
說明=可以用來治療遺傳疾病、改良農作物；但用在人類胚胎上有很大的倫理爭議
@貓有九條命|貓有幾條命,貓總共有幾條命,貓有九條命嗎|常識
簡介=貓當然只有一條命！「貓有九條命」是一種說法，因為貓的平衡感很好、身體柔軟，從高處掉下來常常能翻身用腳著地，看起來命很硬；但從高樓摔下來貓一樣會受重傷，家裡的窗戶要裝紗窗
@鋼琴鍵|鋼琴總共有幾個鍵,鋼琴有幾個鍵,鋼琴幾個鍵|常識
簡介=標準的鋼琴有 88 個鍵：52 個白鍵、36 個黑鍵，音域超過七個八度
@落枕|落枕怎麼辦,脖子落枕,睡醒脖子痛,起床脖子痛,起床脖子好痛,睡醒脖子好痛,早上起來脖子痛,脖子轉不過去|健康常識
簡介=落枕是睡覺姿勢不良或枕頭不合適，讓脖子的肌肉拉傷、抽筋，醒來脖子很痛、轉不動。可以先冰敷（前一兩天），之後熱敷；輕輕、慢慢地活動脖子，不要用力扭或大力按摩；可以吃止痛藥；通常幾天到一週會好。手麻、無力、痛很久要看醫生
@過年紅包|過年紅包給多少,過年紅包要包多少,壓歲錢給多少,過年紅包多少,紅包給爸媽多少,發紅包要注意什麼,紅包要包多少,紅包包多少,發紅包|常識
簡介=台灣過年紅包沒有固定標準，看家裡習慣和自己的收入：給小孩常見 600 到 2,000 元；剛出社會給爸媽可以從 3,600、6,000 開始，有能力再多包；給長輩、阿公阿嬤也常見 2,000 到 6,000。習慣包雙數、避開 4，用新鈔，紅包袋寫上祝福更貼心
@年夜飯|年夜飯吃什麼,年夜飯要吃什麼,除夕吃什麼,年菜有哪些|常識
簡介=台灣年夜飯常見的菜和意思：長年菜（長壽）、魚（年年有餘，習慣不吃完）、雞（起家）、韭菜（長長久久）、蘿蔔糕（好彩頭）、發糕（發財）、佛跳牆、獅子頭（團圓），很多家庭也會吃火鍋「圍爐」，一家人圍著吃
@清明節準備|清明節要準備什麼,掃墓要準備什麼,清明掃墓準備什麼|常識
簡介=清明掃墓一般會準備：鐮刀、掃把、手套等清潔工具（整理墓地雜草）；祭品：水果、糕餅、潤餅、雞鴨魚肉（依家裡習慣）；香、金紙、蠟燭；有些地方會「掛紙」（在墓上壓五色紙）。現在也有很多人改用鮮花、網路祭祖或環保方式，不燒金紙。記得穿輕便的鞋、帶水和防曬
@的得地|的得地怎麼分,的得地的差別,「的」「得」「地」怎麼分,的地得怎麼分|常識
簡介=「的」接名詞：美麗「的」花、我「的」書；「地」接動詞，前面是形容怎麼做：慢慢「地」走、開心「地」笑；「得」放在動詞或形容詞後面，接程度或結果：跑「得」很快、累「得」睡著了。簡單記：名詞前用「的」，動詞前用「地」，動詞後用「得」
@在和再|在和再的差別,再和在的差別,在跟再怎麼分,在再怎麼分|常識
簡介=「在」表示位置或正在進行：我「在」家、他「在」吃飯；「再」表示重複或之後：「再」說一次、吃完「再」走、明天「再」見。簡單記：還沒發生、又一次，用「再」；地點和正在做，用「在」
@因為所以造句|因為所以怎麼造句,用因為所以造句,因為所以造句|常識
簡介=「因為……所以……」前面說原因，後面說結果。例句：「因為今天下大雨，所以運動會延期了。」「因為他每天練習，所以進步得很快。」「因為我昨天熬夜，所以今天上課一直打瞌睡。」
@基本工資|最低工資是多少,基本工資多少,最低工資,時薪最低多少,最低時薪,基本工資是多少|常識
簡介=台灣 2026 年起的基本工資：月薪 29,500 元、時薪 196 元（勞動部每年檢討調整，以最新公告為準）。雇主給的薪水不能低於這個標準
@勞退|勞退是什麼,勞工退休金,勞退新制|經濟
簡介=勞工退休金（勞退新制）：雇主每個月至少要提撥你薪水的 6%，存進你自己的勞退個人專戶，換工作也會跟著你；你也可以自己再提撥最多 6%，這部分可以從當年的所得中扣除、節稅
說明=滿 60 歲可以請領；可以用勞保局的 App 或網站查自己的勞退帳戶有多少錢
@育嬰假|育嬰假可以請多久,育嬰留職停薪,育嬰假多久|常識
簡介=台灣的育嬰留職停薪：孩子滿 3 歲前，爸爸媽媽都可以申請，每個孩子最長 2 年；期間可以領育嬰留職停薪津貼，大約是投保薪資的八成（勞保給六成、政府再加發兩成）。規定常有調整，以勞動部最新公告為準
@產假|產假有幾天,產假幾天,產假多久|常識
簡介=台灣勞基法規定的產假是 8 週（56 天），分娩前後都可以請；工作滿 6 個月以上工資照給，未滿 6 個月減半。懷孕 3 個月以上流產有 4 週產假
@陪產假|陪產假幾天,陪產假有幾天,陪產檢假|常識
簡介=台灣的「陪產檢及陪產假」一共 7 天，工資照給：可以陪配偶產檢，也可以在配偶分娩前後請
@病假|病假一年幾天,病假可以請幾天,病假有薪水嗎|常識
簡介=台灣勞工請假規則：沒有住院的普通傷病假，一年合計不超過 30 天；住院的話兩年內合計不超過一年。一年 30 天以內的病假，工資折半發給
@事假|事假可以請幾天,事假一年幾天,事假有薪水嗎|常識
簡介=台灣勞工請假規則：事假一年不超過 14 天，雇主可以不給工資
@喪假|喪假幾天,喪假有幾天|常識
簡介=台灣勞工請假規則的喪假（工資照給）：父母、養父母、繼父母、配偶過世 8 天；祖父母、子女、配偶的父母 6 天；曾祖父母、兄弟姊妹、配偶的祖父母 3 天
@婚假|婚假幾天,婚假有幾天|常識
簡介=台灣勞工請假規則的婚假是 8 天，工資照給；一般要在結婚前 10 天到結婚後 3 個月內請完，可以跟雇主協調分開請
@國定假日|國定假日有哪些,台灣的國定假日,放假的節日有哪些|常識
簡介=台灣的國定放假日主要有：元旦（1/1）、春節（除夕到初三）、和平紀念日（2/28）、兒童節（4/4）、清明節、勞動節（5/1，勞工放假）、端午節、中秋節、國慶日（10/10）；2025 年通過的《紀念日及節日實施條例》再加上教師節（9/28）、台灣光復節（10/25）、行憲紀念日（12/25）等。實際放假和補假以行政院人事行政總處的行事曆為準
@台灣的最南端和最北端|台灣最南端在哪裡,台灣最北端在哪裡,台灣最東端在哪裡,台灣最南端,台灣最北端,台灣最東端|常識
簡介=台灣本島的最南端是屏東縣恆春鎮的鵝鑾鼻（墾丁國家公園裡，有鵝鑾鼻燈塔）；最北端是新北市石門區的富貴角；最東端是新北市貢寮區的三貂角
@台灣人口最多的城市|台灣人口最多的城市,台灣最多人的城市,台灣哪個城市人最多|常識
簡介=台灣人口最多的城市是新北市，大約 400 萬人；接著是台中市、高雄市、台北市、桃園市和台南市（數字每年會變動，以內政部最新統計為準）
@百岳|台灣有幾座百岳,台灣百岳,百岳是什麼|常識
簡介=「台灣百岳」是登山界選出的 100 座海拔 3,000 公尺以上、各有特色的高山，像玉山、雪山、秀姑巒山、南湖大山；其實台灣 3,000 公尺以上的山峰有兩百多座，百岳是其中最有代表性的 100 座
@珍珠奶茶的由來|珍珠奶茶是哪裡發明的,珍奶是誰發明的,珍珠奶茶的由來,珍奶發源地,珍珠奶茶是哪裡的,珍奶是哪裡的,珍珠奶茶的發源地,珍珠奶茶起源|常識
簡介=珍珠奶茶在 1980 年代發源於台灣，台中的春水堂和台南的翰林茶館都說自己是發明者；後來紅遍全世界，成為台灣最有名的飲料之一
@小籠包有名的店|小籠包哪家最有名,哪裡的小籠包好吃,有名的小籠包|常識
簡介=台灣最有名的小籠包是鼎泰豐，從台北信義路的老店開始，現在在很多國家都有分店，以 18 摺的皮聞名；其他各地也有很多在地老店，想找附近的可以叫我上網查
@臭豆腐為什麼臭|臭豆腐為什麼臭,臭豆腐為什麼這麼臭,臭豆腐怎麼做的|常識
簡介=臭豆腐是把豆腐泡在用蔬菜、筍子、莧菜等發酵做成的「臭滷水」裡，裡面的微生物分解豆腐的蛋白質，產生帶有硫磺味和氨味的物質，所以聞起來很臭；但吃起來外酥內嫩，所以有人說「聞起來臭、吃起來香」
@身分證遺失|身分證不見怎麼辦,身分證遺失,身分證掉了怎麼辦,補辦身分證,身分證掉了,身分證不見了,身分證弄丟了|常識
簡介=身分證不見了：先打內政部 1996 服務專線或到戶政事務所辦理掛失，避免被冒用；再到任一戶政事務所申請補發，帶近 2 年內的照片、印章或簽名、可以證明身分的證件（像健保卡、護照、駕照），繳規費就可以；被偷的話可以先到警察局報案
@駕照換照|駕照怎麼換,駕照要換照嗎,駕照過期,駕照補發|常識
簡介=台灣的普通駕照現在大多不用定期換照，但年滿 75 歲要通過體檢和認知測驗換發（之後每 3 年一次）；駕照遺失、損壞或改名，可以到監理站或上監理服務網申請補換發，帶身分證和照片。職業駕照要定期審驗
@怎麼報警|怎麼報警,報警要打幾號,警察電話|常識
簡介=遇到緊急狀況打 110 報警，說清楚：在哪裡、發生什麼事、有沒有人受傷、對方的特徵；需要救護車或火災打 119。手機沒有 SIM 卡或沒訊號時，可以撥 112 緊急電話。不緊急的事也可以直接到附近的派出所
@法律諮詢|法律問題要問誰,免費法律諮詢,哪裡可以問法律問題,法律扶助|常識
簡介=有法律問題可以：打法律扶助基金會（法扶）的專線 412-8518（手機加 02），經濟有困難的人可以申請律師協助；各縣市政府、地方法院、律師公會常有免費法律諮詢；鄰里糾紛可以到鄉鎮市區公所的調解委員會免費調解
@低收入戶申請|怎麼申請低收入戶,低收入戶怎麼申請,申請低收入戶,中低收入戶|常識
簡介=低收入戶和中低收入戶，要向戶籍所在地的鄉鎮市區公所申請：家庭總收入平均分給每個人，每月低於當地的最低生活費標準，而且家庭的存款、房地產也不能超過一定金額。帶身分證、戶口名簿和相關證明，也可以先打 1957 福利諮詢專線問
@學測|學測是什麼,學科能力測驗,大學學測|常識
簡介=學測是「大學學科能力測驗」，每年 1 月舉行，高三上學期考，科目有國文、英文、數學 A 或 B、社會、自然；成績主要用在繁星推薦和個人申請入學
@分科測驗|分科測驗是什麼,分科測驗,指考是什麼,指考|常識
簡介=分科測驗是 2022 年起取代「指考」的考試，每年 7 月舉行，考數學甲、物理、化學、生物、歷史、地理、公民與社會；成績用在大學的分發入學
@會考|會考是什麼,國中會考,國中教育會考|常識
簡介=會考是「國中教育會考」，國三的 5 月舉行，考國文、英文（含聽力）、數學、社會、自然和寫作測驗，成績用來申請高中職的免試入學
@大學申請|大學怎麼申請,升大學的管道,怎麼上大學,大學入學管道|常識
簡介=台灣上大學主要有三種管道：繁星推薦（看高中在校成績和學測）、個人申請（學測成績＋學習歷程檔案＋面試等）、分發入學（看分科測驗成績填志願）；另外還有特殊選才。每年的規定以大學招生委員會聯合會公告為準
@開銀行帳戶|怎麼開銀行帳戶,銀行開戶,怎麼開戶,開戶要帶什麼|常識
簡介=開銀行帳戶一般要本人帶身分證、第二證件（像健保卡、駕照）到銀行臨櫃辦理，有些銀行要印章和一點開戶金；未成年要法定代理人陪同。現在也可以在網路銀行或純網銀線上開「數位帳戶」，但轉帳額度可能比較低
@信用卡申請|信用卡怎麼申請,申請信用卡,辦信用卡|常識
簡介=申請信用卡要年滿 18 歲，準備身分證、第二證件和財力證明（薪資單、扣繳憑單或存款證明），可以上銀行網站或到臨櫃申請；學生通常額度比較低。選卡時看回饋、年費和自己常用的地方，記得每月全額繳清
@股票開戶|股票怎麼開戶,證券開戶,怎麼開證券戶,買股票要開戶,股票怎麼買,怎麼買股票,買股票,買股票要怎麼開始,想買股票,股票要怎麼開始買|常識
簡介=買台股要開兩個帳戶：證券商的「證券帳戶」和銀行的「交割帳戶」（用來扣款、收錢）。年滿 18 歲帶身分證和第二證件到券商臨櫃，或用券商 App 線上開戶，通常幾天內就好；開好後就能用 App 下單，也可以選擇定期定額買 ETF
@0050|0050是什麼,元大台灣50,台灣50|經濟
簡介=「元大台灣 50」ETF，2003 年上市，追蹤台灣市值最大的 50 家公司，台積電佔了很大的比例；買一張 0050 就等於分散投資這 50 家公司，是很多人長期投資台股的入門選擇
說明=要注意：它還是會跟著台股漲跌，短期可能虧損；也可以零股或定期定額買
@定存|定存是什麼,定期存款,定存利率|經濟
簡介=定期存款，把錢放在銀行一段固定時間（從 1 個月到 3 年都有），利率比活期存款高一點；提前解約通常會少拿一些利息（大多打八折）。適合放短期內不會用到、又不想冒險的錢
@為什麼會流眼淚|為什麼會流眼淚,為什麼會哭,人為什麼會流淚,為什麼哭會流眼淚|常識
簡介=眼淚有三種：基礎淚一直在分泌，保持眼睛濕潤；反射淚是有灰塵、洋蔥的刺激時，把東西沖掉；情緒淚是難過、感動、太開心時流的，科學家認為它能幫助舒緩情緒，也讓別人知道你需要安慰。所以想哭的時候哭一哭，其實是身體在照顧自己
@影子|為什麼會有影子,影子是怎麼來的,影子為什麼會變長|常識
簡介=光是直直前進的，被不透光的東西擋住，後面光照不到的地方就變暗，那就是影子。太陽越低（早上和傍晚），光斜斜地照，影子就越長；中午太陽最高，影子最短
@變色龍|變色龍為什麼會變色,為什麼變色龍會變色,避役|動物
簡介=變色龍是會改變皮膚顏色的蜥蜴，大多住在非洲和馬達加斯加
因:變色/會變色/改變顏色=變色龍的皮膚裡有一層含有奈米晶體的細胞，放鬆或繃緊時晶體的間距改變，反射出來的光的顏色就不一樣；牠變色主要是為了表達情緒、溝通（吸引異性、警告對手）和調節體溫，偽裝反而是次要的
@化石|為什麼會有化石,化石是怎麼形成的,化石怎麼來的|常識
簡介=生物死後很快被泥沙埋起來，隔絕空氣、不容易腐爛；經過幾千年到幾億年，骨頭、貝殼這些硬的部分慢慢被周圍水裡的礦物質取代，變成像石頭一樣的東西，就是化石。腳印、蛋、樹葉的痕跡也可能保存下來
@為什麼會長高|為什麼會長高,人為什麼會長高,怎麼長高,長高的原因|常識
簡介=小時候骨頭兩端有「生長板」（骨骺板），會一直製造新的骨頭讓骨頭變長，所以人會長高；青春期荷爾蒙增加，長得特別快，大約在十幾歲後期生長板閉合，就不再長高了。身高主要看遺傳，但睡飽、營養（蛋白質、鈣）和運動也有幫助
@四季冷熱|為什麼夏天比較熱,為什麼冬天比較冷,夏天為什麼熱,冬天為什麼冷,為什麼會有四季,四季是怎麼形成的,四季怎麼形成,為什麼有春夏秋冬,四季的成因|常識
簡介=因為地球的自轉軸是斜的（大約 23.5 度）：夏天時我們這半邊地球朝向太陽，陽光比較直射、白天比較長，吸收的熱量多，所以熱；冬天陽光斜斜地照、白天短，所以冷。跟地球離太陽的遠近關係不大，北半球的冬天時地球反而離太陽比較近
@船為什麼不會沉|為什麼船不會沉,船為什麼浮在水上,鐵做的船為什麼不會沉|常識
簡介=因為浮力：船的形狀中間是空的，排開了很多水，水往上推的浮力等於被排開的水的重量；只要船排開的水比船本身重，船就能浮起來。這叫阿基米德原理，所以很重的鐵船也能浮在海上
@冰融化|為什麼冰會融化,冰為什麼會融化,冰塊為什麼會融化|常識
簡介=冰是水分子排得整整齊齊的固體；周圍比 0°C 溫暖時，冰吸收熱量，分子動得越來越快，掙脫固定的位置，就變回能流動的水
@水沸騰|為什麼水會沸騰,水為什麼會滾,水沸騰的原因|常識
簡介=水加熱時分子越動越快，到了大約 100°C（一大氣壓），水裡面也開始變成水蒸氣，形成很多氣泡往上冒，就是沸騰；高山上氣壓低，不到 100°C 就會滾了
@回音|為什麼有回音,回音是怎麼來的,為什麼會有回音|常識
簡介=聲音是一種波，碰到山壁、大樓牆壁這種又大又硬的表面會反彈回來；如果反彈回來的聲音比原本的聲音晚大約 0.1 秒以上到達耳朵，我們就會聽到兩次，那就是回音。蝙蝠和海豚就是用回音來找路、找食物
@雞下蛋|為什麼雞會下蛋,母雞為什麼每天下蛋,雞為什麼一直下蛋,為什麼雞會生蛋,雞為什麼會生蛋,雞怎麼生蛋|常識
簡介=鳥類都是靠下蛋繁殖的；人類飼養的蛋雞經過長期選種，加上光照和營養充足，幾乎每天都會排卵、下一顆蛋，就算沒有公雞也一樣（所以超市的雞蛋大多是孵不出小雞的「無精蛋」）
@螢火蟲|螢火蟲為什麼會發光,為什麼螢火蟲會發光,螢火蟲|動物
簡介=會發光的甲蟲，台灣大約 3 到 5 月是賞螢季節
因:發光/會發光/亮=螢火蟲腹部的發光器裡有螢光素，在螢光素酶和氧氣的作用下產生化學反應發出冷光，幾乎不會發熱；牠們用閃光的節奏和同伴溝通、吸引另一半，每種螢火蟲的閃法都不一樣
@向日葵|太陽花|植物
簡介=菊科的植物，花很大、像一個小太陽，種子就是葵花子，可以吃也可以榨油
因:向著太陽/向太陽/跟著太陽/朝著太陽/向陽/朝太陽=還沒開花的小向日葵，莖背光那一側長得比較快，讓花苞白天跟著太陽從東轉到西，晚上再慢慢轉回東邊，這和它體內的生理時鐘有關；等到花完全開了，大多就固定朝向東方不再轉，因為早上曬到太陽、花比較暖，比較能吸引蜜蜂來授粉
@火星上的水|火星上有水嗎,火星有水嗎,火星有沒有水,火星上有沒有水|常識
簡介=有，但大多是冰：火星的南北極有冰帽（水冰加上乾冰），地底下也發現了大量的冰。因為火星很冷、大氣很稀薄，液態水很難在表面穩定存在；不過探測車發現古代的河床和湖泊沉積物，代表很久以前火星表面曾經有流動的水
@珍珠奶茶的熱量|珍珠奶茶熱量多少,珍珠奶茶熱量,珍奶熱量,珍奶幾大卡,珍珠奶茶幾大卡,珍奶熱量多少,喝珍奶會胖嗎|常識
簡介=一杯大杯（700 c.c.）全糖珍珠奶茶大約 600 到 700 大卡，差不多是一個便當的熱量；珍珠本身就大約 200 到 300 大卡。想少一點熱量，可以改成微糖或無糖、珍珠減半、用鮮奶茶代替奶精，或改點中杯
@牛肉麵|紅燒牛肉麵|食物
簡介=台灣很有代表性的麵食。紅燒牛肉麵一般認為是二戰後在台灣發展出來的，常見的說法是跟眷村、岡山的四川籍老兵有關，用豆瓣醬燉牛肉；中國的蘭州牛肉麵是清燉的，風格不一樣
由來=常見的說法是二戰後，來自四川的老兵在高雄岡山用豆瓣醬做出紅燒牛肉，後來在台北等地流行起來；台北每年還有牛肉麵節
@深蹲|深蹲|活動
簡介=蹲下再站起來的肌力訓練，練大腿、屁股和核心
好處=練到大腿、臀部這些全身最大的肌肉，提高基礎代謝；強化膝蓋和髖關節周圍的肌肉，讓上下樓梯、提重物更輕鬆；改善平衡感，老了比較不容易跌倒；不用器材，在家就能做
@伏地挺身|伏地挺身|活動
簡介=用手撐地、推起身體的肌力訓練，練胸、肩膀、手臂後側和核心
好處=不用器材、在哪裡都能做；練上半身的力氣和核心穩定；可以從跪姿或斜面開始，程度慢慢進步
@游泳減肥|游泳可以減肥嗎,游泳能減肥嗎,游泳會瘦嗎,游泳減肥有效嗎,游泳可以瘦嗎|常識
簡介=可以。游泳是全身的有氧運動，以中等速度游 30 分鐘大約消耗 200 到 300 大卡（自由式、蝶式更多），而且對膝蓋負擔小，很適合體重比較重的人。不過游完常常很餓，吃太多就抵消了；減肥還是要配合飲食控制，一週游 3 次以上、每次 30 分鐘以上比較看得到效果
@循環利息|信用卡循環利息,循環利率,什麼是循環利息,循環信用,循環利息是什麼|經濟
簡介=信用卡帳單如果只繳「最低應繳金額」，沒繳清的部分銀行會借給你、算利息，就是循環利息（循環信用）。台灣的循環利率上限是年利率 15%，比一般貸款高很多，而且利息會一直滾，所以帳單最好每個月全額繳清
@日文好不好學|日文好學嗎,日文難嗎,日文難不難,學日文難嗎,日語好學嗎,日語難嗎,日文好學,日語好學,學日文要多久,日文要學多久,學日文要學多久,日文學多久,日文要學多久才會|常識
簡介=對會中文的人來說，日文入門算比較友善：很多漢字看得懂，讀文章有優勢。比較難的是文法（動詞在句尾、各種變化）、敬語，還有同一個漢字有好幾種念法；聽力和口說也要多練。一般說法是，從零開始穩定學習，大約一年左右可以到日常對話（日檢 N3 附近），但每個人的時間和方法不同
@為什麼會抽筋|為什麼會抽筋,抽筋的原因,為什麼腳會抽筋,為什麼半夜會抽筋,腳為什麼會抽筋,抽筋是什麼原因|健康常識
簡介=抽筋是肌肉突然不自主地強烈收縮。常見的原因有：運動太久、肌肉疲勞；流很多汗、喝水太少，電解質（鈉、鉀、鎂、鈣）不夠；天氣冷或睡覺時腳底板伸直、小腿肌肉縮著；久站、久坐；懷孕、年紀大也比較容易發生。偶爾抽筋多半沒關係，但如果常常抽筋、腳又腫又痛或無力，要去看醫生
@為什麼會頭暈|為什麼會頭暈,頭暈的原因,頭暈是什麼原因,為什麼常常頭暈,為什麼一直頭暈,為什麼站起來會頭暈|健康常識
簡介=頭暈的原因很多，常見的有：蹲久或躺著突然站起來，血壓一時跟不上（姿勢性低血壓）；沒吃飯血糖低、喝水太少脫水；睡不夠、太累；貧血；內耳的平衡出問題（像耳石脫落，轉頭時天旋地轉）；暈車暈船；有些藥物的副作用。偶爾一下多半先坐下或躺下休息、喝點水；如果頭暈很嚴重、一直反覆，或伴隨講話不清楚、手腳無力、臉歪、胸痛、昏倒，要馬上就醫
@一天喝幾杯咖啡|一天喝幾杯咖啡,一天可以喝幾杯咖啡,咖啡一天喝幾杯,一天喝幾杯咖啡比較好,咖啡一天可以喝多少,咖啡喝多少比較好,一天喝多少咖啡,咖啡一天可以喝幾杯,咖啡喝太多會怎樣,咖啡因一天上限,咖啡一天喝多少|健康常識
簡介=健康的成年人一天咖啡因建議不超過 300 到 400 毫克，一杯中杯美式或拿鐵大約 100 到 200 毫克，所以大約 2 到 3 杯以內；孕婦一天不要超過 200 毫克（大約 1 杯）。下午之後少喝，比較不會影響睡眠；喝了會心悸、手抖、睡不著的人要再減量
@喝牛奶的時間|牛奶什麼時候喝比較好,牛奶什麼時候喝,什麼時候喝牛奶,牛奶早上喝還是晚上喝,睡前可以喝牛奶嗎,睡前喝牛奶|健康常識
簡介=牛奶什麼時候喝都可以，沒有絕對最好的時間：早餐配牛奶可以補充蛋白質和鈣；運動後喝有助肌肉恢復；睡前喝一杯溫牛奶也可以，有些人覺得比較好睡。乳糖不耐的人空腹喝容易脹氣、拉肚子，可以配著食物喝、少量多次，或改喝無乳糖牛奶、優格
@吃香蕉的時間|香蕉什麼時候吃最好,香蕉什麼時候吃,什麼時候吃香蕉,香蕉早上吃還是晚上吃,空腹可以吃香蕉嗎,空腹吃香蕉|健康常識
簡介=香蕉什麼時候吃都可以：早餐吃很方便，運動前後吃可以補充能量和鉀。一般健康的人空腹吃香蕉也沒問題，「空腹吃香蕉會鎂中毒」是謠言；比較要注意的是腎臟病的人要控制鉀，血糖高的人一次不要吃太多、選不要太熟的
@吃太鹹|吃太鹹有什麼影響,吃太鹹會怎樣,吃太鹹的壞處,鹽吃太多,吃太多鹽,鈉攝取太多,吃太鹹對身體不好嗎|健康常識
簡介=鹽裡的鈉吃太多，會讓身體留住水分，血壓升高，長期下來增加中風、心臟病和腎臟病的風險，也容易水腫、口渴。建議一天的鈉不要超過 2,400 毫克（大約 6 公克鹽，一小茶匙多一點）；加工食品、泡麵、湯、醬料是鈉的大宗，湯少喝一點、醬料沾少一點、多吃新鮮的食物就能減很多
@螞蟻怎麼找食物|螞蟻怎麼找到食物,螞蟻怎麼找食物,螞蟻如何找到食物,螞蟻怎麼知道哪裡有食物,螞蟻為什麼找得到食物|常識
簡介=靠氣味和費洛蒙：負責找食物的工蟻先四處亂走，用觸角聞味道；找到食物後，回巢的路上沿路留下費洛蒙，其他螞蟻就循著這條氣味路線走過去，搬回來的螞蟻再補上氣味，路線越走越明顯，所以螞蟻會排成一列。食物搬完了，氣味會慢慢散掉，大家就不再走那條路
@廢電池|廢電池要丟哪裡,廢電池怎麼丟,舊電池丟哪裡,電池要怎麼丟,沒電的電池怎麼丟,電池丟哪裡,廢電池回收|常識
簡介=廢電池不要丟一般垃圾，裡面有重金屬，鋰電池壓到還可能起火。可以拿到便利商店、超市、量販店、3C 賣場的電池回收筒，或交給資源回收車；鋰電池、行動電源最好先用膠帶把正負極貼起來再回收。在台灣，廢乾電池還可以拿到便利商店換購物金或點數（依當時的活動）
@過期的藥怎麼丟|過期的藥怎麼丟,過期藥怎麼丟,過期的藥要丟哪裡,吃不完的藥怎麼丟,廢棄藥品怎麼處理,過期藥品|健康常識
簡介=在台灣，大部分一般的藥可以照「廢棄藥品處理七步驟」當一般垃圾丟：把藥丸從包裝裡拿出來，集中在夾鏈袋；藥水倒進夾鏈袋；加入用過的茶葉渣或咖啡渣混在一起；把夾鏈袋封好，跟一般垃圾一起丟；藥袋、藥盒可以資源回收。抗生素、抗癌藥、荷爾蒙、管制藥品和針頭這些比較特別的，要拿回藥局或醫院的回收站。不要直接倒進馬桶或水槽
@冷氣清洗|冷氣多久要清一次,冷氣多久清一次,冷氣濾網多久清,冷氣要多久洗一次,冷氣濾網多久洗一次,冷氣多久要洗|常識
簡介=冷氣的濾網大約每 2 週到 1 個月清一次（拆下來用清水沖、陰乾再裝回去），常開的話更勤一點；整台冷氣的內部（散熱片、風扇、出風口）建議每年請專業清洗一次，最好在夏天開始用之前。濾網髒了會更耗電、冷氣不冷，還會有霉味、讓過敏變嚴重
@牙刷多久換|牙刷多久換一次,牙刷要多久換,多久換一次牙刷,牙刷多久要換,電動牙刷刷頭多久換|健康常識
簡介=牙刷大約每 3 個月換一次；如果刷毛開花、變形，不到 3 個月也要換；感冒或生病好了之後最好也換一支。電動牙刷的刷頭也一樣大約 3 個月換一次
@枕頭多久換|枕頭多久換一次,枕頭要多久換,多久換一次枕頭,枕頭多久要換|常識
簡介=一般的枕頭大約 1 到 2 年換一次，乳膠、記憶枕可以用 2 到 3 年。如果對折後彈不回來、塌掉、有異味或黃斑，或睡醒常常脖子痠，就該換了；枕頭套最好每週洗一次
@床單多久洗|床單多久洗一次,床單要多久洗,多久洗一次床單,床單被套多久洗,床單多久換一次|常識
簡介=床單和枕頭套大約每 1 到 2 週洗一次；容易流汗、有過敏、和寵物一起睡的人最好每週洗。用 60°C 以上的熱水洗或烘乾，能減少塵蟎；被子和枕頭本身也可以每隔幾個月曬一曬或清洗
@毛巾多久換|毛巾多久換一次,毛巾要多久換,毛巾多久洗一次,浴巾多久洗一次,多久換一次毛巾|常識
簡介=毛巾每次用完要攤開晾乾，大約用 3 次就洗一次，浴巾一週洗 1 到 2 次；毛巾本身大約 3 個月到半年換新，如果變硬、洗完還有臭味或發黑，就該換了。浴室比較潮濕，毛巾最好拿到通風的地方晾
@剩飯可以放多久|剩飯可以放多久,白飯可以放多久,飯可以放多久,隔夜飯可以吃嗎,剩飯放冰箱可以放多久,飯放冰箱可以放幾天|健康常識
簡介=煮好的飯最好在 2 小時內放涼、蓋好放冰箱：冷藏大約可以放 3 到 4 天，冷凍可以放 1 個月左右，吃之前要徹底加熱。不要在室溫放太久，米飯容易長仙人掌桿菌（蠟樣芽孢桿菌），它產生的毒素加熱也破壞不了，會讓人上吐下瀉；聞起來酸酸的或黏黏的就丟掉
@水煮蛋要煮多久|水煮蛋要煮幾分鐘,水煮蛋煮幾分鐘,水煮蛋要煮多久,半熟蛋要煮幾分鐘,溏心蛋煮幾分鐘,全熟蛋要煮幾分鐘,雞蛋要煮幾分鐘,煮蛋要幾分鐘,煮蛋要多久,煮蛋要煮多久,煮水煮蛋要多久,白煮蛋要煮多久,雞蛋要煮多久,雞蛋煮多久,雞蛋要煮幾分,煮雞蛋要多久|常識
簡介=大約這樣抓（水滾後放入從冰箱拿出來的中型蛋）：6 到 7 分鐘是溏心蛋，蛋黃還會流；8 到 9 分鐘是半熟，蛋黃中間軟軟的；10 到 12 分鐘是全熟。煮好馬上泡冰水，比較好剝，也不會繼續熟下去；蛋比較大或從室溫下鍋，時間要稍微調整
@霧|起霧,大霧,濃霧|自然
簡介=貼近地面的雲，由很多很小的水滴飄在空中形成，會讓能見度變很低
因:起霧/會起霧/有霧/霧=空氣裡的水氣遇冷凝結成很小的水滴，飄在貼近地面的地方就是霧。冬天和春天的清晨最常見：晚上地面散熱很快，貼近地面的空氣變冷，水氣就凝結成霧（輻射霧）；暖濕的空氣吹到比較冷的地面或海面，也會起霧（平流霧，像金門、馬祖春天常見的霧）。太陽出來地面變暖，霧就慢慢散了
@人不吃不喝能撐多久|人可以幾天不吃東西,人可以幾天不喝水,幾天不吃東西會死,幾天不喝水會死,人不吃東西可以活多久,人不喝水可以活多久,人多久不喝水會死,人多久不吃東西會死|健康常識
簡介=水比食物重要得多：完全不喝水，一般大約只能撐 3 天左右（看天氣和活動量，炎熱、流汗多時更短）；有喝水但不吃東西，可以撐好幾週，大約 3 週到 2 個月，看身體的脂肪和健康狀況。不過不吃東西幾天身體就會開始出問題，千萬不要拿自己試
@血型|ABO血型,血型有幾種,血型有哪些|科學
簡介=依紅血球表面的抗原來分類血液的方法，最常見的是 ABO 血型：A、B、AB、O 四種；另外還有 Rh 血型（陽性、陰性），台灣大部分人是 Rh 陽性，Rh 陰性的人很少，大約千分之三
說明=台灣人最多的是 O 型（大約四成多），其次是 A 型、B 型，AB 型最少；「血型決定個性」沒有科學根據
@輸血血型|O型血可以輸給誰,O型可以輸給誰,O型血可以輸給哪些血型,AB型可以接受什麼血,什麼血型可以輸給,萬能捐血者,萬能受血者,輸血血型,誰可以輸血給我|健康常識
簡介=只看 ABO 的話：O 型的紅血球可以輸給 A、B、AB、O 型（所以叫萬能捐血者），但 O 型只能接受 O 型；AB 型可以接受 A、B、AB、O 型的紅血球（萬能受血者）；A 型可以接受 A 和 O，B 型可以接受 B 和 O。實際上醫院會盡量輸同血型的血，還要看 Rh 血型、做交叉配合試驗，確定安全才輸
@畢氏定理|畢達哥拉斯定理,勾股定理|科學
簡介=直角三角形兩條直角邊的平方加起來，等於斜邊的平方：a² + b² = c²。最有名的例子是 3、4、5：3² + 4² = 9 + 16 = 25 = 5²
說明=中國古代叫「勾股定理」，有「勾三股四弦五」的說法；它可以用來算距離，例如知道兩邊就能算出第三邊
@函數|函式|科學
簡介=一種對應關係：每丟進一個輸入，就會得到唯一一個輸出，常寫成 y = f(x)。例如 f(x) = 2x + 1，x 是 3 時，y 就是 7
說明=生活裡的例子：計程車資跟著里程變、電費跟著用電量變；寫程式時的「函式」也是同樣的概念，把一段步驟包起來，給它輸入就回傳結果
@平方根|開根號,根號|科學
簡介=「自己乘自己會等於某個數」的數。例如 3 × 3 = 9，所以 9 的平方根是 3（還有 -3），寫成 √9 = 3
說明=√2 大約是 1.414，√3 大約是 1.732；在實數裡，負數沒有平方根
@機率|概率|科學
簡介=一件事情發生的可能性有多大，用 0 到 1（或 0% 到 100%）表示：0 是不可能，1 是一定會發生。例如丟銅板出現正面的機率是 1/2，擲骰子擲出 6 的機率是 1/6
說明=算法是「想要的結果有幾種」除以「所有可能的結果有幾種」（每種結果機會一樣時）；「這次沒中，下次比較容易中」是常見的誤會，每次丟銅板都是獨立的
@化學反應|化學變化|科學
簡介=物質變成另一種新物質的過程：原子重新排列組合，例如鐵生鏽、木頭燃燒、蛋煮熟、食物被消化
說明=跟「物理變化」不一樣：冰融化成水只是樣子改變，還是水，不算化學反應；常見的跡象有變色、冒泡產生氣體、發光發熱、產生沉澱
@演化|演化論,進化論,天擇,物競天擇,進化|科學
簡介=生物的族群經過很多世代，遺傳特徵慢慢改變的過程。達爾文提出「天擇」：比較適應環境的個體比較容易活下來、留下後代，有利的特徵就一代一代累積下來
說明=人不是從現在的猴子變來的，而是和黑猩猩有共同的祖先，大約六七百萬年前分開，各自演化
@棒球規則|棒球怎麼玩,棒球規則,棒球怎麼打,棒球的規則,看不懂棒球,棒球比賽規則|常識
簡介=兩隊各 9 個人，輪流進攻和防守，一場比賽打 9 局。進攻的打者在本壘打擊，打出去後要跑壘，依序踩過一壘、二壘、三壘再回到本壘就得 1 分；防守方讓 3 個人出局（三振、被接殺、被刺殺或封殺）就攻守交換
說明=三個好球是三振出局，四個壞球打者可以保送上一壘；球飛出全壘打牆是全壘打，壘上所有跑者都能回來得分。9 局打完分數高的贏，平手就打延長賽
@太極拳|太極|活動
簡介=中國傳統武術，動作緩慢、連貫、圓順，配合呼吸，現在很多人當成養生運動
好處=改善平衡感、預防跌倒，對膝蓋負擔小，很適合長輩；也能放鬆心情、增加柔軟度和腿部肌力
@瑜珈|瑜伽,yoga,Yoga|活動
簡介=源自印度，結合身體姿勢、呼吸和放鬆冥想的運動
好處=增加柔軟度和肌力（特別是核心），改善姿勢和腰痠背痛，放鬆壓力、幫助睡眠；強度可以很溫和也可以很累，初學者從基礎課開始，不要勉強拉筋
@捷運|MRT,地鐵|科技
簡介=在城市裡行駛的大眾運輸電聯車，大多走地下或高架，班次密、不會塞車。台灣有台北捷運、新北捷運、桃園機場捷運、台中捷運和高雄捷運
說明=大部分可以刷悠遊卡、一卡通等電子票證；車廂和付費區裡不能吃東西、喝飲料、嚼口香糖
@匯率|匯率是什麼,什麼是匯率|經濟
簡介=兩種貨幣互相換算的比例，例如 1 美元可以換多少新台幣，每天都會變動
說明=台幣升值，代表同樣的台幣能換到更多外幣，出國玩、買進口貨比較划算；台幣貶值則對出口的公司有利。實際換匯時銀行還有買價、賣價的差別
@健保|全民健保,全民健康保險,健保是什麼|經濟
簡介=台灣的全民健康保險，1995 年開始，所有國民和在台灣住滿一定時間的外籍人士都要加入，每個月繳保費；看病、住院、拿藥時只要付部分負擔，大部分的費用由健保支付
說明=保費依薪水計算，有工作的人由公司、自己和政府一起分擔；看病記得帶健保卡
@台中美食|台中有什麼好吃的,台中美食,台中必吃,台中有什麼好吃,台中好吃的|常識
簡介=台中可以吃這些：太陽餅（台中的代表伴手禮）、珍珠奶茶（一般認為發源於台中）、大麵羹、東海大學附近的雞爪凍、第二市場的老店小吃、逢甲夜市和一中街的各種小吃，還有宮原眼科的冰淇淋和伴手禮
說明=逢甲夜市是台灣很大的夜市之一，晚上去最熱鬧
@蒙娜麗莎|蒙娜麗莎的微笑,蒙娜麗莎畫像,Mona Lisa|藝術
簡介=義大利文藝復興時期的畫家達文西畫的肖像畫，大約畫於 1503 到 1519 年，以神秘的微笑聞名，是世界上最有名的畫之一
位置=法國巴黎的羅浮宮，放在防彈玻璃後面，每天都有很多人排隊看
說明=畫本身不大，大約 77 × 53 公分；1911 年曾經被偷，兩年後才找回來
@靜夜思|床前明月光,床前明月光是誰寫的,舉頭望明月,低頭思故鄉,靜夜思是誰寫的|常識
簡介=「床前明月光，疑是地上霜。舉頭望明月，低頭思故鄉。」是唐朝詩人李白的〈靜夜思〉，寫在異鄉看到月光，想念家鄉的心情，是最多人會背的唐詩之一
@正常體溫|正常體溫幾度,正常體溫是幾度,體溫幾度正常,體溫多少正常,正常的體溫,正常體溫多少|健康常識
簡介=人的正常體溫大約在 36°C 到 37.5°C 之間，一天之中會小小變動：清晨最低、傍晚比較高；量的部位也有差，耳溫、口溫比較接近身體內部的溫度，腋溫通常比較低一點。剛運動完、洗完澡、吃完熱的東西，體溫會暫時偏高，休息一下再量比較準
@每天蛋白質|一天要吃多少蛋白質,一天需要多少蛋白質,蛋白質一天要吃多少,每天要吃多少蛋白質,蛋白質要吃多少,一天蛋白質要多少|健康常識
簡介=一般健康的成年人，每天大約每公斤體重吃 0.8 到 1.2 公克蛋白質，例如 60 公斤大約 50 到 70 公克；常運動、想增肌的人可以到每公斤 1.2 到 1.6 公克，長輩也建議多吃一點。一顆蛋大約 7 公克、一杯 240 毫升的牛奶或豆漿大約 7 到 8 公克、一個手掌大的肉或魚大約 20 到 25 公克。有腎臟病的人要依醫生建議
@維他命D|維生素D,維他命D怎麼補充,維生素D怎麼補充,怎麼補充維他命D,怎麼補充維生素D,維他命D要怎麼補|健康常識
簡介=維他命 D 主要靠曬太陽讓皮膚自己製造：一週幾次、每次大約 10 到 20 分鐘，讓手臂、腿曬到太陽（避開正中午、不要曬傷）。食物裡比較多的有鮭魚、鯖魚、秋刀魚這類多油的魚、蛋黃、曬過太陽的香菇（乾香菇）、強化維他命 D 的牛奶。很少曬太陽、長輩或檢查出缺乏的人，可以請醫生建議要不要吃補充劑，不要自己吃太多
@久坐|久坐對身體不好嗎,久坐的壞處,久坐有什麼影響,坐太久對身體不好,一直坐著對身體不好嗎,久坐傷身,坐太久會怎樣|健康常識
簡介=對，久坐不動對身體不好：會讓血液循環變差、腿水腫，增加肥胖、糖尿病、心血管疾病的風險，也容易腰痠背痛、肩頸僵硬。最簡單的方法是每坐 30 到 60 分鐘就站起來動一動 2 到 3 分鐘：倒杯水、伸展一下、走一走；講電話時站著講，能走樓梯就走樓梯，下班後再找時間運動
@竹子是草還是樹|竹子是草還是樹,竹子是樹嗎,竹子是草嗎,竹子是不是樹,竹子是不是草|常識
簡介=竹子其實是「草」：它是禾本科的植物，跟稻子、小麥是親戚，只是長得特別高大。竹子的莖中空、有一節一節，也不像樹一樣每年長出年輪、越長越粗；有些竹子一天可以長將近 1 公尺，是長得最快的植物之一
@午睡多久|午睡睡多久最好,午睡要睡多久,午睡多久比較好,午覺睡多久,午睡睡多久,午睡要睡多久比較好|健康常識
簡介=午睡大約 10 到 30 分鐘最好，最好不要超過 30 分鐘，不然容易進入深層睡眠，醒來反而更昏沉；時間最好在下午 1 點到 3 點之間，太晚睡或睡太久會影響晚上的睡眠。趴著睡的話，墊個枕頭，避免壓到手和眼睛
@鯊魚睡覺|鯊魚會睡覺嗎,鯊魚怎麼睡覺,鯊魚睡覺嗎,鯊魚會不會睡覺|常識
簡介=鯊魚會休息，但不像人一樣閉上眼睛熟睡。有些鯊魚（像護士鯊）可以停在海底休息，靠張嘴讓水流過鰓；有些鯊魚（像大白鯊）要一直游，水才會流過鰓，研究認為牠們會進入一種一邊慢慢游、一邊休息的狀態
@魚睡覺|魚會睡覺嗎,魚怎麼睡覺,魚睡覺嗎,魚會不會睡覺,魚會睡覺|常識
簡介=會，魚也需要休息。因為魚沒有眼皮，所以是睜著眼睛「睡」：很多魚晚上會停在水草、石頭縫或缸底不太動，反應變慢、新陳代謝變低；有些鸚哥魚還會吐黏液包住自己，像睡袋一樣保護自己
@長頸鹿睡覺|長頸鹿怎麼睡覺,長頸鹿睡覺,長頸鹿會躺著睡嗎,長頸鹿睡多久,長頸鹿一天睡多久|常識
簡介=野外的長頸鹿一天只睡大約 30 分鐘到 2 小時，而且分成很多次，每次只睡幾分鐘；大多站著打盹，偶爾會趴下，把長脖子彎過來、頭靠在屁股上睡。因為身體很高大，躺下再站起來要花時間，遇到獅子不容易馬上逃跑，所以睡得很少
@袋鼠生小孩|袋鼠怎麼生小孩,袋鼠怎麼生寶寶,袋鼠寶寶怎麼長大,袋鼠的育兒袋,袋鼠為什麼有袋子|常識
簡介=袋鼠是有袋類動物：懷孕大約一個月就生下寶寶，剛出生的寶寶只有大約 2 公分，像一顆豆子，眼睛還沒張開；牠會自己爬進媽媽肚子上的育兒袋，含住乳頭喝奶，在袋子裡長大，大約 6 個月才探出頭，8 個月左右才會離開袋子
@烏鴉聰明|烏鴉很聰明嗎,烏鴉聰明嗎,烏鴉有多聰明,烏鴉為什麼那麼聰明|常識
簡介=很聰明，烏鴉是最聰明的鳥之一：會使用工具（新喀里多尼亞烏鴉會把樹枝彎成鉤子掏蟲），能記住人的臉，對欺負過牠的人會「記仇」，還會把堅果丟在馬路上讓車子壓開，等紅燈時再去撿。研究認為牠們解決問題的能力可以跟大型猿類相比
@蜂蜜怎麼來的|蜜蜂怎麼做蜂蜜,蜂蜜怎麼來的,蜂蜜是怎麼做的,蜜蜂怎麼釀蜜,蜂蜜是怎麼來的|常識
簡介=工蜂吸了花蜜存在胃裡（蜜胃），帶回蜂巢交給其他蜜蜂，經過體內的酵素把花蜜裡的蔗糖分解成葡萄糖和果糖；接著把花蜜放進蜂巢的格子裡，蜜蜂一起拍翅膀搧風讓水分蒸發，水分降到大約 18% 到 20% 就成了濃稠的蜂蜜，最後用蜂蠟封起來保存。一隻工蜂一輩子大約只能做出十二分之一茶匙的蜂蜜
@台灣三千公尺高山|台灣有幾座山超過3000公尺,台灣有幾座3000公尺的山,台灣三千公尺以上的山,台灣有幾座高山,台灣3000公尺以上的山有幾座|常識
簡介=台灣海拔超過 3,000 公尺的山峰有兩百多座（常見的說法是 268 座），對一個這麼小的島來說非常多；登山界從裡面挑出 100 座有代表性的，叫「台灣百岳」。最高的是玉山，海拔 3,952 公尺
@日本有幾個島|日本有幾個島,日本有多少個島,日本有幾座島,日本由幾個島組成|常識
簡介=日本由北海道、本州、四國、九州四個主要的大島，加上沖繩和許多小島組成。2023 年日本政府用新的地圖重新計算，島嶼數量是 14,125 個（以前的說法是 6,852 個）
@南極北極哪個冷|北極和南極哪個比較冷,南極和北極哪個比較冷,南極北極哪個冷,南極比北極冷嗎,北極比較冷還是南極比較冷|常識
簡介=南極比較冷。南極是一大塊陸地，平均海拔大約 2,500 公尺，上面覆蓋很厚的冰，冬天平均大約零下 60°C，曾經測到零下 89.2°C；北極主要是結冰的海洋，海水會保留熱量，冬天大約零下 30 到 40°C。另外，企鵝住在南極、北極熊住在北極，牠們不會遇到彼此
@時區|時區是什麼,什麼是時區|科學
簡介=依照經度把地球分成的時間區域：地球自轉一圈大約 24 小時，所以大致分成 24 個時區，每差 15 度經度、時間就差 1 小時
說明=台灣是 UTC+8；日本是 UTC+9，比台灣快 1 小時；英國冬天是 UTC+0，比台灣慢 8 小時。有些國家夏天會實施夏令時間，把時鐘撥快 1 小時
@打哈欠會傳染|打哈欠會傳染嗎,為什麼打哈欠會傳染,哈欠會傳染嗎,打哈欠會傳染|常識
簡介=會。看到、聽到，甚至只是讀到或想到別人打哈欠，都可能跟著打。科學家認為這跟模仿和同理心有關：越親近的人越容易互相「傳染」；狗也會被主人的哈欠傳染
@拗手指|手指關節喀喀響有關係嗎,拗手指會怎樣,拗手指有關係嗎,扳手指會關節炎嗎,手指關節喀喀響,折手指會怎樣|健康常識
簡介=拗手指發出的「喀」聲，是關節液裡的氣泡突然形成或破掉的聲音。目前的研究沒有發現它會造成關節炎，偶爾拗沒有關係；但如果拗的時候會痛、關節腫起來，或關節卡卡的、活動變差，就要去看醫生
@近視可以恢復嗎|近視可以恢復嗎,近視會好嗎,近視能恢復嗎,近視可以治好嗎,近視會不會好|健康常識
簡介=真正的近視（眼球拉長）沒辦法自己恢復，眼藥水、護眼操也不能讓它消失；可以用眼鏡、隱形眼鏡矯正，成年後度數穩定了可以評估雷射手術。小朋友的「假性近視」是看近太久、眼睛的肌肉太緊，休息和治療可以改善。預防近視加深：每用眼 30 分鐘休息 10 分鐘、每天到戶外 2 小時（3010），小朋友可以請眼科醫師評估低濃度散瞳劑或角膜塑型片
@飯後洗澡|飯後可以馬上洗澡嗎,吃飽可以馬上洗澡嗎,飯後洗澡,吃飽洗澡,剛吃飽可以洗澡嗎|健康常識
簡介=一般健康的人沒有大問題，但剛吃飽時血液集中在腸胃幫忙消化，馬上洗熱水澡會讓皮膚血管擴張，可能讓消化變慢，也有人會覺得頭暈；長輩、心血管疾病的人更要注意。建議吃飽後休息 30 分鐘到 1 小時再洗
@喝冰水會胖嗎|喝冰水會變胖嗎,喝冰水會胖嗎,冰水會讓人變胖嗎,喝冰的會胖嗎|健康常識
簡介=不會。水本身沒有熱量，冰水也一樣，身體還會花一點點熱量把它加熱（很少）。會讓人變胖的是含糖的冰飲料。腸胃比較敏感的人喝太冰可能會不舒服，可以改喝常溫的水
@每天洗頭|每天洗頭好嗎,每天洗頭可以嗎,頭要多久洗一次,每天都要洗頭嗎,多久洗一次頭|健康常識
簡介=可以。頭皮比較油、常流汗、天氣熱的時候，每天洗反而比較好；頭皮比較乾的人可以兩三天洗一次。重點是用溫水不要太燙、用指腹按摩不要抓，洗完把頭皮吹乾，不要濕著頭髮睡覺
@雞蛋要洗嗎|雞蛋要洗嗎,雞蛋要不要洗,買回來的雞蛋要洗嗎,雞蛋要先洗再放冰箱嗎|健康常識
簡介=買回來的雞蛋不要先洗再放冰箱：蛋殼外面有一層保護膜，洗掉後細菌比較容易從蛋殼的小孔跑進去。要用的時候再洗，洗完馬上煮。台灣超市賣的「洗選蛋」已經清洗消毒過，可以直接放冰箱
@冰箱溫度|冰箱冷藏幾度,冰箱要幾度,冷藏室幾度,冷凍庫幾度,冰箱溫度要設多少|常識
簡介=冷藏室最好保持在 7°C 以下（理想大約 1 到 5°C），冷凍庫在零下 18°C 以下。冰箱不要塞太滿，大約七八分滿，冷空氣才能循環；門邊的溫度比較高、變化大，適合放飲料和調味料，牛奶、蛋、肉這些容易壞的放裡面
@微波爐放金屬|微波爐可以放鐵碗嗎,微波爐可以放不鏽鋼嗎,微波爐可以放鋁箔紙嗎,微波爐可以放金屬嗎,鐵碗可以微波嗎,不鏽鋼碗可以微波嗎|常識
簡介=不行。鐵碗、不鏽鋼、鋁箔紙、有金邊或銀邊的碗盤都是金屬，會反射微波，可能冒出火花、弄壞微波爐，甚至起火。微波要用標示「可微波」的玻璃、陶瓷或耐熱塑膠容器
@保鮮膜微波|保鮮膜可以微波嗎,保鮮膜可以加熱嗎,保鮮膜能微波嗎,保鮮膜可以放微波爐嗎|健康常識
簡介=要看材質：標示「可微波」的 PE（聚乙烯）保鮮膜才可以，PVC 保鮮膜不要拿去加熱。就算可以微波，也不要讓保鮮膜碰到食物，特別是很油的食物，還要留一點縫讓蒸氣跑出來；更好的方法是用可微波的蓋子或盤子蓋著加熱
@不沾鍋刮傷|不沾鍋刮傷還能用嗎,不沾鍋刮傷,不沾鍋塗層掉了,不沾鍋掉漆,不沾鍋多久換|健康常識
簡介=輕微的小刮痕一般還能用；但如果塗層大片剝落、刮痕很多、開始容易黏鍋，就建議換新。平常用木頭或矽膠鍋鏟，不要用鐵鏟和菜瓜布；不要空燒或大火乾燒（太高溫塗層可能分解），洗的時候等鍋子冷了再用軟海綿洗
@塑膠袋裝熱湯|塑膠袋可以裝熱湯嗎,塑膠袋裝熱食,塑膠袋可以裝熱的嗎,熱湯可以用塑膠袋裝嗎|健康常識
簡介=最好不要，尤其是有顏色的、來路不明的塑膠袋，遇到高溫可能讓塑化劑等物質跑進食物裡。外帶熱湯、熱飲盡量用自己的耐熱容器（玻璃、不鏽鋼），塑膠的話選標示耐熱的 PP（5 號）材質
@月球上的空氣|月球上有空氣嗎,月亮上有空氣嗎,月球有空氣嗎,月亮有空氣嗎,月球上可以呼吸嗎|常識
簡介=幾乎沒有。月球的引力太小，留不住氣體，所以沒有可以呼吸的空氣，也沒有風、沒有聲音，就算白天天空也是黑的；只有非常非常稀薄的一層「外氣層」。太空人在月球上要穿太空衣、背氧氣
@太陽的壽命|太陽會燒完嗎,太陽會不會燒完,太陽還能燒多久,太陽會熄滅嗎,太陽會死嗎,太陽會不會消失|常識
簡介=會，但還要很久很久：太陽大約 46 億歲，大概還能穩定燃燒 50 億年左右。之後它會膨脹成紅巨星，可能吞掉水星和金星，最後變成一顆小小的白矮星，慢慢冷卻下來
@用電鍋|電鍋怎麼用,大同電鍋怎麼用,電鍋怎麼蒸,電鍋怎麼煮飯,電鍋外鍋要放多少水|常識
簡介=電鍋的用法：外鍋倒水，水量決定加熱的時間（大約 1 杯水蒸 15 到 20 分鐘），內鍋放食物，蓋上蓋子按下開關，水煮乾了開關會自己跳起來；跳起來後再燜 5 到 10 分鐘更好。煮白飯：內鍋米和水大約 1 比 1 到 1.2，外鍋放 1 杯水；熱包子、饅頭外鍋放半杯到 1 杯水就好
@學日文App|學日文有推薦的app嗎,學日文的app,學日文app,日文app推薦,學日文推薦什麼app,學日文用什麼app,學日文推薦app|常識
簡介=學日文可以試試這些 App：Duolingo（多鄰國，遊戲化，適合入門）、LingoDeer（文法講解清楚，適合從五十音開始）、Anki 或 Quizlet（用閃卡背單字）、MOJi 辭書（查字典）、NHK NEWS WEB EASY（簡單日文新聞，練閱讀）。再搭配日劇、動畫和 YouTube 的日文頻道，學起來更有趣
@鯨豚呼吸|海豚怎麼呼吸,鯨魚怎麼呼吸,鯨魚用什麼呼吸,海豚用什麼呼吸,鯨魚怎麼換氣,海豚怎麼換氣,鯨魚會不會淹死,鯨豚怎麼呼吸|常識
簡介=鯨魚和海豚是哺乳類，用肺呼吸：頭頂上有噴氣孔（就是牠們的鼻孔），浮到水面時打開噴氣孔換氣，潛下去時再關起來。鯨魚噴出的「水柱」，其實是溫暖的呼氣遇到冷空氣凝結的水氣，加上一點海水。海豚睡覺時一次只讓一半的大腦休息，另一半保持清醒，記得浮上來呼吸
@台灣第二高的山|台灣第二高的山,台灣第二高峰,台灣第二高山,台灣第三高的山|常識
簡介=台灣第二高的山是雪山，海拔 3,886 公尺，在台中市和苗栗縣交界，是雪霸國家公園的主峰。第三高要看怎麼算：把玉山的子峰分開算，是玉山東峰（3,869 公尺）；以獨立的山來說，是秀姑巒山（3,825 公尺）。最高的是玉山主峰（3,952 公尺）
@學游泳要多久|學游泳要多久,學會游泳要多久,游泳要學多久,多久可以學會游泳,學游泳多久會,學游泳要多久才會|常識
簡介=每個人不一樣，一般成人一週上 2 到 3 次課，大約 10 到 20 堂課可以學會換氣、游完 25 公尺的蛙式或自由式；小朋友和不怕水的人通常更快。怕水的話，先花幾堂課練習憋氣、漂浮，不要急，放鬆了才學得快
@學游泳要準備什麼|學游泳要買什麼,學游泳要準備什麼,游泳要帶什麼,游泳要準備什麼,游泳要買什麼,去游泳要帶什麼|常識
簡介=學游泳可以準備：泳衣、泳帽（很多泳池規定一定要戴）、蛙鏡、毛巾或吸水巾、拖鞋、沐浴用品和換洗衣物；耳塞、鼻夾看自己需要；浮板泳池通常有。蛙鏡選不會壓眼眶、吸得住的就好，不用一開始就買很貴的
@減肥一天吃多少|減肥一天要吃多少,減肥一天吃多少熱量,減肥要吃多少,減肥一天吃多少大卡,減肥一天要吃多少熱量|健康常識
簡介=每個人不一樣：先估算自己一天消耗的熱量（和體重、身高、年齡、活動量有關，可以上網用 TDEE 計算機算），再每天少吃大約 300 到 500 大卡就好。一般女性一天最好不要低於大約 1,200 大卡、男性不要低於大約 1,500 大卡，吃太少會掉肌肉、代謝變慢，也容易復胖
@減肥不吃晚餐|晚餐可以不吃嗎,減肥可以不吃晚餐嗎,不吃晚餐會瘦嗎,減肥不吃晚餐,不吃晚餐可以減肥嗎,減肥要不要吃晚餐|健康常識
簡介=不建議完全不吃：不吃晚餐容易半夜餓、隔天暴飲暴食，長期也可能營養不夠，減重的關鍵還是一天的總熱量。晚餐可以吃少一點、早一點吃（睡前 3 小時吃完），多選蛋白質和蔬菜，少一點澱粉和油炸
@晚上喝咖啡|晚上喝咖啡會睡不著嗎,晚上可以喝咖啡嗎,晚上喝咖啡,睡前喝咖啡,晚上喝什麼,睡前喝什麼比較好,晚上想喝咖啡|健康常識
簡介=晚上喝咖啡容易睡不著：咖啡因大約要 5 到 6 個小時才會代謝掉一半，所以一般建議下午兩三點以後就少喝。晚上想喝點東西，可以選低咖啡因咖啡、熱牛奶、麥茶、黑豆水，或洋甘菊這類花草茶
@生日怎麼慶祝|生日要怎麼慶祝,生日怎麼過,生日要做什麼,生日怎麼慶祝,要怎麼慶祝生日,生日可以做什麼|常識
簡介=生日可以這樣過：約家人或好朋友吃一頓想吃很久的餐廳；買一個自己喜歡的蛋糕，許個願；給自己一個小禮物，或一段不被打擾的時間；去一個沒去過的地方走走、拍照留念；寫下這一年最感謝的事和新的一歲想做的事。一個人過也可以很好，重點是好好對待自己
@每月存多少|每個月存多少比較好,每個月要存多少,每月存多少錢,薪水要存多少,一個月存多少,每個月存多少錢比較好|常識
簡介=常見的建議是收入的 10% 到 20%，能存到 20% 以上更好；剛出社會或房租很高的人，先從 10% 開始也很好。順序是先存 3 到 6 個月生活費當緊急預備金，再開始存長期目標和投資。最重要的是「領到薪水先存」，固定自動轉帳，比月底看剩多少存有效
@存錢放哪裡|存錢要放哪裡,錢要放哪裡,存款放哪裡,存的錢放哪裡,存下來的錢放哪裡,存錢放哪裡|常識
簡介=可以依用途分開放：緊急預備金放活存或利率比較高的數位帳戶，要用隨時領得到；一兩年內會用到的錢（旅遊、學費）可以放定存；五年以上用不到的長期資金，可以考慮定期定額買指數型 ETF。不要把所有錢放同一個地方，投資也一定有賠錢的可能
@天冷穿什麼|天冷要穿什麼,冷要穿什麼,好冷要穿什麼,冬天要穿什麼,很冷要穿什麼,天氣冷穿什麼,冷的時候要穿什麼|常識
簡介=天冷可以用「洋蔥式穿法」：最裡面穿吸濕排汗或發熱衣，中間穿毛衣、刷毛衣這類保暖層，最外面穿防風防水的外套；進到室內熱了可以一層層脫。脖子、手、頭最容易散熱，戴圍巾、手套、毛帽會暖很多；腳冷的人可以穿厚襪子
@好養的狗|什麼狗比較好養,哪種狗比較好養,好養的狗,新手養什麼狗,適合新手的狗,什麼狗好養,新手適合養什麼狗|常識
簡介=新手可以考慮這些：米克斯（台灣土狗）適應力強、身體健壯；貴賓狗聰明、不太掉毛；馬爾濟斯、西施體型小，適合公寓；柴犬愛乾淨但個性比較獨立；黃金獵犬很親人，但體型大、需要很多運動空間。比品種更重要的是你的時間（每天散步和陪伴）、空間和預算，也很推薦去收容所領養
@好養的貓|什麼貓比較好養,哪種貓比較好養,好養的貓,新手養什麼貓,適合新手的貓,什麼貓好養,新手適合養什麼貓|常識
簡介=新手可以考慮：米克斯（台灣的混種貓）身體健壯、個性多樣；美國短毛貓個性穩定、好相處；英國短毛貓安靜、不太黏人；布偶貓很溫和親人，但毛長要常梳。貓比狗獨立、不用每天出門散步，但要準備貓砂盆、貓抓板，也要結紮、打預防針；很推薦去收容所領養
@養狗花費|養狗要花多少錢,養狗一個月要多少錢,養一隻狗要多少錢,養狗花費,養狗要多少錢,養狗貴嗎|常識
簡介=大約這樣抓：一開始的打預防針、晶片、結紮和用品（籠子、碗、牽繩）大約 5 千到 1 萬多元；之後每個月的飼料、零食、尿布墊，小型狗大約 2 千到 4 千元，大型狗更多，美容洗澡另外算；每年還有健康檢查、預防針和心絲蟲藥。生病的醫藥費可能很高，可以考慮存一筆寵物醫療基金或保寵物險
@養貓花費|養貓要花多少錢,養貓一個月要多少錢,養一隻貓要多少錢,養貓花費,養貓要多少錢,養貓貴嗎|常識
簡介=大約這樣抓：一開始的預防針、晶片、結紮和用品（貓砂盆、貓抓板、提籠）大約 5 千到 1 萬元；之後每個月的飼料、罐頭、貓砂大約 1 千 5 到 3 千元；每年健康檢查和預防針另外算。生病的醫藥費可能很高，可以考慮存一筆寵物醫療基金
@台南美食|台南有什麼好吃的,台南美食,台南必吃,台南小吃,台南有什麼好吃,台南好吃的|常識
簡介=台南是小吃之都，可以吃：牛肉湯（一大早喝最鮮）、虱目魚粥、擔仔麵、碗粿、蝦捲、棺材板、鱔魚意麵、肉圓、豆花，夏天還有芒果冰。國華街、保安路一帶、花園夜市都很好逛
說明=很多老店早上就開、賣完就收，想吃的店最好先查營業時間
@該不該道歉|我該道歉嗎,要不要道歉,我需要道歉嗎,該不該先道歉,我要先道歉嗎,我應該道歉嗎|常識
簡介=道歉不代表你全錯，而是為「讓對方受傷的那部分」負責。如果你也覺得委屈，可以先說「我不是故意讓你難過，對不起」，再好好說出你的感受和想法；如果覺得自己沒錯，也可以不急著道歉，先冷靜一下，再找機會把話說開。重要的是你想不想保住這段關係
@電腦要重灌嗎|電腦要重灌嗎,電腦很慢要重灌嗎,要不要重灌,電腦需要重灌嗎,重灌電腦,電腦要不要重灌|常識
簡介=通常不用一開始就重灌：先試試關掉開機自動啟動的程式、清出硬碟空間、掃毒、更新系統；如果還是傳統硬碟（HDD），換成 SSD 速度會快很多。都試過還是很慢、或中毒很嚴重，再考慮重灌，重灌前一定要先備份照片和文件；Windows 也可以用「重設此電腦」，選擇保留個人檔案
@流鼻血要抬頭嗎|流鼻血要抬頭嗎,流鼻血要仰頭嗎,流鼻血可以抬頭嗎,流鼻血頭要往後仰嗎,流鼻血要不要抬頭|健康常識
簡介=不要抬頭！流鼻血時頭要稍微往前傾，不要往後仰，不然血會流進喉嚨，可能嗆到或讓人想吐。坐著、身體往前傾，用拇指和食指捏住鼻子前端軟的地方，持續壓 10 到 15 分鐘不要放開，用嘴巴呼吸；也可以在鼻樑上冰敷。壓了 20 分鐘還止不住，或撞到頭之後流鼻血，要去看醫生
@貓呼嚕|貓呼嚕是什麼意思,貓咪呼嚕代表什麼,貓呼嚕代表什麼,貓咪呼嚕是什麼意思,貓咪為什麼呼嚕呼嚕,貓咪發出呼嚕聲|常識
