@安太歲|安太歲是什麼,怎麼安太歲,安太歲要做什麼,太歲是什麼,要安太歲嗎|常識
簡介=太歲是民間信仰中每年輪值的神明。當年的生肖跟太歲相同或相沖，就叫「犯太歲」，傳統上會到廟裡「安太歲」：填寫姓名、生日和地址，點太歲燈祈求平安，通常在農曆過年前後到元宵節之間辦理。這是民間信仰，求的是一份安心；想從九型十二宮看你今年的走向，可以問我「今年運勢」
@犯太歲|犯太歲怎麼辦,什麼是犯太歲,犯太歲要注意什麼,今年犯太歲,哪些生肖犯太歲,犯太歲是什麼|常識
簡介=犯太歲是民間說法：當年生肖跟太歲一樣叫「值太歲」，相沖叫「沖太歲」，另外還有刑、害、破的說法。傳統的做法是到廟裡安太歲、點光明燈，平常低調一點、重要的決定多想想、注意健康。這些說法沒有科學根據，當成提醒自己多注意也很好；想看看你今年各方面的走向，可以問我「今年運勢」
@農民曆|什麼是農民曆,農民曆是什麼,農民曆怎麼看,農民曆要怎麼看|常識
簡介=農民曆是傳統的曆書，除了國曆、農曆日期和二十四節氣，還會列出每天的宜忌（適合結婚、搬家、開市或要避開什麼）、沖煞的生肖和吉時。以前是給農民看節氣種田，現在很多人挑日子時會參考
@黃道吉日|黃道吉日是什麼,什麼是黃道吉日,好日子怎麼挑,怎麼挑日子,吉日怎麼看|常識
簡介=黃道吉日是傳統曆法裡認為做事比較順利的好日子，農民曆上會標每天的吉凶和宜忌。結婚、搬家、開市、動土的時候，很多人會挑農民曆上「宜」那件事、而且不沖自己生肖的日子
@搬家看日子|搬家要看日子嗎,搬家怎麼挑日子,搬家吉日,入厝要看日子嗎,入厝要做什麼,入厝習俗,搬家習俗|常識
簡介=很多人搬家（入厝）會看農民曆，挑「宜移徙、入宅」、又不沖到家裡成員生肖的日子，也會挑吉時進門；不過這是習俗，看不看都可以，安全和方便最重要。入厝常見的習俗：帶米、鹽和新掃把進門，開火煮一鍋甜湯、打開燈和水龍頭，象徵生活圓滿。告訴我你的生日，我也可以用九型十二宮看看哪段時間比較順
@白包|白包要包多少,奠儀要包多少,白包怎麼包,喪禮包多少,白包要包單數嗎,包白包,喪禮要包多少,告別式要包多少,告別式包多少|常識
