@滿月禮|滿月要送什麼,彌月要送什麼,滿月禮,彌月禮,滿月包多少,寶寶滿月送什麼,滿月要包多少,滿月紅包包多少,滿月禮要包多少|常識
簡介=朋友的寶寶滿月，常見的禮物有：金飾（金手鍊、金鎖片）、嬰兒衣服或包巾（可以買大一號的）、實用的尿布和濕紙巾，或包紅包（大約 1,200 到 3,600 元，看交情）。主人家通常會回送油飯、紅蛋或彌月蛋糕
@拜拜準備|拜拜要準備什麼,拜拜要買什麼,拜拜怎麼拜,拜神要準備什麼,廟裡拜拜要準備什麼,去廟裡拜拜|常識
簡介=到廟裡拜拜一般準備：香（廟裡通常有）、鮮花、水果（像蘋果、香蕉、柳丁，民間習慣不放芭樂和番茄）、餅乾或糕點，有需要再準備金紙。順序跟著廟裡的指示，通常先拜天公爐，再拜主神和其他神明；拿香時先說自己的姓名、生日和地址，再說想祈求的事。供品可以帶回家吃，代表接受神明的祝福；各地習俗不太一樣，可以問廟方
