簡介=尾牙是農曆十二月十六日，傳統上商家會拜土地公、請員工吃飯，感謝一年的辛勞；現在很多公司會在年底到過年前辦尾牙聚餐、抽獎。傳統尾牙會吃刈包（虎咬豬），象徵把壞運咬掉、包住福氣
