簡介=中元節（農曆七月十五）普渡拜「好兄弟」，常見供品：餅乾、泡麵、罐頭、飲料、米、水果，再放一盆清水和毛巾讓好兄弟洗手洗臉；水果的民間說法是避開芭樂、番茄和釋迦。通常在門口或騎樓拜，香可以插在供品上，拜完燒銀紙；很多公司和社區會集體普渡
