簡介=過年前常見的準備：大掃除（除舊佈新）、辦年貨（糖果、瓜子、年糕、發糕、零食、飲料）、貼春聯和福字、準備紅包（用新鈔）、買新衣、準備或訂好年夜飯、安排回家的車票。除夕吃年夜飯、守歲，初一走春拜年
