簡介=生肖相沖（六沖）是傳統說法，依地支相隔六位：鼠馬沖（子午）、牛羊沖（丑未）、虎猴沖（寅申）、兔雞沖（卯酉）、龍狗沖（辰戌）、蛇豬沖（巳亥）。挑結婚、搬家的日子時，很多人會避開沖到自己生肖的日子；兩個人合不合，還是要看相處
