簡介=本命年是遇到自己生肖的那一年（每 12 年一次），民間說法是這一年「值太歲」，變動比較多；傳統上會穿紅色內衣、戴紅繩，或到廟裡安太歲求平安，凡事謹慎一點、注意健康。告訴我生日，我可以幫你看今年的運勢
@士林夜市|士林夜市|地標
