位置=台北市士林區，捷運劍潭站旁
美食=大香腸、炸雞排、生炒花枝、蚵仔煎、青蛙下蛋（粉圓冰）、胡椒餅、藥燉排骨、士林大餅包小餅
@逢甲夜市|逢甲夜市|地標
簡介=台中最大的夜市，也是台灣最大的觀光夜市之一，很多創意小吃從這裡紅起來
位置=台中市西屯區，逢甲大學旁
@鹿港美食|鹿港有什麼好吃的,鹿港美食,鹿港小吃,鹿港必吃,鹿港特產,鹿港有什麼特產,鹿港名產,鹿港有什麼名產|常識
簡介=彰化鹿港可以吃：蚵仔煎、肉圓、麵線糊、蝦猴（炸的小蝦蛄）、牛舌餅、鳳眼糕、芋丸；鹿港老街、天后宮、九曲巷一邊逛一邊吃最剛好
@澎湖最佳季節|澎湖什麼時候去最好,澎湖幾月去,什麼時候去澎湖,澎湖最佳季節|常識
簡介=4 月到 9 月最適合去澎湖：天氣溫暖、可以玩水跳島，4 到 6 月有澎湖花火節；7、8 月最熱也最多人。10 月到隔年 3 月東北季風很強、很冷，船班和水上活動也比較少
@肉圓|肉丸|食物
簡介=用地瓜粉或在來米漿做成透明 Q 彈的皮，包豬肉、筍子和香菇的台灣小吃，淋上甜辣醬吃
由來=一般說是從彰化北斗開始的；各地做法不一樣：彰化肉圓用油泡，新竹肉圓和屏東肉圓用蒸的
@大腸包小腸|大腸包小腸是什麼|食物
簡介=台灣夜市小吃：用烤過的糯米腸當「麵包」，切開夾台式香腸，再加蒜片、酸菜、小黃瓜和醬料
@鳳梨酥|鳳梨酥是哪裡的名產|食物
簡介=台灣最有名的伴手禮之一，酥鬆的餅皮包鳳梨餡（有些會加冬瓜讓口感更細），全台都有很多名店，常說是台中的名產
@胡椒餅|胡椒餅是哪裡的|食物
簡介=源自福州的烤餅，把餅貼在炭火甕壁上烤，外皮酥脆，裡面是胡椒豬肉和很多蔥；台北饒河夜市的胡椒餅很有名
@刈包|虎咬豬|食物
簡介=用對折的白色麵皮夾滷五花肉、酸菜、花生糖粉和香菜，又叫「虎咬豬」；台灣尾牙常吃，象徵咬住福氣
@粉圓|珍珠是什麼做的,粉圓是什麼做的,珍珠奶茶的珍珠是什麼|常識
簡介=珍珠奶茶裡的珍珠（粉圓）是用樹薯粉（木薯澱粉）做的，加黑糖或焦糖一起煮成黑色，口感 Q 彈；白色的是沒有加糖色的白珍珠
@太陽餅|太陽餅裡面有太陽嗎,太陽餅是哪裡的|食物
簡介=台中的名產，層層酥皮包著麥芽糖做的內餡，名字一般說是來自當年的「太陽堂」餅店；裡面當然沒有太陽 😄
@剩菜可以放多久|剩菜可以放多久,剩菜放多久,剩菜可以放幾天,剩菜放冰箱可以放多久,飯菜可以放多久,煮好的菜可以放多久,菜可以放冰箱幾天,剩菜能放冰箱幾天,剩菜放冰箱幾天,剩菜能放幾天|健康常識
簡介=煮好的菜要在 2 小時內放涼、分裝蓋好放冰箱：一般冷藏 3 到 4 天內吃完；海鮮、涼拌菜、蛋料理最好 1 到 2 天內吃完；冷凍可以放 2 到 3 個月。吃之前要整個熱透，加熱過一次就不要再反覆冰了又熱
說明=綠葉菜隔夜容易變色、變味，最好當餐吃完；聞起來怪怪的、牽絲、冒泡就不要吃了
@電費怎麼算|電費怎麼算,電費計算,電費是怎麼算的,一度電多少錢,電費怎麼計算,一度電是多少|常識
簡介=電費＝用了幾度電 × 每度電的價錢。1 度電就是 1 千瓦小時，例如 1,000 瓦的電暖器開 1 小時，或 100 瓦的電器開 10 小時，都是 1 度
說明=台灣住家用電是「累進費率」：用得越多，每一度越貴；夏天（6 到 9 月）的電價也比較高。電費單通常兩個月一期，想知道最新的每度電價可以看台電網站
@換輪胎|輪胎多久換一次,輪胎多久要換,輪胎什麼時候要換,輪胎要換了嗎,輪胎多久換,汽車輪胎多久換一次,機車輪胎多久換|常識
簡介=一般汽車輪胎大約跑 4 到 5 萬公里、或用了 4 到 5 年左右就該換；胎紋深度剩不到 1.6 公釐（胎紋裡的磨耗指示點跟胎面一樣平）一定要換。出現龜裂、鼓包、被釘子刺破補過很多次，也要換
說明=機車輪胎磨得比較快，大約 1 到 2 萬公里就要檢查；每個月檢查一次胎壓，胎壓不足會更耗油也更容易爆胎
@煮麵放鹽|煮麵要放鹽嗎,煮麵加鹽,煮義大利麵要放鹽嗎,煮麵水要加鹽嗎,煮麵為什麼要放鹽,煮麵要不要加鹽|常識
簡介=煮義大利麵建議要放：大約每 1 公升水放 10 公克鹽（1 小匙半左右），讓麵條本身有味道；一般中式麵條、泡麵就不用放，湯頭和醬料本身已經夠鹹
說明=放鹽主要是調味，不是為了讓水滾得比較快；在水裡加一點油防黏的效果也不大，煮的時候攪一攪比較有用
