名言=吾生也有涯，而知也無涯
@李白|李太白,青蓮居士,詩仙|人物
簡介=唐朝最有名的詩人之一，被稱為「詩仙」，詩風豪放、想像力驚人
年代=唐朝，西元 701 年到 762 年
國籍=中國（唐朝）
代表作=〈靜夜思〉〈將進酒〉〈蜀道難〉〈早發白帝城〉〈月下獨酌〉
名言=床前明月光，疑是地上霜；天生我材必有用，千金散盡還復來
看法=我喜歡他的自信——「天生我材必有用」到今天都還是很好的打氣話
@杜甫|杜子美,詩聖|人物
