國籍=中國（唐朝）
代表作=〈長恨歌〉〈琵琶行〉〈賦得古原草送別〉
名言=野火燒不盡，春風吹又生
@蘇軾|蘇東坡,東坡居士|人物
簡介=北宋的文學家、書法家、畫家，詩詞文章都是一流，人生幾度被貶卻很樂觀
年代=北宋，西元 1037 年到 1101 年
國籍=中國（宋朝）
