開頭=遇到消費糾紛，可以這樣申訴：
步驟=先跟店家或購物平台的客服反映，說清楚問題和你希望的處理方式；留好證據：發票、訂單、對話紀錄、商品照片；沒解決的話，打 1950 消費者服務專線，或到行政院消費者保護會的網站線上申訴；業者收到申訴後，要在 15 天內妥善處理；還是談不攏，可以向縣市政府申請消費爭議調解
@瑕疵品|買到瑕疵品怎麼辦,瑕疵品怎麼辦,買到壞掉的東西,買到有問題的東西,商品有瑕疵,收到的東西壞了|生活
開頭=買到瑕疵品，可以這樣處理：
步驟=先拍照或錄影，記錄瑕疵和包裝；網購的話，收到 7 天內可以申請退貨，或直接要求換貨；實體店拿發票回店家要求退換；在保固期內，也可以直接找原廠維修或更換；店家不處理，就打 1950 消費者服務專線申訴
@騷擾電話|一直接到騷擾電話,騷擾電話怎麼辦,一直接到推銷電話,陌生電話一直打來,怎麼封鎖電話,推銷電話怎麼辦|生活
開頭=一直接到騷擾或推銷電話，可以這樣處理：
步驟=陌生號碼不想接就不要接，接了也不要透露個人資料或驗證碼；在手機裡封鎖那個號碼；iPhone 可以打開「設定」→「電話」→「將未知來電者靜音」；裝來電辨識 App（像 Whoscall），會先提醒你是不是推銷或可疑電話；如果內容是威脅、恐嚇，保留紀錄並打 110 報警
@撿到東西|撿到錢包怎麼辦,撿到東西怎麼辦,撿到錢怎麼辦,撿到手機怎麼辦,撿到東西要交給誰,撿到東西可以拿走嗎|生活
開頭=撿到別人的東西，可以這樣處理：
步驟=在捷運站、商店、學校撿到的，交給那裡的服務台或管理單位；其他地方撿到的，送到附近的派出所，警察會登記、幫忙找失主；不要自己留下來，拿走別人的遺失物可能觸法；依民法，招領 6 個月沒有人認領，東西可以歸拾得人所有；失主領回時，拾得人可以請求報酬，最多是東西價值的十分之三
@法院的信|收到法院的信怎麼辦,收到法院傳票,收到法院通知,收到支付命令怎麼辦,收到法院的通知怎麼辦,法院寄信來|生活
開頭=收到法院的信，先冷靜，照這個順序處理：
步驟=先確認是不是真的法院寄的：看信封上的法院名稱、案號，自己查法院的總機電話打去確認，不要打信裡來路不明的電話或匯款；看清楚是什麼文件：開庭通知、支付命令、判決書，還有上面的期限；收到「支付命令」如果有意見，要在 20 天內向法院提出異議，不然可能跟判決一樣有效力；不懂的地方可以找法律扶助基金會（412-8518）或律師諮詢
提醒=法院不會打電話要你轉帳、或要你交出存摺和提款卡
@保險規劃|要不要買保險,保險怎麼買,保險要怎麼買,保險要買什麼,第一張保單要買什麼,保險怎麼規劃,買保險要注意什麼|生活
開頭=買保險可以照這個順序想：
步驟=台灣已經有健保和勞保，商業保險是補不足的地方；先保「萬一發生會讓家裡經濟出大問題」的風險：意外險、醫療險（實支實付）、重大傷病或癌症險；有家人要靠你養、或有房貸的人，再加定期壽險；保費大約抓年收入的 10% 以內，不要買到影響生活；簽約前看清楚條款、等待期和不理賠的情況
提醒=保險主要是保障，不太適合當儲蓄投資；收到保單後 10 天內，可以無條件撤銷契約
@頭期款|買房頭期款要幾成,頭期款要幾成,頭期款要準備多少,買房要準備多少錢,房貸可以貸幾成|生活
開頭=買房的頭期款大概這樣抓：
步驟=一般銀行房貸大多可以貸 7 到 8 成，所以頭期款要準備房價的 2 到 3 成；另外還要準備稅費、仲介費、代書費等，大約房價的 3% 到 5%；裝潢、家具、搬家也要另外算；第二間房、高價房或部分地區，政府和銀行可能限制貸款成數，頭期款要準備更多
提醒=買房前先算好每個月的房貸，最好不要超過家庭收入的三分之一
@擲筊|擲筊怎麼擲,怎麼擲筊,擲筊,擲杯怎麼擲,聖筊是什麼,笑筊是什麼,陰筊是什麼,筊杯怎麼看|生活
開頭=擲筊（擲杯）是向神明請示的方法，大概這樣做：
步驟=先在神明前合掌，說清楚自己的姓名、生日、住址和想請示的事，問題要具體；雙手捧著兩個筊杯，拜一拜，再輕輕拋在地上；一平一凸是「聖筊」，代表神明同意或肯定；兩個平面都朝上是「笑筊」，代表神明笑而不答，可能問題不清楚，可以換個方式再問；兩個凸面都朝上是「陰筊」，代表不同意或不太適合；很多人會以連續三個聖筊才算確定
提醒=這是民間信仰的習俗，拜拜時保持恭敬就好
@求籤|求籤怎麼求,怎麼求籤,求籤,抽籤怎麼抽,廟裡怎麼抽籤,求籤要注意什麼|生活
開頭=到廟裡求籤，大概這樣做：
步驟=先上香拜拜，跟神明說自己的姓名、生日、住址和想問的事，一次問一件事、問得具體一點；到籤筒抽出一支籤；擲筊確認是不是這一支，要擲到聖筊才算；確認後照籤上的號碼去拿籤詩；看不懂的話，可以請廟方的解籤人員幫忙解讀
@籤詩|籤詩怎麼看,籤詩怎麼解,抽到下籤怎麼辦,籤詩的意思,下下籤怎麼辦,抽到下籤|生活
開頭=籤詩可以這樣看：
步驟=籤詩通常有籤號、等級（上上、上、中、下）、四句詩，有的還附典故；要對照你問的那件事來解讀，不是只看上籤或下籤；很多廟有解籤服務或解籤的書，可以請教；抽到下籤也不用太擔心，常常是提醒你這件事要小心、放慢腳步
看法=籤詩比較像一面鏡子，提醒你從另一個角度想想；最後怎麼做，還是你自己決定
@塔羅牌|塔羅牌是什麼,塔羅是什麼,塔羅牌怎麼玩,塔羅占卜,塔羅牌有幾張|生活
開頭=塔羅牌是一套 78 張的牌：
步驟=22 張「大阿爾克那」代表人生的大主題，像愚者、戀人、命運之輪；56 張「小阿爾克那」分成權杖、聖杯、寶劍、錢幣四種，講日常生活的事；占卜時先想好問題，洗牌、抽牌，照牌陣的位置看牌面，正位和逆位的意思不一樣；它原本是遊戲用的紙牌，後來才拿來占卜
看法=可以把塔羅當成整理想法、看見自己內心的工具，重要的決定還是要回到現實好好評估
@居家風水|風水要注意什麼,居家風水,家裡風水要注意什麼,房間風水,風水禁忌,家裡的風水|生活
開頭=居家風水常見的說法有這些（民間說法，參考就好）：
步驟=大門不要直直對著窗戶或後門，民間叫「穿堂煞」，說是財氣留不住；床頭最好靠牆，床不要在橫樑正下方，也不要正對房門；鏡子不要正對著床；家裡保持明亮、通風、整齊乾淨；很多說法其實跟生活習慣相通：採光好、空氣流通、動線順暢，住起來就舒服
@地瓜粥|怎麼煮地瓜粥,地瓜粥怎麼煮,地瓜稀飯怎麼煮,煮地瓜粥,番薯粥怎麼煮,地瓜粥|做法
開頭=地瓜粥可以這樣煮：
步驟=白米洗乾淨，地瓜削皮切小塊；鍋子放米和水，米跟水大約 1 比 8 到 10，喜歡稀一點水就多放；大火煮滾後放地瓜，轉小火煮 30 到 40 分鐘，中間要攪拌，免得黏鍋；煮到米粒開花、地瓜軟爛就好；用電鍋的話：米、地瓜、水（約 1 比 6）放內鍋，外鍋放 1.5 到 2 杯水
提醒=用冷飯煮更快，水滾後放飯和地瓜，煮 15 分鐘左右就可以
@煮玉米|玉米要煮多久,玉米怎麼煮,煮玉米要多久,玉米煮幾分鐘,玉米要煮幾分鐘,怎麼煮玉米,水煮玉米|做法
開頭=水煮玉米大概這樣抓時間：
步驟=玉米剝掉外皮和鬚，洗乾淨，太長可以切半；冷水下鍋，水要蓋過玉米；水滾後，甜玉米再煮 5 到 8 分鐘，白玉米、糯玉米煮 15 到 20 分鐘；用筷子戳玉米粒，軟了就好；用電鍋的話外鍋放 1 杯水
提醒=甜玉米煮太久反而會變老、不甜；水裡加一小塊奶油或一點點鹽，味道更好
@涼拌小黃瓜|怎麼做涼拌小黃瓜,涼拌小黃瓜怎麼做,涼拌小黃瓜,拍小黃瓜怎麼做,醃小黃瓜怎麼做,涼拌黃瓜怎麼做|做法
開頭=涼拌小黃瓜的做法：
步驟=小黃瓜洗乾淨，用刀背拍裂，切成一口大小；加一小匙鹽抓一抓，醃 10 到 15 分鐘，把出的水倒掉；加蒜末、辣椒、醬油、白醋、一點糖和香油拌勻；放冰箱冷藏 30 分鐘以上更入味
提醒=先用鹽殺青是脆的關鍵；不吃辣就不放辣椒
@滷豆干|怎麼滷豆干,滷豆干怎麼做,豆干怎麼滷,滷豆干,滷豆乾怎麼做,怎麼滷豆乾|做法
開頭=滷豆干可以這樣做：
步驟=豆干洗一洗，大的可以切半；鍋裡放一點油，爆香蔥段、薑片、蒜頭；加醬油、冰糖、八角（或一包滷包）和水，水要蓋過豆干；放豆干，大火煮滾後轉小火，滷 20 到 30 分鐘；關火後泡在滷汁裡放涼，越泡越入味
提醒=同一鍋可以一起滷海帶、雞蛋、豬肉
@蔥油餅|怎麼做蔥油餅,蔥油餅怎麼做,蔥油餅,自己做蔥油餅,蔥抓餅怎麼做,冷凍蔥油餅怎麼煎|做法
開頭=蔥油餅的做法：
步驟=中筋麵粉 300 克，先倒約 120 毫升熱水用筷子拌，再加約 60 毫升冷水揉成光滑的麵團，蓋起來醒 30 分鐘；麵團分成幾份，擀成薄片，刷油、撒鹽和蔥花；從一邊捲成長條，再盤成圓形，壓扁後擀成餅；平底鍋放油，中小火煎到兩面金黃，大約 5 到 6 分鐘；起鍋前用鍋鏟從邊緣往中間推一推，餅會比較有層次
提醒=冷凍蔥油餅不用退冰，直接下鍋小火煎，兩面金黃就好
@煎鮭魚|怎麼煎鮭魚,鮭魚怎麼煎,煎鮭魚,鮭魚怎麼煮,煎魚怎麼煎,怎麼煎魚才不會破|做法
開頭=煎鮭魚可以這樣做：
步驟=鮭魚用紙巾擦乾表面的水，撒鹽和一點胡椒；鍋子先燒熱，放少少的油（鮭魚自己會出油）；皮朝下放進鍋，中火煎 3 到 4 分鐘，先不要動它，等皮煎脆、魚肉變色到一半；翻面再煎 2 到 3 分鐘，側面都變不透明就熟了；起鍋擠一點檸檬汁
提醒=魚要擦乾、鍋要夠熱、不要一直翻，魚皮就不容易黏鍋破掉
@法式吐司|怎麼做法式吐司,法式吐司怎麼做,法式吐司,西多士怎麼做|做法
開頭=法式吐司的做法：
步驟=2 顆蛋、100 毫升牛奶、1 匙糖打勻；吐司兩面都泡進蛋液，讓它吸飽；平底鍋小火，放一小塊奶油；吐司下鍋，每一面煎 2 到 3 分鐘到金黃；淋蜂蜜或楓糖，也可以撒糖粉、放水果
提醒=火要小，不然外面焦了裡面還濕濕的；放一兩天有點乾的吐司反而最適合
@切鳳梨|鳳梨要怎麼切,鳳梨怎麼切,怎麼切鳳梨,切鳳梨,鳳梨怎麼削皮,鳳梨怎麼削|做法
開頭=鳳梨可以這樣切：
步驟=先切掉頭和尾，讓鳳梨可以立起來；從上往下沿著邊把皮削掉，皮可以削厚一點，把「釘眼」一起去掉；直切成四等份，把中間比較硬的芯切掉；再切成一口大小
提醒=吃鳳梨嘴巴刺刺的，是鳳梨酵素的關係，切好泡一下淡鹽水會好很多
@米長蟲|米長蟲怎麼辦,米生蟲怎麼辦,米有蟲,米裡有蟲,米蟲怎麼處理,米有米蟲怎麼辦,米長米蟲|生活
開頭=米長了米蟲，可以這樣處理：
步驟=把米倒在陰涼通風的地方攤開，蟲會自己爬走，不要拿去曬太陽，米會變質；或把米放冷凍 2 到 3 天把蟲凍死，再篩一篩、多洗幾次；如果米發霉、結塊或有怪味，就不要吃了，整包丟掉；裝米的桶子洗乾淨、擦乾再裝
提醒=預防：買小包裝、倒進密封罐，天氣熱時放冰箱冷藏；米桶裡放幾瓣大蒜或乾辣椒也有幫助
@菜刀生鏽|菜刀生鏽怎麼辦,刀子生鏽怎麼辦,菜刀生鏽,刀生鏽怎麼處理,菜刀生鏽還能用嗎,剪刀生鏽怎麼辦|做法
開頭=菜刀生鏽可以這樣處理：
步驟=輕微的鏽：用菜瓜布沾小蘇打粉加一點水，或擠一點牙膏，順著刀面刷；鏽比較多：用磨刀石磨掉，磨完順便把刀磨利；清乾淨後用熱水沖，馬上擦乾；長時間不用的話，刀面抹一層薄薄的食用油
提醒=洗好的刀不要泡在水槽裡、也不要沒擦乾就收，是最常見的生鏽原因
@氣炸鍋放油|氣炸鍋要放油嗎,氣炸鍋需要放油嗎,氣炸鍋要不要噴油,氣炸鍋要噴油嗎|做法
開頭=氣炸鍋要不要放油，看食物：
步驟=本身有油的（雞翅、五花肉、冷凍薯條和冷凍炸物）不用放油；蔬菜、瘦肉、自己裹粉的東西，表面噴一層薄薄的油，會比較金黃酥脆；用噴油瓶或刷子，不要直接把油倒在鍋底；可以墊烘焙紙或錫箔紙，但要用食物壓住，免得被風吹到發熱管
提醒=中途拉出來翻面或搖一搖，熟得比較均勻
@電鍋外鍋水量|電鍋外鍋要放幾杯水,外鍋要放幾杯水,電鍋要放多少水,電鍋外鍋放多少水,外鍋一杯水可以蒸多久|做法
開頭=電鍋外鍋的水，大概這樣放（用電鍋附的量米杯）：
步驟=外鍋 1 杯水大約可以蒸 15 到 20 分鐘；煮白飯：內鍋米和水 1 比 1，外鍋 1 杯；糙米、五穀米：外鍋 2 杯；蒸蛋、蒸魚：外鍋半杯到 1 杯；蒸包子饅頭：外鍋半杯，冷凍的放 1 杯；滷肉、燉湯：外鍋 2 到 3 杯，跳起來不夠軟就再加水再按一次
提醒=電鍋跳起來後先燜幾分鐘再開蓋；外鍋用久了有水垢，可以放白醋加水煮一次清掉
@不沾鍋保養|不沾鍋怎麼保養,不沾鍋怎麼洗,不沾鍋要注意什麼|做法
開頭=不沾鍋這樣用會比較耐用：
步驟=用木頭或矽膠鍋鏟，不要用鐵鏟、鋼絲刷；中小火就好，不要空燒，也不要大火乾燒；熱鍋不要馬上沖冷水，等它稍微變涼再洗；用軟海綿和洗碗精洗，洗完擦乾；收的時候不要跟其他鍋子直接疊著磨
提醒=塗層已經明顯刮傷、剝落，就該換新的鍋子了，一般用 2 到 3 年要換
@紗窗清潔|紗窗怎麼清,紗窗怎麼洗,紗窗很髒怎麼辦,清紗窗,紗窗怎麼清潔|做法
開頭=紗窗可以這樣清：
步驟=能拆的話拆下來，到浴室或陽台用水沖，用軟毛刷沾洗碗精水上下刷，再沖乾淨、立著晾乾；不能拆的：先用吸塵器或軟毛刷把灰塵刷掉；一邊貼一張舊報紙或廚房紙巾擋著，另一邊用海綿沾洗碗精水擦，髒東西會吸在紙上；最後用乾淨的濕布再擦一次
提醒=手不要太用力壓，紗網容易變形或破洞
@排水孔臭味|排水孔有臭味怎麼辦,排水孔很臭,水槽有臭味,浴室排水孔很臭,排水孔臭味,地板排水孔有臭味,水管有臭味怎麼辦|做法
開頭=排水孔有臭味，可以這樣處理：
步驟=很久沒用的排水孔先倒一大桶水，讓下面的「存水彎」重新有水擋住臭味；把毛髮、菜渣清掉；倒半杯小蘇打，再倒一杯白醋，放 15 到 30 分鐘，再用熱水沖（不要用滾水，塑膠管會變形）；換一個有防臭功能的排水孔蓋；之後每週用熱水沖一次
提醒=常常很臭、水也流不太下去，可能是管線堵住或設計有問題，要請水電師傅來看
@跳電|家裡跳電怎麼辦,跳電怎麼辦,跳電了,家裡突然沒電,一直跳電怎麼辦,總開關跳掉,電源開關跳掉怎麼辦|生活
開頭=家裡跳電，可以這樣處理：
步驟=先把剛剛在用的大電器關掉、拔插頭（像吹風機、電暖器、微波爐、冷氣）；找到家裡的配電箱（總開關），看哪一個開關跳下來或停在中間；把那個開關先往下推到底，再推回「ON」；如果是「漏電斷路器」跳掉，或推上去馬上又跳，可能有漏電或短路，不要一直硬推，請水電師傅檢查；整棟或整條街都停電，打台電 1911 查詢
提醒=同一個插座不要同時插好幾個大電器，延長線也不要串來串去
@門鎖卡住|門鎖卡住打不開怎麼辦,門鎖卡住怎麼辦,鑰匙轉不動怎麼辦,鎖打不開怎麼辦,鑰匙卡住拔不出來,被鎖在門外怎麼辦,門打不開怎麼辦|生活
開頭=門鎖卡住，可以這樣試：
步驟=先把門往裡或往外輕推、拉一下，再轉鑰匙，有時是門框擠到鎖舌；鑰匙孔噴一點鎖用潤滑劑或石墨粉，不要用食用油，會越黏越卡；鑰匙彎了或磨損，去打一把新的；被鎖在門外，找有登記的鎖匠，正派的鎖匠會核對你的身分和住址才開門；租屋的話先找房東或管理員，可能有備用鑰匙
提醒=不要硬轉鑰匙，斷在鎖孔裡會更麻煩
@殘膠|牆上的殘膠怎麼清,殘膠怎麼清,殘膠怎麼去除,貼紙殘膠怎麼清,膠帶殘膠怎麼清,標籤殘膠怎麼去掉,黏黏的膠怎麼清,牆上的貼紙撕不掉,貼紙撕不掉,膠帶痕跡怎麼去|做法
開頭=殘膠可以這樣清：
步驟=用吹風機熱風吹 30 秒，讓膠變軟，再慢慢撕或刮掉；剩下的用酒精、去漬油或橘油擦，沒有的話用一點護手霜或食用油抹上去，放幾分鐘再擦；小面積可以用橡皮擦搓掉；最後用濕布把油擦乾淨
提醒=牆壁是油漆面的話，先在不明顯的地方試，免得把漆一起擦掉
@床墊清潔|床墊怎麼清,床墊怎麼清潔,床墊髒了怎麼辦,床墊有黃斑怎麼辦,床墊怎麼除塵蟎,床墊多久要換|做法
開頭=床墊可以這樣清：
步驟=先用吸塵器把床墊表面和縫隙吸一遍；整面撒小蘇打粉，放幾個小時，再用吸塵器吸掉，可以除臭；有汙漬的地方，用濕布沾一點中性清潔劑輕輕擦，不要直接倒水，床墊很難乾；打開窗戶通風讓它乾透；每 3 個月把床墊翻面、轉個方向
提醒=鋪一層保潔墊並定期換洗，最省事；床墊一般 8 到 10 年要換
@曬棉被|棉被怎麼曬,曬棉被,棉被要曬多久,棉被要拍嗎,棉被怎麼除塵蟎,被子怎麼曬|做法
開頭=曬棉被可以這樣做：
步驟=挑晴天、空氣乾燥的日子，上午 10 點到下午 3 點最好；兩面都要曬，每面 1 到 2 小時就夠；不要用力拍打，會把纖維打斷，塵蟎屍體碎得更細，輕拍或收回來後用吸塵器吸就好；收之前放涼再摺
提醒=羽絨被、蠶絲被不適合曝曬，掛在陰涼通風的地方晾就好
@洗衣分色|洗衣服要分顏色嗎,洗衣服要分開洗嗎,白色衣服要分開洗嗎,深色衣服要分開洗嗎,衣服會染色嗎,洗衣服怎麼分類|做法
開頭=要，洗衣服分開洗比較不會出問題：
步驟=白色、淺色、深色分開洗，新的深色衣服和牛仔褲前幾次最容易掉色；毛巾、會掉毛的衣服跟深色衣服分開，免得沾上棉絮；內衣褲、貼身衣物可以另外洗；看洗標：要手洗、不能烘的分出來
提醒=不確定會不會掉色，先用白色紙巾沾濕按一下衣服內側，有沾到顏色就單獨洗
@牛仔褲洗法|牛仔褲多久洗一次,牛仔褲怎麼洗,牛仔褲要常洗嗎,牛仔褲可以丟洗衣機嗎,牛仔褲會褪色嗎|做法
開頭=牛仔褲不用穿一次洗一次：
步驟=一般穿 5 到 10 次，或明顯有味道、髒了再洗；洗的時候把褲子翻面、拉鍊扣子扣好，放洗衣袋；用冷水、溫和的行程，深色的單獨洗或跟深色一起洗；不要烘乾，翻面晾在陰涼處，比較不會褪色和縮水
提醒=原色牛仔褲前幾次洗一定要單獨洗，會掉很多色
@口紅沾衣服|口紅沾到衣服怎麼辦,口紅印怎麼洗,衣服沾到口紅,粉底沾到衣服怎麼辦,化妝品沾到衣服怎麼洗|做法
開頭=口紅、粉底沾到衣服，可以這樣洗：
步驟=先用紙巾把表面的口紅輕輕吸起來，不要用力擦，會越擦越大片；在汙漬上塗一點卸妝油或洗碗精，從衣服背面輕輕搓，讓油脂溶出來；放 10 分鐘後用溫水沖；再照平常的方式丟洗衣機洗
提醒=洗完確定乾淨了再烘乾或熨燙，熱會讓汙漬固定下來
@洗球鞋|球鞋怎麼洗,白鞋怎麼洗,布鞋怎麼洗,運動鞋怎麼洗,洗鞋子,鞋子怎麼洗,小白鞋怎麼清|做法
開頭=球鞋可以這樣洗：
步驟=先拆下鞋帶和鞋墊，分開洗；用軟毛刷沾洗碗精或小蘇打加水，刷鞋面和鞋底；白色鞋邊可以用牙膏或科技海綿擦；用乾淨的濕布把泡沫擦掉，不要整雙泡水太久；鞋子裡塞紙巾或報紙吸水，放陰涼通風處晾乾
提醒=白鞋不要曝曬，容易發黃；大部分球鞋不建議丟洗衣機，容易變形、脫膠
@血漬|衣服沾到血怎麼洗,血漬怎麼洗,衣服有血漬,床單沾到血怎麼洗,血跡怎麼洗掉,生理期弄到褲子怎麼洗,經血怎麼洗|做法
開頭=血漬要用冷水洗：
步驟=越快處理越好，馬上用冷水從背面沖，不要用熱水，熱會讓血裡的蛋白質凝固、更難洗；抹肥皂或洗碗精，用手輕輕搓；舊的血漬，先泡冷的淡鹽水或含酵素的洗衣精 30 分鐘再搓；白色衣服還有痕跡，可以用棉花棒沾一點雙氧水點在上面（有顏色的衣服先在內側試）；確定洗乾淨再晾乾，不要烘
提醒=全程用冷水是最重要的一件事
@手機充電慢|手機充電很慢怎麼辦,手機充電好慢,充電速度變慢,手機充電變慢,充電很慢,iPhone充電很慢,手機怎麼充比較快|生活
開頭=手機充電變慢，可以這樣檢查：
步驟=用原廠或有認證的快充頭和線，舊的、便宜的線常常只能慢充；充電孔裡的棉絮灰塵用牙籤輕輕挑出來；充電時不要一直玩遊戲、看影片，開飛航模式會更快；手機太燙會自動降速，拿掉手機殼、放在涼一點的地方充；電池老化也會充得慢、掉電快
提醒=iPhone 可以在「設定 → 電池 → 電池健康度」看電池狀況
@選信用卡|信用卡怎麼選,信用卡要辦哪張,哪張信用卡比較好,第一張信用卡要辦什麼,信用卡推薦,辦信用卡要注意什麼|生活
開頭=選信用卡可以這樣想：
步驟=先看自己最常花錢的地方：網購、超商、加油、餐廳、出國，挑那一類回饋高的；比較年費：很多卡首年免年費，或刷到一定金額就免；看回饋的條件和上限，有的要登錄、有的每月有上限；第一張卡選無腦回饋、免年費的就好，不用一次辦很多張
提醒=信用卡最重要的是每個月全額繳清，循環利息很高，回饋再多都抵不過
@蕁麻疹|蕁麻疹怎麼辦,起蕁麻疹,蕁麻疹,身體起疹子很癢,皮膚突然起一塊一塊,風疹塊怎麼辦,過敏起疹子怎麼辦|健康
開頭=起蕁麻疹，可以這樣處理：
步驟=忍住不要抓，用冷毛巾冷敷止癢；穿寬鬆的棉質衣服，洗澡水不要太熱；想想最近有沒有吃新的食物、藥物，或壓力大、溫差大，先避開可能的誘因；藥局可以買抗組織胺的止癢藥，照說明吃
就醫=嘴唇或眼皮腫起來、喉嚨緊、呼吸困難、頭暈，可能是嚴重過敏，馬上打 119（歐洲 112）；反覆發作超過 6 週，去看皮膚科
@痔瘡|痔瘡怎麼辦,痔瘡,上廁所流血,大便出血,屁股痛,肛門痛,大便有血怎麼辦,痔瘡要看哪一科|健康
開頭=痔瘡可以這樣改善：
步驟=多喝水、多吃蔬菜水果和全穀，讓大便軟一點；上廁所不要滑手機、不要蹲超過 5 分鐘，也不要太用力；每天溫水坐浴 10 到 15 分鐘，可以消腫止痛；避免久坐久站，少吃辣、少喝酒；藥局有痔瘡藥膏或塞劑可以暫時緩解
就醫=出血很多、大便顏色變黑或混著暗紅色的血、痛得很厲害、脫出來推不回去，要看大腸直腸外科；40 歲以上有便血，要檢查排除大腸的問題
@針眼|長針眼怎麼辦,針眼怎麼辦,長針眼,眼皮長顆粒,眼皮腫一顆,麥粒腫怎麼辦,針眼要多久才會好|健康
開頭=長針眼可以這樣處理：
步驟=用乾淨的溫熱毛巾熱敷眼皮，一次 10 到 15 分鐘，一天 3 到 4 次；不要擠、不要揉，免得感染擴散；這幾天先不要化眼妝、不要戴隱形眼鏡；手洗乾淨再碰眼睛；大多一週左右會自己好
就醫=熱敷 3 到 5 天沒改善、越腫越大、整個眼皮紅腫、影響視力或發燒，要去看眼科
@耳鳴|耳鳴怎麼辦,耳鳴,耳朵嗡嗡叫,耳朵一直有聲音,耳鳴是怎麼回事,耳朵有蟬叫聲|健康
開頭=耳鳴常見的原因有噪音、壓力、睡眠不足、耳垢太多或耳朵發炎，可以這樣做：
步驟=先讓耳朵休息，遠離吵雜的環境，耳機音量調小、不要一直戴著；睡飽、放鬆，壓力大時耳鳴常會變明顯；安靜的時候開一點白噪音或輕音樂，比較不會一直注意它；少喝咖啡和酒
就醫=突然一邊耳鳴，又覺得聽不清楚，可能是突發性耳聾，要盡快（最好 72 小時內）看耳鼻喉科；耳鳴超過一週、伴隨頭暈、耳朵痛或流膿，也要去看醫生
@香港腳|香港腳怎麼辦,香港腳,腳很癢,腳趾縫很癢,腳脫皮很癢,足癬怎麼辦,香港腳會傳染嗎,腳底很癢,腳底癢怎麼辦,腳底好癢怎麼辦,腳底很癢怎麼辦|健康
開頭=香港腳是黴菌感染，可以這樣處理：
步驟=藥局可以買抗黴菌的藥膏，洗完腳擦乾後塗，症狀好了之後要再擦 2 到 4 週，不然很容易復發；腳趾縫一定要擦乾，可以用吹風機冷風吹；穿透氣的鞋襪，襪子每天換，鞋子輪流穿、放通風處；毛巾、拖鞋不要跟家人共用，會傳染
就醫=擦藥 2 到 4 週沒改善、紅腫流湯、指甲也變厚變色，或本身有糖尿病，要看皮膚科
@灰指甲|灰指甲怎麼辦,灰指甲,指甲變厚變黃,指甲變色,灰指甲會好嗎,灰指甲會傳染嗎|健康
開頭=灰指甲是指甲的黴菌感染，自己很難擦好，建議這樣做：
步驟=去看皮膚科，確定是不是黴菌感染；醫生會開口服藥或擦的藥，療程很長，手指甲大約 3 到 6 個月，腳趾甲常常要一年，要耐心擦到新的指甲長出來；腳保持乾燥，鞋襪透氣；指甲剪、拖鞋不要跟家人共用
就醫=有糖尿病、指甲周圍紅腫化膿，要盡快就醫
@貓抓傷|被貓抓傷要打針嗎,被貓抓傷怎麼辦,被貓咬傷怎麼辦,被貓抓到要打狂犬病嗎,被流浪貓抓傷,被貓抓傷會怎樣|健康
開頭=被貓抓傷，先這樣處理：
步驟=馬上用肥皂和大量清水沖洗傷口 15 分鐘；用優碘或酒精消毒，擦乾後貼上透氣的 OK 繃；接下來幾天注意有沒有紅、腫、熱、痛或化膿；自己家裡、有打疫苗的貓抓傷，一般不需要打狂犬病疫苗
就醫=傷口很深、流血不止、被流浪貓或野生動物（像鼬獾、白鼻心）咬傷抓傷、幾天後紅腫化膿或淋巴結腫痛發燒，要去看醫生，醫生會評估要不要打破傷風或狂犬病疫苗
@手機發燙|手機很燙怎麼辦,手機發燙,手機變很燙,手機過熱怎麼辦,手機好燙,手機一直發熱,手機很熱怎麼辦|生活
開頭=手機很燙，可以這樣做：
步驟=先暫停在玩的遊戲、影片或導航，把用不到的 App 關掉；如果正在充電，先拔掉，不要邊充邊玩；拿掉手機殼，放在通風、沒有太陽直射的地方；開省電模式、把螢幕亮度調低；等它自然降溫，不要放冰箱或吹冷氣出風口，溫差太大會讓裡面起水氣
提醒=沒在用也一直很燙、電池鼓起來或有怪味，要停止使用，送原廠檢查
@電池健康度|電池健康度多少要換,電池健康度,電池要不要換,手機電池多久要換,手機很快沒電,電池健康度80,iPhone電池要換嗎,手機電池老化|生活
開頭=iPhone 的「電池健康度」掉到 80% 以下，蘋果就建議更換電池：
步驟=在「設定 → 電池 → 電池健康度與充電」可以看到最大容量；低於 80% 會比較耗電、可能突然關機，設定裡也會出現「服務」提醒；Android 手機可以在設定或原廠的支援 App 看電池狀態；手機一天要充兩三次、掉電很快，也是該換的訊號
提醒=換電池到原廠或授權維修中心比較有保障，保固內或有加購保險可能比較便宜
@手機備份|手機怎麼備份,手機要怎麼備份,iPhone怎麼備份,安卓怎麼備份,Android怎麼備份,手機資料怎麼備份|生活
開頭=手機可以這樣備份：
步驟=iPhone：設定 → 最上面的名字 → iCloud → iCloud 備份，打開後接 Wi-Fi 充電時會自動備份；空間不夠也可以接電腦，用 Mac 的 Finder 或 Windows 的 iTunes 備份；Android：設定 → Google（或系統）→ 備份，打開「Google One 備份」；照片可以另外開 Google 相簿或 iCloud 照片的自動備份；LINE 的聊天記錄要在 LINE 裡另外備份
提醒=重要的照片最好存兩個地方，例如雲端加一顆隨身硬碟
@Word頁碼|Word怎麼插入頁碼,Word頁碼怎麼加,Word怎麼加頁碼,Word頁碼,Word第一頁不要頁碼|做法
開頭=Word 插入頁碼可以這樣做：
步驟=點上方的「插入」→「頁碼」；選要放在頁首或頁尾，以及靠左、置中、靠右；想改格式（像 1、i、A）點「頁碼格式」；第一頁是封面不想要頁碼：在頁首頁尾的工具裡勾「第一頁不同」；做完按「關閉頁首及頁尾」或按 Esc 回到內文
提醒=Mac 版的 Word 選單位置差不多，也在「插入 → 頁碼」
@帳號被盜|FB帳號被盜怎麼辦,LINE被盜用了,LINE被盜用,LINE帳號被盜,LINE被盜,Facebook帳號被鎖,臉書帳號被鎖,臉書帳號被盜怎麼辦,IG帳號被盜怎麼辦,帳號被盜怎麼辦,Facebook被盜,Instagram被盜,LINE帳號被盜怎麼辦,帳號被駭怎麼辦|生活
開頭=帳號被盜，先照這個順序處理：
步驟=還登得進去：馬上改密碼、打開兩步驟驗證，登出所有不認得的裝置；登不進去：Facebook 到 facebook.com/hacked，Instagram 在登入頁點「忘記密碼」或「取得登入協助」，照步驟用信箱、手機或自拍影片驗證身分；檢查綁定的信箱和手機號碼有沒有被改；用其他方式告訴親友：帳號被盜了，有人借錢、要點數或傳連結都不要理；同一組密碼用在別的網站的，也要一起改
提醒=以後每個網站用不同的密碼，再加上兩步驟驗證，就很難被盜
@VPN|什麼是VPN,VPN是什麼,VPN是什麼意思,VPN要做什麼,VPN安全嗎,要不要用VPN|生活
開頭=VPN（虛擬私人網路）是在你的裝置和網路之間建一條加密的通道：
步驟=它可以保護你在咖啡廳、機場這類公共 Wi-Fi 上網時的資料，不容易被偷看；公司常用 VPN 讓員工在外面也能連回公司內部網路；也有人用來換成別的國家的連線位置；免費的 VPN 要小心，有的會收集或賣你的資料
看法=VPN 不是萬能的，不會讓你變得完全匿名，也擋不住釣魚網站和詐騙
@吃素營養|吃素會營養不良嗎,吃素健康嗎,吃素要注意什麼,吃全素會怎樣,素食者要補充什麼,吃素會缺什麼營養|健康
開頭=吃素只要吃得均衡，不會營養不良，但要注意這幾種營養：
步驟=蛋白質：每餐都要有豆腐、豆干、豆漿、毛豆這類豆製品，蛋奶素也可以吃蛋和乳製品；維生素 B12：幾乎只存在動物性食物，吃全素的人建議吃補充劑；鐵：多吃深綠色蔬菜、豆類，搭配富含維生素 C 的水果幫助吸收；鈣：喝高鈣豆漿、吃深綠色蔬菜、黑芝麻；也可以多吃堅果、亞麻仁籽補充好的油脂
提醒=小孩、孕婦、老人吃全素，最好請營養師幫忙規劃
@喝酒臉紅|喝酒會臉紅是怎樣,喝酒臉紅,為什麼喝酒會臉紅,喝酒臉紅代表什麼,喝酒臉紅是酒量好嗎,一喝酒就臉紅|健康
開頭=喝酒會臉紅，通常是身體分解酒精的能力比較弱：
步驟=酒精在身體裡會先變成「乙醛」，再靠一種叫 ALDH2 的酵素分解掉；很多東亞人這個酵素天生比較弱，乙醛累積就會臉紅、心跳快、頭痛；台灣大約將近一半的人有這種體質，比例是全世界最高之一；這不是酒量好，反而代表乙醛在身體裡停留比較久，喝多了得食道癌、頭頸癌的風險會更高
提醒=一喝就臉紅的人，最好少喝或不喝，不要被勸酒
@買基金|怎麼買基金,基金怎麼買,買基金要注意什麼,基金要怎麼選,第一次買基金,在哪裡買基金|生活
開頭=第一次買基金，可以這樣做：
步驟=找管道：銀行、證券商、投信，或基金平台都可以買，手續費差很多，可以比較一下；開戶時會做「風險屬性評估」，先知道自己能承受多大的漲跌；選基金看：投資什麼（股票、債券、平衡、指數）、各種費用（手續費、經理費）、長期的績效和規模，不要只看去年賺最多的；可以單筆買，或用定期定額每個月固定投入
提醒=基金不保本，看不懂的商品先不要買；想省費用，可以研究跟著大盤走的指數型基金或 ETF
@除權息|什麼是除權息,除權息是什麼,除權息是什麼意思,除息是什麼,除權是什麼,填息是什麼,參加除權息要注意什麼|生活
開頭=除權息是公司把賺到的錢分給股東的日子：
步驟=「除息」是發現金股利，「除權」是發股票股利；要在除權息日的前一個交易日（含）以前買進並持有，才拿得到這次的股利；除權息那天股價會扣掉股利，所以一除息股價就會下降；之後股價漲回除息前的價位，叫做「填息」或「填權」
提醒=股利要繳稅，單筆股利超過 2 萬元還會被扣二代健保補充保費；只為了領股利搶在除息前買，不一定划算
@緊急預備金|緊急預備金要存多少,緊急預備金,預備金要存多少,緊急備用金要多少,應該存多少錢在身上,要存多少錢才安全|生活
開頭=緊急預備金一般建議存「3 到 6 個月的生活必要開銷」：
步驟=先算每個月一定要花的錢：房租或房貸、伙食、交通、保險、水電電話；乘上 3 到 6 就是目標，例如一個月 3 萬元，就是 9 萬到 18 萬；收入不穩定（接案、業務）、家裡只有一份收入，或有小孩長輩要照顧的，最好存 6 個月以上；放在隨時領得出來的活存或數位帳戶，不要拿去投資
提醒=先存好緊急預備金再開始投資，遇到失業或急事才不用賠本賣掉股票
@信用貸款|怎麼申請信用貸款,信用貸款怎麼申請,信貸怎麼辦,怎麼辦信貸,信貸要準備什麼,信貸要注意什麼|生活
開頭=申請信用貸款，可以這樣準備：
步驟=先準備身分證、第二證件，和收入證明（薪資轉帳存摺、扣繳憑單或在職證明）；先問自己的薪轉銀行，條件通常比較好；比較各家的「總費用年百分率」，它把利率和手續費、帳管費都算進去，比只看利率準；算清楚每月要還多少，最好不要超過月收入的三分之一；同時去好幾家銀行申請，聯徵次數太多反而會影響審核
提醒=要你先付手續費、交出存摺提款卡的「代辦」，很可能是詐騙
@學貸還款|學貸怎麼還,就學貸款怎麼還,學貸什麼時候開始還,學貸要還多久,學貸還不出來怎麼辦,就學貸款還款|生活
開頭=就學貸款大概這樣還：
步驟=畢業（或退伍）後滿一年開始還，繼續念研究所或服兵役可以延後；還款年限大致是「借幾個學期，就分幾年還」，按月攤還；到當初借款的銀行還（大多是台灣銀行），可以臨櫃、ATM 轉帳或設定自動扣款；收入比較低、一時還不出來，可以向銀行申請緩繳或延長還款，條件以教育部最新規定為準
提醒=不要放著不繳，逾期會影響信用紀錄，以後辦信用卡、房貸都會受影響
@勞退自提|什麼是勞退自提,勞退自提是什麼,勞退自提要不要提,勞退自提好嗎,勞退自願提繳,勞退6%自提|生活
開頭=勞退自提是自己每個月再從薪水多存一點到勞退個人帳戶：
步驟=老闆本來就要每月幫你提繳薪水的 6% 到勞退專戶；你可以另外「自願提繳」0 到 6%，從薪水直接扣；自提的金額可以從當年度的所得裡全部扣除，等於這部分先不用繳所得稅；這筆錢由勞動基金運用，政府保證最低收益（不低於二年期定存利率），60 歲以後才能領
看法=所得稅率比較高、又不急著用這筆錢的人，自提比較划算；手頭緊、隨時需要現金的人就不一定要提
@遷戶口|怎麼遷戶口,遷戶口要帶什麼,遷戶籍怎麼辦,戶口要怎麼遷,遷入登記,戶籍遷移|生活
開頭=遷戶口（遷入登記）這樣辦：
步驟=搬家後 30 天內辦理，到新住址所在地的戶政事務所（很多地方可以跨區辦）；帶身分證、印章（或簽名）；遷進別人的戶，要帶那一戶的戶口名簿，並取得戶長同意；遷到自己買或租的房子，帶房屋所有權狀或租約，租屋要有屋主同意；舊地址的遷出會一起辦好，不用另外跑
提醒=遷完戶籍，駕照、行照、銀行和信用卡的地址也記得一起改
@結婚登記|結婚登記要帶什麼,結婚登記怎麼辦,怎麼辦結婚登記,結婚登記,登記結婚要準備什麼,去戶政事務所結婚要帶什麼|生活
開頭=在台灣辦結婚登記，要準備：
步驟=雙方本人一起到任一個戶政事務所；身分證、印章（或簽名）、戶口名簿；結婚書約：要有兩位證人簽名蓋章，戶政事務所可以拿到表格；要換新的身分證（配偶欄會更新），帶一張近 6 個月的 2 吋照片；外籍配偶要另外準備經過驗證的文件，先打去戶政事務所問清楚
提醒=台灣是「登記才生效」，只有請客沒有登記，法律上還不算結婚
@出生登記|出生登記怎麼辦,報戶口怎麼辦,新生兒報戶口,寶寶報戶口要帶什麼,出生登記要帶什麼,小孩報戶口|生活
開頭=寶寶出生後，要這樣辦出生登記：
步驟=出生後 60 天內，到任一個戶政事務所辦理；帶醫院開的出生證明書、申請人的身分證和印章、戶口名簿；先想好名字，父母要決定孩子的姓；辦好後就可以接著辦健保卡，再申請育兒津貼、生育補助
提醒=有些醫院和戶政事務所有「出生通報」連線，辦起來更快，可以先問醫院
@驗車|汽車多久要驗車,汽車要多久驗一次,車子多久要驗車,驗車,車子要驗車嗎,新車要驗車嗎,機車要驗車嗎,機車排氣定檢|生活
開頭=自用小客車的定期驗車大概這樣：
步驟=出廠 5 年內不用驗車；出廠滿 5 年到 10 年，每年驗一次；滿 10 年以上，每年驗兩次；到期前後一個月內，到監理站或代檢廠驗，監理單位會寄通知；機車出廠滿 5 年，每年要做排氣定期檢驗，在環保局認證的機車行就可以做
提醒=逾期沒驗會被罰款，太久沒驗還可能被吊銷牌照
@牌照稅|牌照稅什麼時候繳,汽車牌照稅什麼時候繳,使用牌照稅什麼時候繳,牌照稅幾月繳,牌照稅怎麼繳|生活
開頭=使用牌照稅大概這樣繳：
步驟=自用汽車每年繳一次，期間是 4 月 1 日到 4 月 30 日；營業用車分兩期，4 月和 10 月；排氣量 150cc 以下的機車不用繳牌照稅；繳費單會寄到車籍地址，可以在超商、銀行、網路或用信用卡、行動支付繳
提醒=牌照稅和燃料費是兩筆不一樣的錢，燃料費是另外繳的
@燃料費|燃料稅什麼時候繳,燃料費什麼時候繳,汽車燃料費什麼時候繳,汽燃費什麼時候繳,燃料稅幾月繳,汽車燃料使用費|生活
開頭=汽車燃料使用費（俗稱燃料稅）大概這樣繳：
步驟=自用小客車每年繳一次，期間是 7 月 1 日到 7 月 31 日；營業車按季繳；機車的燃料費照監理單位寄的繳費通知繳；可以在超商、郵局、銀行、監理服務網或用信用卡、行動支付繳
提醒=4 月繳的是牌照稅，7 月繳的是燃料費，兩筆都要繳
@停車費|路邊停車費怎麼繳,停車費怎麼繳,停車單怎麼繳,路邊停車單怎麼繳,停車費逾期怎麼辦,路邊停車怎麼付錢|生活
開頭=路邊停車費可以這樣繳：
步驟=拿著停車繳費單，到便利商店掃條碼繳；用各縣市的停車繳費網站或 App，輸入車號查詢後線上付；很多縣市可以綁定行動支付或信用卡自動扣款，以後不用自己繳；照單子上的期限繳，過期會寄催繳單，還可能加收工本費
提醒=停車費是「停車費」，不是罰單；但超過期限一直不繳，可能會被罰款
@拖吊|車子被拖吊怎麼辦,車被拖吊怎麼辦,機車被拖吊怎麼辦,車子不見了,拖吊場在哪,被拖吊要帶什麼|生活
開頭=車子不見了，可能是被拖吊，可以這樣處理：
步驟=先看原地的地上或牆上有沒有寫拖吊場的位置，或打 110、1999 查詢是不是被拖吊，不是的話就要報案（可能被偷）；到拖吊場領車，帶駕照、行照（或身分證）；要繳拖吊費和保管費，違規停車的罰單通常會一起開；領車時先檢查車子有沒有刮傷，有問題當場反映
提醒=越晚領保管費越多，確認被拖吊後盡快去領
@生育給付|生育津貼怎麼申請,生育補助怎麼申請,生育給付怎麼申請,勞保生育給付,生小孩有什麼補助,生育補助有多少|生活
開頭=生小孩可以申請的補助，常見的有這些：
步驟=有勞保的媽媽：向勞保局申請「生育給付」，參加勞保滿 280 天後生產（或滿 181 天後早產）可以領，一次發 2 個月的平均月投保薪資，雙胞胎以上加倍；沒有勞保但有國民年金的，可以申請國保的生育給付；很多縣市政府另外有生育津貼或生育獎勵金，向戶籍地的區公所申請，金額各縣市不同；可以上勞保局網站、e 化服務系統或臨櫃申請
提醒=之後還有育兒津貼、育嬰留職停薪津貼，每一項的申請條件和期限不一樣，建議先查勞保局和縣市政府最新的公告
@勞資糾紛|勞資糾紛怎麼申訴,勞資糾紛怎麼辦,怎麼檢舉公司違法,公司違反勞基法怎麼辦,老闆違法怎麼檢舉,勞資爭議調解,怎麼申訴公司|生活
開頭=遇到勞資糾紛，可以這樣處理：
步驟=先把證據留好：薪資單、打卡紀錄、勞動契約、LINE 和 email 的對話、班表；打勞動部的 1955 專線，可以諮詢也可以申訴，免費、可以匿名；到公司所在地的縣市政府勞工局（勞動局）申請「勞資爭議調解」，不用錢，雙方坐下來談；調解不成，可以找法律扶助基金會（412-8518）諮詢，再考慮提告
提醒=申訴、檢舉是法律保障的權利，公司不能因此開除你或對你不利
@房東不修|房東不修東西怎麼辦,房東不修怎麼辦,租屋東西壞了誰要修,租房子壞了誰修,房東不處理怎麼辦,租屋漏水房東不修|生活
開頭=租屋的東西壞了，大多是房東要修，可以這樣處理：
步驟=依民法，租的房子和設備要維修，除了合約另外寫清楚的以外，原則上是房東負責；先拍照、錄影，用 LINE 或簡訊通知房東，寫清楚哪裡壞、什麼時候壞，並給一個合理的期限請他修；期限過了還不修，可以自己請人修，留好收據，請房東付錢或從房租裡扣；談不攏可以到區公所申請調解，或打 1999 問市政府的租屋服務
提醒=如果是你自己弄壞的，就要自己負責修；搬進去前拍照記錄房子的狀況，最能保障自己
@狗掉毛|狗狗掉毛很多怎麼辦,狗掉毛很多,狗狗一直掉毛,狗掉毛怎麼辦,狗狗換毛,狗毛到處都是怎麼辦|生活
開頭=狗狗掉毛多，可以這樣處理：
步驟=換季（春秋）掉毛多是正常的換毛期，每天用針梳或排梳梳毛，把廢毛梳掉，家裡的毛會少很多；吃營養均衡的飼料，可以問獸醫要不要補充魚油；洗澡不要太頻繁，用狗專用洗毛精；家裡用滾筒黏毛器、吸塵器勤清理
就醫=如果掉到一塊一塊禿掉、皮膚紅腫、很癢一直抓、有皮屑或異味，可能是皮膚病、黴菌或寄生蟲，要帶去看獸醫
@狗吃大便|狗吃大便正常嗎,狗狗吃大便,狗吃自己的大便,狗會吃大便,狗狗為什麼吃大便,狗吃大便怎麼辦|生活
開頭=狗吃大便（食糞）在幼犬很常見，通常可以改善：
步驟=常見原因：好奇模仿、無聊、肚子餓、消化吸收不好，或是被罵過而想「湮滅證據」；牠一上完廁所就馬上清掉，不給機會；不要打罵，看到牠要吃時叫牠過來、給零食獎勵，轉移注意力；多帶牠散步、玩耍，減少無聊；檢查飼料的份量和品質
就醫=原本不會、突然開始吃，或同時體重變輕、拉肚子、食慾變很大，要帶去看獸醫，排除寄生蟲或消化的問題
@貓洗澡|貓需要洗澡嗎,貓要洗澡嗎,貓多久洗一次澡,怎麼幫貓洗澡,貓咪要洗澡嗎,幫貓洗澡|生活
開頭=貓會自己理毛，室內貓一般不需要常洗澡：
步驟=大約幾個月洗一次，或弄髒、有味道的時候再洗；長毛貓、年紀大理毛不方便的貓，可能要比較常洗；要洗的話用溫水、貓專用的洗毛精，避開臉和耳朵，動作要快；洗完一定要用毛巾和吹風機吹乾，不然容易感冒、長黴菌；平常多梳毛，可以減少毛球和掉毛
提醒=很怕水的貓不要硬洗，可以用寵物濕紙巾局部擦，或交給寵物美容
@幫狗剪指甲|怎麼幫狗剪指甲,狗指甲怎麼剪,幫狗剪指甲,狗狗指甲要剪嗎,狗指甲多久剪一次,剪狗指甲流血怎麼辦|生活
開頭=幫狗剪指甲可以這樣做：
步驟=用寵物專用的指甲剪，準備止血粉和零食；淺色指甲可以看到裡面粉紅色的「血線」，只剪前端尖尖的部分，不要剪到血線；黑色指甲看不到血線，每次只剪一點點，看到切面中間出現濕濕的黑點就停；一次不用全部剪完，邊剪邊給零食；大約 2 到 4 週剪一次，走路時指甲碰地有喀喀聲就是太長了
提醒=不小心剪到流血，用止血粉或乾淨的紗布壓住幾分鐘就會止血
@貓吃鮪魚罐頭|貓可以吃鮪魚罐頭嗎,貓可以吃鮪魚嗎,貓吃鮪魚罐頭,貓可以吃人吃的罐頭嗎,貓可以吃魚罐頭嗎|常識
簡介=人吃的鮪魚罐頭不建議給貓吃：油漬的油太多，鹽水的鈉太高，偶爾吃一小口沒關係，但不要當正餐。長期大量吃鮪魚，可能讓貓缺乏維生素 E、得到「黃脂症」，營養也不均衡
說明=想給貓吃魚，選貓專用的鮪魚罐頭（主食罐），或用水煮、沒有調味的魚肉，去刺後少量給
@寵物走失|寵物走失怎麼辦,狗走失怎麼辦,貓走失怎麼辦,狗不見了,貓不見了怎麼辦,貓跑出去了,狗跑掉了怎麼辦|生活
開頭=寵物走失，可以這樣找：
步驟=馬上在家附近仔細找，貓常常就躲在附近的角落、車底，晚上安靜時帶著牠喜歡的零食輕聲叫牠；通知附近的動物醫院、收容所、各縣市動保處，還有大樓管理員和里長；做協尋海報：清楚的照片、特徵、走失地點、聯絡電話，貼在附近，也發到臉書的走失協尋社團；每天上全國收容所的網站看有沒有被送去；確認寵物登記晶片裡的聯絡電話是最新的
提醒=有人說撿到了卻要你先匯錢，要小心是騙局，見到寵物再說
@狗上廁所訓練|怎麼訓練狗狗上廁所,狗亂尿尿怎麼辦,教狗上廁所,狗狗定點大小便,狗亂上廁所怎麼辦,幼犬上廁所訓練|生活
開頭=訓練狗狗定點上廁所，可以這樣做：
步驟=先決定一個固定的地方（尿布墊或固定帶出門）；起床後、吃飯後、玩完、睡前，帶牠到那個地方，幼犬大約每 2 小時一次；上對地方馬上稱讚、給零食；上錯地方不要罵、也不要壓牠的鼻子去聞，默默用酵素清潔劑把味道清乾淨，不然牠會一直回去那裡上；還沒學會前，先把活動範圍縮小
提醒=大部分狗狗要幾週才能穩定，耐心最重要；成犬突然開始亂尿，要先看獸醫排除泌尿道問題
@養倉鼠|倉鼠要怎麼養,倉鼠怎麼養,養倉鼠要注意什麼,養倉鼠,倉鼠可以吃什麼,倉鼠要準備什麼|生活
開頭=養倉鼠可以這樣準備：
步驟=籠子越大越好，底面積要夠大；鋪厚厚的木屑或紙棉，讓牠可以挖洞；放一個夠大的滾輪、躲藏的小屋、滴水式水瓶，水每天換；主食用倉鼠飼料，可以少量給蘋果（去籽）、紅蘿蔔這類蔬果，不要給洋蔥、大蒜、柑橘、巧克力；倉鼠大多要一隻一隻分開養，黃金鼠養在一起一定會打架
提醒=倉鼠是夜行性動物，白天睡覺不要吵醒牠；壽命大約 2 到 3 年
@養烏龜|烏龜要怎麼養,烏龜怎麼養,養烏龜要注意什麼,烏龜吃什麼,養烏龜,巴西龜怎麼養|生活
開頭=養烏龜可以這樣準備：
步驟=先分清楚是水龜還是陸龜，養法不一樣；水龜的缸要有水區，也要有可以爬上去曬背的陸地；放 UVB 燈和加溫燈，或每天讓牠曬一點太陽，不然殼會軟、生病；水要保持乾淨，加過濾器、定期換水；水龜吃烏龜飼料加一點蔬菜，陸龜主要吃高纖的草和蔬菜
提醒=烏龜可以活很多年，不能養了也不要放生到河裡（巴西龜是外來種）；摸完烏龜要洗手
@魚缸換水|魚缸多久換水,魚缸怎麼換水,魚缸要多久換一次水,魚缸換水,魚缸水很髒怎麼辦,養魚要換水嗎|生活
開頭=魚缸換水可以這樣做：
步驟=有過濾器的魚缸，一般每週換掉四分之一到三分之一的水就好，不要一次全部換掉，魚會受不了；新的自來水要先除氯：放一兩天曬一曬，或加除氯劑；新水的溫度要跟缸裡的差不多；過濾棉用換下來的舊缸水洗，不要用自來水沖，會把好菌洗掉；沒有過濾器的小魚缸要換得更勤
提醒=魚一直浮在水面大口呼吸、水變混濁有臭味，就是水質不好了
@養兔子|養兔子要注意什麼,兔子怎麼養,兔子吃什麼,養兔子,養兔子要準備什麼|生活
開頭=養兔子要注意這些：
步驟=主食是牧草（像提摩西草），要隨時吃得到，兔子的牙齒會一直長，靠吃草磨牙；兔子飼料和蔬菜少量就好，不要給甜食、巧克力、洋蔥；不要抓耳朵把牠提起來，要一手托屁股一手扶胸口；兔子很怕熱，室溫超過 28 度要開冷氣；每天讓牠出來活動、跑一跑
提醒=母兔不結紮，年紀大了子宮的疾病很常見，可以問獸醫什麼時候結紮；兔子大約可以活 8 到 12 年
@狗狗中暑|狗狗中暑怎麼辦,狗中暑怎麼辦,狗中暑,貓中暑怎麼辦,寵物中暑,狗熱到一直喘,狗狗中暑症狀|生活
開頭=狗狗中暑要馬上處理：
步驟=立刻移到陰涼通風的地方，開電風扇或冷氣；用常溫的水（不要用冰水）弄濕牠的腳掌、肚子、腋下和脖子，幫牠散熱；給牠少量的水，不要強灌；處理完馬上送獸醫，就算看起來好了，內臟也可能受傷
就醫=大口喘氣、一直流口水、牙齦變很紅或發紫、站不穩、嘔吐，都是中暑的徵兆，要盡快就醫；夏天不要在中午散步，也絕對不要把狗留在車上
@挑洗衣機|洗衣機怎麼挑,洗衣機要買哪種,直立式還是滾筒式,洗衣機要買幾公斤,滾筒洗衣機好嗎,挑洗衣機,買洗衣機要注意什麼|生活
開頭=挑洗衣機可以這樣看：
步驟=直立式：比較便宜、洗得快、洗淨力強；滾筒式：省水、比較不傷衣服，常有烘乾功能，但比較貴、洗得比較久；容量：一個人大約 10 公斤，一家三四口 13 到 15 公斤，想洗棉被選 15 公斤以上；選變頻的比較省電、安靜，看能源效率標章，1 級最省電；買之前先量好放的位置和門的寬度
提醒=滾筒洗衣機的門邊橡膠圈要常擦乾，不然容易發霉
@跟爸媽吵架|跟爸媽吵架怎麼辦,和爸媽吵架,跟媽媽吵架,跟爸爸吵架,跟爸媽吵架,跟父母吵架,和媽媽吵架了,跟媽媽說話總是吵起來,跟媽媽一講話就吵架,跟爸爸一講話就吵|生活
開頭=跟爸媽吵架了，可以這樣做：
步驟=先讓自己冷靜下來，可以先回房間，不要在氣頭上說更傷人的話；想想他們在意的是什麼，爸媽很多時候是擔心，只是說話的方式讓人不舒服；等大家都冷靜了，找時間好好談，用「我覺得…」說自己的感受，也聽聽他們的想法；先為自己不好的態度道歉，不代表你就認輸了；當面說不出口，可以傳訊息或寫張卡片
看法=家人之間的吵架，常常是因為太在乎彼此；把話說開，通常比冷戰好
@小孩不吃青菜|小孩不吃青菜怎麼辦,小孩不吃菜,孩子不吃蔬菜,小孩不愛吃青菜,小孩很挑食|生活
開頭=小孩不吃青菜，可以這樣試：
步驟=大人自己先吃，讓孩子看到大家都吃青菜；讓他一起買菜、洗菜、幫忙煮，自己參與的比較願意吃；切小、混進他喜歡的東西，像炒飯、水餃、蛋餅、咖哩；每次給一點點，一種新的菜常常要試 8 到 15 次才會接受；不要逼、不要罵，也不要用「吃完才有甜點」交換
看法=挑食大多是一個階段，餐桌的氣氛輕鬆，孩子反而比較願意嘗試
@小孩自己睡|小孩幾歲可以自己睡,小孩幾歲分房睡,小孩什麼時候自己睡,孩子分房睡,怎麼讓小孩自己睡,小孩不敢自己睡怎麼辦|生活
開頭=小孩幾歲自己睡沒有標準答案，大概可以這樣抓：
步驟=嬰兒建議至少到 6 個月（最好 1 歲）跟爸媽同房、但睡自己的嬰兒床，比較安全；很多家庭在 3 到 6 歲之間開始分房，看孩子和家裡的狀況；可以分階段：先同房分床，再分房；建立固定的睡前儀式：洗澡、刷牙、講故事、說晚安；留一盞小夜燈、讓他抱喜歡的娃娃，半夜來找你時溫和地陪他回房
看法=不用跟別人比早晚，孩子覺得安心，自然就能自己睡
@小孩打人|小孩打人怎麼辦,孩子打人怎麼辦,小孩會打人,小孩打同學,小孩打爸媽,小孩動手打人|生活
開頭=小孩打人，可以這樣引導：
步驟=當下冷靜但堅定地制止：「我不會讓你打人」，必要時先把他抱開；不要用打他來教他不能打人；等他冷靜後，幫他說出感覺：「你很生氣，因為他拿走你的玩具」；教他可以怎麼做：用說的、走開、深呼吸、找大人幫忙；再陪他去關心、道歉被打的人；觀察常在什麼時候打人（累了、餓了、搶東西），提前預防
提醒=常常打人、怎麼教都沒改善，可以找兒童心智科或早療評估，早點幫忙比較好
@新生兒喝奶|新生兒多久喝一次奶,新生兒一天喝幾次奶,寶寶多久喝一次奶,新生兒喝多少奶,嬰兒多久餵一次奶,新生兒奶量|健康
開頭=新生兒喝奶大概這樣抓：
步驟=新生兒大約每 2 到 3 小時喝一次，一天 8 到 12 次；餵母乳的寶寶照他的需求餵，不用太看時間；配方奶剛開始每次大約 30 到 90 毫升，隨著長大慢慢增加；看寶寶餓了的訊號：轉頭找奶、吸手、嘴巴張張的，哭通常已經是很餓了；有沒有喝夠：一天有 6 片以上濕的尿布、體重有正常增加
就醫=尿布很少、精神很差、一直不喝奶、皮膚和眼白越來越黃，要盡快帶去看小兒科
@嬰兒喝水|嬰兒可以喝水嗎,寶寶可以喝水嗎,新生兒可以喝水嗎,嬰兒要喝水嗎,寶寶幾個月可以喝水,寶寶要喝水嗎|健康
開頭=6 個月以下的寶寶，一般不需要另外喝水：
步驟=母乳和配方奶裡面已經有足夠的水分；太小的寶寶喝太多水，可能影響喝奶的量，嚴重時會造成水中毒；大約 6 個月開始吃副食品後，可以用杯子讓他小口喝一點水；1 歲以後就可以正常喝水了
提醒=天氣熱也是用多餵奶來補水，不用另外餵水
@長輩失智|長輩失智怎麼辦,家人失智怎麼辦,失智症怎麼辦,爸媽失智怎麼辦,失智要看哪一科,阿嬤失智,阿公失智,爸爸記性很差,我爸記性很差,媽媽記性變差,我媽記性很差,長輩記性變差,爸媽常常忘東忘西,老人家記性變差,阿嬤記性很差,阿公記性很差|生活
開頭=家裡長輩疑似失智，可以這樣做：
步驟=先帶去醫院的神經內科、精神科或「記憶門診」檢查，有些記憶變差是可以治療的原因造成的（像甲狀腺、維生素 B12 不足、憂鬱）；常見的警訊：最近的事一下就忘、重複問同樣的問題、迷路、算錢有困難、個性變很多；照顧時說話慢一點、一次說一件事，不要跟他爭對錯；保持規律作息和運動，讓他做還能做的事；可以打長照專線 1966，或台灣失智症協會的關懷專線 0800-474-580 問資源
提醒=照顧失智的家人很辛苦，照顧者也要記得休息，長照有「喘息服務」可以申請
@陪伴長輩|怎麼陪伴長輩,怎麼陪老人家,怎麼孝順爸媽,怎麼陪伴爸媽,陪長輩可以做什麼,長輩很孤單怎麼辦|生活
開頭=陪伴長輩，可以從這些小事開始：
步驟=固定時間打電話或視訊，固定回家吃飯，讓他有期待；多聽他說以前的故事，他會覺得被重視；一起做點事：散步、買菜、拍照、教他用手機和 LINE；讓他參與家裡的決定、請他幫點小忙，長輩會覺得自己被需要；留意他的身體和情緒變化，陪他去看醫生、做健康檢查
看法=陪伴不一定要做什麼大事，常常出現、好好聽他說話，就是最好的禮物
@長輩重複說話|長輩一直重複講同樣的話,老人家一直重複說話,爸媽一直講一樣的事,長輩講話一直重複,阿嬤一直問同樣的問題|生活
開頭=長輩一直重複講同樣的話，可以這樣面對：
步驟=很多時候只是年紀大了記性變差，或是想跟你多聊一點，耐心地回應就好；不要說「你剛剛講過了」，可以換個方式接話，或順著聊下去；如果同時有最近的事一下就忘、迷路、忘記吃飯或吃藥、個性變很多，可能是失智的早期徵兆，要帶去記憶門診檢查
看法=同一個故事講很多次，常常是那件事對他很重要；聽他說，也是一種陪伴
@外籍看護|外籍看護怎麼申請,怎麼申請外籍看護,外勞看護怎麼申請,請外籍看護的條件,申請看護,請看護要怎麼申請|生活
開頭=申請外籍看護，大致的流程是：
步驟=先帶被照顧的人到勞動部指定的醫院做評估，拿到「病症暨失能診斷證明書」，確認符合需要全日照顧的條件（年紀越大條件越寬）；到各縣市的長期照顧管理中心辦理國內媒合，先推介本國看護；沒有媒合成功，再向勞動部勞動力發展署申請招募許可；找合法的仲介，或透過勞動部的直聘中心自己辦，引進看護；看護入國後要做健康檢查、申請聘僱許可，並按月繳就業安定費
提醒=條件和流程常有調整，申請前先打 1955 或上勞動力發展署的網站確認最新規定
@被主管針對怎麼辦|被主管針對怎麼辦,老闆針對我怎麼辦,被主管刁難怎麼辦,主管很難搞怎麼辦,主管很難搞,老闆很難搞怎麼辦,遇到難搞的主管怎麼辦,主管很難相處怎麼辦|生活
開頭=覺得被主管針對，可以這樣處理：
步驟=先冷靜記錄：哪一天、發生什麼事、說了什麼，分辨是針對你，還是他對每個人都這樣；也看看自己的工作有沒有能改進的地方；主動約主管一對一談，問清楚他的期待和標準；交辦的事情用 email 或訊息再確認一次，留下紀錄；如果是辱罵、羞辱、不合理的對待，可以找人資、勞工局或 1955 專線申訴
看法=證據和紀錄是保護自己最好的方法；真的長期待不下去，換部門或換工作也是一種選擇
@不想上班怎麼辦|不想上班怎麼辦|生活
開頭=不想上班的感覺很多人都有，可以這樣想想：
步驟=先分辨是最近太累、還是長期都很排斥；太累就好好休息，請一天特休、週末不要碰工作；找出最不想面對的是什麼：人、工作內容、薪水，還是看不到未來；給自己一點期待：下班後的小獎勵、週末的計畫；如果長期都這樣，可以開始規劃轉調或轉職
就醫=如果同時睡不好、吃不下、對什麼都沒興趣、常常想哭，可能是過勞或憂鬱，可以找身心科或心理諮商聊聊
@寫週報|怎麼寫週報,週報怎麼寫,工作週報怎麼寫,週報要寫什麼,工作報告怎麼寫,日報怎麼寫|學習
開頭=週報可以照這個結構寫：
步驟=本週完成：條列重點成果，能用數字就用數字；進行中：還在做的事和進度；遇到的問題：卡住的地方、需要誰幫忙；下週計畫：接下來要做的 3 到 5 件事；每一點一兩句就好，最重要的寫在最前面
提醒=每天下班前花兩分鐘記下今天做了什麼，寫週報就很快
@拒絕加班|怎麼拒絕主管叫我加班,怎麼拒絕加班,不想加班怎麼拒絕,可以拒絕加班嗎,加班可以不要嗎,主管一直叫我加班|生活
開頭=想拒絕加班，可以這樣說：
步驟=先問清楚這件事有多急、最晚什麼時候要；委婉但清楚地說明：「我今天晚上已經有安排，沒辦法留下來」；提出替代方案：「我明天早上提早來處理」或「我先把最急的 A 做完」；不需要編很多理由，態度誠懇就好；常常被要求加班，可以跟主管討論工作量和人力分配
提醒=依台灣勞基法，延長工時要經過勞工同意，因為健康或正當理由不能加班時，雇主不能強迫；有加班就一定要有加班費或補休
@被扣薪水|被扣薪水怎麼辦,公司亂扣薪水,老闆扣我薪水,薪水被扣,被扣錢怎麼辦,公司罰錢合法嗎,遲到被扣錢|生活
開頭=被扣薪水，可以這樣處理：
步驟=先看薪資單，問清楚扣的是什麼；依勞基法，工資應該全額直接給勞工，公司不能隨便扣薪或罰錢；請假、遲到可以照比例扣那段時間的薪水，但不能用「罰款」扣更多；勞健保、所得稅、勞退自提是依法可以扣的；覺得不合理，保留薪資單、打卡紀錄，打 1955 或到勞工局申訴、申請調解
提醒=簽了同意扣薪的切結書，也不代表公司違法扣薪就變合法
@職場性騷擾|職場性騷擾怎麼辦,被同事性騷擾,被主管性騷擾,公司有人性騷擾,被性騷擾怎麼辦,職場性騷擾怎麼申訴|生活
開頭=在職場遇到性騷擾，可以這樣保護自己：
步驟=安全的話當下明確拒絕：「請不要這樣，我覺得不舒服」；馬上留下證據：訊息截圖、錄音、日期時間地點、在場的人；向公司的申訴管道申訴，公司依法要處理、要保護你，不能因此對你不利；加害人是老闆或主管、公司不處理，可以直接向縣市政府勞工局申訴，也可以打 1955；涉及強迫、碰觸身體，可以報警，或打 113 保護專線
看法=這不是你的錯，不用自己吞下去；找信任的人陪你一起處理
@英文口說|怎麼練習英文口說,英文口說怎麼練,怎麼練英文口說,英文怎麼說得流利,英文不敢開口怎麼辦,怎麼練英文會話|學習
開頭=練英文口說可以這樣做：
步驟=每天花 10 到 15 分鐘大聲唸：跟著影片或 Podcast 一句一句模仿（跟讀法）；用手機錄下自己的聲音，跟原音比較發音和語調；背常用的句型，例如 I was wondering if…、Do you mind if…；自言自語：用英文描述自己正在做的事、今天發生的事；找語言交換、線上家教或 AI 對話練習，習慣開口
看法=口說最大的關卡是不敢說錯；說錯了被糾正，記得最牢
@學測準備|學測怎麼準備,學測要怎麼準備,怎麼準備學測,學測讀書計畫,學測複習,高三怎麼準備學測|學習
開頭=準備學測可以這樣規劃：
步驟=先查好目標科系要採計哪些科目、門檻和倍率，把時間花在對的地方；把高一到高三的範圍排成每週的複習進度，弱的科目多留時間；寫歷屆試題（大考中心網站可以下載），錯的題目整理成錯題本，考前反覆看；考前一兩個月做幾回完整的模擬考，練習時間分配；作息照考試的時間調整，睡飽比熬夜有用
看法=學測考的是理解和觀念，把常錯的地方弄懂，比多寫很多新題目更有效
@申請獎學金|怎麼申請獎學金,獎學金怎麼申請,有什麼獎學金可以申請,哪裡有獎學金,大學生獎學金,申請獎學金要準備什麼|學習
開頭=想申請獎學金，可以這樣找：
步驟=學校：學務處、生輔組、系辦常有公告，校內的獎助學金最好拿；政府：教育部、縣市政府有清寒、原住民、身心障礙等各種獎助；民間：很多基金會、企業、宗教團體每年都有獎學金；準備成績單、清寒證明（有的需要）、申請表、推薦信，照要求寫申請的說明；把截止日期記在行事曆上，很多一年只開一次
提醒=條件寫得清楚的獎學金，申請的人常常比想像中少，符合就去申請看看
@曖昧很久怎麼辦|曖昧很久怎麼辦,曖昧怎麼辦,曖昧要怎麼進一步,我們算什麼關係|生活
開頭=曖昧很久了，可以這樣想想：
步驟=先想清楚自己想要什麼：想在一起，還是其實這樣就好；觀察對方：會不會主動找你、約你、在意你的事；試著讓關係往前一步：約單獨出去、聊聊彼此對感情的想法；直接問也可以：「我很喜歡跟你相處，我們現在算什麼？」；給自己一個停損點，不要一直等
看法=答案不管是什麼，都比一直懸在那裡好；被拒絕會難過，但你就能往前走了
@求婚|求婚要怎麼準備,怎麼求婚,求婚要準備什麼,求婚方法,怎麼求婚比較好,想跟女朋友求婚,想跟男朋友求婚,我想求婚,想要求婚,打算求婚,求婚戒指怎麼選|生活
開頭=求婚可以這樣準備：
步驟=先確定兩個人都有結婚的打算，求婚最好是驚喜，但結婚這件事不要是驚喜；戒指：偷偷借她平常戴的戒指去量尺寸，或先買可以改圍的；選一個對你們有意義的地方，私下或找親友一起都可以，看對方喜歡哪一種；準備想說的話，不用很長，真心最重要；找朋友幫忙拍照錄影，也準備下雨或臨時變化的備案
看法=最讓人感動的通常不是排場，而是你有多了解她
@朋友遲到|朋友一直遲到怎麼辦,朋友每次都遲到,朋友常常遲到,約會對方一直遲到,朋友很愛遲到|生活
開頭=朋友一直遲到，可以這樣處理：
步驟=找個輕鬆的時候直接說出你的感受：「每次等很久，我會有點不開心」；約的時候先說好：「超過 15 分鐘我就先進去吃」；約在可以等的地方，像書店、咖啡廳、商場；跟他約時間時，可以抓早一點；如果怎麼說都不改，就調整自己的期待，重要的場合不要只靠他
看法=說出來不是在吵架，是讓這段友誼走得更久
@被朋友背叛怎麼辦|被朋友背叛怎麼辦|生活
開頭=被朋友背叛真的很痛，可以這樣慢慢處理：
步驟=先允許自己難過、生氣，這是很正常的感受；先不要在氣頭上回擊或公開吵，等冷靜一點再決定；可以把事情問清楚，有時候中間有誤會；想想這段友誼還想不想繼續，你有權利拉開距離；找其他信任的家人朋友聊聊，不要一個人悶著
看法=一個人讓你失望，不代表每個人都不值得信任；看清楚誰會一直在你身邊，也是一種收穫
@買二手車|買二手車要注意什麼,二手車怎麼挑,買中古車要注意什麼,中古車怎麼買,買二手車,二手車要看什麼|生活
開頭=買二手車要注意這些：
步驟=先抓好預算，記得加上過戶費、稅金和保險；看車況：請懂車的朋友或第三方驗車，檢查有沒有撞過、泡過水、引擎和底盤狀況；看保養紀錄，確認里程數有沒有被調過；一定要試開，聽聽有沒有怪聲、煞車和方向盤正不正常；到監理服務網查這台車有沒有欠稅、罰單或被設定動產擔保；簽約寫清楚車況保證和退換的條件，過戶在監理站完成
提醒=價錢比行情便宜很多的，要特別小心是泡水車或事故車
@殺價|怎麼殺價,殺價技巧,怎麼講價,怎麼砍價,買東西怎麼殺價,殺價要怎麼說|生活
開頭=想殺價，可以試試這些：
步驟=先比價，知道行情才知道能砍多少；買多一點、買整組，或問付現有沒有比較便宜；有禮貌地問：「有沒有活動或優惠？」「可以算便宜一點嗎？」；指出小瑕疵或請他送個小東西，也是一種折扣；真的不划算，願意離開，老闆常會叫住你
提醒=夜市、傳統市場、二手店比較能殺價，連鎖店和百貨公司通常是不二價
@外送平台|外送平台怎麼用,外送怎麼叫,怎麼叫外送,Uber Eats怎麼用,foodpanda怎麼用,外送怎麼點,怎麼點外送|生活
開頭=叫外送可以這樣做：
步驟=下載外送 App（像 Uber Eats、foodpanda），用手機號碼或信箱註冊；設定送達地址，寫清楚樓層和備註（例如「放管理室」）；選餐廳、把餐點加進購物車，結帳時看清楚外送費、服務費和小額訂單費；選付款方式：信用卡、行動支付或現金；送出後可以在 App 上看外送員的位置，收到後檢查餐點
提醒=常叫的話可以看看平台的訂閱方案，外送費可能比較省
@搭捷運|怎麼搭捷運,捷運怎麼搭,第一次搭捷運,捷運要怎麼坐,搭捷運要注意什麼,捷運怎麼買票|生活
開頭=第一次搭捷運可以這樣做：
步驟=先看路線圖，找出要去的站、在哪一站轉車；用悠遊卡、一卡通，或在售票機買單程票；進站時在閘門感應票卡，照指標走到要搭的方向的月台；上車前先讓車上的人下來，博愛座留給需要的人；到站後出站感應，跟著出口號碼走
提醒=台北捷運的車站和車廂裡不能吃東西、喝飲料和嚼口香糖，會被罰款
@台鐵訂票|台鐵票怎麼訂,台鐵怎麼訂票,火車票怎麼買,台鐵怎麼買票,怎麼訂火車票,自強號怎麼訂票|生活
開頭=台鐵的票可以這樣買：
步驟=網路：用台鐵的官方網站或「鐵路 e 訂通」App 訂位；超商：7-11 等超商的機台可以訂票、取票；車站：售票窗口或自動售票機；網路訂好後要在期限內付款、取票，不然會被取消；區間車不用訂位，直接用悠遊卡、一卡通進站就可以搭
提醒=連假和節日的票很搶，開放訂票的時間一到就要上網訂
@考汽車駕照|怎麼考汽車駕照,汽車駕照怎麼考,考駕照要怎麼考,考汽車駕照要多久,汽車駕照要考什麼,考駕照流程|生活
開頭=考汽車駕照大概的流程：
步驟=年滿 18 歲，先做體格檢查（醫院或監理站都可以）；大部分人會報名駕訓班，上課大約一個多月，學完在駕訓班考；也可以自己準備：申請學習駕駛證，找有駕照的人陪同練習；考試有筆試（交通規則和號誌，用題庫準備）和路考；考過後拿到駕照，前兩年是「普通駕照」的新手期，要特別小心
提醒=題庫可以在監理服務網下載，考前多寫幾次就很容易過
@加幾號汽油|加油要加幾號,汽油要加幾號,95還是98,車子要加92還是95,機車要加幾號汽油,加錯油怎麼辦|生活
開頭=加幾號汽油，看車子原廠的建議：
步驟=看車主手冊，或打開油箱蓋，內側常貼著建議的汽油種類；台灣的無鉛汽油有 92、95、98，大部分的車加 95 就可以；高壓縮比的引擎或部分進口車會要求 95 或 98；加比建議更高的號數，沒有明顯的好處；機車大多加 92 或 95，照車廠的建議
提醒=柴油車和汽油車絕對不能加錯；加錯了不要發動引擎，直接請拖車和保養廠處理
@爆胎|爆胎怎麼辦,開車爆胎怎麼辦,輪胎爆了怎麼辦,高速公路爆胎,機車爆胎怎麼辦,輪胎沒氣了怎麼辦|生活
開頭=開車爆胎，要這樣處理：
步驟=雙手握緊方向盤，不要急踩煞車，慢慢放開油門讓車子減速；打方向燈，把車慢慢停到路肩或安全的地方；打開雙黃燈，在車後方放三角警示架（高速公路要放在 100 公尺外）；人移到護欄外，不要站在車子旁邊或後面；會換備胎就換，不會的話打保險公司的道路救援，高速公路可以打 1968
提醒=騎機車爆胎也一樣：不要急煞，握穩龍頭，慢慢減速靠邊
@地震包|地震包要準備什麼,緊急避難包要準備什麼,防災包要放什麼,避難包內容,緊急避難包,地震包|生活
開頭=緊急避難包（地震包）可以準備這些：
步驟=水和食物：每人至少 3 天的飲用水和不用煮的乾糧；照明和通訊：手電筒、備用電池、行動電源、收音機；醫療：急救包、常備藥、慢性病的藥；證件影本、一點現金（小鈔和零錢）；口罩、雨衣、保暖衣物、哨子、衛生用品
提醒=包包放在門口附近，每半年檢查一次水和食物有沒有過期
@打雷洗澡|打雷可以洗澡嗎,打雷可以用手機嗎,打雷的時候要注意什麼,打雷要拔插頭嗎,雷雨天要注意什麼,打雷可以碰水嗎|常識
簡介=打雷時最好先不要洗澡。雷擊有機會順著金屬水管和水傳進屋子裡，機率不高，但等雷雨過去再洗比較保險；也盡量不要用有線電話、不要碰插著電的電器，重要的電器可以拔插頭
說明=在戶外遇到打雷：趕快進室內或車裡，不要躲在大樹下、不要待在空曠的地方或水邊；手機本身不會引雷，但不要在空曠處講電話
@淹水|下大雨淹水怎麼辦,淹水怎麼辦,家裡淹水怎麼辦,豪雨要注意什麼,大雨要準備什麼,淹水要注意什麼|生活
開頭=大雨可能淹水時，可以這樣做：
步驟=注意氣象署的豪雨特報；車子先移到高處，不要停在地下室；把家電、重要的東西和插座附近的物品墊高；用沙包或防水閘門擋住門口；水快淹到插座前，先關掉總電源；不要涉水，水超過膝蓋就很危險，也不要開車穿過淹水的路段；有危險就往高處避難，打 119
提醒=水退了以後，確認電線和插座都乾了、安全了再通電，家裡記得消毒，拍照留存可以申請災害補助
@整理房間|怎麼整理房間,房間很亂怎麼辦,房間怎麼整理,怎麼收拾房間,房間好亂,家裡很亂怎麼整理|生活
開頭=整理房間可以這樣做：
步驟=一次只整理一區，例如今天書桌、明天衣櫃，不要一次全部攤開；把那一區的東西全部拿出來，分成「留下、丟掉、送人、還沒決定」；每樣東西都有固定的位置，用收納盒分類；最常用的東西放在最好拿的地方；每天睡前花 5 到 10 分鐘把東西放回原位
看法=整理最難的是開始，先整理一個抽屜，就會有動力了
@家裡有老鼠|家裡有老鼠怎麼辦,家裡有老鼠,怎麼抓老鼠,怎麼趕老鼠,老鼠怎麼處理,天花板有老鼠|生活
開頭=家裡有老鼠，可以這樣處理：
步驟=找出老鼠進來的洞和縫隙，用鋼絲絨、水泥或防鼠網封起來；食物都要密封，垃圾桶加蓋，廚餘每天清掉；在牆邊、老鼠常走的路線放捕鼠籠或黏鼠板；家裡有小孩和寵物，用老鼠藥要特別小心；嚴重的話找合格的除蟲公司處理
提醒=清老鼠屎要戴口罩和手套，先噴稀釋的漂白水再擦，不要用掃把直接掃，避免感染漢他病毒
@冷氣不冷|冷氣不冷怎麼辦,冷氣不涼怎麼辦,冷氣吹不涼,冷氣變不冷,冷氣開了還是很熱,冷氣冷度不夠|生活
開頭=冷氣不冷，可以先這樣檢查：
步驟=看遙控器是不是開到送風或除濕模式，溫度設定對不對；拆下濾網清洗，濾網太髒是最常見的原因；看室外機有沒有被雜物擋住、是不是被太陽直曬，通風不好就散不了熱；把門窗關好、拉上窗簾；都試過還是不冷，可能是冷媒不足或機器故障，請廠商或冷氣師傅檢查
提醒=冷氣用超過 10 年，常常修不如換一台新的變頻冷氣，比較省電
@電風扇清潔|電風扇怎麼清,電風扇怎麼洗,電扇怎麼清,電風扇怎麼拆,電扇扇葉怎麼洗,電風扇清潔|生活
開頭=電風扇可以這樣清：
步驟=先拔掉插頭；拆下前面的網罩（通常有扣環或螺絲），再拆扇葉，照說明書的方向轉開中間的蓋子；網罩和扇葉用洗碗精加水刷洗，沖乾淨後擦乾或晾乾；馬達和機身不能碰水，用擰乾的濕布擦；全部乾了再裝回去
提醒=夏天常用的話，大約一兩個月清一次，吹出來的風比較乾淨
@空氣清淨機|空氣清淨機有用嗎,空氣清淨機有效嗎,需要買空氣清淨機嗎,空氣清淨機要開多久|常識
簡介=有用。用 HEPA 濾網的空氣清淨機，能濾掉 PM2.5、花粉、塵蟎、寵物毛屑，對過敏的人特別有幫助；想去除異味、甲醛，要有活性碳濾網
說明=挑的時候看適用坪數（選比房間大一點的）和 CADR 值（越高越快）；濾網要照說明定期換；它不能取代開窗通風，二氧化碳還是要靠通風換氣
@牛排熟度|牛排要煎幾分熟,牛排幾分熟比較好吃,牛排幾分熟,怎麼煎牛排比較好吃,牛排熟度怎麼分|做法
開頭=牛排的熟度大概這樣分：
步驟=三分熟：中心是紅色、溫溫的，肉最嫩多汁；五分熟：中心粉紅，最多人點，軟嫩又不會太生；七分熟：中心只剩一點點粉紅，口感比較紮實；全熟：完全沒有粉紅色，比較乾硬；在家煎：牛排先退冰、擦乾、撒鹽，鍋子燒到很熱，每面煎 1 到 3 分鐘看厚度，起鍋後靜置 5 分鐘再切
提醒=孕婦、小孩和免疫力比較差的人，建議吃全熟的
@火鍋|怎麼煮火鍋,在家煮火鍋,火鍋湯底怎麼煮,火鍋料要買什麼,自己煮火鍋|做法
開頭=在家煮火鍋可以這樣準備：
步驟=湯底：高麗菜、洋蔥、玉米、白蘿蔔先下去煮出甜味，可以加昆布或大骨，或直接用市售的湯底包；準備料：肉片、海鮮、豆腐、菇類、青菜、火鍋餃類；先放耐煮的（蘿蔔、玉米、餃類），再放肉片和海鮮，青菜最後放；調沾醬：醬油、蔥花、蒜泥、辣椒、沙茶，加一點烏醋或蘿蔔泥
提醒=肉片涮到變色就可以吃，不要煮太久會老；火鍋料一般比較鹹，湯不要喝太多
@麻油雞|麻油雞怎麼做,怎麼做麻油雞,麻油雞做法,麻油雞湯怎麼煮|做法
開頭=麻油雞的做法：
步驟=雞肉切塊，用熱水汆燙去血水、沖乾淨；老薑切片，用黑麻油小火慢慢煸到薑片捲曲、有香味（火不要大，麻油會變苦）；放雞肉下去炒到表面變色；倒米酒（可以全酒或加一半水），煮滾後轉小火燉 20 到 30 分鐘；最後依口味加一點鹽或不加
提醒=傳統的麻油雞酒精多，孕婦、要開車的人可以煮久一點讓酒精揮發，或用一半水
@壽司|怎麼做壽司,壽司怎麼做,捲壽司怎麼做,自己做壽司,壽司飯怎麼做|做法
開頭=在家做捲壽司：
步驟=壽司飯：煮好的白飯趁熱拌入壽司醋（醋 3：糖 2：鹽 1 的比例），用切的方式拌，搧涼；竹簾上鋪海苔，粗糙面朝上；手沾水，把飯薄薄鋪滿海苔，上面留 2 公分不鋪；放餡料：小黃瓜條、玉子燒、肉鬆、蟹肉棒或鮪魚；用竹簾從自己這邊捲起來，捲緊，刀子沾濕再切
提醒=飯不要鋪太厚，捲的時候才不會爆開
@打發鮮奶油|怎麼打發鮮奶油,鮮奶油怎麼打發,打發鮮奶油,動物性鮮奶油怎麼打,鮮奶油打不發|做法
開頭=打發鮮奶油可以這樣做：
步驟=鮮奶油、鋼盆和打蛋器都要先冰過，天氣熱時鋼盆下面墊一盆冰水；加糖（大約鮮奶油重量的 8% 到 10%）；用電動打蛋器先低速再轉中高速打；打到出現紋路、拿起來尖角會彎彎的是「濕性發泡」，適合抹面；再打一下尖角直挺是「乾性發泡」，適合擠花
提醒=打太久會油水分離變成奶油，看到紋路變粗就要停
@宮保雞丁|宮保雞丁怎麼做,怎麼做宮保雞丁,宮保雞丁做法|做法
開頭=宮保雞丁的做法：
步驟=雞腿肉切丁，用醬油、米酒、太白粉醃 15 分鐘；調醬汁：醬油、醋、糖、一點太白粉水；乾辣椒剪段、花椒、蔥段、蒜片準備好；鍋裡放油，先把雞丁炒到變色撈起；用剩下的油小火炒香花椒和乾辣椒，放蔥蒜，雞丁回鍋，倒醬汁快炒，最後放炸花生拌勻
提醒=乾辣椒和花椒要小火炒，炒焦了會苦
@蛤蜊吐沙|蛤蜊怎麼吐沙,蛤蜊吐沙,蛤蠣怎麼吐沙,蛤蜊要泡多久,文蛤怎麼吐沙,蛤蜊怎麼洗|做法
開頭=蛤蜊吐沙可以這樣做：
步驟=蛤蜊先沖洗外殼；泡在鹽水裡，鹽水的鹹度接近海水（大約 1 公升水加 30 公克鹽）；水剛好蓋過蛤蜊就好，放在陰暗的地方，可以蓋上報紙或鍋蓋；泡 1 到 2 小時，中間可以換一次鹽水；煮之前再搓洗一次，張開又碰了不會合起來的就丟掉
提醒=鹽水裡放一根鐵湯匙或鐵釘，有人說吐沙比較快
@煮螃蟹|螃蟹怎麼煮,怎麼煮螃蟹,螃蟹要煮多久,螃蟹怎麼蒸,蒸螃蟹要多久,螃蟹怎麼處理|做法
開頭=蒸螃蟹可以這樣做：
步驟=活的螃蟹先放冷凍 20 到 30 分鐘讓牠昏睡，比較好處理，也不會掉腳；用刷子刷乾淨，特別是腹部和腳的縫；肚子朝上放進蒸鍋，可以鋪幾片薑；水滾後大火蒸，一般大小約 12 到 15 分鐘，大隻的蒸 18 到 20 分鐘，殼全部變紅就熟了；沾醬：薑末加醋和一點糖
提醒=死掉很久的螃蟹不要吃，容易壞
@豬肝|豬肝怎麼煮才嫩,豬肝怎麼煮,豬肝湯怎麼煮,麻油豬肝怎麼做,豬肝怎麼處理|做法
開頭=豬肝要煮得嫩，關鍵是先處理好、快煮：
步驟=豬肝切成大約 0.5 公分的薄片，泡清水 15 到 30 分鐘去血水，中間換幾次水；瀝乾後用米酒、一點太白粉抓醃 10 分鐘；煮湯：水滾後放薑絲，下豬肝，等水再滾、豬肝變色就關火；炒的話也是大火快炒，變色就起鍋
提醒=豬肝煮太久會變硬變柴，看到切面沒有血水、顏色均勻就熟了
@燙青菜|青菜怎麼燙比較綠,燙青菜,怎麼燙青菜,燙青菜要多久,燙青菜怎麼比較好吃,青菜怎麼燙|做法
開頭=燙青菜要又綠又脆，可以這樣做：
步驟=水要多，煮到大滾；水裡加一小撮鹽和幾滴油，菜的顏色會比較翠綠；先放菜梗，等幾秒再放菜葉；葉菜類大約燙 30 秒到 1 分鐘，變軟、顏色變鮮綠就撈起來；撈起來可以泡一下冰水或冷開水，比較不會繼續變黃
提醒=淋上蒜泥、醬油膏、香油或油蔥酥，就是一道燙青菜
@冷凍水餃|冷凍水餃要煮多久,冷凍水餃怎麼煮,水餃要煮多久,冷凍水餃要退冰嗎,水餃怎麼煮才不會破,水餃要煮幾分鐘,水餃煮多久,水餃煮幾分鐘,煮水餃要多久,水餃要煮幾分,冷凍水餃要煮幾分鐘|做法
開頭=冷凍水餃這樣煮：
步驟=不用退冰，直接下鍋；水要多，大滾後放水餃，用湯杓輕輕推一下，免得黏鍋底；水再滾起來時，加一碗冷水，重複 2 到 3 次（「點水」）；水餃全部浮起來、外皮鼓鼓的，大約 6 到 8 分鐘就熟了
提醒=點水可以讓餃子外皮不會煮破、內餡熟透
@雞蛋新鮮|怎麼知道雞蛋新不新鮮,雞蛋新不新鮮怎麼看,怎麼看雞蛋壞了沒,雞蛋壞掉怎麼知道,雞蛋放在水裡浮起來,雞蛋可以放多久|做法
開頭=判斷雞蛋新不新鮮，可以這樣看：
步驟=泡水法：把蛋放進一碗水裡，沉到底躺平的最新鮮；一頭翹起來的放比較久了，要盡快吃；浮起來的蛋不要吃；打開來看：新鮮的蛋黃圓圓鼓鼓的，蛋白濃稠、不會一下攤很開；聞起來有臭味就丟掉
提醒=冷藏的雞蛋大約 2 到 3 週內吃完最好
@地瓜發芽|地瓜發芽可以吃嗎,地瓜發芽還能吃嗎,番薯發芽可以吃嗎,地瓜發芽有毒嗎,地瓜長芽可以吃嗎|生活
開頭=地瓜發芽一般還可以吃（跟馬鈴薯不一樣）：
步驟=地瓜發芽不會產生像馬鈴薯那樣的毒素，把芽切掉就可以煮；但發芽會消耗養分，口感和甜度比較差；如果地瓜有黑斑、變軟、發霉或聞起來苦苦的，可能是長了黑斑病菌，不要吃
提醒=地瓜放在陰涼通風的地方，不要放冰箱，比較不會壞
@日本旅遊注意|第一次去日本要注意什麼,去日本要注意什麼,去日本玩要注意什麼,日本旅遊注意事項,去日本有什麼禁忌,日本旅遊要注意什麼|生活
開頭=第一次去日本，可以注意這些：
步驟=入境：出發前在 Visit Japan Web 填好入境和海關資料，入境時出示 QR code 比較快；交通：買一張 Suica、ICOCA 這類 IC 卡，搭電車、公車、超商都能用；很多小店只收現金，身上帶一些日幣；禮儀：電車上講話小聲、不講電話，排隊照順序；垃圾桶很少，垃圾常要帶著走；不要邊走邊吃，也不用給小費；插頭和台灣一樣是雙平腳，電壓 100V，一般手機充電器可以直接用
提醒=日本常有地震，到了先看一下飯店的避難路線
@韓國旅遊注意|去韓國要注意什麼,去韓國玩要注意什麼,韓國旅遊注意事項,第一次去韓國要注意什麼,韓國有什麼禁忌|生活
開頭=去韓國玩，可以注意這些：
步驟=入境：台灣護照免簽，出發前看清楚是否需要先申請 K-ETA（電子旅行許可，規定會變動）；交通：買 T-money 卡，搭地鐵、公車、計程車和便利商店都能用；地圖 App 用 Naver Map 或 KakaoMap，Google 地圖在韓國的導航功能比較弱；插頭是圓形雙孔、電壓 220V，要帶轉接頭；餐廳的小菜通常可以免費續；不用給小費
提醒=韓國的地鐵博愛座、孕婦座要讓出來，長輩很在意
@泰國旅遊注意|去泰國要注意什麼,去泰國玩要注意什麼,泰國旅遊注意事項,第一次去泰國要注意什麼,泰國有什麼禁忌|生活
開頭=去泰國玩，可以注意這些：
步驟=入境：先查好目前的簽證規定（台灣護照有時免簽、有時要落地簽或電子簽，常有變動）；泰國人很尊敬王室，不要批評或拿來開玩笑；進寺廟要穿有袖子的上衣和過膝的褲裙，進殿要脫鞋；不要摸別人的頭，用腳指人或東西也不禮貌；搭計程車要求跳錶，或用 Grab、Bolt 叫車比較不會被亂喊價；路邊攤的冰塊和生水要小心，容易拉肚子
提醒=泰國天氣熱，記得防曬、多喝水
@國外刷卡|信用卡在國外刷要注意什麼,國外刷卡要注意什麼,出國刷卡要注意什麼,國外刷卡手續費,出國刷信用卡,海外刷卡|生活
開頭=在國外刷信用卡要注意這些：
步驟=海外消費通常有大約 1.5% 的國外交易手續費，可以挑海外回饋高的卡；結帳時選「當地貨幣」付款，不要選台幣（動態貨幣轉換），常常比較貴；出發前確認卡片有開通海外交易，帶兩張不同發卡組織的卡（例如 Visa 和 Mastercard）比較保險；刷卡時卡片不要離開視線，小心被側錄；手機打開消費通知，有不認識的刷卡馬上打給銀行
提醒=保留簽單和收據，回國對帳單比較方便
@生日卡片|生日卡片要寫什麼,生日卡片怎麼寫,生日卡要寫什麼,生日卡片內容,寫生日卡片|生活
開頭=生日卡片可以照這個方式寫：
步驟=開頭稱呼對方，用平常叫他的方式；寫一件你們之間的回憶，或你欣賞他的地方，越具體越動人；送上祝福，例如健康、順利，或祝他完成正在努力的事；結尾加上自己的名字和日期；例如：「生日快樂！謝謝你這一年常常聽我抱怨，跟你一起吃宵夜是我最快樂的時光。祝你新的一歲一切順利，夢想都實現！」
提醒=不用寫很長，真心的一兩句話就很夠
@感謝卡|怎麼寫感謝卡,感謝卡怎麼寫,感謝卡要寫什麼,怎麼寫感謝信,感謝信怎麼寫,謝卡怎麼寫,感謝的話怎麼寫|生活
開頭=感謝卡可以照這個順序寫：
步驟=稱呼對方；具體說謝謝什麼事，例如「謝謝您上次在我搬家時來幫忙」；說說這件事對你的幫助或意義；表達祝福或希望之後再見面；最後署名和日期
提醒=比起很多客套話，寫出一件具體的小事，對方會更感動
@拒絕推銷|怎麼拒絕推銷,怎麼拒絕推銷電話,推銷電話怎麼拒絕,不好意思拒絕推銷,怎麼拒絕業務,怎麼拒絕別人推銷|生活
開頭=想拒絕推銷，可以這樣做：
步驟=直接、有禮貌地說：「謝謝，我不需要」，不用解釋太多理由，理由越多對方越有機會說服你；對方一直說，就重複同一句話，然後結束對話；電話推銷可以說「請把我的號碼從名單移除」，再把號碼封鎖；不要當場簽約、付錢或給個人資料，說要回家想想
提醒=當場被逼著簽的約，要看清楚有沒有猶豫期（像網購、到府推銷有 7 天猶豫期）
@想太多怎麼辦|怎麼不要想太多,怎麼停止想太多,很容易想太多怎麼辦,一直胡思亂想怎麼辦,想太多怎麼辦|生活
開頭=想太多停不下來的時候，可以試試這些：
步驟=把在想的事寫下來，分成「我能做點什麼的」和「我控制不了的」；能做的就定一個最小的下一步，控制不了的先放下；給自己一段固定的「煩惱時間」，例如晚上 15 分鐘，其他時間想到就提醒自己待會再想；把注意力拉回身體：深呼吸、散步、洗個熱水澡；跟信任的人說說，常常一說出來就輕鬆很多
看法=腦袋會一直轉，通常是因為你很在乎；先照顧好自己，事情才看得清楚
@做決定|怎麼做決定,不知道怎麼選,很難做決定怎麼辦,選擇困難怎麼辦,猶豫不決怎麼辦|生活
開頭=做決定卡住的時候，可以這樣幫自己：
步驟=把選項全部寫下來，各列出好處和壞處；問自己：這件事最重要的是什麼（錢、時間、心情、長遠的發展），用它來比；想想最壞的情況，能不能承受；給自己一個期限，不要一直拖；小事可以丟硬幣，丟出來的那一瞬間，你會發現自己其實希望是哪一面
看法=沒有完美的選擇，選了之後好好把它變成對的選擇，比一直猶豫更重要
@放下一個人|怎麼放下一個人,忘不了一個人怎麼辦,怎麼忘記一個人,放不下前任怎麼辦,一直想念一個人怎麼辦,怎麼放下|生活
開頭=想放下一個人需要時間，可以這樣慢慢來：
步驟=允許自己難過，不用急著假裝沒事；減少會勾起回憶的東西：先把照片收起來、取消追蹤或隱藏他的動態；把時間填滿：運動、學新東西、跟朋友見面；寫下想對他說的話，但不用寄出去；想他的時候不要責怪自己，告訴自己「我正在好起來」
看法=放下不是忘記，是想起他的時候，心不再那麼痛了
@走出低潮|怎麼走出低潮,低潮怎麼辦,心情低潮怎麼辦,人生低潮怎麼辦,怎麼走出谷底|生活
開頭=在低潮的時候，可以這樣照顧自己：
步驟=先把生活的基本顧好：睡飽、吃飯、曬太陽、出去走走；把目標縮小，每天完成一件小事就好，例如整理桌子、散步 15 分鐘；跟信任的人聯絡，不用一個人撐著；少滑讓你更沮喪的社群；記錄每天一件還不錯的小事
就醫=低潮持續兩週以上、睡不好吃不下、對什麼都沒興趣，或有不想活的念頭，請找身心科或心理諮商，也可以打 1925 安心專線（24 小時）
@面對批評|怎麼面對別人的批評,被批評怎麼辦,怎麼面對批評,被罵很難過怎麼辦,被別人說壞話怎麼辦|生活
開頭=面對別人的批評，可以這樣處理：
步驟=先不急著反擊或解釋，深呼吸，讓情緒過去；分辨是針對事情的建議，還是單純的攻擊；有道理的部分拿來改進，說聲「謝謝你提醒」；沒道理、只是攻擊的，不用全部吸收，可以直接放下；想想說的人是誰，他的意見對你重不重要
看法=被批評不代表你這個人不好，它只是關於某件事的一個看法
@重訓入門|重訓要怎麼開始,怎麼開始重訓,重訓新手,重量訓練怎麼開始,第一次重訓,重訓要注意什麼,健身怎麼開始,健身房怎麼開始,想開始健身|健康
開頭=重訓可以這樣開始：
步驟=先學好動作，再慢慢加重量，可以請教練或看可靠的教學影片；從大肌群的動作開始：深蹲、硬舉、臥推、划船、肩推；選能做 8 到 12 下的重量，每個動作 3 組，組間休息 1 到 2 分鐘；每週練 2 到 3 次，同一個部位中間休息 48 小時；練完吃點蛋白質，睡飽，肌肉是休息的時候長的
提醒=動作做不標準、會痛就停下來，重量寧可輕一點
@平板支撐|平板支撐怎麼做,棒式怎麼做,plank怎麼做,平板支撐要做多久,棒式要撐多久|健康
開頭=平板支撐（棒式）這樣做：
步驟=趴在地上，手肘放在肩膀正下方，前臂貼地；腳尖撐地，把身體撐起來；從頭、肩、屁股到腳跟保持一直線，不要塌腰也不要把屁股翹太高；肚子和屁股出力，正常呼吸，不要憋氣；新手先撐 20 到 30 秒，做 3 組，慢慢增加時間
提醒=腰開始痠或塌下去就停，姿勢正確比撐很久重要
@騎腳踏車注意|騎腳踏車要注意什麼,騎自行車要注意什麼,騎單車要注意什麼,騎YouBike要注意什麼,騎腳踏車安全|生活
開頭=騎腳踏車要注意這些：
步驟=戴安全帽，晚上開前後燈、穿亮色或有反光的衣服；靠右騎，跟著車流方向，不要逆向；在人行道上要讓行人，慢慢騎；路口看清楚左右，不要搶黃燈，注意右轉的大車有視線死角；不要邊騎邊滑手機或戴耳機
提醒=騎之前捏一下煞車、看輪胎有沒有氣
@國外生病|在國外生病怎麼辦,出國生病怎麼辦,在國外看醫生,出國受傷怎麼辦|生活
開頭=在國外生病或受傷，可以這樣處理：
步驟=小症狀先到藥局買藥，跟藥師說症狀；比較嚴重就去診所或醫院，記得帶護照，打給旅平險的海外急難救助專線，他們可以幫忙找醫院、翻譯；看病時要收據、診斷書和費用明細（要有英文或附翻譯）；回台灣後 6 個月內，可以拿這些文件向健保署申請「自墊醫療費用核退」，再向保險公司申請理賠
提醒=緊急狀況直接打當地的急救電話；也可以聯絡外交部的旅外國人急難救助專線
@選飯店|怎麼選飯店,訂飯店要注意什麼,怎麼挑飯店,怎麼訂房比較便宜,訂房要注意什麼,飯店怎麼挑,怎麼訂飯店比較便宜,訂飯店怎麼比較便宜,飯店怎麼訂比較便宜|生活
開頭=選飯店可以這樣看：
步驟=先看位置：離車站、捷運近，或在要去的景點附近，可以省很多交通時間；看最近的評論，特別是乾淨、隔音、床和服務；比較不同訂房網站和飯店官網的價錢，官網有時更便宜或有加值；看清楚取消規定、有沒有含早餐、是不是另外收稅和服務費；看照片注意房間大小，有的便宜房型沒有窗戶
提醒=訂好後把確認信存在手機，入住時比較順利
@小費怎麼算|小費怎麼算,15%的小費怎麼算,小費要給多少,國外小費怎麼給,美國小費怎麼算,小費要給幾%,10%的服務費怎麼算|生活
開頭=小費可以這樣算：
步驟=用帳單金額乘上百分比：例如帳單 1,000 元給 15% 小費，就是 1,000 × 0.15 = 150 元；心算小技巧：先算 10%（把小數點往左移一位），15% 就是 10% 再加一半，20% 就是 10% 乘 2；美國餐廳一般給 15% 到 20%，服務好可以多一點；很多國家（像日本、台灣）不用給小費，台灣餐廳常直接收 10% 服務費
提醒=有些帳單已經含服務費（service charge），就不用再另外給小費
@分期付款|分期12期每個月要付多少,分期付款怎麼算,分期每個月付多少,分期付款每期多少,信用卡分期怎麼算,零利率分期是什麼,分期付款划算嗎|生活
開頭=分期付款這樣算：
步驟=零利率分期：每期 = 總金額 ÷ 期數，例如 36,000 元分 12 期，每個月付 3,000 元；有利息的分期：要看「總費用年百分率」，總共付的錢會比原價多；信用卡帳單分期常有手續費，先算清楚總共多付多少；分期會佔用信用額度，每期都要準時繳
提醒=告訴我總金額和期數，我可以幫你算每期多少；分期雖然輕鬆，還是要確定每個月付得起
@痛風|痛風怎麼辦,痛風發作怎麼辦,痛風發作,痛風要注意什麼,痛風不能吃什麼,腳趾關節紅腫痛|健康
開頭=痛風是尿酸在關節裡結晶造成的發炎，常發生在大腳趾，發作時可以這樣處理：
步驟=讓痛的關節休息、墊高，可以冰敷，不要熱敷或用力按摩；多喝水；照醫生開的藥吃，不要自己亂吃偏方；平常少喝酒（尤其是啤酒）、少喝含糖飲料，少吃內臟、海鮮、濃肉湯；控制體重，定期抽血追蹤尿酸
就醫=第一次發作、紅腫熱痛很厲害、合併發燒，或一年發作好幾次，要去看醫生（家醫科或風濕免疫科），長期把尿酸控制好才能減少發作
@尿酸高|尿酸高要注意什麼,尿酸高怎麼辦,尿酸太高,尿酸高不能吃什麼,尿酸多少算高|健康
開頭=尿酸偏高（一般超過 7 mg/dL 就算高），可以這樣調整：
步驟=多喝水，幫助尿酸排出；少喝酒和含糖飲料，果糖會讓尿酸升高；少吃內臟、海鮮、濃肉湯、火鍋湯底；體重過重的話慢慢減重，不要突然節食；定期抽血追蹤
就醫=尿酸很高、已經痛風發作過，或有腎結石，要讓醫生評估要不要吃降尿酸的藥
@帶狀皰疹|帶狀皰疹會傳染嗎,帶狀皰疹,皮蛇,皮蛇會傳染嗎,帶狀皰疹怎麼辦,飛蛇怎麼辦,帶狀皰疹疫苗|健康
開頭=帶狀皰疹（俗稱皮蛇）是小時候得過的水痘病毒再次活化：
步驟=它本身不會讓別人得帶狀皰疹，但水泡裡的病毒，可能讓沒得過水痘、也沒打過疫苗的人得到水痘；水泡結痂以前，避免接觸孕婦、新生兒和免疫力差的人，水泡蓋起來、不要抓破；越早吃抗病毒藥效果越好，最好在出疹後 72 小時內看醫生；50 歲以上可以考慮打帶狀皰疹疫苗
就醫=長在臉上、眼睛附近，或痛得很厲害，要盡快就醫；好了以後還一直神經痛，也要回診
@流感疫苗|流感疫苗要打嗎,流感疫苗要每年打嗎,流感疫苗,打流感疫苗有用嗎,流感疫苗副作用,誰可以打公費流感疫苗|健康
開頭=建議每年打流感疫苗：
步驟=流感病毒每年都會變，疫苗也每年更新，所以要每年打；6 個月以上的人都可以打，長輩、幼兒、孕婦、慢性病患者特別建議；台灣每年秋天開打，符合資格的人可以打公費疫苗（像 65 歲以上、學生、孕婦等，以疾管署公告為準）；打完大約兩週後才有保護力；常見的副作用是手臂痠痛、輕微疲倦，一兩天就好
提醒=對疫苗成分有嚴重過敏的人不能打；當天身體不舒服、發燒的話，先跟醫生說
@腸病毒|腸病毒怎麼預防,腸病毒,腸病毒症狀,腸病毒會傳染嗎,小孩得腸病毒怎麼辦,手足口病怎麼辦|健康
開頭=預防腸病毒，最重要的是勤洗手：
步驟=用肥皂洗手，照「濕、搓、沖、捧、擦」，回家、吃東西前、換尿布後都要洗；5 歲以下的小孩最容易被傳染、也比較容易變嚴重；生病的孩子在家休息至少 7 天，不要上學；玩具、門把用稀釋的漂白水消毒；照顧生病孩子的大人也要勤洗手
就醫=出現嗜睡、意識不清、活力很差、手腳無力、無故驚嚇或全身肌肉突然收縮、一直嘔吐、呼吸急促或心跳很快，是重症的前兆，要馬上送大醫院
@諾羅病毒|諾羅病毒怎麼辦,諾羅病毒,諾羅病毒症狀,諾羅病毒會傳染嗎,上吐下瀉怎麼辦|健康
開頭=得了諾羅病毒（上吐下瀉），可以這樣照顧：
步驟=多補充水分和電解質，小口小口喝，可以喝口服電解質液；先吃清淡好消化的東西，通常 1 到 3 天會好；傳染力很強，酒精對它沒什麼用，一定要用肥皂洗手；嘔吐物和排泄物用稀釋的漂白水消毒，清理時戴口罩手套；生病期間不要幫家人煮飯，症狀好了以後兩天內還是可能傳染
就醫=尿很少、嘴唇很乾、精神很差這類脫水的情況，或有血便、高燒，嬰幼兒和長輩更要小心，要去看醫生
@登革熱|登革熱有什麼症狀,登革熱,登革熱怎麼預防,登革熱症狀,登革熱會傳染嗎|健康
開頭=登革熱是被帶病毒的斑蚊叮咬傳染的，常見症狀是：
步驟=突然發高燒、頭痛、眼睛後面痛、肌肉和關節痠痛、出疹子；懷疑的話去看醫生，告訴醫生最近去過哪裡、住在哪；退燒止痛可以用醫生開的乙醯胺酚，不要自己吃阿斯匹靈或布洛芬，可能增加出血的風險；預防：家裡和附近的積水容器倒掉、刷乾淨（巡、倒、清、刷），出門防蚊
就醫=退燒後反而精神變差、肚子痛、一直吐、牙齦或皮膚出血，可能是重症，要馬上就醫
@過敏性鼻炎|過敏性鼻炎怎麼辦,過敏性鼻炎,鼻子過敏怎麼辦,鼻子過敏一直打噴嚏,早上一直打噴嚏,一直打噴嚏流鼻水|健康
開頭=過敏性鼻炎可以這樣改善：
步驟=找出過敏原並避開：常見的是塵蟎、黴菌、花粉、寵物毛、冷空氣；寢具每 1 到 2 週用 55 度以上的熱水洗，少用地毯、絨毛玩具；用生理食鹽水洗鼻子；出門戴口罩，早上起床先喝杯溫水；症狀多的話，醫生可以開抗組織胺或鼻噴劑
就醫=鼻塞嚴重影響睡覺、流黃綠色鼻涕、臉部脹痛，或藥局買的藥沒效，去看耳鼻喉科
@氣喘發作|氣喘發作怎麼辦,氣喘怎麼辦,氣喘發作,氣喘喘不過氣,氣喘急救|健康
開頭=氣喘發作時，可以這樣處理：
步驟=馬上停下手邊的事，坐直、不要躺下；照醫生的指示用急救型的吸入劑（支氣管擴張劑）；保持冷靜，慢慢呼吸；遠離菸味、冷空氣這些誘發的東西；平常照醫囑用控制型的藥，不要症狀好了就自己停藥
就醫=吸入劑用了沒改善、喘到說不出完整的話、嘴唇或指甲發紫、越來越喘，要馬上打 119（歐洲 112）
@近視雷射|近視雷射要注意什麼,近視雷射,雷射手術要注意什麼,近視手術,近視雷射幾歲可以做,近視雷射有什麼風險|健康
開頭=考慮近視雷射，可以先注意這些：
步驟=一般建議 20 歲左右以後、度數穩定（一兩年內變化不大）再做；術前要做完整的檢查，角膜太薄、圓錐角膜、嚴重乾眼的人可能不適合；檢查前要先停戴隱形眼鏡一段時間（照醫院的指示）；術後照醫生的指示點藥，不要揉眼睛，一段時間內避免游泳、眼部化妝；可能會有乾眼、晚上看燈光有光暈的情況
提醒=雷射治的是度數，不會讓眼睛不再退化，年紀大了一樣會老花
@隱形眼鏡|隱形眼鏡可以戴多久,隱形眼鏡一天可以戴幾小時,隱形眼鏡要注意什麼,月拋可以戴多久,戴隱形眼鏡可以睡覺嗎|健康
開頭=隱形眼鏡這樣戴比較安全：
步驟=一天配戴最好不要超過 8 小時；日拋戴一天就丟，月拋從打開那天起最多用 30 天；不要戴著睡覺、游泳或洗澡；用專用的保養液清潔，不能用自來水或口水；手洗乾淨再拿鏡片
就醫=眼睛紅、痛、怕光、視力變模糊，馬上拿下來，去看眼科
@洗牙|洗牙多久洗一次,多久要洗牙,洗牙,洗牙會痛嗎|健康
開頭=建議每半年洗一次牙：
步驟=台灣的健保給付每半年一次全口洗牙（洗牙石）；洗牙順便檢查有沒有蛀牙、牙周病；洗牙時可能有點痠，牙齦發炎的人比較容易流血；平常刷牙用牙線，牙結石會長得比較慢
提醒=抽菸、愛喝茶咖啡的人牙結石和染色比較多，可以問牙醫要不要更常洗
@智齒|智齒要拔嗎,智齒一定要拔嗎,智齒要不要拔,拔智齒要注意什麼,拔智齒,智齒長歪|健康
開頭=智齒不一定要拔，看情況：
步驟=長得正、可以刷乾淨、沒有症狀，可以先留著；常常發炎腫痛、蛀牙、長歪或卡在骨頭裡（阻生齒）推擠旁邊的牙齒、刷不乾淨，就建議拔掉；先讓牙醫照 X 光評估；拔完咬紗布 30 到 60 分鐘，24 小時內可以冰敷；拔完幾天不要用吸管、不要太用力漱口，吃軟一點的食物
提醒=拔牙前告訴牙醫你有沒有在吃抗凝血藥或有其他疾病
@甲狀腺亢進|甲狀腺亢進是什麼,甲狀腺亢進,甲亢是什麼,甲狀腺亢進症狀,甲狀腺功能亢進|健康
開頭=甲狀腺亢進是甲狀腺素分泌太多，讓身體的代謝變得太快：
步驟=常見的症狀：心跳快、心悸、手抖、怕熱、很會流汗、吃很多卻變瘦、容易緊張、睡不好；有的人眼睛會變凸（葛瑞夫茲病）；抽血驗甲狀腺功能就能知道；治療有吃藥、放射性碘、手術幾種，醫生會依狀況選
就醫=有這些症狀可以看新陳代謝科（內分泌科）；心悸很嚴重、胸痛、發高燒、意識改變要馬上就醫
@白頭髮能拔嗎|白頭髮可以拔嗎,白頭髮能拔嗎,白頭髮拔了會長更多嗎,白頭髮怎麼辦,少年白怎麼辦|健康
開頭=白頭髮不建議用拔的：
步驟=拔了還是會再長出白的，反覆拔可能傷到毛囊，讓那裡發炎、甚至不再長頭髮；「拔一根長三根」是迷思，拔掉不會讓白頭髮變多；在意的話可以剪短或染髮；白頭髮和遺傳、年紀、壓力、睡眠有關，作息規律、營養均衡有幫助
提醒=年紀輕輕白髮突然變很多，可以檢查一下甲狀腺、貧血或維生素 B12
@貧血吃什麼|貧血要吃什麼,貧血吃什麼,貧血怎麼補,缺鐵要吃什麼,補鐵要吃什麼,貧血怎麼辦,缺鐵性貧血|健康
開頭=貧血要先知道原因，缺鐵的話可以這樣吃：
步驟=多吃含鐵的食物：紅肉（牛肉、豬肉）、豬肝、蛋黃、文蛤、深綠色蔬菜、紅莧菜、豆類；搭配富含維生素 C 的水果（芭樂、柳丁、奇異果），幫助吸收鐵；飯後一兩個小時內先不要喝茶、咖啡，會影響吸收；吃素的人更要注意，必要時照醫生的建議吃鐵劑
就醫=貧血的原因很多（缺鐵、缺維生素 B12 或葉酸、地中海型貧血、慢性出血），先抽血檢查再補；地中海型貧血的人不能亂補鐵；頭暈、喘、心悸、臉色很蒼白要去看醫生
@手機資費|手機資費怎麼選,手機方案怎麼選,電信方案怎麼選,手機月租怎麼選,上網吃到飽要辦嗎,哪家電信比較好|生活
開頭=選手機資費可以這樣想：
步驟=先看自己每個月實際用多少：手機設定裡可以看行動數據用量和通話時間；上網量大、常看影片的選吃到飽，用量小的選定量方案比較省；打電話多的看網內、網外和市話的通話優惠；比較綁約和不綁約：綁約常有手機折扣或月租優惠，但不能隨便解約；也可以看虛擬電信、學生或家庭共享方案
提醒=合約快到期時，打給電信客服常可以談到更好的續約方案
@信用卡年費|信用卡年費怎麼免,信用卡年費,信用卡年費可以不繳嗎,怎麼免年費,信用卡要年費嗎|生活
開頭=信用卡年費常常可以免：
步驟=很多卡首年免年費；刷卡滿一定次數或金額，就免次年年費；有的設定電子帳單、自動扣繳也能免；收到年費帳單時，打客服說明自己有在用，常可以要求減免；用不到的卡，直接申請停卡比較乾淨
提醒=停卡前先確認沒有自動扣款綁在那張卡上
@保險理賠|保險怎麼申請理賠,保險理賠怎麼申請,理賠要準備什麼,保險理賠要多久,怎麼申請理賠,保險公司不理賠怎麼辦|生活
開頭=申請保險理賠可以這樣做：
步驟=事故發生後盡快通知保險公司，請求理賠的時效一般是 2 年；準備文件：理賠申請書、診斷證明書、醫療收據（實支實付常要正本）、身分證明、存摺封面；可以交給業務員、用保險公司的 App 或官網、臨櫃或郵寄；資料齊全後，通常 15 天內會給付，有問題保險公司會通知補件
提醒=覺得被不合理拒賠，可以向保險公司申訴，或找金融消費評議中心（0800-789-885）
@役男出國|役男可以出國嗎,役男出國要申請嗎,還沒當兵可以出國嗎,役男出境,役男出國規定|生活
開頭=役男可以出國，但要先申請：
步驟=18 歲到 36 歲還沒服完兵役的男生，出國前要先申請核准；可以上內政部役政署的網站線上申請，或到戶籍地的區公所兵役課辦；一般短期出國每次最長 4 個月，要準時回來；在學、出國留學、工作等有不同的規定和期限
提醒=護照上已經有役男的註記，出境時會查，記得先申請好再訂機票
@查兵役|怎麼查兵役,兵役怎麼查,怎麼查當兵的時間,兵役狀況怎麼查,什麼時候要當兵,兵單什麼時候來|生活
開頭=想查自己的兵役狀況，可以這樣做：
步驟=上內政部役政署的網站，用自然人憑證或健保卡登入，查役別、徵集時間；也可以打電話或到戶籍地的區公所兵役課問；兵單會寄到戶籍地址，搬家記得遷戶籍或改地址
提醒=要延後入伍（像繼續升學），要在規定的時間內申請
@投票要帶什麼|投票要帶什麼,投票要帶身分證嗎,怎麼投票,投票流程,投票要帶印章嗎|生活
開頭=去投票要帶這些：
步驟=國民身分證正本（一定要帶）；印章，沒有的話也可以簽名；投票通知單可以帶，方便知道投票所和號碼；到戶籍地的指定投票所，投票時間通常是早上 8 點到下午 4 點；領票後在圈票處圈選，不能拍選票、不能把選票帶出去
提醒=選票摺好投進票匭，圈的時候用投票所準備的圈選章
@身心障礙證明|身心障礙手冊怎麼申請,身心障礙證明怎麼申請,身障手冊怎麼申請,身障證明怎麼申請,怎麼申請身障|生活
開頭=身心障礙手冊現在已經改成「身心障礙證明」，可以這樣申請：
步驟=到戶籍地的區公所（鄉鎮市區公所）提出申請，帶身分證、照片和印章；區公所會給鑑定表，到指定的醫院做鑑定；之後會有需求評估，評估通過就核發身心障礙證明；可以申請的補助、交通優惠、稅的減免，可以問區公所或社會局
提醒=證明有效期限到了要重新鑑定，記得提早申請
@自然人憑證|怎麼申請自然人憑證,自然人憑證怎麼申請,自然人憑證,自然人憑證要多久,自然人憑證有什麼用|生活
開頭=申請自然人憑證可以這樣做：
步驟=帶身分證到任何一個戶政事務所臨櫃申請，當場就能拿到卡片；第一次申請要繳一點工本費；現場設定 PIN 碼，一定要記住；用讀卡機插在電腦上，就能網路報稅、申辦政府服務、查詢資料；手機也可以申請「行動自然人憑證」
提醒=PIN 碼輸錯太多次會鎖卡，要到戶政事務所解鎖
@報稅準備|報稅要準備什麼,怎麼報稅,報稅要帶什麼,報稅怎麼報,第一次報稅,所得稅怎麼報|生活
開頭=報綜合所得稅可以這樣準備：
步驟=每年 5 月申報去年的所得；登入方式：健保卡加註冊密碼、自然人憑證、行動自然人憑證或金融憑證，用報稅軟體或手機報稅；所得資料可以在線上下載，薪水、利息、股利會自動帶入；有扶養的家人、保險費、醫藥費、房租這類可以扣除的，準備好單據或資料；第一次報稅，可以到國稅局臨櫃請人協助
提醒=所得不多的人也建議申報，有被扣的稅可以申請退回
@標點符號|標點符號怎麼用,標點符號,逗號怎麼用,句號怎麼用,分號怎麼用,冒號怎麼用,引號怎麼用|學習
開頭=常用的標點符號這樣用：
步驟=逗號（，）：句子中間停頓；句號（。）：一句話說完；頓號（、）：並列的詞，像「蘋果、香蕉、橘子」；分號（；）：並列的句子；冒號（：）：後面要說明或列舉；引號（「」）：引用別人說的話，或特別指出的詞；問號（？）、驚嘆號（！）：問句和語氣強烈的句子；書名號（《》）：書、電影、文章的名稱
提醒=中文的標點要用全形，一個標點佔一個字的位置
@頓號逗號|頓號和逗號差在哪,頓號跟逗號,頓號怎麼用,逗號和頓號的差別,什麼時候用頓號|學習
開頭=頓號和逗號的差別：
步驟=頓號（、）用在並列的「詞語」中間：「我喜歡蘋果、香蕉和葡萄」；逗號（，）用在句子裡的停頓：「我喜歡水果，也喜歡蔬菜」；簡單判斷：前後都只是名詞、可以換成「和」的，用頓號；前後是有主詞動詞的句子，用逗號
提醒=數字並列也常用頓號，例如「第一、二、三名」
@再和在|再和在怎麼分,在和再怎麼分,再跟在的差別,再見還是在見,在和再的用法|學習
開頭=「再」和「在」這樣分：
步驟=「再」是重複一次、或之後才做：再見、再來一次、明天再說；「在」是在某個地方、或正在做：我在家、在學校、我在吃飯；小技巧：能換成「又」「之後」的用「再」，能換成「正在」「位於」的用「在」；所以是「再見」，不是「在見」
提醒=「現在」「存在」「自在」這些詞都是「在」
@做和作|做和作怎麼分,作和做怎麼分,做跟作的差別,作業還是做業,工作還是工做,做事還是作事|學習
開頭=「做」和「作」可以這樣分：
步驟=「做」多用在具體、動手做出東西的事：做飯、做功課、做衣服、做生意、做人；「作」多用在比較抽象或書面的固定詞：作文、作業、工作、作者、作品、作用、作為、合作；不確定時，可以查字典看看那個詞的固定寫法
提醒=「作業」「工作」是作，「做功課」「做事」是做
@英文文法|怎麼記英文文法,英文文法怎麼學,英文文法很差怎麼辦,英文文法要怎麼讀,文法怎麼學|學習
開頭=學英文文法可以這樣做：
步驟=先掌握最基本的句子結構：主詞＋動詞＋受詞；用例句記，不要只背規則，每個文法點找兩三句自己會用到的句子；一次專心一個重點，像時態、單複數、冠詞 a/the；多讀簡單的文章，看文法怎麼用在真的句子裡；寫短短的日記或句子，請老師或 AI 幫你改
提醒=文法是幫你看懂和說對的工具，不用一開始就追求完全沒有錯
@for和to|for和to差在哪,for跟to的差別,to和for怎麼分,for和to怎麼用|學習
開頭=for 和 to 常見的分法：
步驟=to 表示方向、目的地：I went to the park.；to 後面接動詞原形，表示目的：I study English to get a better job.；for 表示對象、為了誰：This gift is for you.；for 表示用途：This knife is for cutting bread.；for 表示一段時間：I have lived here for three years.
提醒=give 和 send 這類動詞後面接人用 to（give it to me），buy 和 make 接人常用 for（buy a gift for her）
@英文時態|英文的時態有哪些,英文時態,英文有幾種時態,現在完成式怎麼用,英文時態怎麼分|學習
開頭=英文有 12 種時態（現在、過去、未來，各有簡單、進行、完成、完成進行），最常用的是這幾種：
步驟=現在簡單式：習慣或事實，I drink coffee every day.；現在進行式：現在正在做，I am drinking coffee now.；過去簡單式：過去發生、已經結束，I drank coffee yesterday.；現在完成式：從過去到現在、或對現在有影響，I have already had coffee.；未來式：will 或 be going to，I will drink coffee later.
提醒=先把這五種用熟，日常對話就夠用了
@五十音|日文五十音怎麼背,五十音怎麼背,五十音要背多久,平假名怎麼背,日文字母怎麼背|學習
開頭=背日文五十音可以這樣做：
步驟=先學平假名，從「あいうえお」開始，每天背一兩行（5 到 10 個字）；用字形聯想幫助記憶，像「ぬ」像麵條；邊寫邊唸，用 App 或閃卡每天複習；平假名熟了再學片假名，順便記一些外來語單字；大概 2 到 4 週可以把平假名背熟
提醒=背完後多讀簡單的單字和句子，用得到才記得牢
@韓文好學嗎|韓文好學嗎,韓文難學嗎,學韓文難嗎,韓文怎麼學,韓文字母難嗎|學習
開頭=韓文對會中文的人來說算好入門：
步驟=韓文字母（諺文）很有規則，一兩週就能拼讀；很多單字是漢字詞，發音和中文很像，像「圖書館」是도서관；文法順序像日文，動詞放在句子最後，要花時間習慣；敬語和語尾變化是比較難的地方；看韓劇、聽韓文歌是很好的練習
提醒=先把字母和發音學好，後面學單字會快很多
@防毒軟體|需要裝防毒軟體嗎,要不要裝防毒軟體,防毒軟體要裝嗎,手機要裝防毒軟體嗎,Mac需要防毒軟體嗎,防毒軟體推薦|生活
開頭=一般使用的話，大多不用另外買防毒軟體：
步驟=Windows 內建的 Microsoft Defender 已經足夠一般人用，記得保持開啟；Mac 和 iPhone 系統本身比較封閉，一般不需要另外裝；Android 只從 Google Play 下載 App、開啟 Play Protect 就好；比防毒更重要的是：系統和 App 常更新、不亂點連結、不安裝來路不明的軟體
提醒=會跳出「你的手機中毒了」要你下載東西的廣告，幾乎都是騙人的
@選雲端硬碟|雲端硬碟要選哪個,雲端硬碟推薦,雲端空間要買哪個,Google雲端和iCloud哪個好,照片要存哪個雲端|生活
開頭=選雲端硬碟可以這樣看：
步驟=Google 雲端硬碟：免費 15GB（和 Gmail、Google 相簿共用），用 Android 或 Google 服務的人方便；iCloud：免費 5GB，用 iPhone、Mac 的人最順；OneDrive：免費 5GB，常用 Word、Excel 的人方便；Dropbox：免費 2GB，分享檔案很方便；看你用什麼手機電腦、要放多少東西，不夠再買小額的月費方案
提醒=重要的資料最好存兩個地方，例如雲端加一顆外接硬碟
@密碼記不住|密碼記不住怎麼辦,密碼太多記不住,密碼要怎麼記,密碼管理器是什麼,密碼要寫下來嗎|生活
開頭=密碼記不住，可以這樣解決：
步驟=用密碼管理器：iPhone 的 iCloud 鑰匙圈、Google 密碼管理工具，或 1Password、Bitwarden，幫你產生和記住每個網站不同的密碼；你只要記一組很長、很好記的主密碼（例如一句話）；重要的帳號都打開兩步驟驗證；不要把密碼寫在便利貼貼在電腦旁邊
提醒=忘記密碼時，用官方的「忘記密碼」流程重設，不要相信要你提供密碼的訊息
@兩步驟驗證|什麼是兩步驟驗證,兩步驟驗證是什麼,雙重驗證是什麼,兩步驟驗證要開嗎,怎麼開兩步驟驗證|生活
開頭=兩步驟驗證是登入時，除了密碼再多一道確認：
步驟=輸入密碼後，還要輸入手機簡訊的驗證碼、驗證器 App 上的 6 位數字，或在手機上按「是我」；就算密碼被偷，別人也登不進去；建議用 Google Authenticator、Microsoft Authenticator 這類驗證器 App，比簡訊更安全；開啟時會給你一組備用碼，要存在安全的地方
提醒=FB、IG、Google、LINE 和網路銀行，都建議打開兩步驟驗證
@關閉自動更新|iPhone怎麼關閉App自動更新,關閉App自動更新,怎麼關掉自動更新,App自動更新怎麼關,安卓怎麼關閉自動更新|生活
開頭=關閉 App 自動更新可以這樣做：
步驟=iPhone：設定 → App Store → 關掉「App 更新」，也可以關掉「自動下載」裡的行動網路；Android：打開 Play 商店 → 右上角頭像 → 設定 → 網路偏好設定 → 自動更新應用程式 → 選「不要自動更新」或「只透過 Wi-Fi」
提醒=關掉自動更新後記得偶爾手動更新，安全性修補很重要
@清除快取|怎麼清除瀏覽器快取,清除快取,瀏覽器快取怎麼清,Chrome怎麼清快取,Safari怎麼清除快取,怎麼清除瀏覽紀錄|生活
開頭=清除瀏覽器快取可以這樣做：
步驟=電腦的 Chrome：按右上角三個點 → 刪除瀏覽資料（或按 Ctrl＋Shift＋Delete），勾「快取圖片和檔案」，選時間範圍後刪除；iPhone 的 Safari：設定 → Safari → 清除瀏覽紀錄和網站資料；Android 的 Chrome：右上角三個點 → 設定 → 隱私權和安全性 → 清除瀏覽資料
提醒=只想讓網頁重新整理，可以先試試 Ctrl＋F5（Mac 是 Command＋Shift＋R）
@小孩走失|小孩走失怎麼辦,孩子走失怎麼辦,小孩不見了怎麼辦,孩子不見了,在賣場小孩走失,找不到小孩怎麼辦|生活
開頭=小孩走失要馬上行動：
步驟=立刻在附近大聲叫他的名字、找一遍，請身邊的人一起幫忙看；在賣場、捷運站、遊樂園，馬上找服務台或站務人員廣播、看出口；直接打 110 報警，不用等 24 小時，越早越好；提供孩子的照片、穿的衣服、身高、最後出現的地點；有人留在原地，孩子可能會走回來
提醒=平常教孩子記住爸媽的電話，走失時留在原地，或找穿制服的店員、警察幫忙，不要跟陌生人走
@個資外洩|個資外洩怎麼辦,個資被洩漏怎麼辦,資料外洩怎麼辦,收到個資外洩通知,密碼外洩怎麼辦,帳號密碼外洩|生活
開頭=知道個資外洩了，可以這樣處理：
步驟=馬上改密碼，同一組密碼用在別的網站的也要一起改，並打開兩步驟驗證；小心接下來冒充客服、銀行、物流的電話和簡訊，有人要你操作 ATM、匯款或給驗證碼，都不要理，打 165 查證；信用卡資料外洩，請銀行停卡換新卡；注意帳單和銀行通知有沒有不認識的交易
提醒=可以向聯徵中心查自己的信用報告，看有沒有人冒用你的名字申請貸款或信用卡
@心臟病發作|心臟病發作怎麼辦,心肌梗塞怎麼辦,心臟病發作的症狀,胸口痛冒冷汗,心肌梗塞的症狀|健康
開頭=懷疑心臟病發作，要馬上這樣做：
步驟=常見的症狀：胸口悶痛、像被壓住，可能痛到左肩、手臂、下巴或背，加上冒冷汗、喘、噁心；立刻打 119，不要自己開車去醫院；讓病人坐下或半躺休息，鬆開衣服；醫生以前有開舌下含片的，照指示使用；病人失去意識、沒有呼吸，馬上做 CPR，請人拿 AED
就醫=不要等「看會不會好一點」，心肌梗塞越早治療，存活和恢復越好
@中風症狀|中風的症狀,中風有什麼症狀,中風怎麼辦,怎麼知道是不是中風,中風前兆|健康
開頭=中風的症狀可以用「微笑、舉手、說你好」快速判斷：
步驟=請他微笑：一邊的臉歪掉、嘴角下垂；請他兩手舉高：一邊沒力、手掉下來；請他說「你好」：口齒不清、說不出話；還有突然一眼看不清楚、走路不穩、劇烈頭痛；有任何一個，馬上打 119，記下症狀開始的時間
就醫=中風搶的是時間，越早送醫越可能用藥打通血管，不要等症狀過去，也不要餵他吃東西喝水
@觸電|觸電怎麼辦,被電到怎麼辦,有人觸電怎麼辦,觸電急救,被電到要看醫生嗎|健康
開頭=有人觸電，先確保自己安全：
步驟=先切斷電源：拔插頭或關總電源開關；不能直接用手去拉觸電的人，可以用乾燥的木棍、塑膠椅推開電線；打 119；病人沒有呼吸心跳，馬上做 CPR、請人拿 AED；有電擊傷的地方用乾淨的布蓋著
就醫=就算看起來沒事，被家用電電到也建議去看醫生，電流可能影響心臟
@溺水|有人溺水怎麼辦,溺水怎麼辦,溺水急救,看到有人溺水,救溺五步|健康
開頭=看到有人溺水，記得救溺五步「叫、叫、伸、拋、划」：
步驟=叫：大聲呼救，請人幫忙；叫：打 119；伸：用竹竿、樹枝、衣服延伸過去讓他抓；拋：丟救生圈、寶特瓶這類會浮的東西；划：有船或浮具才划過去；不會游泳或沒有救生訓練，千萬不要自己下水
就醫=救上岸後沒有呼吸，馬上做 CPR；就算看起來恢復了，也要送醫檢查
@誤食清潔劑|誤食清潔劑怎麼辦,喝到清潔劑怎麼辦,誤食漂白水怎麼辦,小孩喝到清潔劑,誤食化學藥品怎麼辦,吃到洗衣球怎麼辦|健康
開頭=誤食清潔劑、漂白水，可以這樣處理：
步驟=不要催吐，吐出來會再傷一次食道；用清水漱口，可以小口喝一點水；把產品的瓶子或包裝帶著，讓醫生知道是什麼成分；馬上打 119 或去急診，也可以打台北榮總毒藥物諮詢中心（02-2871-7121）問；沾到皮膚或眼睛，用大量清水沖 15 分鐘
就醫=喘、喉嚨痛到吞不下、流口水、意識不清，要馬上打 119
@一氧化碳中毒|一氧化碳中毒怎麼辦,一氧化碳中毒,一氧化碳中毒症狀,熱水器中毒怎麼辦,怎麼預防一氧化碳中毒|健康
開頭=懷疑一氧化碳中毒，要馬上這樣做：
步驟=立刻打開門窗通風，關掉熱水器、瓦斯；把人移到空氣流通的地方，不要開關電器、不要點火；打 119；症狀：頭痛、頭暈、噁心、很想睡、全身無力，嚴重會意識不清；預防：熱水器裝在室外通風的地方，不要把陽台封起來，可以裝一氧化碳警報器
就醫=就算醒過來了也要送醫，一氧化碳會傷害腦和心臟
@被水母螫|被水母螫到怎麼辦,被水母螫,水母螫傷怎麼辦,被水母咬,海邊被螫到|健康
開頭=被水母螫到，可以這樣處理：
步驟=先離開水裡，不要用手直接抓觸手；用海水沖洗，不要用淡水，淡水會讓刺胞釋放更多毒；戴手套或用卡片把殘留的觸手刮掉；用可以忍受的熱水（大約 45 度）泡 20 分鐘，可以減輕疼痛；不要揉、不要用尿沖
就醫=呼吸困難、全身起疹子、胸悶、意識改變，可能是嚴重過敏，馬上打 119；被大面積螫傷或小孩被螫，也要去看醫生
@小孩吞硬幣|小孩吞了硬幣怎麼辦,小孩吞東西怎麼辦,小孩吞到東西,吞了硬幣,小孩吞電池,小孩吞磁鐵|健康
開頭=小孩吞了硬幣這類小東西，可以這樣處理：
步驟=先看呼吸：如果嗆到、不能呼吸、說不出話，馬上做哈姆立克法並打 119；呼吸正常的話，不要催吐，帶去看醫生照 X 光，確認東西在哪裡；卡在食道要請醫生取出；已經到胃裡的，大多會在幾天內隨大便排出，醫生會告訴你怎麼觀察
就醫=吞了鈕扣電池或磁鐵非常危險，會灼傷腸胃，一定要馬上去急診；吞了以後一直流口水、吞不下、肚子痛、吐，也要馬上就醫
@鑰匙斷在鎖裡|鑰匙斷在鎖裡怎麼辦,鑰匙斷掉怎麼辦,鑰匙斷在鎖孔裡,鑰匙斷了,斷掉的鑰匙怎麼拿出來|生活
開頭=鑰匙斷在鎖裡，可以這樣處理：
步驟=先不要再插其他東西進去，會推得更裡面；如果還有露出一小截，用尖嘴鉗或鑷子夾住慢慢拉出來；沒有露出來，可以用很細的鋸條或專門的斷匙取出器勾出來；弄不出來就找鎖匠；斷掉的兩截都留著，鎖匠可以照著打新鑰匙
提醒=鑰匙很容易斷，常常是鎖心卡卡的，可以順便清潔、上點石墨粉，或換新的鎖心
@車子沒油|車子沒油怎麼辦,開車沒油了怎麼辦,汽車沒油,高速公路沒油怎麼辦,機車沒油怎麼辦|生活
開頭=開到一半沒油，可以這樣處理：
步驟=開雙黃燈，把車滑到路肩或安全的地方停好，高速公路上要在車後放三角警示架；人移到護欄外；打保險公司或車廠的道路救援，高速公路可以打 1968；加油站很近的話，用合格的油桶去買油回來加；機車沒油就牽去附近的加油站
提醒=平常油表剩四分之一就去加，長途或山路前先加滿
@皮夾掉了|皮夾掉了怎麼辦,錢包掉了怎麼辦,錢包不見了,皮夾不見了,證件掉了怎麼辦,錢包被偷|生活
開頭=皮夾掉了，可以照這個順序處理：
步驟=先打給銀行掛失信用卡和金融卡，避免被盜用；到附近的派出所報案，拿報案證明；身分證可以先打 1996 或上戶政網站掛失，再到戶政事務所補發；健保卡、駕照、行照分別到健保署、監理站補辦；記名的悠遊卡、一卡通可以掛失，餘額有機會退回
提醒=想一想最後在哪裡用過，回去問問店家或失物招領，很多人會送到派出所
@錯過班機|錯過班機怎麼辦,沒趕上飛機怎麼辦,錯過飛機怎麼辦,趕不上飛機,轉機沒趕上怎麼辦|生活
開頭=錯過班機，可以這樣處理：
步驟=馬上聯絡航空公司的櫃台或客服，問能不能改搭下一班，可能要付改票費或差價；因為前一段航班延誤而錯過轉機，航空公司通常要幫你安排；廉價航空大多要重新買票，先看清楚票的規定；有買旅遊不便險的話，留好證明，可能可以申請理賠
提醒=國際線建議起飛前 2 到 3 小時到機場，報到和登機都有截止時間
@行李遺失|行李遺失怎麼辦,行李不見了,行李沒到怎麼辦,托運行李遺失,飛機行李不見,行李延誤怎麼辦|生活
開頭=行李沒有出現在轉盤上，可以這樣處理：
步驟=先不要離開機場，到行李服務櫃台填寫「行李事故報告」，留下聯絡電話和住宿地址；保留登機證和行李條；急需的盥洗用品、衣服先買，收據留著，向航空公司或保險公司申請費用；大部分延誤的行李幾天內會送到；超過 21 天沒找到就算遺失，可以向航空公司求償
提醒=有買旅遊不便險的話，行李延誤或遺失通常都能理賠
@訂房被取消|訂房被取消怎麼辦,飯店取消我的訂房,訂房被飯店取消,飯店超賣怎麼辦,訂好的房間沒了|生活
開頭=訂好的房間被取消，可以這樣處理：
步驟=先截圖保存訂單和確認信；馬上聯絡訂房網站的客服，他們常會協助找同等級的飯店或退款；如果是飯店超賣，可以要求安排同等級的住宿、負擔差價或補償；已經刷卡付款的，請對方退款，沒退可以向發卡銀行申請爭議款
提醒=旺季出門前一兩天，可以先打電話給飯店確認訂房
@外送送錯|外送送錯怎麼辦,外送少送怎麼辦,外送餐點錯了,外送沒送到怎麼辦,外送送錯餐|生活
開頭=外送送錯或少送，可以這樣處理：
步驟=先拍照：送來的餐點、包裝上的訂單貼紙；在 App 的訂單裡找「回報問題」或聯絡客服，說明哪裡不對；通常會退款、補償優惠券或重新送；餐點品質問題（灑出來、冷掉）也一樣在 App 上回報
提醒=盡量在收到後馬上回報，時間拖太久比較難處理
@吃到蟲|點餐吃到蟲怎麼辦,吃到蟲怎麼辦,食物裡有蟲,餐點裡有異物,吃到頭髮怎麼辦,餐廳食物有蟲|生活
開頭=餐點裡吃到蟲或異物，可以這樣處理：
步驟=先拍照、錄影留證，餐點不要丟，發票留著；跟店家反映，要求退款或重做；有身體不舒服的話去看醫生，保留看診紀錄和收據；店家處理得不好，可以打 1950 消費者服務專線，或向衛生局檢舉
提醒=大部分店家願意好好處理，態度清楚冷靜，比較容易談
@過期食品|買到過期食品怎麼辦,買到過期的東西,過期食品可以退嗎,超商賣過期食品,買到過期食品,過期的東西可以吃嗎|生活
開頭=買到過期的食品，可以這樣處理：
步驟=先不要吃；拍下有效期限，保留商品和發票；拿回店家退款或換貨；販售過期食品違反食品安全衛生管理法，可以向各縣市衛生局檢舉，或打 1919 食品安全專線；如果已經吃了、不舒服，去看醫生並保留紀錄
提醒=「有效日期」過了就不要吃；「最佳賞味期」過了品質可能變差，但不一定不安全
@被房仲騙|被房仲騙怎麼辦,房仲不實廣告,仲介亂收費怎麼辦,被仲介騙|生活
開頭=覺得被房仲誤導或不實銷售，可以這樣處理：
步驟=先把合約、廣告、對話紀錄、看屋資料都存好；向那家房仲品牌的總部客服申訴；不動產經紀業違規（像隱瞞房屋瑕疵、亂收服務費），可以向縣市政府的地政局檢舉；消費爭議可以打 1950 申訴，或到區公所申請調解；金額大、涉及刑事的，諮詢律師或法律扶助
提醒=買賣房屋的服務費有上限（買方加賣方合計不超過 6%），簽約前看清楚
@房東漲房租|房東要漲房租怎麼辦,房東漲房租,房東可以漲房租嗎,租約期間可以漲房租嗎,續約要漲房租|生活
開頭=房東要漲房租，可以這樣處理：
步驟=先看租約：依內政部的住宅租賃契約規定，租約期間內房東不能任意調漲租金；要漲通常是租約到期、重新續約的時候；續約前查查附近同類房子的行情，有根據比較好談；可以跟房東協商：願意簽長一點、準時繳租、好好維護房子，換取不漲或少漲；談不攏就提早找房子，搬家前把押金和點交處理好
提醒=有任何約定都寫進新的租約裡，不要只是口頭說好
@提前解約租屋|提前解約租屋要賠嗎,租屋提前解約,租約提前終止,提前退租要賠錢嗎,租房子提早搬走要賠嗎|生活
開頭=租屋想提前解約，可以這樣看：
步驟=先看租約有沒有「提前終止」的約定；依內政部的定型化契約規定，有約定可以提前終止的，要提前一個月通知對方；沒有提早一個月通知的，違約金最多不超過一個月的租金；租約完全沒寫可以提前終止的話，就要跟房東協商，例如幫忙找下一個房客
提醒=搬走前跟房東一起點交、拍照，押金扣了什麼要說清楚
@押金退還|押金什麼時候退,押金可以拿回來嗎,押金要退多少,租屋押金|生活
開頭=租屋押金大致這樣處理：
步驟=押金最多不能超過兩個月的租金；租約到期、房子交還、點交完成後，房東應該返還押金；可以扣的是欠的房租、水電費，或你造成的損壞修理費，正常使用的損耗不能扣；搬走時拍照錄影，寫好點交清單，雙方簽名；房東不還，可以先寄存證信函，再到區公所調解，或打 1999 問市政府的租屋協助
提醒=當初入住時也拍照記錄房子的狀況，最能保障自己
@分電費|怎麼跟室友分電費,冷氣電費怎麼分,合租電費怎麼分|生活
開頭=和室友分電費，可以這樣分：
步驟=先看電費怎麼算：台電是用「度數 × 每度的價錢」，夏天比較貴、用越多每度越貴；每個房間有獨立電表的，就各付自己的度數；只有一個總電表的，公共區域平分，冷氣這種用電大戶可以照使用時間或房間大小算比例；房東自己訂每度電價的，看合不合理（大約台電的價錢）；一開始就講好規則，用分帳 App 記錄
提醒=冷氣設 26 到 28 度、加電扇，大家都省電費
@上班遲到|上班遲到怎麼辦,要遲到了怎麼辦,快遲到了,上班睡過頭怎麼辦,遲到要怎麼跟主管說|生活
開頭=上班要遲到了，可以這樣處理：
步驟=第一時間傳訊息或打電話給主管，說清楚預計幾點到，不用編很誇張的理由；有會議或急事的話，先請同事幫忙頂一下；到了以後先處理最急的事，誠懇地說聲抱歉；照公司規定補請假或補時數；之後提早出門、設兩個鬧鐘，避免再發生
提醒=偶爾一次遲到沒什麼，誠實通知比什麼都重要
@塞車|塞車很嚴重怎麼辦,塞車怎麼辦,一直塞車,遇到塞車怎麼辦,上班塞車|生活
開頭=遇到塞車，可以這樣做：
步驟=保持安全距離，不要一直換車道，反而更容易擦撞；用導航看即時路況，有別的路就改道；放點音樂或 Podcast，讓自己放鬆；會遲到的話，等停好車或請同車的人幫忙通知，不要邊開車邊滑手機；長期都塞的話，試試錯開尖峰時間，或改搭大眾運輸
提醒=急也不要搶快，塞車時最容易發生追撞
@帶便當|便當要怎麼帶,帶便當要注意什麼,便當怎麼準備,隔夜便當可以吃嗎,便當要冰嗎,帶便當怎麼保存|生活
開頭=帶便當可以這樣準備：
步驟=前一晚煮好後先放涼，再裝進可微波的玻璃保鮮盒，蓋好放冰箱冷藏；到公司也盡量放冰箱；中午用微波爐熱透再吃；避開容易壞的菜：涼拌菜、半熟蛋、海鮮；綠色葉菜隔天容易變黃，可以改帶花椰菜、根莖類
提醒=夏天沒有冰箱的話，加保冷袋和保冷劑，最好在早上現做
@做惡夢|做惡夢怎麼辦,常常做惡夢,一直做惡夢,做惡夢嚇醒,晚上做惡夢|健康
開頭=做惡夢醒來，可以這樣做：
步驟=先深呼吸，開一盞小燈、喝口水，提醒自己那只是夢；睡前少看恐怖或刺激的內容，少滑手機、少喝咖啡和酒；作息規律，壓力大時多夢，可以睡前寫寫日記，把煩惱放下；把反覆出現的惡夢寫下來，想像一個好的結局，有時候能減少它出現
就醫=如果惡夢跟可怕的經歷有關、常常被嚇醒，影響白天的生活，可以找身心科或心理諮商
@一直做夢|睡覺一直做夢正常嗎,一直做夢,晚上一直做夢,每天都做夢正常嗎,睡覺做夢是好是壞,多夢|健康
開頭=每個人每晚都會做夢，只是不一定記得：
步驟=做夢大多發生在「快速動眼期」，一個晚上會有好幾次；常常記得夢，可能是睡得比較淺，或剛好在做夢時醒來；壓力大、睡前滑手機、喝酒、太晚吃東西，都會讓睡眠變淺；只要白天精神不錯，多夢一般不用擔心
提醒=白天常常很累、睡不飽，或打呼很大聲、會憋氣，可以去睡眠門診檢查
@聚餐分帳|聚餐怎麼分帳,怎麼分帳,吃飯怎麼分帳,聚餐要平分嗎,朋友吃飯怎麼算錢,AA制怎麼算|生活
開頭=聚餐分帳可以這樣做：
步驟=出發前先說好：平分，還是各付各的；點的東西差很多（有人喝酒、有人沒喝），可以把個人的部分分開算，共享的再平分；可以一個人先刷卡，大家再轉帳給他；用分帳 App 或 LINE 記帳，誰付了多少一目了然；服務費、小費也記得算進去
提醒=金額不大時，大家輪流請客也很好，比算到個位數更自在
@尷尬|很尷尬的時候怎麼辦,好尷尬怎麼辦,尷尬怎麼化解,說錯話很尷尬,場面很尷尬怎麼辦,冷場怎麼辦|生活
開頭=覺得尷尬的時候，可以這樣化解：
步驟=大方承認、自嘲一下：「哈，我剛剛有點糗」，大家通常就笑一笑過去了；說錯話就簡單道個歉，不用一直解釋；冷場的時候，問對方一個開放式的問題，或聊聊眼前的東西；深呼吸，提醒自己：別人其實沒有那麼在意，很快就會忘記
看法=尷尬代表你在乎別人的感受，這是優點；會自嘲的人，通常最受歡迎
@客戶溝通|跟客戶溝通要注意什麼,怎麼跟客戶溝通,客戶溝通技巧,怎麼跟客戶講,跟廠商溝通要注意什麼|生活
開頭=跟客戶溝通可以注意這些：
步驟=先聽懂需求：多問開放式的問題，最後用自己的話重述一次確認；用對方聽得懂的話，少用專業術語；答應的事寫下來，會後用 email 或訊息確認；準時回覆，就算還沒有答案，也先回「收到，我明天下午前給你」；遇到抱怨，先處理情緒再處理事情
提醒=做不到的事不要先答應，寧可保守承諾、超出期待
@被客戶罵|被客戶罵怎麼辦,客戶很兇怎麼辦,遇到奧客怎麼辦,被客人罵怎麼辦,客戶一直抱怨怎麼辦|生活
開頭=被客戶罵，可以這樣面對：
步驟=先讓自己冷靜，不要當下反擊，讓他把話說完；表示理解他的感受：「造成您的困擾，真的很抱歉」；確認問題到底是什麼，提出可以做到的解決方法和時間；超出自己權限的，請主管一起處理；遇到人身攻擊、威脅或性騷擾，回報主管，公司有責任保護員工
看法=客戶罵的是那件事，不是你這個人；下班後找人聊聊、做點喜歡的事，別把它帶回家
@離婚|離婚要怎麼辦,離婚怎麼辦,怎麼辦離婚,離婚手續,協議離婚怎麼辦,離婚要準備什麼|生活
開頭=在台灣辦離婚，大致是這樣：
步驟=雙方都同意的「兩願離婚」：寫離婚協議書，要有兩位證人簽名，再一起到戶政事務所辦離婚登記，登記了才生效；協議書寫清楚：孩子的監護權、探視和扶養費，財產怎麼分；一方不同意，可以先申請調解，或向法院訴請離婚（要有法律規定的理由）；可以打法律扶助基金會 412-8518 諮詢
提醒=有家暴的情況，先保護自己，打 113，也可以向法院申請保護令
@遺產繼承|遺產怎麼繼承,遺產繼承順序,繼承要辦什麼,遺產要繳稅嗎,繼承債務怎麼辦,拋棄繼承怎麼辦|生活
開頭=遺產繼承大致是這樣：
步驟=繼承順序：配偶一定是繼承人，另外依序是子女、父母、兄弟姊妹、祖父母；家人過世後 6 個月內，向國稅局申報遺產稅（沒超過免稅額也要申報，拿到證明才能辦後續）；房子土地要到地政事務所辦繼承登記，存款要帶相關證明到銀行辦；如果債務很多，可以在知道自己是繼承人後 3 個月內向法院聲明拋棄繼承
提醒=現在台灣的繼承人，只用繼承到的遺產去還債，不會要用自己的錢還；程序比較複雜，可以找代書或律師協助
@退休準備|退休要準備多少錢,退休金要存多少,退休要存多少錢,怎麼準備退休金,退休規劃,幾歲可以退休|生活
開頭=退休要準備多少錢，可以這樣估算：
步驟=先算退休後每個月的生活費，例如 3 萬元；乘上 12 個月、再乘上退休後大約要過的年數，例如 25 年，就是 900 萬元；扣掉之後會領到的勞保年金、勞退和其他收入，剩下的就是要自己存的；再多抓一些給醫療、長照和通膨；越早開始越輕鬆，可以用定期定額投資、勞退自提
提醒=勞保局的網站可以試算自己的勞保年金和勞退大概可以領多少
@買車|買車要注意什麼,買新車要注意什麼,買車怎麼挑,第一台車買什麼,買車要準備多少錢,買車貸款|生活
開頭=買車可以注意這些：
步驟=預算不只車價：還有保險、牌照稅、燃料費、油錢、保養、停車費，一年常常要好幾萬；想清楚用途：通勤、載家人、長途，決定車型和大小；多比較油耗、安全配備（主動煞車、盲點偵測）、保值性和保固；一定要試駕，看坐起來舒不舒服、視野好不好；貸款的話比較利率和總費用，交車時仔細檢查外觀和配備
提醒=新手第一台車，選好開、好停、保養便宜的就好
@被告|被告了怎麼辦,被人告了怎麼辦,收到傳票怎麼辦,被提告怎麼辦,被告上法院,被告了要請律師嗎|生活
開頭=被告了，先冷靜，這樣處理：
步驟=看清楚收到的文件：是法院還是地檢署、是民事還是刑事、案由和開庭時間；千萬不要不理：民事不到可能直接被判，刑事被傳喚不到可能被拘提；把相關的證據整理好：合約、對話紀錄、收據；諮詢律師，經濟有困難可以找法律扶助基金會（412-8518）；刑事案件可以請律師陪同，有權保持沉默
提醒=法院、檢察署不會打電話要你匯款或交出存摺，接到這種電話先打 165 查證
@車禍和解|車禍怎麼和解,車禍和解要注意什麼,車禍賠償怎麼算,車禍調解,車禍和解書怎麼寫|生活
開頭=車禍要和解，可以這樣做：
步驟=事故當下先報警，警察做筆錄，拿「道路交通事故當事人登記聯單」，之後可以申請初步分析研判表，不服可以申請鑑定；把醫療收據、修車估價單、請假證明都留好；和解要談：醫療費、修車費、工作損失、精神慰撫金；可以到區公所的調解委員會免費調解，法院核定後效力等於判決；和解書寫清楚金額、付款方式，簽之前看清楚有沒有「拋棄其他請求」的條款
提醒=過失傷害要提告，期限是知道對方是誰後 6 個月內
@被偷拍|被偷拍怎麼辦,發現被偷拍,被偷拍了,有人偷拍我,廁所有針孔怎麼辦,私密照被散布怎麼辦|生活
開頭=發現被偷拍，可以這樣處理：
步驟=安全的話大聲制止，請旁邊的人協助，記下對方的樣子；拍下現場、對方、時間地點，保留證據；打 110 報警，偷拍別人的身體隱私部位、性影像是刑事犯罪；私密影像被散布到網路上，可以向衛福部的性影像處理中心申請協助下架，也可以打 113
看法=這不是你的錯，不用一個人承受，找信任的人陪你一起處理
@讀書方法|怎麼讀書,要怎麼讀書,讀書方法,讀書技巧,怎麼讀書比較有效,讀書效率很差,有效的讀書方法,怎麼讀書才記得住|學習
開頭=讀書可以用這些比較有效的方法：
步驟=先看一遍目錄和重點，知道整章在講什麼；主動回想：讀完一段闔上書，自己說出重點或寫題目，比重讀好幾次有效；間隔複習：隔 1 天、3 天、1 週再回來看一次；用番茄工作法：專心 25 分鐘、休息 5 分鐘，手機放遠一點；做題目、寫考古題，錯的整理成錯題本；睡飽，睡眠時大腦會整理記憶
看法=最有效的方法常常讓人覺得有點吃力，像自己考自己；感覺輕鬆的重讀，效果反而比較差
@沒時間運動|沒時間運動怎麼辦,太忙沒時間運動,加班沒時間運動,上班族怎麼運動,工作很忙怎麼運動,沒空運動怎麼辦|健康
開頭=沒時間運動，可以把運動塞進生活裡：
步驟=一次不用很久，每次 10 分鐘、一天累積 30 分鐘也有效；通勤多走一點：提早一站下車、走樓梯不搭電梯；在家做徒手運動：深蹲、伏地挺身、棒式、開合跳，做 7 到 10 分鐘就會流汗；午休或看劇時起來伸展、動一動；週末安排一次比較長的運動，像游泳、騎腳踏車
看法=與其等「有空再好好運動」，不如每天做一點點，養成習慣最重要
@語言發展遲緩|孩子三歲了還不太會說話正常嗎,小孩說話比較慢怎麼辦,小孩不太會說話,孩子說話慢正常嗎,兩歲還不會說話,小孩語言發展慢,寶寶什麼時候會說話|健康
開頭=每個孩子說話的速度不太一樣，但可以參考這些時間點：
步驟=大約 1 歲會叫爸爸媽媽、說第一個有意義的詞；1 歲半左右會說幾個到幾十個詞；2 歲會把兩個詞連起來說，像「媽媽抱」；3 歲大多能說簡單的句子，家人以外的人也大致聽得懂；平常多跟孩子說話、唸繪本，少讓他一個人看螢幕
就醫=2 歲還不太會說單字、3 歲還不會說短句、聽不太懂簡單的指令，或原本會說的話變少了，建議到兒童發展中心或兒童心智科做發展評估，越早協助效果越好
@聊天技巧|怎麼聊天才不會尷尬,怎麼聊天,聊天技巧,不會聊天怎麼辦,跟人聊天沒話題,怎麼開啟話題|生活
開頭=聊天不尷尬，可以這樣做：
步驟=多問開放式的問題：「你週末都在做什麼？」比「你週末有出去嗎？」更好接；認真聽，從對方的回答裡找下一個問題：「哇，你會潛水？在哪裡學的？」；分享一點自己的事，有來有往，對方才會放鬆；聊身邊的東西：天氣、食物、正在看的劇、最近的新聞；冷場時不用急，笑一笑換個話題就好
看法=會聊天的人不一定很會說，而是很會聽、會好奇
@讓對方喜歡我|怎麼讓對方喜歡我,怎麼讓他喜歡我,怎麼讓她喜歡我,怎麼吸引喜歡的人,怎麼讓喜歡的人注意到我|生活
開頭=想讓喜歡的人也喜歡你，可以這樣做：
步驟=先把自己照顧好：整潔、有精神，做自己喜歡的事，發光的人自然有吸引力；多找自然的機會相處，一起參加活動、聊共同的興趣；記住他說過的小事，下次提起，他會覺得被在意；真誠地關心，但不要黏太緊，給彼此空間；相處一段時間覺得有機會，就找個輕鬆的時候表達心意
看法=沒有辦法強迫一個人喜歡你；做真實的自己，喜歡上你的人，才是真的喜歡你
@伴侶很忙|男朋友很忙沒時間陪我怎麼辦,男朋友很忙,女朋友很忙沒時間陪我,另一半很忙怎麼辦,他太忙沒時間陪我,另一半工作很忙|生活
開頭=另一半很忙，覺得被冷落，可以這樣做：
步驟=先說出感受，不要指責：「我知道你最近很忙，但我有點想你」，比「你都不陪我」更容易被聽進去；一起約定固定的相處時間，像每天睡前講十分鐘電話、週末一起吃一頓飯；在他忙的時候，用小事表達關心：一則訊息、一杯咖啡；也安排好自己的生活，有自己的朋友和興趣，等待不會那麼難熬
看法=忙不代表不在乎；如果長期都只有你在配合、他也不願意調整，就值得好好談談這段關係
@婚前要談什麼|婚前要談什麼,結婚前要聊什麼,婚前溝通,結婚前要討論什麼,婚前要確認什麼|生活
開頭=結婚前，可以好好談談這些：
步驟=錢：收入、存款、負債，婚後錢怎麼管、怎麼分攤；住哪裡：要不要跟長輩住、買房還是租房；要不要生小孩、生幾個、怎麼教養；家務怎麼分工；跟雙方家人的相處方式、過年過節回誰家；彼此的工作和人生規劃
看法=這些話題現在談會有點尷尬，但婚後才吵會更累；談的時候重點是互相理解，不是說服對方
@培養興趣|怎麼培養興趣,找不到興趣怎麼辦,沒有興趣嗜好怎麼辦,怎麼找到自己的興趣,沒有喜歡做的事,怎麼培養一個新嗜好,想找個新嗜好,沒有嗜好|生活
開頭=想培養興趣，可以這樣開始：
步驟=想想小時候喜歡做什麼、做什麼時會忘記時間；列幾個好奇的事，每個都試試看，例如上一堂體驗課、看幾支教學影片；不用一開始就很厲害，給自己一個月試試看；找一起的同伴或社團，比較容易持續；試了不喜歡就換，這也是在認識自己
看法=興趣常常不是「找到」的，是做了以後慢慢喜歡上的
@人生方向|找不到人生方向怎麼辦,不知道自己要什麼,人生很迷惘怎麼辦,不知道未來要做什麼,找不到目標怎麼辦,不知道自己想做什麼,我很迷惘怎麼辦,很迷惘怎麼辦,迷惘怎麼辦,好迷惘怎麼辦,覺得很迷惘怎麼辦,怎麼找到人生目標,沒有人生目標,不知道人生要幹嘛|生活
開頭=找不到方向的時候，可以這樣慢慢找：
步驟=先不用急著找到「一生的志業」，從眼前的小事開始；寫下：做什麼事會讓你有成就感、別人常稱讚你什麼、你最不能忍受什麼；多嘗試：上課、做志工、打工、跟不同工作的人聊天；把想試的事變成小實驗，給自己三個月；照顧好身體和睡眠，人在很累的時候特別容易覺得迷惘
看法=方向常常是走出來的，不是想出來的；你願意想這件事，就已經在路上了
@不在意眼光|怎麼不在意別人的眼光,很在意別人的看法怎麼辦,太在意別人怎麼想,怎麼做自己,怕別人怎麼看我|生活
開頭=想少在意別人的眼光，可以這樣練習：
步驟=提醒自己：大部分的人其實沒那麼注意你，每個人都在忙自己的事；分清楚誰的意見重要：在乎你、了解你的人說的，可以參考，其他的聽聽就好；先問自己「我想要什麼」，再問「別人會怎麼想」；從小事開始做自己：穿想穿的、說真實的想法；做一件怕被看的事，你會發現結果沒想像中可怕
看法=在意別人是因為你善良、想被接納；但你的人生，最後是你自己在過
@改善人際關係|怎麼改善人際關係,人際關係不好怎麼辦,怎麼跟人相處,人緣不好怎麼辦,怎麼讓人緣變好,怎麼讓別人喜歡我,怎麼讓大家喜歡我,怎麼變得受歡迎,怎麼讓人喜歡我|生活
開頭=想改善人際關係，可以從這些小事做起：
步驟=主動打招呼、記住別人的名字；認真聽別人說話，不急著給建議或說自己的事；說到做到、準時，讓人覺得你可靠；真誠地稱讚和感謝，說出具體的地方；有不同意見時對事不對人，好好說；不用討好每個人，找到幾個合得來的朋友就很好
看法=人際關係是一點一點累積的，從今天對一個人好一點開始就好
@安太歲|安太歲要怎麼安,安太歲怎麼安,安太歲,安太歲要去哪裡,安太歲多少錢,犯太歲要安太歲嗎|生活
開頭=安太歲是民間的習俗，大致這樣做：
步驟=多在農曆新年到元宵節前後，到有供奉太歲星君的廟裡登記，填上姓名、生辰和地址；很多廟可以網路或電話登記，費用各廟不同，通常幾百元；登記後廟方會幫你安奉，一整年祈求平安；年底（農曆十二月）可以回去「謝太歲」，有的廟會統一辦理
提醒=信不信看個人，是一種讓心安的習俗；想知道自己今年的運勢，也可以跟我說生日，我用九型十二宮幫你看
@初一十五拜拜|初一十五要拜拜嗎,初一十五拜什麼,初一十五要拜嗎,初一十五拜拜要準備什麼,初一十五拜土地公|生活
開頭=初一、十五拜拜是台灣民間常見的習慣，不是一定要做：
步驟=很多家庭和商家在農曆初一、十五拜神明或土地公，祈求平安、生意興隆；家裡有神明廳的，會上香、換水、供奉水果或餅乾；商家常在初二、十六拜地基主和土地公；沒有拜拜習慣的也沒關係，心意最重要
提醒=拜拜的水果，民間習慣不放芭樂和番茄
@過年禁忌|過年有什麼禁忌,過年不能做什麼,春節禁忌,大年初一不能做什麼,過年不能掃地嗎|生活
開頭=過年常見的民間禁忌（信不信看個人）：
步驟=大年初一不掃地、不倒垃圾，怕把財氣掃出去；不打破東西，打破了要說「歲歲（碎碎）平安」；不說不吉利的話、不吵架；不借錢、不討債；初一不洗頭、不剪頭髮，有「洗掉好運」的說法；年初不哭、不罵小孩
看法=這些禁忌大多是希望新年有個好兆頭，輕鬆看待、大家開開心心最重要
@飽足感食物|吃什麼比較有飽足感,吃什麼比較不會餓,什麼食物比較有飽足感,怎麼吃比較不會餓,容易餓怎麼辦|健康
開頭=想吃得飽又不會一下就餓，可以選這些：
步驟=蛋白質：雞蛋、豆腐、無糖豆漿、雞胸肉、魚；高纖維的：蔬菜、燕麥、地瓜、糙米、全麥麵包；好的油脂：少量堅果、酪梨；喝湯、多喝水；少吃精緻的甜點和含糖飲料，血糖升得快、降得也快，很快又會餓
提醒=吃飯慢一點，大腦大約要 20 分鐘才會感覺到飽
@喝酒傷肝|喝酒傷肝嗎,喝酒對肝不好嗎,喝酒會傷肝嗎,喝酒對身體的影響|健康
開頭=會，酒精要靠肝臟代謝，喝多了會傷肝：
步驟=長期喝太多，會從脂肪肝、酒精性肝炎，慢慢變成肝硬化；酒精也會增加口腔、食道、肝臟、大腸和乳癌的風險；一喝就臉紅的人代表分解酒精的能力比較弱，傷害更大；就算要喝，也盡量少量、不要空腹喝、不要一次喝很多
提醒=一次喝很多（狂飲）可能酒精中毒，意識不清、叫不醒、呼吸很慢，要馬上打 119
@喝太多水|喝太多水會怎樣,水喝太多會怎樣,喝太多水會中毒嗎,水中毒是什麼|健康
開頭=一般人正常喝水不太會喝太多，但短時間喝非常多可能「水中毒」：
步驟=短時間內大量喝水（像幾小時內喝好幾公升），血液裡的鈉被稀釋，可能頭痛、噁心、意識不清，嚴重會抽筋；長時間運動、大量流汗時，只喝白開水不補電解質，也比較容易發生；平常分次喝、口渴就喝就好；有心臟、腎臟疾病的人，喝水量要照醫生的建議
提醒=尿液淡黃色，通常代表水喝得剛剛好
@物聯網|什麼是物聯網,物聯網是什麼,IoT是什麼,物聯網是什麼意思|生活
開頭=物聯網（IoT）是讓各種東西連上網路、互相溝通：
步驟=像智慧插座、掃地機器人、冷氣、電燈、門鎖、手錶都能連網；可以用手機遠端控制，例如回家前先開冷氣；東西可以自己收集資料、自動反應，例如感應到有人才開燈；也用在工廠、農業、交通和醫療
提醒=連網的設備記得改掉預設密碼、定期更新，避免被駭
@大數據|什麼是大數據,大數據是什麼,大數據是什麼意思,Big Data是什麼|生活
開頭=大數據指的是量非常大、種類很多、產生得很快的資料，用電腦分析找出規律：
步驟=例如網購平台分析大家買了什麼，推薦你可能喜歡的東西；地圖 App 用大家的位置資料算出塞車路段；醫院分析很多病歷，找出疾病的風險因素；資料越多，分析出來的結果通常越準
提醒=大數據也牽涉到個人隱私，使用時要注意個資保護
@API|什麼是API,API是什麼,API是什麼意思|生活
開頭=API（應用程式介面）是讓不同程式互相溝通的「窗口」：
步驟=就像餐廳的菜單和服務生：你不用知道廚房怎麼煮，只要照菜單點菜，服務生就把餐點送來；例如訂房網站用航空公司和飯店的 API 查空位和價格；天氣 App 用氣象單位的 API 拿到天氣資料；用 LINE、Google 帳號登入其他網站，也是透過 API
提醒=很多公司會開放 API，讓別人的程式可以使用他們的服務
@USB-C|什麼是USB-C,USB-C是什麼,Type-C是什麼,USB-C和Lightning差在哪,Type C是什麼|生活
開頭=USB-C（也叫 Type-C）是一種橢圓形、正反都能插的接頭：
步驟=現在大部分的 Android 手機、筆電、平板和新款 iPhone（iPhone 15 以後）都用 USB-C；同一條線可以充電、傳資料，有的還能接螢幕；支援快速充電，充電速度看充電器和線的規格；舊款 iPhone 用的是蘋果自己的 Lightning 接頭
提醒=USB-C 的線外觀都一樣，但速度和瓦數差很多，買的時候看清楚規格
@手機投影電視|手機怎麼投影到電視,手機畫面怎麼投到電視,怎麼把影片傳到電視,手機怎麼連電視,iPhone怎麼投影到電視,電視怎麼看YouTube|生活
開頭=把手機畫面放到電視上，有這幾種方法：
步驟=電視是智慧電視或有 Chromecast：手機和電視連同一個 Wi-Fi，在 YouTube、Netflix 裡按「投放」圖示；iPhone 搭配 Apple TV 或支援 AirPlay 的電視：打開控制中心 →「螢幕鏡像輸出」；Android 手機：下拉選單找「螢幕投放」或「Smart View」；用轉接線（像 USB-C 轉 HDMI）直接接電視，最穩定；智慧電視本身也有 YouTube App，可以直接用電視看
提醒=投放不了時，先確認手機和電視連的是同一個 Wi-Fi
@藍牙喇叭|藍牙喇叭怎麼連,藍牙喇叭怎麼配對,手機怎麼連藍牙喇叭,藍牙音響怎麼連,藍牙喇叭連不上|生活
開頭=連藍牙喇叭可以這樣做：
步驟=喇叭開機，長按藍牙鍵或配對鍵，直到燈號快速閃爍（進入配對模式）；打開手機的藍牙，在可用的裝置裡找到喇叭的名字，按一下配對；連上後喇叭通常會有提示音；連不上的話，把手機藍牙關掉再開，或在手機上「忘記此裝置」再重新配對；喇叭離手機近一點，中間不要隔太多東西
提醒=同時連了好幾個裝置時，喇叭可能會連到別台手機，先把其他裝置的藍牙關掉
@筆電接螢幕|筆電可以接螢幕嗎,筆電怎麼接螢幕,筆電接外接螢幕,筆電接電視,筆電怎麼雙螢幕|生活
開頭=可以，大部分筆電都能接外接螢幕：
步驟=先看筆電有什麼接孔：HDMI、USB-C（要支援影像輸出）或 DisplayPort；用對應的線或轉接頭接上螢幕；Windows 按「Windows 鍵 + P」選「延伸」，就能變成雙螢幕；Mac 到「系統設定 → 顯示器」調整排列；接電視也一樣，用 HDMI 線最方便
提醒=想用一條線同時充電和接螢幕，可以找支援 USB-C 的螢幕或擴充座
@吞嚥困難|老人吞嚥困難怎麼辦,長輩吞嚥困難,吃東西容易嗆到怎麼辦,老人吃飯容易嗆到,吞嚥困難怎麼辦,阿嬤吃東西會嗆到,長輩吃東西容易嗆到,老人家喝水會嗆到|健康
開頭=長輩吞嚥困難，可以這樣幫忙：
步驟=吃飯時坐正，頭微微往前低，吃完再坐 30 分鐘；一口份量小一點，慢慢吃，吞完再吃下一口；食物切小、煮軟，湯或飲料可以用增稠劑調成糊狀，比較不容易嗆；吃飯時不要說話、不要看電視分心；飯後檢查嘴巴裡有沒有殘留的食物
就醫=常常嗆咳、吃飯時聲音變沙啞、體重下降、反覆發燒或肺炎，要去看醫生，可以請復健科或語言治療師做吞嚥評估
@長輩喝水|長輩不愛喝水怎麼辦,老人不喝水怎麼辦,長輩喝水太少,爸媽不喜歡喝水,老人家不喝水|健康
開頭=長輩不愛喝水，可以這樣幫他多喝一點：
步驟=年紀大了口渴的感覺會變差，常常不覺得渴，所以要定時提醒；把水杯放在看得到、拿得到的地方，用他喜歡的杯子；溫開水、淡茶、湯、豆漿都算，也可以多吃水分多的蔬菜水果；少量多次，一次幾口就好；晚上怕跑廁所的，白天多喝一點
就醫=有心臟、腎臟疾病的長輩，喝水量要照醫生的建議；出現嘴唇乾、尿很少、意識不清，可能脫水了，要就醫
@排水孔堵住|排水孔堵住怎麼辦,排水孔堵住,浴室排水孔堵住,浴室排水孔堵住了,洗手台堵住,洗手台不通,水管堵住,水管不通,排水管堵住,水槽堵住,水槽不通,浴室積水,排水很慢,浴缸排水很慢,排水孔不通|生活
開頭=排水孔堵住，可以照這個順序試：
步驟=先把排水孔蓋拆下來，戴手套或用夾子把頭髮、菜渣撈出來，很多時候這樣就通了；倒一大壺熱水沖一沖（PVC 水管不要用滾燙的水，大約 60 到 70 度就好）；倒半杯小蘇打粉，再倒一杯白醋，等 15 到 30 分鐘後用熱水沖；用吸盤式通管器（皮老虎）對準排水孔，上下用力壓幾次；還是不通，可以用通管條，或照說明使用市售的通管劑（戴手套、保持通風，不要跟其他清潔劑混用）
提醒=平常在排水孔放一個濾網，頭髮、菜渣不要直接沖下去，炒菜的油也不要倒進水槽
看法=試過還是堵住、或好幾個排水孔一起堵，可能是管線深處的問題，就找水電師傅處理比較安全
@磨菜刀|菜刀不利,菜刀不利了,菜刀不利了怎麼辦,菜刀不利怎麼辦,刀子不利,刀不利,刀子鈍了,菜刀鈍了,刀鈍了,怎麼磨刀,磨刀,菜刀怎麼磨,刀子怎麼磨,怎麼磨菜刀,刀子變鈍,刀子不好切|生活
開頭=菜刀不利了，可以這樣磨：
步驟=用磨刀石最好：先把磨刀石泡水 10 到 15 分鐘，泡到不再冒泡；刀刃和磨刀石保持大約 15 到 20 度（刀背下面墊大約兩枚十元硬幣的高度）；從刀跟到刀尖，用穩定的力道來回推拉，兩面各磨 10 到 20 次；先用粗面磨出刃口，再換細面磨順；磨好用清水洗乾淨、擦乾，切一張紙試試，能順順切開就好了
提醒=懶得用磨刀石，可以用簡易磨刀器順著同一個方向拉幾次；陶瓷刀、鋸齒刀比較不適合自己磨
看法=平常用完洗乾淨擦乾，不要拿來剁骨頭、切冷凍的東西，刀子會利比較久
@讀書沒動力|讀書的動力,給我讀書的動力,給我一些讀書的動力,給我一點讀書的動力,讀書沒動力,讀書沒有動力,沒有讀書動力,讀不下去,書讀不下去,讀書讀不下去,書念不下去,念書念不下去,讀書提不起勁,念書沒動力,沒動力讀書,怎麼有讀書動力,怎麼讓自己想讀書,書讀不下去怎麼辦,讀不下去怎麼辦|學習
開頭=讀書沒動力的時候，可以這樣幫自己一把：
步驟=把目標切小：不要想「今天要讀完一整章」，改成「先讀 25 分鐘、做完 5 題」；用番茄鐘：讀 25 分鐘、休息 5 分鐘，開始比想像中容易；手機放到另一個房間，或打開專注模式；想清楚為什麼要讀：想考上的學校、想做的工作，寫下來貼在書桌前；讀完一段就給自己一點小獎勵，例如一杯飲料、一集影片；找讀書夥伴或去圖書館，周圍的人都在讀，自己也比較讀得下去
看法=動力常常是「開始做了之後」才出現的，所以先逼自己開始 5 分鐘就好；如果是累到讀不下去，先睡飽也是一種進度
@慶祝方法|我要怎麼慶祝,怎麼幫自己慶祝,升職要怎麼慶祝,升職怎麼慶祝,怎麼慶祝升職,考上怎麼慶祝,考上要怎麼慶祝,畢業怎麼慶祝|生活
開頭=值得慶祝的事，可以這樣好好犒賞自己：
步驟=吃一頓想吃很久的大餐，或約家人朋友一起吃；買一個想要很久的小禮物送給自己；把好消息分享給一路支持你的人，順便謝謝他們；安排一天假或一趟小旅行，好好放鬆；寫下這次是怎麼做到的，以後遇到困難時拿出來看
提醒=升職的話，可以請團隊喝飲料或吃點心，謝謝一起努力的同事；慶祝之外也別忘了休息，接下來的挑戰會更順
看法=我覺得最棒的慶祝是跟在乎的人一起分享：開心的事說出來，會變成兩倍的開心
@變有錢|我想變有錢,想變有錢,怎麼變有錢,要怎麼變有錢,如何變有錢,怎麼賺更多錢,怎麼讓自己變有錢,想要變有錢,我想要變有錢|生活
開頭=想變有錢，可以從這幾件事開始：
步驟=先記帳一個月，看清楚錢都花到哪裡；先存「緊急預備金」，大約 3 到 6 個月的生活費；收入一進來先存一部分（例如 10% 到 20%），剩下的才拿來花；增加收入：學一個能賺錢的技能、爭取加薪或升職、找適合自己的副業；投資前先學基本的理財知識、分散風險，不要借錢投資，也不要相信「保證獲利」；有高利息的負債（像信用卡循環利息）先還清
看法=變有錢沒有捷徑，最可靠的是「花得比賺得少、把差額存下來、再讓它慢慢長大」，時間會幫你
@變聰明|怎麼變聰明,要怎麼變聰明,如何變聰明,想變聰明,我想變聰明,怎麼讓自己變聰明,怎麼讓腦袋變好,怎麼變得更聰明,頭腦怎麼變好|學習
開頭=想讓腦袋更靈活，可以這樣做：
步驟=睡飽：睡覺時大腦會整理記憶，熬夜最傷思考；每天運動 20 到 30 分鐘，有氧運動讓大腦更有精神；多讀書、多問「為什麼」，遇到不懂的就查清楚；學一個新技能，像樂器、外語或寫程式，會讓大腦建立新的連結；把學到的東西講給別人聽，講得出來才是真的懂；少一點滑短影音，多做需要專心的事
看法=聰明不是天生固定的，大腦像肌肉，越用越靈活；我覺得最重要的是保持好奇心
@變快樂|怎麼樣才會快樂,怎麼才會快樂,怎樣才會快樂,怎麼讓自己快樂,怎麼讓自己開心,如何快樂,怎麼變快樂,要怎麼快樂起來,怎麼快樂起來,怎樣才能快樂,怎麼過得快樂|生活
開頭=想讓自己快樂一點，可以從這些小事開始：
步驟=先顧好身體：睡飽、吃好、每天動一動、曬點太陽，心情很吃身體的狀態；跟在乎的人聯絡，聊聊天、一起吃頓飯；每天寫下三件讓你感謝或開心的小事，練習看見好的地方；做一件讓你投入到忘記時間的事，像畫畫、運動、做菜；幫別人一個小忙，給出去的善意常常會回到自己身上；少一點跟別人比較，滑社群累了就放下手機
看法=快樂不是一直都很開心，而是心裡有空間、有人陪、有期待的事；如果低落持續兩週以上、做什麼都提不起勁，找身心科或心理諮商聊聊，也是照顧自己的一種方式
@清手機快取|怎麼清理手機快取,手機快取怎麼清,怎麼清快取,手機暫存檔怎麼清,清理手機暫存,快取怎麼清,手機快取要怎麼清|生活
開頭=清手機快取可以這樣做：
步驟=Android：打開「設定」→「應用程式」→ 選要清的 App →「儲存空間」→「清除快取」（不要按「清除資料」，會把登入和設定一起清掉）；iPhone 沒有一鍵清快取：Safari 到「設定 → Safari → 清除瀏覽紀錄和網站資料」；其他 App 到「設定 → 一般 → iPhone 儲存空間」，點佔空間大的 App，選「卸載 App」（會保留資料）或刪掉重新安裝；LINE、YouTube 這類 App 的設定裡，通常也有清除快取的選項
提醒=快取是 App 為了開得更快暫存的檔案，清掉不會刪你的照片和聊天紀錄，但第一次開會慢一點；清完過一陣子又會慢慢長回來，是正常的
@白飯加熱|白飯冷掉怎麼加熱,冷飯怎麼加熱,隔夜飯怎麼加熱,剩飯怎麼加熱,白飯怎麼加熱,飯冷掉怎麼辦,冷掉的飯怎麼加熱,剩飯要怎麼熱|做法
開頭=冷掉的白飯可以這樣加熱：
步驟=微波：在飯上灑一點水，蓋上微波蓋或保鮮膜（留一點縫），微波 1 到 2 分鐘，中途翻一下比較均勻；電鍋：飯放在碗裡，外鍋加半杯到一杯水，跳起來就好，最像剛煮好的口感；炒成炒飯：冷飯水分少，炒起來粒粒分明；加水或高湯煮成粥、泡飯，也很適合
提醒=剩飯最好在煮好 2 小時內放涼、蓋好冷藏；加熱要熱透，整碗都冒熱氣再吃
@包禮物|禮物怎麼包,禮物怎麼包比較好看,怎麼包禮物,包裝禮物,禮物包裝,怎麼包裝禮物,盒子怎麼包|生活
開頭=把禮物包得漂亮，可以這樣做：
步驟=量紙：包裝紙的長度要能繞盒子一圈再多 3 到 5 公分，寬度比盒子高度的兩倍多一點；盒子正面朝下放在紙中間，一邊的紙先往內摺 1 公分當漂亮的邊，包住盒子後用雙面膠或膠帶黏好；兩端的紙先把上面往下摺，左右兩邊往內摺成三角形，最後把下面的三角往上摺、黏好；綁上緞帶或麻繩，貼一張小卡片
提醒=用雙面膠黏在紙的內側，外面看不到膠帶會更漂亮；不是方形的禮物，可以先放進盒子或用不織布袋、紙袋裝
@寫信封|信封怎麼寫,怎麼寫信封,信封的寫法,信封格式,寄信信封怎麼寫,信封要怎麼寫|生活
開頭=台灣的信封可以這樣寫：
步驟=橫式信封（最常用）：左上角寫寄件人的郵遞區號、地址和姓名；正中間偏右寫收件人的郵遞區號、地址，下一行寫收件人姓名，後面加「先生／小姐 收」；郵票貼在右上角；直式信封：收件人地址寫在右邊、姓名寫在中間（字寫最大），寄件人寫在左下角，郵票貼在左上角；郵遞區號寫 3+3 碼（六碼）送得比較快，可以上中華郵政網站查
提醒=寫給長輩或正式的信，可以把「收」改成「啟」或「鈞啟」；重要的文件用掛號寄，比較能追蹤
@手機拍照|怎麼拍出好看的照片,怎麼拍照比較好看,手機拍照技巧,怎麼拍照,自拍怎麼拍比較好看,怎麼自拍比較好看,自拍技巧|生活
開頭=想拍出好看的照片，可以這樣做：
步驟=找好光線：靠窗的自然光最好，日出後和日落前一小時的「黃金時刻」光線最柔；打開相機的格線，用三分法構圖，把主角放在線的交叉點，不要每張都放正中間；拍之前把鏡頭擦乾淨；背景越簡單越好，雜物會搶走主角；點一下螢幕對焦，再上下滑調亮度；拍人的時候手機放低一點，腳會看起來比較長
提醒=自拍的話：手機拿得比眼睛稍微高一點，臉微微側一點，面向光源，用計時器或藍牙遙控就不會手晃；多拍幾張再挑
@練字|怎麼練字,練字方法,怎麼把字寫漂亮,字醜怎麼辦,怎麼寫字比較好看,字寫得很醜,怎麼練習寫字|學習
開頭=想把字練好，可以這樣做：
步驟=先挑一本喜歡的字帖，入門最適合楷書，可以先用描紅或透明紙描；握筆姿勢要正確、坐正，手腕放鬆；每天練 15 到 20 分鐘，比一週寫一次兩小時有效；注意字的結構：橫平豎直、重心要穩、左右或上下的比例；寫完拿去跟字帖比，圈出差最多的地方再練；用田字格、九宮格紙練，字的大小比較容易一致
看法=練字最重要的是「慢」：先寫慢寫對，熟了自然就快了
@學騎腳踏車|怎麼學騎腳踏車,學騎腳踏車,腳踏車怎麼騎,大人怎麼學騎腳踏車,騎腳踏車怎麼學,學腳踏車|生活
開頭=學騎腳踏車可以這樣練：
步驟=選高度合適的車，先把座墊調低，坐著時雙腳腳掌能踩到地；戴安全帽，在平坦、空曠、沒有車的地方練；先不踩踏板，用雙腳在地上滑行，練習平衡，能滑一段距離再進下一步；一腳踩在高處的踏板上，用力踩下去出發，眼睛看前方、不要看地上；練習輕輕捏煞車，停下來時先煞車再把腳放下；轉彎時放慢速度，身體跟著車自然傾斜
提醒=熟練後再把座墊調高到腳尖點地的高度，騎起來比較省力；上路要遵守交通規則，晚上記得開車燈
@種花|怎麼種花,種花的方法,在家怎麼種花,陽台種花,盆栽花怎麼種,怎麼種盆栽花|生活
開頭=在家種花可以這樣開始：
步驟=先看環境選花：陽台日照多可以選日日春、九重葛、繡球花，日照少的室內選觀葉植物；盆底要有排水孔，用排水好的培養土；澆水的原則是「土乾了再澆，一次澆透」，盆底流出水就夠了；大多數開花植物每天要有 4 到 6 小時的日照；開花期大約每兩週施一次開花用的肥料；把枯掉的花和黃葉剪掉，會開得更好
提醒=最常見的失敗是澆太多水讓根爛掉；買花的時候可以問店家這種花喜歡陽光還是半陰
@養魚|怎麼養魚,養魚的方法,魚缸怎麼弄,新手養魚,養魚要注意什麼,第一次養魚,在家養魚|生活
開頭=新手養魚可以這樣做：
步驟=新魚缸要先「養水」：裝好水、開著過濾器運轉 1 到 2 週，讓分解廢物的好菌長起來，再放魚；自來水要先除氯：放一天，或加水族店賣的除氯劑；新手可以選好養的魚，像孔雀魚、斑馬魚、燈科魚，不要一次放太多隻；一天餵 1 到 2 次，2 到 3 分鐘吃得完的量就好，吃不完的飼料會弄髒水；每週換四分之一到三分之一的水，不要一次全部換掉
提醒=魚缸不要放在太陽直射的地方，水溫變化太大魚會生病；新買的魚連袋子先放進魚缸漂 15 分鐘，讓水溫一樣再放出來
@房間變香|怎麼讓房間變香,房間怎麼變香,房間有味道怎麼辦,房間很臭怎麼辦,怎麼讓房間香香的,房間異味|生活
開頭=想讓房間香香的，可以這樣做：
步驟=先找臭味的源頭：垃圾每天倒、髒衣服和毛巾不要堆著、鞋子放在通風的地方；每天開窗通風至少 10 到 15 分鐘；放一小碗咖啡渣、小蘇打或竹炭吸附異味；床單、枕頭套一到兩週洗一次，窗簾也定期洗；再用擴香、香氛蠟燭或噴一點衣物香氛水；放一盆花或香草植物（像薰衣草、迷迭香）
提醒=家裡有貓狗的話，很多精油對牠們有害，擴香要選寵物可以用的；點蠟燭不要離開人
@黑頭粉刺|怎麼去黑頭粉刺,黑頭粉刺怎麼辦,鼻子黑頭怎麼辦,粉刺怎麼去,怎麼去粉刺,黑頭怎麼去,草莓鼻怎麼辦|健康
開頭=黑頭粉刺可以這樣照顧：
步驟=早晚用溫和的洗面乳洗臉，不要過度清潔、用力搓；用含水楊酸（BHA）的保養品，幫助毛孔裡的角質代謝；一週一到兩次溫和去角質就好；不要用手擠、少用粉刺貼，容易讓毛孔變大、發炎留疤；保養品和防曬選標示「不致粉刺」的；卸妝要卸乾淨
提醒=黑頭是毛孔裡的油脂和角質接觸空氣氧化變黑，不是髒；很嚴重或一直長的話可以看皮膚科，醫生可能會開 A 酸
@跟陌生人聊天|怎麼跟陌生人聊天,跟陌生人怎麼聊,不知道怎麼開話題,跟不熟的人聊什麼,怎麼跟不熟的人聊天|生活
開頭=跟陌生人聊天可以這樣開始：
步驟=先微笑、打招呼，眼神接觸一下；從當下的情境開始聊：今天的活動、天氣、對方身上有特色的東西；問開放式的問題，像「你怎麼會來這個活動？」，比「你好嗎」更容易聊下去；認真聽，接著對方說的話追問一兩句；也適度分享自己的事，對方才會覺得是在聊天不是被訪問；先避開太私人的話題，像收入、感情、政治
看法=聊不下去也沒關係，說一句「很高興認識你」禮貌地結束就好；多練幾次，就會越來越自然
@小孩不肯睡覺|小孩不睡覺怎麼辦,小孩晚上不睡,小孩不肯睡覺,小孩不想睡覺,孩子不睡覺怎麼辦,孩子晚上不睡,小孩很晚睡,哄小孩睡覺,怎麼哄小孩睡覺,小孩晚上不肯睡|生活
開頭=小孩晚上不肯睡，可以這樣試：
步驟=固定睡前流程：每天差不多同一個時間，洗澡、刷牙、換睡衣、講故事、關燈，讓身體知道「要睡了」；睡前 1 小時關掉電視、手機和平板，螢幕的光和聲音會讓小孩更興奮；白天多去戶外跑跑跳跳、曬太陽，把體力用掉；午睡不要太晚，下午 3 點前起床比較好；房間調暗、安靜、溫度舒服，可以給一個安撫物（小被子、玩偶）；小孩一直要玩的時候溫和但堅定：「現在是睡覺時間，明天再玩」，大人也一起躺下、關燈
提醒=新的習慣通常要一兩週才看得出效果，大人要有耐心、每天一樣；如果小孩睡覺打呼很大聲、半夜一直醒來，或白天特別累、脾氣特別差，可以問小兒科醫生
@挑耳機|耳機怎麼選,耳機怎麼挑,怎麼選耳機,怎麼挑耳機,藍牙耳機怎麼選,買耳機要注意什麼,耳機要買哪種|生活
開頭=挑耳機可以照這幾點想：
步驟=先想用途：通勤、搭車選有主動降噪的；運動選防水防汗、不容易掉的；打遊戲選延遲低的；長時間戴選輕、不壓耳朵的；入耳式小巧好帶，耳罩式音場比較好、比較不悶耳道但比較重；看續航力和充電盒能補幾次電；iPhone 搭 AirPods 或支援 AAC 的耳機最順，安卓可以看支援 LDAC、aptX 的；能的話先去門市試戴，舒適度比規格重要
提醒=入門的藍牙耳機大約一兩千元就有不錯的；想要好的降噪，通常要五千元以上
看法=我覺得「戴起來舒服、會想天天戴」比音質多好一點更重要
@被朋友利用|被朋友利用怎麼辦,朋友只會利用我,覺得被朋友利用,朋友只在需要我的時候才找我,被利用怎麼辦|生活
開頭=覺得被朋友利用，可以這樣做：
步驟=先看清楚：對方是不是只在需要幫忙時才出現、從來不回報，也不在乎你的感受；練習拒絕，不用找很多理由：「這次我沒辦法」；設好界線：哪些忙你願意幫、哪些不行；觀察對方被拒絕後的反應，真的朋友會理解；把時間和心力留給真正對你好的人
看法=願意幫忙是你的優點，但幫忙應該是你選擇的，不是被要求的；被拒絕就離開的人，本來就不是真心的朋友
@處理負面情緒|怎麼處理負面情緒,負面情緒怎麼辦,怎麼調適心情,心情怎麼調適,怎麼調整心情,怎麼轉換心情,情緒不好怎麼調適,怎麼管理情緒,情緒管理,怎麼控制情緒,情緒控制不好,怎麼管理情緒|生活
開頭=情緒很重的時候，可以這樣照顧自己：
步驟=先承認情緒，在心裡說出來：「我現在很生氣」「我現在很難過」，說得出來就會減輕一點；讓身體動一動：散步、慢慢深呼吸、洗個熱水澡；把發生的事和腦中的想法寫下來，看看有沒有別的解釋；找一個信任的人說說；做一件能讓自己好一點的小事，像聽喜歡的歌、喝一杯熱飲；情緒最高點的時候先不要做決定、不要傳訊息
看法=情緒沒有好壞，它是在提醒你在乎什麼；如果低落持續兩週以上、影響吃飯睡覺，可以找身心科或心理諮商聊聊
@原諒別人|怎麼原諒別人,怎麼原諒一個人,要怎麼原諒,怎麼學會原諒,該不該原諒他,要不要原諒他|生活
開頭=想原諒一個人，可以這樣慢慢來：
步驟=先承認自己受傷了，允許自己生氣、難過，不用急著原諒；原諒不代表認同對方做的事，也不代表一定要回到原本的關係；試著理解對方當時的處境（不是幫他找藉口，而是讓自己看得更完整）；決定不再讓這件事一直佔據你的心；需要的話設好界線，保護自己不再被同樣的事傷到；給自己時間，原諒常常是一次一次慢慢放下的
看法=原諒最主要是為了放過自己，讓心裡的重量變輕
@面對失敗|怎麼面對失敗,失敗了怎麼辦,怎麼從失敗中站起來,失敗後怎麼重新開始,很怕失敗怎麼辦,怎麼接受失敗|生活
開頭=失敗的時候，可以這樣陪自己走過：
步驟=先允許自己難過一下，不用馬上假裝沒事；把「這件事失敗了」和「我是失敗的人」分開，一次失敗不代表你這個人；冷靜下來後檢討：哪些是自己可以改的，哪些是運氣或環境；從這次學到一件事，寫下來；設一個小目標重新開始，先求有、再求好；跟信任的人聊聊，常常會發現很多人都經歷過
看法=很多厲害的人都失敗過很多次，差別只是他們沒有在失敗那裡停下來
@停止比較|怎麼停止跟別人比較,怎麼不跟別人比較,一直跟別人比較怎麼辦,總是羨慕別人怎麼辦,怎麼不羨慕別人,很愛跟別人比較|生活
開頭=停不下來跟別人比較的時候，可以這樣試：
步驟=提醒自己：社群上看到的是別人的精華片段，不是他的全部生活；少看會讓你不舒服的帳號，滑手機的時間也設個上限；改成跟過去的自己比，看看自己進步了什麼；寫下自己擁有的、做到的，就算是小事；把羨慕當成線索：你羨慕的，可能就是你真正想要的方向，可以開始一點一點去做
看法=每個人的時區不一樣，有人早一點、有人晚一點，你只要照自己的步調走
@冥想方法|冥想怎麼做,怎麼冥想,怎麼練習正念,正念怎麼練習,正念怎麼做,正念冥想怎麼做,冥想要怎麼開始,冥想的方法,怎麼開始冥想|生活
開頭=冥想（正念練習）可以這樣開始：
步驟=找一個安靜的地方坐好，背打直、肩膀放鬆，可以閉上眼睛；設一個計時器，從 3 到 5 分鐘開始就好；把注意力放在呼吸：感覺空氣從鼻子進出、肚子的起伏；分心是正常的，發現自己在想別的事，就溫柔地把注意力帶回呼吸，不用責怪自己；每天固定時間練一點，比偶爾練很久有效；也可以用 Calm、Headspace 這類 App 跟著引導練
提醒=冥想不是要「什麼都不想」，而是練習注意到自己在想什麼，再把注意力帶回來
@變堅強|怎麼讓自己堅強一點,怎麼變堅強,怎麼讓自己更堅強,想變得堅強,怎麼變得堅強,要怎麼堅強|生活
開頭=想變得堅強一點，可以這樣練習：
步驟=先知道：堅強不是不哭、不難過，而是難過完還願意往前走；照顧好身體，睡飽、吃好，身體穩了心才撐得住；遇到事情先分「我能控制的」和「我控制不了的」，力氣只花在前者；每撐過一件難的事就記下來，慢慢累積「我做得到」的信心；把大問題切成小步驟，一次只處理一步；身邊有可以依靠的人，開口求助也是堅強的一種
看法=最堅強的人，往往不是從來沒倒下，而是每次倒下都願意再站起來
@坐骨神經痛|坐骨神經痛怎麼辦,坐骨神經痛,屁股痛到腳,屁股到大腿痛,腰痛到腳|健康
開頭=坐骨神經痛（從腰、屁股一路痛或麻到大腿、小腿）可以這樣照顧：
步驟=痛的時候多休息，但不要整天躺著不動，可以慢慢走路；熱敷腰部和屁股，每次 15 到 20 分鐘；做溫和的伸展，像躺著把膝蓋抱向胸口、梨狀肌伸展，不痛的範圍內做；避免久坐，每 30 到 40 分鐘起來動一動；不要彎腰搬重物，搬東西時蹲下、用腿出力；需要的話照說明吃止痛藥
就醫=腳越來越無力、麻的範圍變大、大小便控制不住，要馬上就醫；一般疼痛超過兩週沒改善，可以看復健科、骨科或神經外科
@肌肉拉傷|肌肉拉傷怎麼辦,拉傷怎麼辦,運動拉傷,肌肉拉傷,大腿拉傷,小腿拉傷,拉到肌肉|健康
開頭=肌肉拉傷可以照這個順序處理：
步驟=馬上停止運動，讓受傷的地方休息；受傷後 48 小時內冰敷，每次 15 到 20 分鐘（隔一條毛巾，不要直接貼皮膚）；用彈性繃帶稍微包住，減少腫脹，但不要包太緊；把受傷的地方抬高，高過心臟；48 小時後腫脹消了，改成熱敷，開始做不會痛的輕度伸展；需要的話照說明吃止痛藥
就醫=受傷時聽到「啪」一聲、很快腫得很厲害或大片瘀青、完全使不上力或不能走路，或一兩週都沒改善，要去看骨科或復健科
@指甲倒刺|指甲旁邊的倒刺怎麼辦,指甲倒刺怎麼辦,手指倒刺,倒刺怎麼辦,手指長倒刺,指甲旁邊脫皮|健康
開頭=手指長倒刺可以這樣處理：
步驟=不要用手撕或用牙齒咬，會越撕越大、容易發炎；用乾淨的指甲剪或小剪刀，從根部把翹起來的皮剪掉；洗手後擦護手霜或指緣油，保持指緣濕潤；做家事、洗碗戴手套，少讓手泡水；多喝水，冬天特別注意保濕
就醫=指甲旁邊紅腫、發熱、化膿（可能是甲溝炎），要去看皮膚科
@眼睛紅|眼睛紅紅的怎麼辦,眼睛紅怎麼辦,眼睛很紅,眼睛充血怎麼辦,眼白很紅,眼睛紅紅的|健康
開頭=眼睛紅紅的，可以這樣處理：
步驟=常見的原因是用眼過度、眼睛乾、過敏或結膜炎；先讓眼睛休息，少看手機和電腦，每 20 分鐘看遠方 20 秒；可以點不含防腐劑的人工淚液；不要揉眼睛，手洗乾淨再碰眼睛；戴隱形眼鏡的先拿下來，改戴眼鏡
就醫=眼睛痛、視力變模糊、很怕光、有很多分泌物、被東西撞到或噴到化學物質，要盡快看眼科
@月經沒來|月經沒來怎麼辦,月經遲到怎麼辦,月經延遲,月經晚來,大姨媽沒來,生理期沒來,月經不來怎麼辦,月經不規則|健康
開頭=月經沒來，可以先這樣想：
步驟=如果有性行為，先用驗孕棒驗孕（月經延遲一週後驗比較準）；壓力大、作息亂、體重變化大、運動量突然增加，都可能讓月經延後；偶爾延後幾天到一週很常見，可以先記錄週期觀察；生活規律、睡飽、吃得均衡，週期通常會慢慢回來
就醫=超過 3 個月沒來、月經一直很不規則、或伴隨劇烈腹痛、異常出血，要去看婦產科
@手麻|手一直麻麻的,手麻怎麼辦,手一直麻,手麻麻的,手指麻怎麼辦,手很麻,手常常麻|健康
開頭=手常常麻麻的，可以這樣處理：
步驟=常見的原因是姿勢壓迫（像睡覺壓到手）、長時間用滑鼠或手機造成的腕隧道症候群，或頸椎的問題；先換個姿勢、甩甩手、活動一下手腕和手指；滑手機、打字時手腕放平，不要一直彎著，每半小時休息一下；睡覺不要把手壓在身體或頭下面
就醫=如果是突然一邊的手腳麻、沒力氣、嘴歪、說話不清楚，可能是中風，要馬上打 119；長時間手麻、半夜被麻醒，可以看神經內科或骨科
@慰問喪親|朋友家人過世要說什麼,朋友家人過世怎麼安慰,怎麼安慰喪親的人,朋友的爸爸過世要說什麼,朋友的媽媽過世要說什麼,同事家人過世要說什麼,節哀要怎麼說,怎麼安慰失去家人的人|生活
開頭=朋友失去家人的時候，可以這樣陪他：
步驟=話簡單、真誠就好：「聽到這個消息我很難過」「我在，有需要隨時找我」；避免說「我懂你的感受」「他去了更好的地方」「你要堅強」，這些話容易讓人更難受；主動提供具體的幫忙，像送一餐飯、幫忙跑腿、陪他處理事情，比「有需要再說」更實在；願意聽他說，提到過世的人也沒關係，很多人其實想聊聊；告別式可以出席，或依對方的宗教和習俗致意；過了幾週、幾個月再關心一次，那時候常常是最孤單的時候
看法=不用怕說錯話，陪在身邊本身就是最大的安慰
@原子筆漬|衣服沾到原子筆,原子筆沾到衣服,原子筆畫到衣服,衣服上的原子筆,原子筆的痕跡怎麼洗,原子筆洗不掉|生活
開頭=衣服沾到原子筆可以這樣處理：
步驟=越快處理越好，先不要直接丟洗衣機，熱水和烘乾會讓墨水更難洗；在污漬下面墊一張紙巾或舊布，用棉花或紙巾沾酒精（75% 的就可以）或卸妝水，輕輕按壓污漬，讓墨水被下面的紙吸走，不要來回用力搓，會越擦越大；換乾淨的地方重複按壓，直到顏色變淡；最後滴一點洗碗精或洗衣精搓一搓，用冷水沖掉，再照平常的方式洗
提醒=先在不明顯的地方試一下會不會褪色；絲、羊毛這類布料或很貴的衣服，直接送洗比較安全
@被狗咬|被狗咬到,被狗咬傷,被狗咬怎麼辦,被狗咬要打針嗎,被狗咬到要打針嗎,被狗狗咬|健康
開頭=被狗咬到，先這樣處理：
步驟=馬上用肥皂和大量清水沖洗傷口至少 15 分鐘，這一步最重要；用優碘消毒，用乾淨的紗布蓋住，傷口流血就壓住止血；盡快去看醫生，醫生會看傷口決定要不要打破傷風疫苗、要不要吃抗生素，以及要不要打狂犬病疫苗；記下是哪一隻狗，有主人的話問清楚有沒有打過狂犬病疫苗，可以的話觀察那隻狗 10 天有沒有異狀
提醒=⚠️ 被流浪狗或不明動物咬到、傷口很深或在臉和手上、流血止不住、之後傷口紅腫發熱化膿或發燒，一定要看醫生；台灣的野生動物（像鼬獾）有狂犬病，被野生動物咬到要馬上就醫
@網路一直斷線|網路一直斷,網路常常斷線,WiFi一直斷線,WiFi一直斷,網路斷斷續續,網路一直掉線,家裡網路一直斷|生活
開頭=網路一直斷線，可以這樣檢查：
步驟=先看是只有一台裝置斷線，還是全部都斷：只有一台的話，重開那台裝置、把 WiFi「忘記這個網路」再重新連；全部都斷的話，把數據機和路由器的電源拔掉，等 30 秒再插回去（先插數據機，等燈號穩定再插路由器）；檢查網路線有沒有鬆掉、折到；離路由器太遠或隔太多牆訊號會不穩，把路由器放在家裡中間、高一點的地方，或改連 5GHz（近距離比較快）、2.4GHz（穿牆比較好）；試過都一樣，就打給網路業者的客服，請他們檢查線路
看法=常常斷線、家裡又大，可以考慮加一台訊號延伸器或 Mesh 路由器
@吃飽想睡|吃完飯就想睡,吃飽就想睡,飯後想睡覺,吃完飯好想睡,吃飽飯就很睏,為什麼吃飽會想睡,午餐後好想睡|健康
開頭=吃飽就想睡很常見，可以這樣改善：
步驟=吃七、八分飽就好，吃太撐身體要花更多力氣消化，會更睏；少吃白飯、麵包、甜點這類精緻澱粉和甜食，多搭配蔬菜和蛋白質（豆、魚、蛋、肉），血糖比較不會忽高忽低；吃完起來走動 10 分鐘，或到戶外曬一下太陽；晚上睡飽，睡不夠的人飯後最容易撐不住；真的很睏，午睡 15 到 20 分鐘就好，睡太久醒來反而更昏
提醒=⚠️ 如果累到影響生活，又常常口渴、尿很多、體重莫名變輕，可以去檢查一下血糖
@耳機一邊沒聲音|耳機一邊沒有聲音,耳機只有一邊有聲音,耳機一邊聽不到,藍牙耳機一邊沒聲音,AirPods一邊沒聲音,耳機單邊沒聲音|生活
開頭=耳機只有一邊有聲音，可以這樣檢查：
步驟=先看手機的左右聲道平衡：iPhone 在「設定 → 輔助使用 → 音訊與視覺 → 平衡」，Android 在「設定 → 協助工具」裡找「音訊平衡」，要在正中間；有線耳機：插頭要插到底，換一台手機或電腦試試，是耳機的問題還是手機的問題；藍牙耳機：兩邊都要有電，把沒聲音的那一邊放回充電盒再拿出來，不行就把耳機從藍牙清單「忘記」，照說明書重置後重新配對；用乾的軟毛刷輕輕清掉耳機出聲孔的耳垢和灰塵
看法=換了裝置還是一樣，通常是耳機本身壞了，在保固期內可以送修
@信用卡遲繳|信用卡忘記繳,信用卡沒繳,信用卡晚繳,信用卡遲繳會怎樣,信用卡忘記繳費,信用卡卡費忘記繳,卡費遲繳|生活
開頭=信用卡忘記繳，可以這樣處理：
步驟=發現了就馬上繳，至少繳「最低應繳金額」；打給銀行客服說明是忘記了，第一次遲繳常常可以請銀行幫忙減免違約金；知道遲繳會有什麼代價：沒繳清的部分要付循環利息（年利率可能到 15%），遲繳還會被收違約金，拖久了會留在聯徵的信用紀錄，以後辦貸款、辦卡會受影響；之後設定從薪資帳戶自動扣繳，或在繳款日前幾天設提醒
看法=能繳全額就繳全額，只繳最低應繳金額，剩下的會一直被算利息
@貓吐毛球|貓咪吐毛球,貓一直吐毛球,貓吐毛球正常嗎,貓咪一直吐毛,貓吐毛,貓咪吐毛球怎麼辦|生活
開頭=貓咪偶爾吐毛球是正常的，可以這樣減少：
步驟=每天幫牠梳毛，換毛季（春天、秋天）更要勤梳，梳掉的毛就不會被吃進肚子；可以吃化毛膏或化毛配方的飼料，幫助毛跟著便便排出來；讓牠多喝水（多放幾個水碗、用流動飲水機，或吃一點濕食）；長毛貓可以請美容師把毛修短一點
提醒=⚠️ 如果一週吐好幾次、一直想吐卻吐不出來、不吃東西、沒精神、好幾天沒大便，可能是毛球卡住或其他問題，要盡快帶去看獸醫
@白飯太硬|白飯煮太硬怎麼辦,飯煮太硬,飯太硬,飯太乾,飯煮太乾,飯沒煮熟,米心沒熟,飯有米心|做法
開頭=白飯煮太硬，可以這樣補救：
步驟=用飯匙把飯翻鬆，一杯米大約灑 2 到 3 大匙水，灑在飯的表面；電鍋外鍋加半杯水再按一次，電子鍋就蓋上鍋蓋再煮或保溫 10 到 15 分鐘，讓飯吸水變軟；下次煮的時候，白米和水大約 1 比 1 到 1 比 1.2（電子鍋看內鍋刻度），新米水少一點、舊米水多一點；煮之前先泡水 20 到 30 分鐘，煮好後再燜 10 分鐘，飯會比較軟、比較均勻
提醒=已經硬掉的冷飯，拿來炒飯反而剛好
@雞胸肉不柴|雞胸肉怎麼煮才不會柴,雞胸肉很柴,雞胸肉好柴,雞胸肉怎麼煮,雞胸肉怎麼煎,雞胸肉嫩,雞胸肉要怎麼煮比較嫩|做法
開頭=雞胸肉不柴的做法：
步驟=先泡鹽水：1 公升水加 1 大匙鹽（可以再加一點糖），放冰箱泡 30 分鐘到幾個小時，肉會比較保水；把厚的地方拍平或切成一樣厚，才會熟得平均；水煮的話，水滾後放進去，馬上關火、蓋上鍋蓋燜 15 到 20 分鐘（看厚度），不要一直大火滾；用煎的就中火每面煎 4 到 5 分鐘，起鍋後靜置 5 分鐘再切，肉汁比較不會流掉；切的時候逆著紋路切，口感比較嫩
提醒=雞肉一定要熟透：有溫度計的話，中心溫度到 74°C 就可以起鍋，再煮下去就會越來越柴
@油炸油溫|炸東西油要多熱,油炸油溫,炸東西的油溫,油溫怎麼看,怎麼知道油夠熱了,炸東西油溫多少|做法
開頭=炸東西的油溫可以這樣看：
步驟=大部分裹粉的炸物用中溫 170 到 180°C 左右；沒有溫度計的話，把乾的木筷子插進油裡：筷子周圍慢慢冒小泡泡大約 160°C，泡泡很多、很快冒上來大約 170 到 180°C；想要外酥內嫩（雞排、薯條、炸雞），可以先用 160°C 左右炸熟，撈起來把油加熱到 180°C 再回鍋炸 1 分鐘；一次不要放太多，油溫會一下子降太多，炸物會吸油變軟
提醒=⚠️ 食物下鍋前先把水擦乾，免得油噴出來；油冒煙就是太熱了，先關火；油鍋起火要蓋上鍋蓋、關火，絕對不能潑水
@菜太鹹|菜太鹹了怎麼救,菜太鹹怎麼辦,煮太鹹了,湯太鹹了,鹽放太多了,煮得太鹹,菜煮太鹹|做法
開頭=菜煮太鹹，可以這樣救：
步驟=湯或滷的：加水或沒有調味的高湯稀釋，再煮滾；增加份量：加一些沒有調味的食材一起煮，像豆腐、蛋、蔬菜、菇類，鹹味會被分掉；炒的菜：可以分成兩份，一份再加新的食材重炒；加一點點糖或醋，味道會比較平衡，吃起來沒那麼死鹹（鹽其實沒有變少）；真的太鹹，就配白飯、白麵或夾吐司吃
看法=下次調味先少放，起鍋前試一下味道再補，鹹了比淡了難救
@救回刪掉的照片|照片不小心刪掉了,手機相簿照片不見了,相簿照片不見了,照片突然不見了,手機照片不見了,照片刪掉了怎麼救,刪掉的照片怎麼救回來,照片誤刪,不小心刪掉照片,手機照片刪掉了,刪除的照片可以救回來嗎|生活
開頭=照片不小心刪掉，先這樣找：
步驟=iPhone：打開「照片」→「相簿」→ 最下面的「最近刪除」，30 天內的都可以按「復原」；Android：Google 相簿的「垃圾桶」通常保留 60 天（有備份的），三星手機的「相簿」也有「資源回收筒」，保留 30 天；看看雲端備份：iCloud、Google 相簿、OneDrive 網頁版裡可能還有；想想有沒有傳給別人過：LINE 聊天室、LINE 相簿、社群貼文；都找不到又很重要的話，先不要再存新的東西進手機，再找專業的資料救援（要付費，也不保證救得回來）
看法=重要的照片平常就開自動備份到雲端，最省事
@電腦開不了機|電腦開不了機怎麼辦,電腦開不起來,電腦開機沒反應,筆電開不了機,電腦打不開,電腦按電源沒反應|生活
開頭=電腦開不了機，可以照這個順序試：
步驟=先檢查電源：插座、延長線開關、電源線有沒有插好，筆電先接上充電器充 30 分鐘再開；長按電源鍵 10 到 15 秒強制關機，再按一次開機；把外接的東西都拔掉（隨身碟、記憶卡、外接螢幕、印表機），再開一次；有亮燈、有轉但進不了系統：Windows 會出現「自動修復」，可以試「安全模式」或「系統還原」；Mac 可以試安全模式啟動；完全沒反應、一直嗶嗶叫，或螢幕黑的但聽得到風扇聲，可能是硬體問題，帶去送修
提醒=重要的資料平常就要備份；送修前問清楚會不會清掉硬碟裡的資料
@曬黑|曬黑了怎麼白回來,曬黑怎麼辦,曬黑了,曬黑多久會白回來,曬太黑了,怎麼快速白回來|健康
開頭=曬黑了，可以這樣照顧：
步驟=曬黑會慢慢退，皮膚大約一個月代謝一次，通常幾個星期到幾個月會淡回來；剛曬完皮膚發紅發燙，先冷敷、擦保濕，這時候先不要去角質或用刺激的保養品；之後每天擦防曬（SPF 30 以上，流汗或游泳後補擦），加上帽子、陽傘、袖套，不然會一直越曬越黑；保養品可以選含維生素 C、菸鹼醯胺這類成分的，幫助淡化
提醒=不要用來路不明、號稱馬上變白的美白產品；曬傷起水泡、發燒或頭暈要看醫生
@汽車電瓶沒電|汽車電瓶沒電怎麼辦,電瓶沒電,車子發不動,車子電瓶沒電,汽車發不動,電瓶沒電怎麼辦|生活
開頭=汽車電瓶沒電，可以這樣處理：
步驟=最省事：打給道路救援，很多汽車保險或信用卡有附免費的道路救援，先查一下保單；有救車線和另一台車可以「跨接」：兩台車都熄火，紅色夾子先夾沒電那台的正極（+），另一端夾好車的正極；黑色夾子一端夾好車的負極（−），另一端夾沒電那台引擎上沒上漆的金屬部分；先發動好的那台，等幾分鐘再發動沒電的那台；發動後照相反的順序拆夾子，讓車子開或發動 30 分鐘以上充電；車上常備一台「救車電源」，自己一個人也能發動
提醒=電瓶大約 2 到 3 年要換；常常沒電、發動很吃力，就該去保養廠檢查了；夾錯正負極很危險，不確定就等救援
@兔子不吃東西|兔子不吃東西怎麼辦,兔子不吃飯,兔子不吃草,兔子都不吃,兔子食慾不好|生活
開頭=兔子不吃東西要特別注意：
步驟=兔子的腸胃需要一直有東西在動，超過 12 小時不吃、或是便便變小、變少、沒有便便，可能是腸胃停滯，要盡快帶去看「特殊寵物」（兔子）門診；等看醫生的時候，放牠喜歡的牧草和乾淨的水在旁邊，讓牠待在安靜、溫暖的地方；看看牙齒有沒有長太長、嘴巴有沒有流口水，這也常讓兔子不想吃；不要自己亂餵藥或硬灌食，照醫生說的做
提醒=平常牧草要吃到飽，零食和水果少給，可以減少腸胃出問題
@小狗半夜哭|小狗半夜一直哭,幼犬半夜哭,幼犬晚上一直叫,小狗晚上一直哭,剛帶回家的小狗一直哭,小狗晚上哭|生活
開頭=剛帶回家的小狗半夜哭，通常是想家、害怕，可以這樣幫牠：
步驟=把牠的籠子或睡墊放在你房間或床邊，聽得到、聞得到你會比較安心；放一件有你味道的舊衣服、一條暖暖的毯子，可以放個小時鐘或白噪音陪牠；睡前帶牠上廁所、陪牠玩一下消耗體力，幼犬半夜可能還要起來上一次廁所；確定牠不餓、不冷、不用尿尿之後，牠為了討抱一直哭的時候，先不要馬上抱起來，安靜時再稱讚牠；不要打罵牠
看法=大部分小狗幾天到兩三個星期就會習慣；一直哭又有拉肚子、嘔吐、沒精神，要帶去看獸醫
@冰箱不冷|冰箱不冷了,冰箱不冷怎麼辦,冰箱好像不冷,冰箱冷藏不冷,冰箱不夠冷,冰箱突然不冷|生活
開頭=冰箱不冷，可以先這樣檢查：
步驟=先看插頭有沒有插好、有沒有跳電，冰箱裡的燈會不會亮；看溫度設定有沒有被調到最弱，冷藏室大約 1 到 5°C；門有沒有關緊：門邊的膠條髒了或變形會漏冷氣，擦乾淨，夾一張紙試試看會不會鬆鬆就抽出來；東西不要塞太滿，擋到出風口冷氣就吹不過去；冰箱背後和兩側要留一點空間散熱；冷凍庫結霜太厚要除霜；剛放進很多東西、剛停過電，要等幾個小時才會冷回來
提醒=都檢查過還是不冷，或是壓縮機一直沒在運轉、發出怪聲，就請原廠或家電行來修；修好之前，容易壞的肉、海鮮、牛奶先移到保冷箱或分給鄰居
@機車發不動|機車發不動了,摩托車發不動,機車發不起來,機車打不著,機車按了沒反應,機車騎不動|生活
開頭=機車發不動，可以照這個順序檢查：
步驟=先看油表，還有沒有油；右手把手上的紅色熄火開關有沒有被按到「OFF」；很多新的機車側柱放下來就發不動，把側柱收起來；按啟動鈕的時候要同時握住煞車；按了完全沒聲音、儀表燈很暗，多半是電瓶沒電，可以用腳踩發動桿試試，或推到附近的機車行充電、換電瓶；很久沒騎，汽油可能變質，也要請機車行看
提醒=電瓶大約 2 到 3 年要換一次；常常要按很多次才發得動，就該去保養了
@沒胃口|最近都沒什麼胃口,沒有胃口,沒胃口怎麼辦,吃不下飯,不想吃東西,食慾不好,食慾不振,最近吃不下|健康
開頭=沒什麼胃口的時候，可以這樣做：
步驟=先想想最近有沒有壓力大、睡不好、天氣太熱或剛感冒，這些都常讓人吃不下；少量多餐，一次吃一點點，不用逼自己吃完一整份；選清淡、好入口的東西，像粥、湯麵、蒸蛋、豆花，酸一點的（番茄、檸檬、醋）比較開胃；吃飯前出門走一走，固定時間吃，不要一直喝含糖飲料、吃零食填肚子
提醒=⚠️ 超過兩個星期都吃不下、體重明顯變輕、常常噁心想吐或肚子痛，或是心情一直很低落、什麼都提不起勁，要去看醫生（可以先掛家醫科）
@手機螢幕破了|手機螢幕摔破了,手機螢幕破掉,手機摔破了,手機螢幕裂了,手機螢幕碎了,螢幕摔破怎麼辦,手機螢幕破了怎麼辦|生活
開頭=手機螢幕摔破了，可以這樣處理：
步驟=先在破的地方貼一層透明膠帶或保護貼，避免碎玻璃割到手、碎屑掉進去；還能用的話，先把照片、聯絡人和 LINE 對話備份起來，送修時才不怕資料不見；查查有沒有保固或手機保險（像 AppleCare+、原廠保險、電信或信用卡附的手機險），可以省很多錢；原廠維修比較貴但零件有保障；外面的維修店比較便宜、比較快，但可能影響防水和原廠保固
提醒=觸控失靈、螢幕出現黑斑或漏液、手機變燙或電池鼓起來，要盡快修，不要再硬用
@手機一直重開機|手機一直自己重開機,手機一直重開,手機自動重開機,手機一直重新開機,iPhone一直重開機,手機會自己重開機|生活
開頭=手機一直自己重開機，可以照這個順序試：
步驟=先把手機和 App 都更新到最新版，系統或 App 的錯誤常常會讓手機重開；想想最近裝了什麼 App，先把它刪掉看看；看看儲存空間是不是快滿了，清出至少幾 GB；把手機殼拿掉、不要邊充電邊玩重的遊戲，太燙也會自己重開；電池老化（iPhone 在「設定 → 電池 → 電池健康度」看）也會讓手機突然關機重開；都沒用的話，先備份資料，再試試「重置所有設定」或回復原廠設定
提醒=電池鼓起來、手機很燙或摔過之後才開始重開，就不要再試了，直接送原廠或維修店
@健保卡註冊|健保卡怎麼註冊,健保卡註冊,健保卡網路註冊,健保卡註冊密碼,健保卡怎麼設定密碼|生活
開頭=健保卡註冊（用來報稅、查健保資料）可以這樣做：
步驟=最方便：下載「全民健保行動快易通」App，照著做「行動裝置認證」，綁定自己的手機；有晶片讀卡機的話，可以到健保署的「個人健保資料網路服務」網站，插健保卡註冊，設定網路服務密碼；不方便自己弄，可以帶健保卡和身分證到健保署各地的服務櫃台請人幫忙
提醒=密碼不要告訴別人，也不要用生日這種好猜的
@瓦斯用完了|瓦斯桶沒瓦斯了,瓦斯沒了,桶裝瓦斯用完了,瓦斯用完怎麼辦,叫瓦斯,怎麼換瓦斯,瓦斯桶怎麼換|生活
開頭=桶裝瓦斯用完了，可以這樣處理：
步驟=打給平常配合的瓦斯行叫一桶，報地址，他們會送來、幫你換好；可以先看瓦斯桶上貼的電話；等待的時候，把瓦斯桶上的開關關好，爐子和熱水器的開關也關掉；自己換的話，先關緊舊桶的開關再拆，新桶接好後用肥皂水塗在接頭上，有冒泡泡就是漏氣，要重新接或請瓦斯行處理
提醒=⚠️ 換好之後聞到瓦斯味，不要開關電器、不要點火，先打開門窗、關掉瓦斯桶開關，到外面再打電話給瓦斯行
@水龍頭滴水|水龍頭一直滴水,水龍頭關不緊,水龍頭一直漏水,水龍頭關了還在滴|生活
開頭=水龍頭一直滴水，可以這樣處理：
步驟=先確定是不是真的關緊了，有些把手要轉到底或壓到底；常見的原因是裡面的橡膠墊片或陶瓷閥芯磨損了：先關掉洗手台下面的止水閥（找不到就關總水閥），把把手拆開，帶舊的零件去五金行買一樣的換上；如果是接頭的地方在滴，可以把螺帽鎖緊一點，或纏一圈止洩帶；水龍頭太舊、拆不開，直接換一個新的或請水電師傅處理
看法=一直滴的水一個月可能浪費好幾百公升，早點修比較省
@喜歡的人不喜歡我|喜歡的人不喜歡我,我喜歡的人不喜歡我,單戀好痛苦,單戀,喜歡的人有喜歡的人了,被喜歡的人拒絕|生活
開頭=喜歡的人不喜歡你，真的很難受。可以這樣陪自己走過去：
步驟=先允許自己難過，想哭就哭，這不代表你不夠好，喜不喜歡本來就勉強不來；暫時拉開一點距離：少看對方的社群、少刻意製造見面的機會，心比較容易平靜下來；把注意力放回自己身上：好好睡、運動、跟朋友出去，做一件一直想做的事；找信任的朋友聊聊，說出來會比悶著好很多；過一陣子再回頭看，你會發現自己其實比想像中更有能力喜歡人、也值得被喜歡
看法=一個人不喜歡你，只代表你們不適合，不代表你不值得被愛
@麵包發霉|麵包發霉了還能吃嗎,麵包發霉切掉還能吃嗎,麵包發霉了切掉還能吃嗎,麵包發霉,吐司發霉,吐司發霉還能吃嗎,發霉的麵包|生活
開頭=麵包發霉了，整個丟掉比較安全：
步驟=麵包、吐司、蛋糕這種鬆軟的食物，黴菌的菌絲會長到看不見的裡面，只切掉發霉的地方，剩下的也可能已經有黴菌和毒素；同一袋裡的其他片也可能被污染了，最好一起丟；硬的起司、紅蘿蔔這類硬的食物，可以切掉發霉處周圍至少 2 到 3 公分再吃；麵包吃不完，可以分裝放冷凍，要吃再烤，比放冷藏更不容易發霉也比較不會變硬
提醒=不要湊近聞發霉的食物，避免吸進孢子
@長輩傳假消息|長輩一直轉傳假消息,長輩傳假新聞,爸媽一直傳假消息,長輩一直傳謠言,阿嬤一直傳假訊息,家族群組一直有假消息|生活
開頭=長輩一直轉傳假消息，可以這樣處理：
步驟=先不要在群組裡直接說「這是假的」，長輩容易覺得沒面子；私下溫和地說：「我查了一下，這個好像不太對，你看這個說明」，附上查核的網址；可以教長輩用「LINE 訊息查證」或把訊息傳給「Cofacts 真的假的」查證機器人，自己就能查；了解他為什麼轉傳，通常是關心你、怕你受騙，可以先謝謝他的好意；健康、投資、要你匯錢的訊息特別要提醒，這類最容易讓人受傷
看法=耐心比糾正更重要，被溫柔對待的長輩，下次比較願意先問你
@冷氣滴水|冷氣一直滴水,冷氣滴水,冷氣漏水,冷氣室內機滴水,冷氣在滴水,冷氣出風口滴水|生活
開頭=冷氣室內機一直滴水，可以這樣處理：
步驟=先關掉冷氣，拿水桶或毛巾接著，免得水滴到插座、電器或木頭地板；拆下濾網洗乾淨，濾網太髒會讓室內機結冰、退冰時就滴水；看看室內機後面的排水管有沒有折到、壓到，出水口有沒有被堵住（可以用吸塵器在出水口吸一下）；室內機有沒有歪掉，排水要往排水管那邊斜才流得出去
提醒=這些都沒問題還是一直滴，可能是排水管堵在牆裡、冷媒不足或安裝有問題，要請冷氣師傅來看；不要自己拆開室內機
@LINE收回訊息|LINE訊息怎麼收回,LINE的訊息收回,LINE傳錯訊息,LINE收回,怎麼收回LINE訊息,LINE傳錯人|生活
開頭=LINE 傳錯訊息可以這樣收回：
步驟=在聊天室裡長按那則訊息，選「收回」，對方那邊就看不到內容了；傳出去 24 小時以內才能收回，超過就沒辦法；收回之後聊天室會留一行「已收回訊息」的提示，對方知道你收回過東西；選「刪除」只會刪掉你自己手機上的，對方還是看得到
提醒=對方如果已經看過或截圖了，收回也沒辦法讓他忘記；重要的東西傳之前先確認是哪個聊天室
@撿到小貓|路上撿到小貓,撿到一隻小貓,撿到小貓怎麼辦,撿到流浪貓,路邊有一隻小貓,撿到幼貓|生活
開頭=路上撿到小貓，可以這樣做：
步驟=先在遠一點的地方觀察兩三個小時，很多小貓是貓媽媽暫時去找食物，太快帶走反而害牠離開媽媽；小貓受傷、在危險的地方、或很小又冷冰冰的，就先帶回來：用毛巾包著保暖（暖暖包要隔著毛巾），放在安靜的紙箱裡；不要餵人喝的牛奶，貓喝了容易拉肚子，要用寵物店的幼貓奶粉；盡快帶去獸醫院檢查年紀、健康，有沒有跳蚤、需不需要驅蟲；自己沒辦法養的話，可以聯絡各縣市的動物保護處或動保團體，請他們協助送養
提醒=小貓還不會自己上廁所時，餵完奶要用沾溫水的棉花輕拍屁股幫牠排便、排尿
@睡覺流口水|睡覺一直流口水,睡覺流口水,晚上睡覺流口水,睡覺會流口水,睡覺流口水正常嗎|健康
開頭=睡覺流口水很常見，常見的原因和改善方法：
步驟=常見原因：側睡或趴睡、鼻子塞住只好用嘴巴呼吸、太累睡得很沉；改善：試著仰睡，枕頭高度調到脖子舒服；鼻塞、鼻子過敏的話先處理鼻子；睡前不要吃太飽、太晚吃東西
提醒=⚠️ 突然一邊嘴角流口水、臉歪一邊、手腳無力或說話不清楚，可能是中風，要馬上打 119；常常打呼很大聲、睡醒還是很累，可以去耳鼻喉科或睡眠中心檢查有沒有睡眠呼吸中止症
@手乾裂|手好乾裂開了,手乾裂,手很乾,手部乾裂,冬天手乾裂,手乾到流血,手指乾裂|健康
開頭=手乾到裂開，可以這樣照顧：
步驟=洗手後馬上擦護手霜，選含凡士林、尿素或甘油的比較保濕；洗手、洗碗用溫水就好，熱水會把皮膚的油脂洗掉；洗碗、打掃時戴手套，少碰清潔劑；睡前厚厚擦一層護手霜或凡士林，再戴棉手套睡覺；已經裂開流血的地方，用凡士林封住或貼 OK 繃，讓它慢慢長好
提醒=擦了一兩週還是一直裂、脫皮、紅腫或很癢，可能是富貴手（手部濕疹），要去看皮膚科
@電腦字變大|電腦的字變大,電腦字太小,電腦的字太小,電腦字怎麼放大,把電腦的字變大,螢幕的字太小|生活
開頭=電腦的字太小，可以這樣放大：
步驟=Windows：到「設定 → 系統 → 顯示」，把「縮放」改成 125% 或 150%；只想放大文字的話，到「設定 → 協助工具 → 文字大小」拉大；Mac：到「系統設定 → 顯示器」選比較大的文字，或在「輔助使用」裡調整；看網頁時，按住 Ctrl（Mac 是 Command）再按加號就能放大，按減號縮小，按 0 恢復原本大小
看法=長輩用電腦，直接把整個縮放調大最方便
@鄰居堆雜物|鄰居一直在走廊堆東西,鄰居在樓梯間堆東西,鄰居亂堆東西,走廊堆雜物,公共走廊堆東西,樓梯間堆雜物|生活
開頭=鄰居在走廊、樓梯間堆東西，可以這樣處理：
步驟=先好好跟鄰居說，說明擋到走路、也是逃生的路線，很多人其實沒想到；有管理員或管委會的大樓，請他們出面提醒，公寓大廈的公共空間本來就不能隨便堆放私人物品；講了還是不改，而且擋到逃生通道、有火災的風險，可以打 1999 市民專線或向當地消防局反映
提醒=自己不要直接把別人的東西丟掉，免得變成另一場糾紛
@咬指甲|一直咬指甲,咬指甲改不掉,咬指甲怎麼改,愛咬指甲,小孩咬指甲|生活
開頭=想改掉咬指甲的習慣，可以這樣做：
步驟=把指甲剪短、修平，沒有東西可以咬；擦有苦味的指甲油（藥局買得到），咬到就會提醒自己；觀察自己什麼時候最會咬：緊張、無聊、滑手機的時候，在那時候讓手有別的事做，像捏壓力球、握筆；改善一段時間就給自己一點小獎勵
提醒=咬到流血、指甲周圍常常紅腫發炎，或是怎麼樣都控制不了、很焦慮，可以去看皮膚科或身心科
@眼鏡起霧|眼鏡一直起霧,戴口罩眼鏡起霧,眼鏡起霧怎麼辦,眼鏡容易起霧,眼鏡起霧|生活
開頭=眼鏡一直起霧，可以這樣改善：
步驟=戴口罩的話，把口罩上緣的鐵絲壓緊貼著鼻樑，眼鏡壓在口罩上面，呼氣比較不會往上跑；用眼鏡防霧噴劑或防霧布擦鏡片；從冷的地方進到溫暖的室內，先把眼鏡拿下來等一下，讓鏡片回溫
提醒=不要用衛生紙或衣服用力擦鏡片，容易刮傷鍍膜
@芒果催熟|芒果還沒熟,芒果還沒熟要怎麼放,芒果怎麼催熟,芒果要放多久才會熟,生芒果怎麼放|生活
開頭=芒果還沒熟，可以這樣放：
步驟=放在室溫、通風、不會曬到太陽的地方，蒂頭朝下；想快一點熟，用報紙包起來，或跟蘋果、香蕉一起放進紙袋，它們會放出幫助水果變熟的乙烯；通常一到三天，聞起來有香味、輕捏有一點軟就是熟了；熟了以後再放冰箱冷藏，兩三天內吃完
提醒=沒熟的芒果不要先冰，冰了就不太會再變熟
@ATM吞卡|ATM卡被吃進去了,提款卡被吃掉,ATM吃卡,提款機吞卡,ATM把卡吞了,金融卡被ATM吃掉|生活
開頭=提款卡被 ATM 吞進去，可以這樣處理：
步驟=先不要離開，也不要讓旁邊的陌生人「幫忙」操作；打 ATM 上面貼的客服電話，或打給你的發卡銀行，說明在哪一台、什麼時間被吞卡；擔心被盜用的話，可以先請銀行掛失；被吞的卡通常銀行會在營業時間取出，本人帶身分證到那家分行領回；如果是別家銀行的 ATM，卡片可能會被銷毀，就要向自己的銀行申請補發
提醒=補發前可以先用網路銀行或行動支付應急
@網銀密碼鎖住|網路銀行密碼鎖住了,網銀被鎖,網路銀行被鎖住,網銀密碼輸錯太多次,網路銀行登入被鎖,網銀密碼忘記|生活
開頭=網路銀行的密碼被鎖住，可以這樣處理：
步驟=先看銀行 App 或網銀登入頁有沒有「忘記密碼」「解鎖」的功能，很多銀行可以用手機門號、晶片金融卡或身分驗證線上重設；不行的話，打銀行的客服專線（在卡片背面或銀行官網）問怎麼解鎖；有些銀行要本人帶身分證、存摺和印鑑到分行重新申請
提醒=客服不會要你提供網銀密碼或簡訊驗證碼，有人這樣要就不要給
@馬桶一直流水|馬桶水一直流不停,馬桶一直在漏水,馬桶一直漏水,馬桶水箱漏水,馬桶一直在流水,馬桶水箱一直進水,馬桶一直漏水到馬桶裡,馬桶水流不停|生活
開頭=馬桶沖完水一直流不停，可以這樣檢查：
步驟=先關掉馬桶旁邊牆上的止水閥，避免一直浪費水；打開水箱蓋看看：最常見是底部的橡膠止水塞（止水皮）老化變形，蓋不緊，水就一直漏到馬桶裡；也可能是沖水把手連著的鍊子太緊，止水塞沒辦法完全蓋下去；或是進水器（浮球）卡住、水位調太高，水從溢流管一直流掉；止水塞、進水器在五金行都買得到，帶舊的去比對型號，自己換不來就請水電師傅
看法=水一直流，一個月可能多好幾度的水費，早點修比較划算
@網頁打不開|網頁打不開,網站打不開,網頁都打不開,瀏覽器打不開網頁,網頁一直轉圈圈|生活
開頭=網頁打不開，可以照這個順序試：
步驟=先開別的網站看看：別的網站都正常，可能是那個網站本身掛了，晚一點再試；別的也打不開，就檢查網路：Wi-Fi 有沒有連上、換用行動數據試試，或重開路由器；確認網址有沒有打錯；按重新整理，或換一個瀏覽器、用無痕視窗開開看；清除瀏覽器的快取和 Cookie；有裝廣告阻擋、VPN 這類外掛，先關掉再試
看法=只有一台裝置打不開、別的裝置正常，通常是那台裝置的設定或瀏覽器的問題
@電視沒聲音|電視沒有聲音,電視沒聲音,電視突然沒聲音,電視有畫面沒聲音|生活
開頭=電視有畫面卻沒聲音，可以這樣檢查：
步驟=先看遙控器是不是按到靜音，或音量被調到 0；用機上盒、遊戲機的話，那台機器自己的音量也要檢查；看看是不是還連著藍牙耳機、聲霸或外接音響，聲音被送到那邊去了；到電視的「聲音」設定，確認輸出是電視喇叭；把電視電源拔掉一分鐘再插回去重開
提醒=換了訊號來源、重開都沒聲音，可能是喇叭或主機板的問題，要找原廠維修
@藍牙耳機斷斷續續|藍牙耳機一直斷斷續續,藍芽耳機一直斷斷續續,藍牙耳機一直斷線,耳機聲音斷斷續續,藍牙耳機斷訊|生活
開頭=藍牙耳機聲音斷斷續續，可以這樣改善：
步驟=手機和耳機不要離太遠，手機放在另一邊口袋、背包裡，被身體擋住也容易斷；附近有很多 Wi-Fi、微波爐在運轉時比較容易被干擾，換個位置試試；耳機和手機都要有足夠的電，關掉手機的省電模式；把耳機從藍牙清單「忘記」，重新配對；更新耳機的 App 或韌體、手機的系統
看法=只有在某個地方特別會斷，多半是那裡的訊號干擾；到哪裡都斷，可能是耳機本身的問題
@洗衣機脫水跳動|洗衣機脫水的時候跳很大力,洗衣機脫水會跳,洗衣機脫水很大聲,洗衣機一直震動,洗衣機脫水晃很大,洗衣機跑來跑去|生活
開頭=洗衣機脫水時跳得很大力，可以這樣處理：
步驟=先按暫停，把衣服重新分散平均，大件的（棉被、牛仔褲、浴巾）吸了水很重，容易偏一邊；一次不要洗太多或太少件；檢查洗衣機有沒有放平，可以調整底下的腳座，或放一個水平儀看看；新買的滾筒洗衣機，要確認背後固定運送用的螺絲有拆掉
提醒=衣服放平均、機器放平還是一直跳、有怪聲或撞擊聲，可能是避震或軸承壞了，要叫維修
@熱水器忽冷忽熱|熱水器的水忽冷忽熱,熱水器忽冷忽熱,洗澡水忽冷忽熱,熱水一下冷一下熱,洗澡洗到一半變冷水|生活
開頭=熱水器的水忽冷忽熱，常見的原因：
步驟=水龍頭開太小：水量不夠，熱水器會一下點火一下熄火，把熱水開大一點再用冷水調溫度；同時有好幾個地方在用水（洗碗又洗澡），水壓變小也會這樣；桶裝瓦斯快用完了，火力不穩；用電池點火的熱水器，電池沒電也會點不太起來，換新電池試試；熱水器在室外、風很大時火容易被吹熄
提醒=⚠️ 熱水器要裝在通風的地方，室內型的一定要有排氣管；洗澡時覺得頭暈、想吐，馬上關水、打開窗戶、離開浴室；問題一直沒改善就請師傅檢查
@Gmail空間滿了|Gmail的空間滿了,Gmail容量不足,Gmail空間不夠,Google空間滿了,Google帳號儲存空間已滿|生活
開頭=Gmail 空間滿了，可以這樣清：
步驟=免費的 15 GB 是 Gmail、Google 雲端硬碟、Google 相簿一起共用的，三個都要看；Gmail 搜尋框輸入「has:attachment larger:10M」，找出大附件的信刪掉；清空「垃圾桶」和「垃圾郵件」，刪掉的信要清空垃圾桶才會釋放空間；到 Google 雲端硬碟和相簿刪掉不要的大檔案、影片；都不想刪的話，可以付費買 Google One 加大空間
提醒=空間滿了以後就收不到新信，要盡快處理
@小孩教育基金|小孩的教育基金,存小孩的教育基金,孩子的教育費怎麼存,幫小孩存錢,幫小孩存大學學費|生活
開頭=想幫孩子存教育基金，可以這樣做：
步驟=越早開始越輕鬆，時間可以幫你累積；開一個專門的帳戶，把孩子的紅包、補助和每個月固定存的錢放在一起，不跟家用混在一起；離要用的時間還很久（十年以上），可以考慮每月定期定額買分散風險的指數型 ETF 或基金；快要用到的錢（三五年內）就放定存或比較穩的地方；先算一下大概需要多少，再推算每個月要存多少
提醒=投資有漲有跌，不要把短期內一定要用的錢拿去投資
@跟另一半沒話題|跟男朋友沒話題,跟女朋友沒話題,我跟我男朋友都沒話題聊,跟老公沒話聊,跟另一半沒話題聊,情侶沒話題|生活
開頭=跟另一半沒什麼話聊，可以這樣試試：
步驟=分享今天的小事：吃了什麼、看到什麼好笑的，不用都是大事；問開放式的問題：「今天最開心的是什麼？」，比「今天好嗎」更好接；一起做新的事：去沒去過的地方、學一樣東西、一起看一部劇再聊心得；聊聊未來想做的事、想去的地方
看法=在一起久了，安靜地待在一起也很正常，不一定每分鐘都要有話題
@狗抓耳朵|狗一直抓耳朵,狗狗一直抓耳朵,狗一直甩頭抓耳朵,狗耳朵很臭,狗耳朵癢|生活
開頭=狗一直抓耳朵、甩頭，可以這樣看：
步驟=翻開耳朵看看：有沒有紅腫、黑黑或黃黃的分泌物、臭味，可能是耳朵發炎或耳疥蟲；不要用棉花棒往裡面挖，會把髒東西推得更深，也可能弄傷耳道；只是耳朵外面髒，可以用寵物專用的清耳液，倒進去輕輕按摩耳根，讓牠自己甩出來，再擦外面
提醒=⚠️ 一直抓到流血、耳朵很臭、頭歪一邊或走路不穩，要帶去看獸醫，耳朵發炎要用藥才會好
@狗便便有血|狗狗便便有血,狗大便有血,狗拉血便,狗的大便有血絲,狗拉肚子有血|生活
開頭=狗狗便便有血，可以這樣判斷：
步驟=只有一次、一點點鮮紅色的血絲，狗狗精神和食慾都正常：可能是吃壞肚子或用力排便，先餵清淡、少量，觀察一兩天；把便便拍照，記下顏色、次數、有沒有吃到奇怪的東西，看醫生時很有用
提醒=⚠️ 一直拉血、血很多、便便是黑色柏油狀、又吐又拉、沒精神不吃東西，或是還沒打完疫苗的幼犬，要馬上帶去看獸醫
@魚浮水面|養的魚一直浮在水面,魚一直浮在水面,魚一直在水面張嘴,魚缸的魚一直浮上來,金魚浮在水面|生活
開頭=魚一直浮在水面張嘴，多半是水裡缺氧或水質變差：
步驟=先確認打氣機、過濾器有沒有在運轉，沒有的話先開起來；換掉三分之一的水（新的水要先除氯、溫度跟原本的差不多）；這一兩天先少餵或不餵，吃剩的飼料撈起來；魚太多、魚缸太小也容易缺氧，考慮分缸
提醒=夏天水溫高，水裡的氧氣比較少，更要注意打氣和換水
@貓打噴嚏|貓咪一直打噴嚏,貓一直打噴嚏,貓打噴嚏,貓咪打噴嚏流鼻水|生活
開頭=貓咪打噴嚏，可以這樣判斷：
步驟=偶爾打幾個，精神食慾正常，可能只是灰塵、香水、清潔劑的味道刺激，保持空氣流通、少用味道重的東西就好；如果一直打噴嚏，又有鼻涕、眼屎變多、眼睛紅，可能是貓的上呼吸道感染（貓感冒）
提醒=⚠️ 不吃東西、沒精神、發燒、鼻涕變黃綠色，或是小貓、老貓，要帶去看獸醫；貓不能吃人吃的感冒藥
@家裡小飛蟲|家裡一直有小飛蟲,家裡好多小飛蟲,廚房有小飛蟲,果蠅好多,浴室有小飛蟲,家裡一直有果蠅|生活
開頭=家裡一直有小飛蟲，可以這樣處理：
步驟=廚房的多半是果蠅：廚餘每天倒、垃圾桶加蓋，熟透的水果放冰箱，水槽的菜渣清乾淨；可以做陷阱：小杯子裝蘋果醋或水果醋，加一滴洗碗精，果蠅會掉進去出不來；浴室、排水孔附近的多半是蛾蚋（小小的、翅膀像蛾）：用刷子刷排水孔，倒熱水或用通管劑清掉裡面的汙垢，晚上把排水孔蓋起來
看法=找到牠們在哪裡繁殖、把源頭清掉，比一直打蟲有效
@樟腦丸味道|衣櫃裡有樟腦丸的味道,衣服有樟腦丸味,樟腦丸的味道怎麼去掉,衣服樟腦味|生活
開頭=衣服、衣櫃有樟腦丸的味道，可以這樣去味：
步驟=把衣服拿出來掛在通風的地方，或拿到外面曬太陽，一兩天味道會散掉很多；還是有味道就照洗標再洗一次；衣櫃打開通風，放小蘇打粉、咖啡渣或活性碳吸味
提醒=⚠️ 家裡有嬰兒、蠶豆症（G6PD 缺乏症）的人，或養貓狗，不要用含萘的樟腦丸，誤吞或吸入太多可能有危險；防蟲可以改用樟木條、薰衣草包或防蟲片
@新衣服要先洗|新買的衣服要先洗嗎,新衣服要不要先洗,新衣服可以直接穿嗎,剛買的衣服要洗嗎|生活
開頭=新買的衣服，建議先洗過再穿：
步驟=衣服在製作和運送過程中可能有化學藥劑、甲醛、多餘的染料和灰塵，也被很多人試穿過；先洗一次可以減少皮膚過敏、發癢；深色和容易褪色的衣服第一次要分開洗，或先用冷水泡一下看會不會掉色；貼身的內衣褲、襪子、嬰兒的衣服一定要先洗
看法=照洗標上的方式洗，第一次洗特別要注意水溫
@羽絨被收納|羽絨被要怎麼收,羽絨被怎麼收納,羽絨衣怎麼收,冬天的被子怎麼收,羽絨被可以壓縮嗎|生活
開頭=羽絨被要收起來，可以這樣做：
步驟=收之前先確定完全乾燥，挑晴天拿出來曬一兩個小時、拍一拍讓它蓬鬆；裝在透氣的收納袋或棉布袋裡，不要用塑膠袋密封，容易悶出霉味；不要用真空壓縮袋壓很久，羽毛會被壓扁、不容易恢復蓬鬆；放在通風乾燥的地方，可以放一包除濕劑，上面不要壓重物
看法=明年拿出來用之前，再拿去曬一下太陽，就會恢復蓬鬆
@地板很黏|地板好黏怎麼拖都黏,地板拖完很黏,地板黏黏的,拖地越拖越黏|生活
開頭=地板怎麼拖都黏黏的，多半是清潔劑放太多或拖把太髒：
步驟=先用乾淨的清水再拖一遍，把殘留的清潔劑帶走；清潔劑照說明的量，不是越多越乾淨；拖把要常常洗乾淨、擰乾，髒水要換；油膩的廚房地板，可以用溫水加一點小蘇打或洗碗精拖，最後再用清水拖一次
看法=拖完開窗讓地板乾得快，也比較不會黏
@抹布很臭|抹布好臭,抹布有臭味,抹布發臭,抹布有霉味,抹布怎麼洗|生活
開頭=抹布有臭味，可以這樣處理：
步驟=每次用完用洗碗精搓洗乾淨、擰乾，攤開晾在通風的地方，不要揉成一團放著；臭了的話，放進鍋子用熱水煮 5 到 10 分鐘，或用溫水加含氧漂白劑（過碳酸鈉）泡半小時；擦桌子和擦地板的抹布分開用
看法=抹布大約一兩個月換一條，破了、洗不乾淨就換
@菜瓜布多久換|菜瓜布多久換,海綿菜瓜布多久換一次,洗碗海綿多久換,菜瓜布會不會很髒|生活
開頭=菜瓜布、洗碗海綿大約 2 到 4 個星期換一次：
步驟=每次用完沖乾淨、擰乾，放在通風的地方晾乾，不要一直泡在水槽裡；有臭味、變形、碎掉，就提早換；洗生肉的跟洗碗盤的最好分開用
看法=菜瓜布濕濕的又有食物殘渣，很容易長細菌，便宜的東西勤換最划算
@冰箱結冰|冰箱結很多冰,冷凍庫結冰,冷凍庫結霜,冰箱一直結冰,冷凍庫好多冰|生活
開頭=冷凍庫結很多冰（結霜），可以這樣處理：
步驟=常見的原因：門沒關緊、門邊膠條髒了或變形、太常開門、熱的東西直接放進去；除霜：把食物移到保冷箱，拔掉電源，打開門讓冰慢慢融化，可以放一碗熱水在裡面加速，下面墊毛巾接水；冰塊鬆了再輕輕拿下來，不要用刀子或尖的東西敲，會刺破冷媒管；擦乾以後再插電，等溫度降下來再放回食物
看法=很快又結一大片冰，就要請廠商檢查門的膠條或除霜功能
@微波爐異味|微波爐有怪味,微波爐好臭,微波爐有味道,微波爐怎麼清,微波爐裡面很髒|生活
開頭=微波爐有怪味、裡面髒，可以這樣清：
步驟=用微波可加熱的碗裝水，放幾片檸檬或倒一點白醋；微波 3 到 5 分鐘，讓蒸氣把裡面的髒污軟化，再悶 5 分鐘不要開門；拿出碗，用濕布把內壁、轉盤擦乾淨，轉盤可以拿出來用洗碗精洗；擦完開著門讓它晾乾
提醒=加熱的碗和水會很燙，戴隔熱手套拿；不要用鋼刷刮內壁
@烤箱清潔|烤箱要怎麼清,烤箱怎麼清理,烤箱好髒,烤箱裡面的油垢,小烤箱怎麼清|生活
開頭=烤箱可以這樣清：
步驟=先拔插頭，等完全冷卻；烤盤、烤網拿出來泡溫水加洗碗精，再用海綿刷；裡面的油垢用小蘇打粉加一點水調成糊，塗在髒的地方（避開加熱管），放幾個小時或一個晚上；用濕布把小蘇打糊擦掉，再用乾淨的濕布擦一遍；開著門讓它乾透再用
提醒=不要用鋼刷刮塗層，也不要把水直接噴到加熱管上
@電鍋內鍋燒焦|電鍋內鍋燒焦,電鍋內鍋燒焦怎麼洗,電鍋燒焦,內鍋燒焦黑黑的,電子鍋內鍋燒焦|生活
開頭=電鍋內鍋燒焦，可以這樣洗：
步驟=內鍋加水蓋過焦掉的地方，放 1 到 2 大匙小蘇打粉，泡幾個小時；或直接把內鍋放回電鍋，外鍋加一杯水按下去蒸一次，焦塊會變軟；不鏽鋼內鍋可以用菜瓜布刷；有不沾塗層的內鍋只能用軟海綿，不要刷
看法=洗乾淨之後，煮東西時水不要放太少、不要燉太久沒顧
@保溫瓶茶垢|保溫瓶有茶垢,保溫瓶怎麼洗,保溫杯有茶垢,杯子有茶垢,保溫瓶有臭味|生活
開頭=保溫瓶、杯子有茶垢，可以這樣洗：
步驟=倒入熱水，加一大匙小蘇打粉或檸檬酸，泡幾個小時或一個晚上；用長柄的瓶刷刷內壁和瓶底，再用清水沖乾淨；蓋子和矽膠圈拆下來分開洗，臭味常常藏在這裡；洗完打開晾乾再蓋起來
提醒=不要用漂白水或鋼刷，會傷到內膽
@腳底長繭|腳底長繭,腳底有厚皮,腳皮很厚,腳底長硬皮,腳底的繭怎麼去|健康
開頭=腳底長繭（厚皮），可以這樣處理：
步驟=洗澡後或用溫水泡腳 10 分鐘，等皮軟了，用磨腳石或磨腳板輕輕磨，不要一次磨太多；磨完擦含尿素的乳霜保濕；穿合腳、有緩衝的鞋子，長繭常常是鞋子磨出來的
提醒=不要自己用刀片割，容易受傷感染；有慢性病、腳的血液循環不好，或繭很痛、裡面有硬硬的核（可能是雞眼），給醫生處理
@暈車|坐車會暈車,暈車怎麼辦,坐車頭暈想吐,一坐車就暈,暈車要怎麼預防|健康
開頭=容易暈車，可以這樣預防：
步驟=盡量坐前座或車子前段，看前方遠的地方；坐車時不要看手機、看書；打開窗戶或把冷氣出風口對著自己，保持空氣流通；出發前不要吃太飽也不要空腹，避開油膩的食物；容易暈的人，可以在出發前 30 分鐘到 1 小時吃暈車藥（照藥盒說明，小孩要用兒童劑量）
看法=已經開始不舒服，就閉上眼睛、深呼吸，車子能停的話下車走一走
@溏心蛋|蛋要怎麼煮才會溏心,溏心蛋怎麼做,溏心蛋要煮幾分鐘,半熟蛋怎麼煮,糖心蛋怎麼做|做法
開頭=溏心蛋（半熟蛋）可以這樣做：
步驟=蛋從冰箱拿出來，鍋子水滾了以後，用湯匙輕輕把蛋放進去；中大火煮 6 到 7 分鐘（蛋比較大顆就煮 7 分鐘）；時間到馬上撈起來泡冰水，泡涼再剝殼比較好剝；想做成溏心蛋的滷汁，把醬油、味醂（或糖）、水大約 1:1:2 煮開放涼，蛋泡進去冷藏一個晚上
提醒=半熟蛋有沙門氏菌的風險，最好用洗選蛋；孕婦、小孩、長輩和免疫力比較差的人，蛋要煮熟再吃
@煮麵水滾再下|煮麵要冷水下還是熱水下,麵要水滾再下嗎,煮麵什麼時候下麵,麵條冷水下鍋可以嗎|做法
開頭=煮麵要等水滾了再下：
步驟=水要多一點，大火煮到大滾再放麵，麵條才不會黏在一起、不會糊；下麵後用筷子撥散，水再滾起來時可以加一碗冷水，重複一兩次（粗的麵）；照包裝上的時間煮，起鍋前撈一根吃吃看熟度
看法=冷水下麵，麵條泡在水裡的時間太長，外面會先糊爛
@醃牛肉|牛肉要怎麼醃才會嫩,炒牛肉怎麼醃,牛肉片怎麼醃,牛肉怎麼炒才嫩,牛肉醃法|做法
開頭=炒牛肉想要嫩，可以這樣醃：
步驟=逆著紋路把牛肉切成薄片；加一點醬油、米酒、少許糖和胡椒抓勻，再加 1 小匙太白粉抓一抓（想更嫩可以加一點點小蘇打粉）；最後倒一點油拌勻，把水分封住；醃 15 到 30 分鐘；下鍋用大火快炒，變色就起鍋，炒太久會變硬
看法=先把牛肉過油或快炒起鍋，等配料炒好再倒回去拌一下，最不容易老
@煎豬排|豬排要怎麼煎才不會硬,豬排怎麼煎,煎豬排會縮,豬排怎麼煎才嫩,里肌肉排怎麼煎|做法
開頭=豬排煎了不硬，可以這樣做：
步驟=用刀尖在豬排邊緣的白色筋膜上切幾刀（斷筋），煎的時候才不會縮起來；用刀背或肉槌把肉拍鬆一點；用醬油、米酒、蒜泥、胡椒醃 15 分鐘以上；中火熱鍋下油，每面煎 2 到 3 分鐘，看到兩面金黃、中間熟了就起鍋；起鍋後放 3 到 5 分鐘再切，肉汁才不會流掉
提醒=豬肉一定要熟透，切開中間不能是生的粉紅色
@魚去腥|魚要怎麼去腥,魚很腥怎麼辦,煮魚怎麼去腥味,魚有腥味,怎麼讓魚不腥|做法
開頭=魚要去腥，可以這樣做：
步驟=買回來把魚肚子裡的血塊和黑色的膜刮乾淨，這些是腥味的主要來源；用清水沖洗後，用紙巾把魚擦乾；兩面抹一點鹽，放薑片、蔥段，淋米酒醃 10 到 15 分鐘；煎或蒸的時候再放薑和蔥，起鍋前淋一點米酒或擠一點檸檬汁
看法=魚越新鮮越不腥，買的時候挑眼睛清亮、魚鰓鮮紅、按下去有彈性的
@蝦去腸泥|蝦子要怎麼去腸泥,蝦的腸泥怎麼挑,蝦子要去沙筋嗎,蝦子背上黑黑的怎麼去,怎麼挑蝦腸|做法
開頭=蝦子去腸泥可以這樣做：
步驟=帶殼的蝦：從頭往下數第二、三節的背部，用牙籤橫著穿過去，輕輕往上挑，就能把黑色的腸泥整條拉出來；剝好殼的蝦：用刀在背上淺淺劃一刀，把腸泥挑掉；挑完用一點鹽和太白粉抓一抓再沖洗，蝦肉會比較乾淨、脆
看法=腸泥是蝦的消化道，吃到不會怎樣，但口感和味道會差一點
@洗花椰菜|花椰菜要怎麼洗,青花菜怎麼洗,花椰菜有蟲怎麼洗,綠花椰怎麼洗乾淨|做法
開頭=花椰菜可以這樣洗：
步驟=先把花椰菜切成一小朵一小朵，菜梗的硬皮削掉；泡在水裡 10 到 15 分鐘（可以加一點鹽），讓藏在花裡的小蟲和髒東西跑出來；再用流動的水一朵一朵沖乾淨
看法=洗好馬上煮，不要洗完放很久，比較不會爛
@煎水餃|冷凍水餃可以用煎的嗎,冷凍水餃怎麼煎,水餃怎麼煎,煎餃怎麼煎,水餃用煎的|做法
開頭=冷凍水餃可以直接煎：
步驟=不用退冰，平底鍋倒一點油，把水餃排好；中火煎 2 到 3 分鐘，底部稍微金黃；倒水，大約到水餃三分之一的高度，馬上蓋上鍋蓋（小心油噴）；中小火悶到水快收乾（約 6 到 8 分鐘）；打開蓋子，再煎一下把底煎脆就好了
看法=想要有冰花，水裡加一點麵粉或太白粉（約 1 小匙麵粉兌 100 毫升水）
@蒸饅頭|蒸饅頭要蒸多久,冷凍饅頭怎麼蒸,饅頭要蒸幾分鐘,電鍋蒸饅頭|做法
開頭=蒸饅頭可以這樣做：
步驟=冷凍的饅頭不用退冰；用蒸鍋的話，水滾了以後放進去，中大火蒸 10 到 15 分鐘；用電鍋的話，外鍋放 1 杯水，饅頭放在盤子或蒸架上，跳起來就好了；蒸好先悶 2 到 3 分鐘再打開蓋子，饅頭比較不會回縮變皺
看法=鍋蓋包一條布或盤子下墊烘焙紙，可以避免水滴到饅頭上
@蒸地瓜|地瓜要怎麼蒸,電鍋蒸地瓜,地瓜要蒸多久,蒸地瓜要多久|做法
開頭=蒸地瓜可以這樣做：
步驟=地瓜刷洗乾淨，不用削皮；電鍋的話，中等大小的地瓜外鍋放 2 杯水，大顆的放 2 到 3 杯，跳起來再悶 10 分鐘；蒸鍋的話，水滾後大火蒸 30 到 40 分鐘；用筷子插插看，可以輕鬆插到中間就熟了
看法=放涼再冰起來，隔天吃冷的地瓜也很好吃
@馬鈴薯泥|馬鈴薯泥怎麼做,馬鈴薯泥做法,怎麼做薯泥,薯泥怎麼做|做法
開頭=馬鈴薯泥的做法：
步驟=馬鈴薯削皮、切塊，冷水下鍋，加一點鹽，煮 15 到 20 分鐘，筷子一插就碎就好了；倒掉水，趁熱用叉子或壓泥器壓成泥；加一小塊奶油、一點牛奶攪拌到滑順，再用鹽和黑胡椒調味
看法=喜歡有口感就不要壓太細；想更香可以加一點蒜末或起司
@手搖飲隔天|手搖飲料可以放到明天嗎,飲料可以放隔夜嗎,奶茶可以放到明天嗎,珍奶可以放冰箱嗎,手搖飲放冰箱|生活
開頭=手搖飲料最好當天喝完：
步驟=有奶的、加料的（珍珠、布丁、仙草）最好在幾個小時內喝完；喝不完要馬上蓋好放冰箱，隔天早上喝，風味會變差；珍珠冰過會變硬，不好吃；放在室溫好幾個小時、聞起來酸酸的、有怪味，就不要喝了
看法=嘴巴碰過吸管再放的，細菌更容易長，放冰箱也不要太久
@剩飯料理|剩下的白飯可以做什麼,剩飯可以做什麼,冷飯可以做什麼,隔夜飯可以煮什麼,白飯吃不完怎麼辦|做法
開頭=剩下的白飯可以做這些：
步驟=炒飯：隔夜飯比較乾，最適合炒；稀飯（粥）：加水或高湯煮成粥，放蛋、青菜、肉絲；飯糰：加一點鹽和海苔捏成飯糰；焗烤飯：鋪上醬料和起司放進烤箱；鍋巴、飯餅：壓扁用一點油煎到兩面酥脆
提醒=煮好的飯要在 2 小時內放冰箱，冷藏 3 到 4 天內吃完，吃之前要徹底加熱
@鑄鐵鍋保養|鑄鐵鍋要怎麼養,鑄鐵鍋怎麼保養,鑄鐵鍋生鏽,鑄鐵鍋養鍋,鑄鐵鍋可以用洗碗精嗎|做法
開頭=鑄鐵鍋可以這樣保養：
步驟=用完趁溫熱用熱水和軟刷洗，少量洗碗精也可以，不要泡在水裡；洗完馬上擦乾，放回爐子小火烘乾水分；用紙巾沾一點油，在鍋子裡外薄薄抹一層，再加熱一兩分鐘；收在乾燥的地方
提醒=生鏽了就用鋼刷把鏽刷掉，洗乾淨擦乾，再重複抹油加熱幾次就能救回來；剛開始少煮酸的東西（番茄、醋）
@重複冷凍|冷凍肉可以重複冷凍嗎,解凍的肉可以再冷凍嗎,退冰的肉可以再冰回去嗎,肉退冰了可以再冷凍嗎|做法
開頭=解凍過的肉，最好不要再冷凍回去：
步驟=每解凍一次，細菌就有機會增加，口感也會變差、出水；在冷藏室慢慢解凍、一直保持冰冷的生肉，如果真的用不完，可以盡快再冷凍，但品質會下降；用室溫或流水解凍的肉，要煮熟以後才能再冷凍；最好的方法是買回來先分成一次份量的小包再冷凍，要用多少拿多少
提醒=解凍後在室溫放超過兩小時的肉，不要再冷凍，也最好不要吃
@飯菜放涼再冰|飯菜放涼才能放冰箱嗎,熱的東西可以直接放冰箱嗎,剩菜要等涼了再冰嗎,熱湯可以直接冰嗎|做法
開頭=飯菜不用完全放涼才冰：
步驟=稍微降溫、不燙手了就可以放進冰箱，最好在煮好 2 小時內放進去，放在室溫太久細菌反而會長；一大鍋湯或滷肉，分成幾個小盒子比較快變涼；放進去之前蓋好蓋子；不要一次塞太多熱的東西，會讓冰箱裡其他食物的溫度上升
看法=夏天室溫高，更要早點冰
@滷肉太油|滷肉太油怎麼辦,滷汁太油,湯太油怎麼辦,滷肉的油怎麼去掉|做法
開頭=滷肉、湯太油，可以這樣去油：
步驟=最有效：整鍋放涼後冰冷藏，油會凝固浮在上面，用湯匙刮掉就好；急著吃的話，用廚房紙巾輕輕放在湯面吸油，或用湯杓沿著表面撇掉；下次做的時候，肉先汆燙，選瘦一點的部位，或先把肥肉煸出油倒掉
看法=冰過再加熱的滷肉，味道通常更入味
@湯太淡|煮湯太淡了,湯太淡怎麼辦,湯沒有味道,湯不夠味,煮的湯很淡|做法
開頭=湯太淡，可以這樣補救：
步驟=先少量加鹽，攪勻後試味道，再慢慢補，不要一次加太多；可以加一點醬油、魚露、味噌或高湯塊增加鮮味；加蔥花、胡椒、香油或一點點醋，味道會比較有層次；開蓋小火再煮一下讓湯收一點
看法=鹽最好在起鍋前再調，煮久了水分減少會變鹹
@蛋糕塌陷|蛋糕為什麼會塌,蛋糕烤完塌下去,蛋糕出爐就塌,戚風蛋糕塌陷,蛋糕回縮|做法
開頭=蛋糕烤完塌下去，常見的原因：
步驟=沒有烤熟：中間還是濕的，出爐就會塌，烤到竹籤插進去拿出來是乾淨的；烤的途中太早打開烤箱門，溫度突然下降；蛋白打發不夠，或拌麵糊時攪太久消泡；溫度太高，一下子膨脹太快，裡面撐不住；戚風蛋糕出爐後要馬上倒扣放涼
看法=每台烤箱溫度不太一樣，可以買一個烤箱溫度計確認
@畢業典禮穿著|畢業典禮要穿什麼,參加畢業典禮穿什麼,畢業典禮穿搭,畢業典禮家長穿什麼|生活
開頭=畢業典禮可以這樣穿：
步驟=畢業生：學校會發學士服、碩士服，裡面穿整齊的襯衫或洋裝，配好走路的皮鞋或乾淨的鞋子；典禮常常要站很久、走上台，不要穿太高的高跟鞋；家長、親友：穿整齊、輕便的便服或小正式就好，顏色明亮一點拍照比較好看；夏天戶外典禮記得防曬、帶水
看法=是開心的場合，不用像喪禮那樣穿全黑
@被搶功勞|開會的時候被搶功勞,同事搶我的功勞,功勞被搶走,主管搶功勞,被同事搶功|生活
開頭=被搶功勞，可以這樣處理：
步驟=平常就留下紀錄：用 email 或群組回報進度，寫清楚哪些部分是你做的；開會時主動補充細節：「這部分的資料是我整理的，我補充一下⋯」，自然地讓大家知道；私下跟對方好好說，說明你的感受和希望以後怎麼分工；如果是主管搶功或反覆發生，找適當的時機跟更上一層的主管談，帶著具體的成果和紀錄
看法=讓自己的工作被看見是一種能力，不是愛現
@不想參加聚餐|不想參加公司聚餐,公司聚餐可以不去嗎,不想參加尾牙,不想去部門聚餐,公司聚會可以拒絕嗎|生活
開頭=不想參加公司聚餐，可以這樣做：
步驟=聚餐通常不是工作義務，下班時間的活動可以婉拒；早一點、禮貌地說，理由簡單就好：「那天家裡有事」「最近比較累想早點休息」，不用解釋太多；偶爾參加一兩次，或只參加前半段、吃個飯就先走，也能維持關係；平常上班時多跟同事聊幾句，不去聚餐也不會被當成不合群
看法=如果是很重要的場合（尾牙、送別），出席一下通常比較好
@小組報告有人不做事|小組報告有人都不做事,分組報告有人不做,組員都不做事,團體作業有人擺爛,分組作業被拖累|生活
開頭=小組報告有人不做事，可以這樣處理：
步驟=一開始就把工作分清楚：每個人負責哪一段、什麼時候交，寫在群組裡；設定小的期限，提早發現誰沒進度；私下問他是不是有困難，給他一個明確、做得到的工作；講了還是不做，就留下紀錄（分工表、群組訊息），跟老師反映，有些老師有組內互評
看法=不要一個人默默全部扛下來，最後最累的是你
@打工被欠薪|打工被老闆欠薪,老闆不給薪水,打工的薪水沒發,薪水被拖欠,老闆欠薪水,工讀生薪水沒給|生活
開頭=打工被欠薪水，可以這樣處理：
步驟=先把證據留好：排班表、打卡紀錄、跟老闆的對話訊息、薪資單或之前的轉帳紀錄；用訊息或文字有禮貌地跟老闆要，寫清楚是哪幾天、多少錢；老闆還是不給，可以打 1955 勞工諮詢申訴專線，或向工作所在地的縣市政府勞工局申請勞資爭議調解，調解不用錢
看法=打工也受勞基法保障，工讀生一樣有基本工資和勞健保
@寫推薦信|要怎麼寫推薦信,推薦信怎麼寫,幫學生寫推薦信,推薦信要寫什麼,推薦函怎麼寫|生活
開頭=推薦信可以這樣寫：
步驟=開頭說明你是誰、跟被推薦人的關係、認識多久（例如「我是他大三專題的指導老師」）；中間寫 2 到 3 個具體的優點，每個都配一個真實的例子或成果，比一堆形容詞有說服力；可以提一點他還在成長的地方，看起來比較真誠；最後寫你推薦的程度，留下聯絡方式；篇幅一頁以內，看申請單位有沒有規定的格式
看法=請別人寫推薦信時，提早至少兩三週說，並附上自己的經歷重點和申請的目標，對方比較好寫
@查交通違規|要怎麼查交通違規,查罰單,怎麼查有沒有被開罰單,查交通罰單,有沒有被拍到超速怎麼查|生活
開頭=想查有沒有交通違規、罰單，可以這樣做：
步驟=到交通部公路局的「監理服務網」，點「違規查詢」，輸入身分證字號和車牌號碼；也可以用「監理服務」App，綁定之後可以收到違規通知；查到的罰單可以在網路上、便利商店或監理站繳
提醒=被拍到違規，通常要過一段時間（幾天到一兩個月）才會寄出、查得到
@查郵局包裹|郵局包裹要怎麼查,郵局掛號怎麼查,查郵件,郵局寄的東西怎麼查,包裹查詢郵局|生活
開頭=郵局的包裹、掛號可以這樣查：
步驟=找到寄件時拿到的收據，上面有郵件號碼；到中華郵政全球資訊網的「郵件查詢」，或用「中華郵政」App，輸入號碼就能看到現在到哪裡；寄到國外的國際包裹也可以用同一個號碼查
提醒=平信（一般信件）沒有號碼，沒辦法查
@想休學|想休學,大學休學要怎麼辦,要不要休學,休學會怎樣,辦休學要注意什麼|生活
開頭=想休學，可以先這樣想、這樣問：
步驟=先想清楚原因：是讀不下去、科系不適合、經濟、身體或心理狀況，有些問題轉系、減修或請長假也能解決；先跟導師、系辦或學校的諮商中心聊聊；問清楚學校的規定：休學最多可以休幾年、什麼時候前申請學費能退多少；男生要注意兵役緩徵會不會受影響，有申請學貸的也要問清楚還款會不會提前開始；也跟家人好好說明你的打算
看法=休學不是失敗，想清楚、有計畫的暫停，有時候反而走得更遠
@機車行照遺失|機車行照不見了,行照遺失,行照掉了怎麼辦,汽車行照不見了,補辦行照|生活
開頭=行照不見了，可以這樣補辦：
步驟=帶身分證和車牌號碼，到任何一個監理站或監理所申請補發，通常當天就能拿到，要繳一點規費；也可以先上監理服務網看看能不能線上申請；被偷的話，先到派出所報案
提醒=行照要隨車帶著，被臨檢沒帶可能會被開罰單
@健保欠費|健保欠費會怎樣,健保費沒繳,健保費繳不出來,健保欠費還能看病嗎,健保費可以分期嗎|生活
開頭=健保費沒繳，可以這樣處理：
步驟=欠費會被加收滯納金，拖久了可能被移送行政執行，所以還是要繳；真的繳不出來，可以打健保署的客服或到聯絡辦公室，申請分期繳納，經濟困難的也可以問有沒有紓困貸款或補助；現在大部分的人就算欠健保費，看病時還是能用健保，不要因為欠費就不敢看醫生
看法=換工作、離職的空窗期，記得把健保轉到公所或職業工會，不然會一直累積欠費
@App閃退|手機的App都閃退,App一直閃退,App打開就關掉,應用程式已停止,手機一直跳出應用程式已停止,App一直當掉|生活
開頭=App 一直閃退，可以照這個順序試：
步驟=把那個 App 完全關掉（從多工畫面滑掉）再打開；到 App Store 或 Google Play 把 App 更新到最新版；重新開機；看看手機的儲存空間是不是快滿了，清出一些空間；Android 可以到「設定 → 應用程式」，清除那個 App 的快取；還是不行就刪掉重新安裝（先確認裡面的資料有備份，像 LINE 的聊天紀錄）；也把手機系統更新到最新
看法=只有一個 App 閃退，多半是那個 App 的問題；很多 App 都閃退，可能是空間不足或系統的問題
@下載不了App|手機下載不了App,App下載不了,App Store下載不了,Google Play下載不了,App一直在等待中|生活
開頭=App 下載不了，可以這樣檢查：
步驟=確認網路正常，換 Wi-Fi 或行動數據試試；看儲存空間夠不夠；手機的日期時間要設成自動；把 App Store 或 Google Play 關掉重開，或登出帳號再登入；付費 App 要確認付款方式有沒有問題；手機系統太舊，有些新 App 不支援，可以先更新系統
看法=一直停在「等待中」，先暫停其他正在下載的東西，再重開機試試
@Apple ID被鎖|Apple ID被鎖住了,Apple ID鎖住,Apple ID被停用,Apple帳號被鎖,蘋果帳號被鎖住|生活
開頭=Apple ID 被鎖住，可以這樣解鎖：
步驟=到 iforgot.apple.com，輸入 Apple ID，用你信任的裝置或電話號碼驗證，重設密碼就能解鎖；iPhone 也可以在「設定 → 你的名字 → 登入與安全性」裡更改密碼；驗證不了的話，可以申請「帳號復原」，要等幾天，期間不要一直重複申請
提醒=蘋果不會用簡訊或電話叫你提供密碼、付款或點奇怪的連結，收到這種訊息不要理它
@iPhone忘記解鎖密碼|iPhone忘記解鎖密碼,iPhone密碼忘記,手機解鎖密碼忘了,iPhone已停用,忘記iPhone密碼,iPad密碼忘記|生活
開頭=iPhone 的解鎖密碼忘記了，只能清除手機再還原：
步驟=新一點的 iOS：鎖定畫面多輸錯幾次，會出現「清除 iPhone」或「忘記密碼？」，輸入 Apple ID 的密碼就能清除重設；或是把 iPhone 接到電腦，用 Finder（Mac）或 iTunes（Windows）進入「復原模式」再回復；清除後手機裡的資料會不見，有 iCloud 或電腦備份的話，設定時可以還原回來；過程中要用到 Apple ID 的密碼，先確定自己記得
提醒=不要找來路不明的「解鎖服務」，資料和帳號都有風險；之後可以用比較好記的密碼，或設定 Face ID
@螢幕亂點|手機螢幕一直自己亂點,手機自己亂按,螢幕亂跳,手機觸控失靈,手機螢幕自己點|生活
開頭=手機螢幕自己亂點，可以這樣試：
步驟=先拔掉充電器試試，用便宜或不合規格的充電器充電時最容易亂點；把螢幕擦乾淨、手擦乾，有水氣也會誤觸；保護貼翹起來或破掉，先撕掉看看；重新開機，把系統更新到最新
提醒=摔過、進過水，或拔掉充電器還是一直亂點，多半是觸控面板壞了，要送修
@手機喇叭破音|手機喇叭聲音破破的,手機喇叭破音,手機聲音沙沙的,手機喇叭有雜音,手機放音樂破音|生活
開頭=手機喇叭聲音破破的，可以這樣檢查：
步驟=用乾的軟毛刷輕輕清喇叭孔的灰塵和棉絮；拿掉手機殼，看看是不是擋到喇叭；音量不要開到最大，有些手機開最大會破音；重新開機；插耳機或連藍牙聽聽看，耳機正常就是喇叭本身的問題
提醒=手機進過水、或喇叭一直破音，多半要換喇叭，送原廠或維修店處理
@手機麥克風|手機麥克風對方聽不到,講電話對方聽不到,手機麥克風壞了,打電話對方聽不到我的聲音,手機收音很小|生活
開頭=講電話對方聽不到你的聲音，可以這樣檢查：
步驟=看看通話畫面是不是按到了「靜音」；手機殼、手指是不是擋住手機底部的收音孔，用軟毛刷清一清；是不是還連著藍牙耳機，聲音被送到耳機那邊；用 LINE、視訊打不出聲音的話，到「設定」確認那個 App 有開麥克風權限；開錄音 App 錄一段聽聽看，或開擴音試試，再重開機
提醒=錄音也錄不到聲音，多半是麥克風壞了，要送修
@電腦風扇很吵|電腦一直發出很大的風扇聲,電腦很燙,筆電很燙,電腦風扇很大聲,筆電風扇一直轉,電腦過熱|生活
開頭=電腦風扇很大聲、很燙，可以這樣改善：
步驟=打開工作管理員（Windows 按 Ctrl+Shift+Esc；Mac 用「活動監視器」），看看是什麼程式在吃 CPU，用不到的關掉；筆電放在硬的桌面上，不要放在床上、棉被、腿上，出風口要留空間；用很久的電腦，裡面常常積滿灰塵，可以請店家清灰塵、換散熱膏；筆電可以墊一個散熱墊
提醒=很燙又會自己關機、或風扇發出喀喀的怪聲，要送修檢查
@USB讀不到|USB插上去讀不到,隨身碟讀不到,隨身碟插電腦沒反應,外接硬碟讀不到,USB沒反應|生活
開頭=隨身碟、外接硬碟插上去讀不到，可以這樣試：
步驟=換一個 USB 孔，或插到別台電腦試試，判斷是隨身碟還是電腦的問題；拔掉重插，外接硬碟要接到電腦本體的孔，不要接在延長的集線器上；Windows 可以打開「磁碟管理」，看看有沒有出現但沒有磁碟代號，可以幫它指派一個；在 Mac 格式化過的硬碟，Windows 可能讀不到，反過來也是
提醒=裡面有重要資料又讀不到，先不要格式化，找專業的資料救援
@筆電鍵盤進水|筆電鍵盤進水,筆電潑到水,筆電打翻飲料,電腦鍵盤進水,筆電泡水|生活
開頭=筆電鍵盤進水，馬上這樣做：
步驟=立刻按住電源鍵關機，拔掉充電線，能拆電池的把電池拆下來；把筆電打開、鍵盤朝下倒扣成「人」字形，讓水流出來；用乾毛巾把表面擦乾，不要用吹風機的熱風吹；放在通風的地方至少等 48 小時，完全乾了才開機
提醒=打翻的是含糖飲料、咖啡、牛奶，乾了也會黏、會腐蝕，最好直接送修清理；不要一直開機測試
@Word沒存檔|Word檔案沒存檔就關掉了,Word沒存檔,Word當掉沒存,Word檔案不見了,忘記存檔|生活
開頭=Word 沒存檔就關掉，可以這樣找回來：
步驟=重新打開 Word，左邊常常會出現「文件修復」，點開找回來後馬上另存新檔；或到「檔案 → 資訊 → 管理文件 → 復原未儲存的文件」找找看；用 OneDrive 存檔的，可以開啟「自動儲存」，之後就不怕忘記存
看法=到「選項 → 儲存」，把自動回復的時間改成每 1 到 5 分鐘，損失會比較少
@Excel亂碼|Excel打開是亂碼,CSV打開亂碼,Excel中文亂碼,CSV檔案亂碼|生活
開頭=Excel 打開 CSV 是亂碼，多半是文字編碼的問題：
步驟=不要直接點兩下打開，改用 Excel 的「資料 → 從文字/CSV」匯入；在「檔案原點」選「65001：Unicode (UTF-8)」，預覽看到中文正常再按載入；或用記事本打開 CSV，另存新檔時編碼選「UTF-8」（有 BOM 的版本），再用 Excel 開
看法=如果是 .xlsx 打開就亂碼，可能是檔案壞了，可以試試「開啟並修復」
@掃描成PDF|怎麼掃描文件成PDF,手機掃描文件,文件怎麼掃描成PDF,用手機掃描,掃描成PDF|生活
開頭=把紙本文件掃描成 PDF，可以這樣做：
步驟=iPhone：打開「備忘錄」，點相機圖示選「掃描文件」，對準紙張會自動拍，存好後可以分享成 PDF；Android：打開「Google 雲端硬碟」，按「＋」選「掃描」，存下來就是 PDF；有掃描器或多功能事務機的話，掃描時選存成 PDF
看法=在光線充足、背景顏色跟紙不一樣的地方拍，掃出來比較清楚
@WiFi換密碼|WiFi要怎麼換密碼,WiFi密碼怎麼改,改WiFi密碼,換無線網路密碼,路由器密碼怎麼改|生活
開頭=要改 Wi-Fi 密碼，可以這樣做：
步驟=看路由器（分享器）底部的貼紙，上面有管理頁的網址（常見是 192.168.0.1 或 192.168.1.1）和登入帳號密碼；用連著這台 Wi-Fi 的電腦或手機打開瀏覽器，輸入那個網址登入；找到「無線設定」或「Wi-Fi 設定」，修改密碼後儲存；很多新的路由器也可以用它們的 App 改
提醒=改完之後，家裡所有連 Wi-Fi 的裝置都要重新輸入新密碼；密碼至少 8 碼，混合英文數字
@舊手機處理|舊手機要怎麼處理,舊手機怎麼辦,不用的手機怎麼處理,舊手機回收,舊手機可以賣嗎|生活
開頭=舊手機要處理掉之前，先這樣做：
步驟=先把照片、聯絡人、LINE 聊天紀錄備份好；登出帳號：iPhone 要關掉「尋找我的 iPhone」、登出 Apple ID，Android 要移除 Google 帳號；再「重置／清除所有內容和設定」；拔掉 SIM 卡和記憶卡；之後可以賣二手、在門市以舊換新、送給家人，或拿到電信門市、回收點做電子廢棄物回收
提醒=手機裡有鋰電池，不要丟進一般垃圾
@電腦錄螢幕|電腦怎麼錄螢幕,Windows錄螢幕,Mac錄螢幕,電腦螢幕錄影,筆電錄螢幕|生活
開頭=電腦錄螢幕可以這樣做：
步驟=Windows 11：打開「剪取工具」，切換到錄影，選範圍就能錄；也可以按 Windows 鍵 + G 打開 Xbox Game Bar 錄目前的視窗；Mac：按 Shift + Command + 5，選錄整個螢幕或選取範圍，按「錄製」；要錄到聲音的話，記得在選項裡開麥克風
看法=需要剪輯、加字幕，可以用免費的 OBS 錄影
@小孩用平板|平板可以給小孩用嗎,小孩可以玩平板嗎,小孩看平板多久,幾歲可以給小孩平板,小孩一直玩平板,小孩一直看電視,小孩電視看太多,小孩一直看卡通|生活
開頭=小孩用平板，可以照這個原則：
步驟=2 歲以下盡量不要看螢幕（跟家人視訊除外）；2 到 5 歲每天不超過 1 小時，最好有大人陪著一起看、一起聊；6 歲以上也要約好每天的時間和內容；用平板內建的家長監護功能，設定時間和能用的 App；放在客廳用，吃飯和睡前一小時不要用
看法=與其完全禁止，不如一起挑好的內容，用完就收起來，讓它變成習慣
@護照換發|護照快過期了要怎麼換,護照過期要怎麼換,護照換新,護照到期怎麼辦,換護照要準備什麼|生活
開頭=護照快過期了，可以這樣換：
步驟=很多國家要求護照效期還有 6 個月以上才能入境，剩不到一年就可以準備換；準備：舊護照、國民身分證正本、6 個月內拍的 2 吋白底彩色照片；可以到外交部領事事務局（台北或中、南、東、雲嘉南辦事處）辦，也可以到任何一個戶政事務所「一站式」申辦；成人護照的規費大約 1,300 元，一般約 4 到 5 個工作天可以拿
看法=出國前一兩個月就要先檢查護照效期，旺季前辦比較不用排隊
@行李箱密碼忘了|行李箱的密碼忘了,行李箱密碼鎖打不開,忘記行李箱密碼,海關鎖密碼忘記|生活
開頭=行李箱的密碼鎖忘記密碼，可以這樣試：
步驟=三位數的密碼鎖只有 000 到 999 一千種，從 000 開始一個一個慢慢轉，每轉一次按一下開關，耐心試大約半小時內會打開；有些鎖仔細看縫隙、輕拉鎖頭慢慢轉，轉到對的數字時會比較鬆；打開以後照說明書重設一組記得住的密碼；真的打不開，可以找行李箱品牌的客服或鎖匠
看法=把密碼記在手機備忘錄裡，別寫在行李箱上
@飛機延誤|飛機延誤怎麼辦,班機延誤,航班延誤,飛機誤點,班機取消怎麼辦|生活
開頭=飛機延誤或取消，可以這樣處理：
步驟=先看航空公司的 App、簡訊或機場螢幕，確認新的起飛時間；到航空公司櫃台或打客服，問能不能改搭其他班機，延誤很久時有些航空公司會提供餐券或住宿；留下延誤證明（航空公司開的延誤證明、登機證）；有買旅遊不便險，或用信用卡刷機票附贈的保險，可以申請延誤理賠；如果有轉機或預訂好的飯店、車子，記得通知對方
看法=延誤時先排隊、同時打客服，常常電話會比排隊更快改到位子
@轉機注意|轉機要注意什麼,第一次轉機,轉機怎麼轉,轉機時間要多久,轉機行李要領嗎|生活
開頭=轉機要注意這些：
步驟=訂票時轉機時間最好留 2 小時以上，大機場、要換航廈的再多一點；問清楚行李是不是直掛到目的地，不是的話要先入境領行李再重新托運；確認轉機的國家需不需要過境簽證；下飛機後跟著「Transfer／轉機」的指標走，看螢幕找下一班的登機門；隨身帶著兩段的登機證和護照
提醒=轉機也要再過一次安檢，液體一樣有 100 毫升的限制
@搭機耳朵痛|在飛機上耳朵塞住,坐飛機耳朵痛,飛機降落耳朵痛,搭飛機耳朵塞住,飛機上耳朵好痛|健康
開頭=搭飛機耳朵塞住、痛，可以這樣做：
步驟=起飛和降落時多吞口水、喝水、嚼口香糖或打哈欠，讓耳朵的壓力平衡；可以捏住鼻子、閉著嘴，輕輕往鼻子鼓氣（不要太用力）；不要在降落時睡覺，醒著比較能一直吞嚥；小寶寶在起降時餵奶或給奶嘴
提醒=感冒、鼻塞嚴重時搭機比較容易耳朵痛，可以問醫生能不能先用藥；下飛機好幾天還是痛、聽不清楚，要看耳鼻喉科
@外幣用不完|外幣用不完怎麼辦,出國剩下的錢怎麼辦,外幣怎麼換回台幣,剩下的日幣怎麼辦|生活
開頭=出國剩下的外幣，可以這樣處理：
步驟=常常去同一個國家的話，留著下次用最划算；想換回台幣，可以到銀行或機場的銀行櫃台換，但只收紙鈔、不收硬幣，而且會有一點匯差；有外幣帳戶的話可以直接存進去；零錢可以在國外機場花掉，或投進機場的零錢捐款箱
看法=出國前不要一次換太多現金，旅程後段多刷卡，比較不會剩
@飯店提早入住|飯店可以提早入住嗎,可以提早入住嗎,飯店提早check in,太早到飯店怎麼辦,飯店寄放行李|生活
開頭=想提早入住飯店，可以這樣做：
步驟=一般的入住時間是下午 2 到 4 點，提早到的話可以先問櫃台有沒有空房，有的會讓你先進去；有些飯店提早入住要加價；房間還沒好的話，可以先把行李寄放在櫃台，輕鬆出去玩；很早就到的話，可以考慮前一晚就訂下來，一到就能進房休息
看法=訂房時先在備註寫預計抵達時間，或寫信問飯店，比較有機會安排
@坐過站|火車坐過站了,捷運坐過站,公車坐過站,坐過站怎麼辦,高鐵坐過站|生活
開頭=坐過站了，可以這樣處理：
步驟=在下一站下車，到對面月台搭回頭的車；出站前跟站務人員說明坐過站，照規定補票或請他們協助；捷運通常只要不出站，換到對面月台搭回去就好；高鐵、台鐵坐過站，要向站務人員說明、補差額
看法=搭長途車可以設鬧鐘或用地圖 App 的到站提醒，睡著比較不怕坐過站
@捷運坐錯方向|捷運坐錯方向,捷運坐反了,捷運搭錯方向,捷運坐錯邊|生活
開頭=捷運坐錯方向，不用擔心：
步驟=在下一站下車，不要出站，走到對面的月台搭反方向的車就好；看月台上的路線圖和「往〇〇方向」的指標，確認終點站的方向；沒有出站的話，車資是照進站和最後出站的地方算
看法=上車前先看一下車門上方或月台上的終點站名稱，比較不會搭錯
@高速公路收費|高速公路收費怎麼算,國道怎麼收費,高速公路要錢嗎,國道通行費怎麼算|生活
開頭=台灣國道是用 ETC 照里程收費：
步驟=每輛車每天前 20 公里免費；小型車超過 20 公里的部分，每公里大約 1.2 元，一天超過 200 公里的部分打九折左右；有裝 eTag 的會自動扣款，沒裝的會寄帳單或可以上 ETC 網站、便利商店繳；大型車、聯結車的費率比較高，假日或連假有時會有特別的收費措施
提醒=eTag 餘額不足或沒裝的，記得在期限內補繳，逾期會被罰
@找不到車|停車場找不到車,忘記車停哪裡,找不到停的車,機車停哪裡忘了|生活
開頭=在停車場找不到車，可以這樣找：
步驟=先冷靜想想進來的入口、樓層、經過的電梯或柱子顏色；很多停車場有車牌辨識的「找車系統」，在繳費機或螢幕輸入車牌就能看到位置；找停車場的管理員幫忙，他們可以看監視器；用 Google 地圖的「已停車位置」或拍照記下柱子編號，下次就不會忘
看法=停好車順手拍一張柱子號碼的照片，是最簡單的方法
@公車到站時間|公車要怎麼查到站時間,公車幾點到,怎麼查公車,公車還有多久到|生活
開頭=想知道公車還要多久到，可以這樣查：
步驟=用「Bus+」、「台北等公車」、各縣市的公車動態 App，或 Google 地圖，搜尋站牌或路線，就能看到預估到站時間；很多站牌有電子看板顯示；用 LINE 也可以加各縣市公車動態的官方帳號查詢
看法=把常坐的站牌加入「我的最愛」，出門前看一眼就好
@寵物搭火車|搭火車可以帶寵物嗎,狗可以坐火車嗎,寵物可以搭捷運嗎,帶貓坐高鐵,寵物搭大眾運輸|生活
開頭=帶寵物搭火車、捷運，一般要這樣：
步驟=寵物要放在籠子、提籃或寵物袋裡，完全裝好、不能把頭伸出來，也不能佔座位；容器的大小有限制，太大的不能帶上車；導盲犬等工作犬不受這個限制；各家（台鐵、高鐵、捷運、客運）的細節不太一樣，出門前先上官網確認
看法=搭車前讓寵物先上廁所，帶一條小毛巾、尿布墊，以防萬一
@爬山迷路|爬山迷路了,登山迷路怎麼辦,在山上迷路,郊山迷路,爬山走錯路|生活
開頭=爬山迷路，可以這樣做：
步驟=先停下來，不要繼續亂走，越走越遠更難找；想想最後一個確定的路標或岔路，有把握就原路退回去；不要往溪谷、山溝往下走，常常走到斷崖或瀑布；手機有訊號就打 119 或 112（沒有 SIM 卡、別家電信的訊號也能打 112），說明大概的位置，開定位；保持體力和體溫，穿上外套，在明顯的地方等待救援
提醒=出發前跟家人說好路線和預計回來的時間，帶頭燈、行動電源、雨衣和足夠的水
@海邊注意|去海邊要注意什麼,去海邊玩要注意什麼,海邊玩水要注意什麼,海邊安全|生活
開頭=去海邊玩，要注意這些：
步驟=只在有救生員、開放的海水浴場下水，不要在禁止戲水的地方游泳；小孩一定要有大人在旁邊看著，穿救生衣；注意離岸流（看起來比較平靜、顏色比較深的一條水道），被拉走時不要逆著游，往和海岸平行的方向游出去；注意漲潮時間，不要在礁石、消波塊上玩；做好防曬、多喝水
提醒=颱風前後、浪大、打雷的時候不要下海，也不要到海邊看浪
@另一半忘記生日|男朋友忘記我生日,女朋友忘記我生日,老公忘記我生日,另一半忘記我的生日,男友忘記紀念日,另一半忘記紀念日|生活
開頭=另一半忘記你的生日，會失望很正常，可以這樣處理：
步驟=先讓自己的情緒穩定一點，再找時間好好說，不要在氣頭上冷戰；說出你的感受，而不是指責：「那天沒被記得，我真的有點難過」，比「你根本不在乎我」容易被聽進去；想想對方最近是不是特別忙、壓力大，也聽聽他怎麼說；下次可以直接說出你的期待，或一起把重要的日子設在手機行事曆裡
看法=一次忘記不代表不愛你；但如果常常被忽略，就值得好好談談彼此的需要
@另一半查手機|女朋友一直查我手機,男朋友一直查我手機,另一半一直查手機,老婆一直看我手機,另一半一直檢查我的手機|生活
開頭=另一半一直查你的手機，可以這樣溝通：
步驟=先想想他為什麼不安：是之前發生過什麼事，還是他本來就比較沒有安全感；找兩個人都平靜的時候談，說出你的感受：「你一直查手機，我覺得不被信任」；一起討論讓他安心的方式，例如多分享自己的行程、主動介紹朋友，但也講清楚你需要的隱私界線；如果一直被控制、被要求交出密碼、限制你跟誰聯絡，這已經不只是不安，要認真想想這段關係
看法=信任要兩個人一起建立，靠查手機是查不完的
@另一半跟前任聯絡|另一半跟前任還有聯絡,男朋友跟前女友還有聯絡,女朋友跟前男友還在聊天,老公跟前任聯絡,另一半還在跟前任聊天|生活
開頭=另一半還跟前任有聯絡，覺得不舒服很正常，可以這樣處理：
步驟=先了解是什麼樣的聯絡：工作上、共同朋友、還是常常私下聊天；找時間好好談，說出你的感受和擔心，而不是直接指控；一起討論彼此能接受的界線，例如可以打招呼，但不私下見面、不聊感情的事；看對方的態度：願意透明、願意顧慮你的感受，比聯絡本身更重要
看法=說出自己的不安不是小氣，好的關係是兩個人都覺得安心
@過年不想回婆家|過年不想回婆家,過年不想回夫家,過年回婆家好累,不想回娘家過年,過年要回誰家|生活
開頭=過年不想回婆家，可以這樣跟另一半商量：
步驟=先想清楚不想回去的原因：是太累、跟長輩處不來，還是被問一堆問題；跟另一半私下好好說，不要只抱怨，一起想折衷的辦法：例如住飯店、縮短停留的天數、輪流在兩邊過年；請另一半在他的家人面前幫你擋一擋，像被催生、被比較的時候；回去的時候給自己一點喘息時間，出去走走也可以
看法=過年是兩個家庭的事，夫妻先站在同一陣線，比誰讓步更重要
@重男輕女|爸媽重男輕女,家裡重男輕女,爸媽比較疼弟弟,爸媽偏心哥哥,家裡偏心|生活
開頭=感覺家裡重男輕女、偏心，那種委屈是真的，可以這樣照顧自己：
步驟=先承認自己的感受：覺得不公平、難過是正常的，不是你小氣；可以找機會跟爸媽說出具體的事情和感受，有些長輩真的沒意識到；說了也改變不了的話，把力氣放回自己身上：經濟和生活慢慢獨立，替自己做決定；找信任的朋友、伴侶或諮商師聊聊，不用一個人消化
看法=你的價值不是由爸媽怎麼對待你決定的
@家人一直要錢|哥哥一直跟家裡要錢,家人一直跟我要錢,弟弟一直伸手要錢,家裡有人一直借錢,爸媽一直跟我拿錢|生活
開頭=家人一直要錢，可以這樣設界線：
步驟=先決定自己能幫多少：算好自己的生活費、存款，給多少是你可以承受、給了不會後悔的；說清楚你的原則：「這次我只能給這些」「我只幫忙付房租，不給現金」；如果是賭博、投資失利、欠債越來越多，直接給錢常常只會讓問題變大，可以幫忙找債務協商、社工的資源；跟其他家人商量，不要一個人扛
看法=拒絕家人很難，但先照顧好自己，才能長久地照顧家人
@朋友結婚沒邀請我|朋友結婚沒邀請我,好朋友結婚沒找我,朋友婚禮沒請我,朋友結婚沒發喜帖給我|生活
開頭=朋友結婚沒邀請你，難免會失落，可以這樣想：
步驟=婚禮的名單常常有很多限制：場地、預算、家人的意見，不一定是他不在乎你；如果你們很要好、你很在意，可以私下輕鬆地問問，或直接送上祝福；看看平常的互動：如果其他時候都很好，就不用因為一次婚禮否定整段友誼；如果覺得關係已經慢慢變遠，也可以接受朋友會隨著人生階段改變
看法=送一句真心的祝福，常常比糾結有沒有被邀請更讓自己舒服
@朋友愛炫耀|朋友一直炫耀,朋友很愛炫耀,同事一直炫耀,朋友一直曬,朋友很愛比較|生活
開頭=朋友一直炫耀，覺得不舒服很正常，可以這樣面對：
步驟=先想想他炫耀的原因：有些人是太開心想分享，有些人其實很需要被肯定；聽到的時候簡單回應就好：「真不錯」，不用跟著比較；社群上看到太多，可以先把他的動態隱藏一陣子；如果他一直貶低別人來抬高自己，可以慢慢拉開距離
看法=別人的成就不會減少你的價值，比較只會讓自己更累
@被朋友封鎖|被好朋友封鎖了,被朋友封鎖,朋友把我封鎖了,被封鎖了,LINE被朋友封鎖|生活
開頭=被好朋友封鎖，很難受，可以這樣處理：
步驟=先讓自己難過一下，被封鎖會覺得被否定，這種感受很正常；想想最近有沒有發生什麼誤會或爭執；如果你們有共同的朋友，或還有其他方式聯絡，可以真誠地傳一段話：說你的在意、道歉（如果需要），但不要一直騷擾；對方需要時間或選擇離開，也要尊重
看法=一段友誼結束不代表你不好；把時間留給在乎你的人
@借東西不還|同學一直借東西不還,朋友借東西不還,借出去的東西要不回來,同事借東西都不還|生活
開頭=別人一直借東西不還，可以這樣處理：
步驟=直接、輕鬆地提醒：「上次借你的筆記本，我明天要用，可以還我嗎？」，說清楚時間；借之前先說好什麼時候還；常常不還的人，下次可以婉拒：「這個我自己也要用，不方便借」；重要或貴的東西，盡量不要借出去
看法=開口要回自己的東西是很正常的，不用覺得不好意思
@室友偷吃東西|室友偷吃我的東西,室友吃我的食物,室友亂拿我的東西,室友偷用我的東西,冰箱的東西被室友吃掉|生活
開頭=室友偷吃、亂拿你的東西，可以這樣處理：
步驟=先確認是不是誤會（例如以為是大家共用的），再私下好好說：「冰箱裡那盒是我的，下次想吃先問我一下」；一起訂規則：冰箱分區、東西貼名字，共用的東西放在固定的地方；重要或貴的東西放自己的房間；講了還是一直發生，可以找房東或其他室友一起討論
看法=一開始就說清楚，比忍到受不了再爆發好得多
@容易被影響|很容易被別人的話影響,很在意別人的看法,別人說一句話就難過很久,太在意別人說什麼|生活
開頭=很容易被別人的話影響，可以這樣練習：
步驟=聽到一句讓你難受的話，先停一下問自己：他說的是事實，還是他的看法？；想想說這句話的人，他的意見對你真的重要嗎；把自己做得好的事、別人的肯定記下來，難過時看一看；跟信任的朋友聊聊，聽聽另一個角度
看法=在意別人的感受是一種溫柔，只是不要讓每一句話都決定你是誰
@想一個人靜一靜|想要一個人靜一靜,想一個人靜一靜,想要自己一個人待著,想要安靜一下,我需要一個人靜一靜|生活
開頭=想一個人靜一靜很正常，這是在照顧自己：
步驟=找一個舒服的地方，關掉通知一陣子；可以散散步、聽音樂、洗個熱水澡，或什麼都不做；想哭就哭，想寫下來就寫下來；跟身邊的人說一聲「我想自己待一下，晚點再聊」，他們比較不會擔心
看法=我在這裡，你想說的時候隨時都可以回來找我
@被多收錢|買東西被多收錢,結帳被多收錢,店家多收錢,被多收費,收銀員算錯錢|生活
開頭=買東西被多收錢，可以這樣處理：
步驟=結帳後當場對一下發票或收據，發現不對馬上跟店員說，最好處理；已經離開的話，帶著發票或收據回店裡，或打給店家的客服說明，請他們退差額；網購、外送被多扣款，在訂單頁面找「問題回報」或客服，附上截圖；店家不處理，可以打 1950 消費者服務專線申訴
看法=發票和刷卡紀錄先留著，有問題時就是證據
@發票不拿|發票可以不要拿嗎,發票一定要拿嗎,不想拿發票,發票可以不用嗎|生活
開頭=發票可以不拿紙本，但店家還是要開：
步驟=結帳時出示手機條碼載具，發票就存在雲端，不用拿紙本，中獎還會自動通知、自動匯款；不想拿也不想存載具，可以跟店員說「不用發票」，店家一樣要開立，通常會幫你捐給慈善團體或丟進捐發票箱；需要報帳的話，記得請店家打上統一編號
看法=用載具最方便，不會弄丟，也不怕忘記對獎
@信用卡分期利息|信用卡分期要利息嗎,信用卡分期有沒有利息,分期零利率,帳單分期利息,信用卡分期划算嗎|生活
開頭=信用卡分期有沒有利息，要看是哪一種：
步驟=店家的「分期零利率」：通常不用利息，但有些要付手續費，看清楚條件；刷完之後才申請的「單筆分期」「帳單分期」：大多要付利息或手續費，要看「總費用年百分率」，常常比想像的高；只繳最低應繳金額不是分期，剩下的會被算循環利息，最貴
看法=分期是把錢晚一點付，不是變便宜；買之前先想每個月付得起再分
@保險解約|保險要怎麼解約,保險可以解約嗎,保單解約,想解約保險,保險解約會虧嗎|生活
開頭=想解約保險，可以先這樣想、這樣做：
步驟=先確認是不是在「契約撤銷期」：收到保單的隔天起 10 天內撤銷，可以全額退費；超過了，解約只能拿回「解約金」，前幾年常常比繳的少很多，先問清楚會拿回多少；也可以考慮不解約的方式：減額繳清、展期、降低保額，保障留著、保費變少；決定解約的話，聯絡保險公司或業務員，填解約申請書，準備身分證和保單
提醒=解約前先想好新的保障，不要在身體有狀況時把保單解掉，之後可能很難再買
@小孩紅包保管|小孩的紅包要誰保管,小孩的紅包錢誰保管,孩子的壓歲錢,壓歲錢要交給爸媽嗎,小孩紅包怎麼處理|生活
開頭=小孩的紅包、壓歲錢，可以這樣處理：
步驟=小小孩的紅包，由爸媽幫忙存進孩子名下的帳戶，告訴他這是他的錢；大一點的孩子，可以讓他自己決定一部分怎麼用，其他存起來，順便學理財；說清楚規則：多少可以自己花、多少要存、存起來要做什麼用
看法=把紅包變成學習管錢的機會，比單純「爸媽幫你收起來」更好
@衝動購物|衝動購物怎麼改,一直亂買東西,忍不住一直買,購物成癮,一直衝動消費|生活
開頭=想改掉衝動購物，可以這樣做：
步驟=想買的東西先放進購物車，等 24 到 48 小時再決定，很多時候就不想要了；每個月先訂好「想要的東西」的預算，花完就停；刪掉常逛的購物 App、取消電子報和推播通知；買之前問自己：真的會常用嗎？家裡有沒有類似的？；壓力大、無聊的時候特別容易亂買，先找別的方式紓壓
看法=記帳一個月，看清楚錢花到哪裡，是最有感的提醒
@股票被套牢|股票被套牢了,股票被套住,股票賠錢要不要賣,基金賠錢要不要賣,股票一直跌要賣嗎,投資虧損怎麼辦|生活
開頭=股票、基金被套牢，可以先這樣想：
步驟=先冷靜，不要因為一時的恐慌全部賣掉，也不要為了攤平一直加碼；重新看你買的理由還在不在：公司、基金的基本面變差了，還是只是整個市場在跌；想想這筆錢多久以後才會用到，短期要用的錢本來就不該放在波動大的地方；以後可以先設好停損點、分散投資，不要把錢全押在同一個標的
提醒=這是一般的觀念，不是買賣建議；金額大或不確定時，可以問專業的理財顧問
@水費變貴|水費突然變很貴,水費變貴,水費暴增,這期水費好貴,水費怎麼那麼高|生活
開頭=水費突然變很貴，可以這樣檢查：
步驟=先把家裡所有水龍頭關好，看水表上的指針或小輪子有沒有在轉，有在轉就是有地方在漏水；常見的是馬桶水箱一直流水、熱水器或水管漏水、水塔浮球壞了；也看看最近是不是用水變多（家人變多、洗衣服變多）；都不是的話，可能是抄表錯誤，打自來水公司的客服請他們查
看法=漏水的話，先關總水閥再請水電師傅修，越早修越省
@手機資費太貴|手機月租費太貴,手機費太貴,電話費太貴,手機方案要換嗎,降低手機月租|生活
開頭=手機月租太貴，可以這樣省：
步驟=先看帳單和手機的用量：每個月實際用了多少網路、通話，很多人辦的方案用不完；換成比較小的方案，或改辦預付卡、低資費的網路方案；可以考慮攜碼到其他電信，常常有比較便宜的優惠；注意合約期間：還在綁約中提早換約可能要付違約金，快到期時再談最划算
看法=家裡有 Wi-Fi 的話，行動網路不一定需要吃到飽
@整理訂閱|訂閱太多了要怎麼整理,怎麼取消訂閱,訂閱的服務太多,每個月好多訂閱費,怎麼查我訂閱了什麼|生活
開頭=訂閱太多，可以這樣整理：
步驟=先列出所有訂閱：iPhone 到「設定 → 你的名字 → 訂閱項目」，Android 到 Google Play 的「付款和訂閱」，再翻一下信用卡帳單，找出每個月固定扣款的；把一個月沒用幾次的先取消，同類型的（影音、音樂、雲端空間）只留一個；年繳通常比月繳便宜，常用的可以改年繳
看法=取消要在下次扣款前完成，取消後通常還能用到這期結束
@寫借據|借錢給朋友要寫借據嗎,借錢要寫借據嗎,借據怎麼寫,借錢給別人要簽什麼,借錢要不要簽借據|生活
開頭=借錢給別人，最好寫借據：
步驟=借據寫清楚：借款人和出借人的姓名、身分證字號、借多少錢、哪一天借的、什麼時候還、怎麼還（一次還或分期）、有沒有利息，最後雙方簽名、寫日期；用轉帳匯款，留下金流紀錄，比給現金更有保障；聊天訊息裡也可以請對方確認「我跟你借了多少、什麼時候還」，截圖留存
看法=借給朋友的錢，最好是就算拿不回來你也還能接受的金額
@指甲白點|指甲有白點,指甲上有白色的點,指甲白斑,指甲有白色斑點|健康
開頭=指甲上有小白點，大多不用擔心：
步驟=最常見的原因是指甲根部（甲床）曾經被撞到、夾到或修指甲時太用力，白點會隨著指甲慢慢長出去，剪掉就沒了；平常指甲不要用力摳、不要把指甲當工具用；均衡飲食、保持手部保濕
提醒=整片指甲變白、變厚、變黃或變形，可能是灰指甲或其他問題，要給皮膚科看
@嵌甲|腳趾甲往肉裡長,凍甲,嵌甲,指甲插進肉裡,腳趾甲嵌進肉裡,大拇指甲往肉裡長|健康
開頭=腳趾甲往肉裡長（嵌甲、凍甲），可以這樣照顧：
步驟=剪趾甲要剪平，兩邊不要剪成圓弧、不要剪太短；穿鞋頭寬一點、不擠腳的鞋子；溫水泡腳 10 分鐘後，可以用乾淨的小棉花墊在趾甲邊緣下面，讓它慢慢往前長；保持乾淨、乾燥
提醒=已經紅腫、流膿、很痛，或有慢性病、血液循環不好的人，不要自己挖，去看皮膚科或骨科（足部）處理
@牙齒變黃|牙齒變黃,牙齒好黃,牙齒黃黃的,牙齒怎麼變白,牙齒美白|健康
開頭=牙齒變黃，可以這樣改善：
步驟=常見原因是咖啡、茶、可樂、紅酒、抽菸染色，或年紀增加牙齒本來的顏色變深；每天早晚好好刷牙、用牙線，喝完深色飲料用清水漱口；定期（大約半年）去牙科洗牙，可以去掉表面的染色和牙結石；想要更白，可以問牙醫做專業美白
提醒=不要自己用小蘇打、檸檬用力刷，會傷害琺瑯質，反而更敏感
@戴牙套注意|戴牙套要注意什麼,牙套怎麼清,矯正牙齒要注意什麼,戴牙套不能吃什麼,牙齒矯正注意事項|健康
開頭=戴牙套（牙齒矯正）要注意這些：
步驟=每次吃完東西都要刷牙，用矯正專用牙刷、牙間刷把牙套周圍清乾淨，食物卡住容易蛀牙；少吃太硬、太黏的東西（堅果、牛軋糖、口香糖），硬的食物切小塊再吃；剛裝上或調整後會痠痛幾天，可以吃軟一點的食物；隱形牙套除了喝水以外都要拿下來，每天戴到規定的時間
提醒=鋼絲刺到嘴巴可以先貼矯正用的蠟，再回診請醫生處理
@眼睛血絲|眼睛有血絲,眼睛紅紅的有血絲,眼白有血絲,眼睛充血|健康
開頭=眼睛有血絲，常見的原因和改善：
步驟=常見原因是睡不夠、用眼太久、眼睛乾、戴隱形眼鏡太久或揉眼睛；先讓眼睛休息，看螢幕每 20 分鐘看遠方 20 秒；睡飽，少戴隱形眼鏡，可以用人工淚液；不要一直揉
提醒=⚠️ 眼睛痛、怕光、視力變模糊、分泌物很多，或眼白突然一大片紅，要去看眼科
@耳朵癢|耳朵癢,耳朵裡面很癢,耳朵一直癢,耳朵癢怎麼辦|健康
開頭=耳朵癢，可以這樣處理：
步驟=常見原因是耳道太乾、挖耳朵挖太多、游泳洗澡後有水、過敏或耳垢；忍住不要一直挖，尤其不要用髮夾、指甲挖，容易刮傷發炎；洗澡後用毛巾把耳朵外面擦乾就好，棉花棒不要伸太深
提醒=又癢又痛、有分泌物、有臭味或聽力變差，可能是外耳炎或黴菌感染，要看耳鼻喉科
@久站腳痠|久站腳很痠,站很久腳好痠,站一整天腳好痛,久站腿痠,上班一直站腳好痠|健康
開頭=久站腳很痠，可以這樣舒緩：
步驟=穿有支撐、有緩衝的鞋子，必要時加一雙好的鞋墊；站的時候常常換腳、踮踮腳尖、動一動腳踝；下班後把腳抬高放在枕頭上 10 到 15 分鐘，幫助血液回流；用溫水泡腳、輕輕按摩小腿；工作需要久站的人可以穿彈性襪
提醒=小腿腫得很厲害、一邊特別腫痛、發紅發熱，要去看醫生
@上廁所會痛|上廁所會痛,小便會痛,尿尿會痛,解尿疼痛,尿尿刺痛|健康
開頭=尿尿會痛，常見的是尿道或膀胱發炎，可以先這樣做：
步驟=多喝水，讓尿量增加、把細菌沖出去；不要憋尿，想上就去；上完廁所從前往後擦；穿透氣的棉質內褲；最好盡快去看泌尿科（女生也可以看婦產科），需要的話醫生會開抗生素，要照醫生說的吃完
提醒=⚠️ 發高燒、發抖、腰側很痛、尿裡有血，要馬上就醫
@換尿布頻率|寶寶多久要換一次尿布,尿布多久換一次,新生兒尿布多久換,寶寶尿布要多久換|生活
開頭=寶寶的尿布，大概這樣換：
步驟=新生兒一天大約要換 8 到 10 片以上，差不多每 2 到 3 小時、餵奶前後看一下；有大便就馬上換，免得紅屁股；大一點的寶寶尿量變多、次數變少，摸起來重重的、尿布上的尿濕顯示線變色就換；每次換的時候用溫水或濕紙巾把屁股擦乾淨、晾乾再穿
提醒=屁股紅紅的可以擦護臀膏；尿布突然變得很少濕、寶寶精神不好，要注意是不是喝太少，問小兒科醫生
@寶寶長牙|寶寶長牙會怎樣,寶寶長牙,寶寶什麼時候長牙,長牙會不舒服嗎,寶寶長牙一直哭|生活
開頭=寶寶長牙，常見的樣子和照顧方法：
步驟=大多在 6 個月左右開始長第一顆牙（早晚幾個月都正常）；常見的表現：口水變多、愛咬東西、牙齦紅腫、比較煩躁、睡不安穩；可以給冰過（冷藏，不要冷凍）的固齒器咬，或用乾淨的手指輕輕按摩牙齦；長出牙齒後，用紗布或軟毛牙刷幫他清潔
提醒=長牙通常只會有一點點不舒服，體溫很高、拉肚子、精神很差，不要都以為是長牙，要看醫生
@小孩不肯刷牙|小孩不肯刷牙,小孩不刷牙,孩子討厭刷牙,怎麼讓小孩刷牙|生活
開頭=小孩不肯刷牙，可以這樣試試：
步驟=大人跟他一起刷，讓他模仿；讓他自己挑喜歡的牙刷、牙膏顏色；唱一首歌或用沙漏計時兩分鐘，把刷牙變成遊戲；先讓他自己刷，最後大人再幫他刷一次（大約到 8 歲都要幫忙）；刷完就稱讚，不要用威脅的
看法=每天固定在同一個時間刷，變成習慣就比較不會抗拒
@小孩說髒話|小孩說髒話,孩子講髒話,小孩學會罵人,小朋友一直說髒話|生活
開頭=小孩說髒話，可以這樣處理：
步驟=先不要大驚小怪或大笑，太大的反應反而會讓他覺得好玩；冷靜地問他知不知道這是什麼意思、從哪裡聽來的；說清楚家裡的規則：這種話會讓別人受傷，我們不說；教他生氣時可以怎麼說：「我很生氣」「我不喜歡這樣」；大人自己也要注意說話
看法=孩子常常只是模仿，耐心說清楚，比處罰有用
@小孩打架|小孩跟同學打架,孩子在學校打架,小孩跟人打架,兒子跟同學打架|生活
開頭=小孩跟同學打架，可以這樣處理：
步驟=先確認有沒有受傷，讓他冷靜下來；聽他說發生了什麼事，先不急著判對錯；跟老師聯絡，了解另一邊的說法；跟孩子討論下次可以怎麼做：先說「停」、走開、找老師；有動手打人就要道歉、負責，有被欺負就要讓大人知道
提醒=如果是同一群人一直欺負他，可能是霸凌，要跟學校一起處理
@孩子交壞朋友|孩子交了壞朋友,小孩交到壞朋友,孩子跟壞朋友在一起,擔心孩子交友|生活
開頭=擔心孩子交了壞朋友，可以這樣做：
步驟=不要一開始就禁止或批評他的朋友，越禁止越想偷偷來往；了解這個朋友吸引他的地方，可能是被接納、好玩；邀請朋友來家裡，或多問問他們在做什麼，認識他的朋友圈；說清楚底線：安全、法律、上學，這些不能妥協；多陪伴、多聊天，家裡讓他覺得被理解，他就比較不會往外找
提醒=發現抽菸、喝酒、偷竊、吸毒或被要求做危險的事，要馬上跟學校或專業單位一起處理
@小孩吸手指|小孩一直吸手指,孩子吸手指,寶寶吸大拇指,小孩吃手指|生活
開頭=小孩吸手指，可以這樣看：
步驟=四歲以前吸手指很常見，是孩子安撫自己的方式，大多會自己慢慢停；不要一直罵或硬拉開，越在意越停不下來；觀察他什麼時候最會吸（想睡、無聊、緊張），給他別的安撫方式：抱抱、小玩偶、讓手有事做；大一點的孩子可以一起約定、做貼紙獎勵
提醒=五六歲以後還一直吸，可能影響牙齒咬合，可以問牙醫
@戒尿布|小孩尿布要戴到幾歲,小孩什麼時候戒尿布,怎麼戒尿布,孩子幾歲不用尿布,訓練小孩上廁所|生活
開頭=戒尿布大多在 2 到 3 歲之間：
步驟=看孩子準備好的信號：尿布可以維持兩小時以上是乾的、會說想尿尿或表現出來、對馬桶有興趣、會自己脫褲子；準備小馬桶或馬桶座，固定時間帶他去坐（起床、飯後、睡前）；成功就稱讚，尿濕了不要責罵；白天先戒，晚上通常比較晚（4、5 歲還會尿床都算常見）
看法=每個孩子的時間不一樣，跟別人比只會讓大人和孩子都有壓力
@小孩自己洗澡|小孩幾歲可以自己洗澡,孩子自己洗澡,小孩什麼時候自己洗澡,教小孩洗澡|生活
開頭=小孩自己洗澡，可以這樣慢慢練習：
步驟=大約五六歲可以開始練習，一開始大人在旁邊陪著；教他順序：先沖溼、洗頭、洗身體、沖乾淨，耳後、腋下、屁股也要洗到；熱水器的水溫先調好，教他先開冷水再開熱水，避免燙傷；浴室放防滑墊；七八歲以後大多可以自己洗，大人偶爾檢查
提醒=幼兒絕對不要單獨留在浴缸或有積水的地方，幾公分的水就可能溺水
@長輩年紀大注意|爸媽年紀大了要注意什麼,長輩年紀大要注意什麼,老人家要注意什麼,照顧年邁的爸媽|生活
開頭=爸媽年紀大了，可以多注意這些：
步驟=定期健康檢查，65 歲以上有免費的成人健檢；預防跌倒：家裡光線充足、地板防滑、浴室加扶手；整理他們吃的藥，一起看醫生時把藥袋都帶去；吃夠蛋白質、多活動，維持肌肉；記得打流感、肺炎鏈球菌等疫苗；多陪他們聊天、出門走走，注意記憶和情緒的變化
看法=常常打電話、常常回家，是最簡單也最重要的照顧
@長輩戴助聽器|長輩不肯戴助聽器,爸爸聽力變差,老人家耳背,長輩聽不清楚,助聽器要怎麼選|生活
開頭=長輩聽力變差、不肯戴助聽器，可以這樣做：
步驟=先陪他去耳鼻喉科做聽力檢查，確認原因，有些是耳垢塞住；了解他不想戴的原因：覺得丟臉、戴起來不舒服、聲音很吵；選擇有試戴、可以調整的店家，戴一陣子再回去微調；從安靜的家裡開始戴，慢慢習慣；說說戴了之後的好處：聽得清楚、跟家人聊天、比較安全；有些縣市或身障證明有助聽器補助
看法=跟長輩講話時面對他、說慢一點，比大聲更有用
@長輩說身體痛|長輩一直說身體痛,老人家一直說這裡痛那裡痛,爸媽一直喊痛,長輩常常說不舒服|生活
開頭=長輩一直說身體痛，可以這樣陪他：
步驟=先認真聽，問清楚哪裡痛、什麼時候痛、怎麼樣會比較好；帶他去看醫生，家醫科或老年醫學科可以一次看很多問題，把他吃的藥都帶去；幫他記下痛的時間和情況，看醫生時比較好說明；有時候說痛也是想被關心、覺得孤單，多陪他說說話、出門走走
提醒=突然很劇烈的痛、胸痛、一邊手腳無力、跌倒後痛，要馬上就醫
@長輩開車|爺爺開車很危險要怎麼勸,長輩開車很危險,爸爸年紀大了還在開車,老人家開車,怎麼勸長輩不要開車|生活
開頭=擔心長輩開車不安全，可以這樣談：
步驟=用關心的語氣說具體的事：「上次差點撞到」比「你老了不要開」好接受；可以請醫生評估視力、反應和用藥會不會影響開車；先從減少開車開始：不開夜車、不上高速公路、只開熟悉的路；幫他安排替代的交通：家人接送、計程車、敬老卡搭公車；台灣 75 歲以上換駕照要通過體檢和認知測驗
看法=開車常常代表長輩的自由和自尊，給他其他出門的方法，比較容易放下方向盤
@教爸媽用手機|爸媽不會用手機,教長輩用手機,長輩手機不會用,教爸媽用LINE,阿嬤不會用智慧型手機|生活
開頭=教爸媽用手機，可以這樣做：
步驟=一次只教一件事，例如先學打 LINE 視訊；把步驟寫在小卡片上，大字、一步一個圖；把常用的 App 放在主畫面第一頁，不用的收起來；把字和圖示調大（很多手機有「簡易模式」或「長輩模式」）；讓他自己操作，不要直接搶過來幫他按
看法=耐心比技巧重要，多教幾次是正常的
@長輩獨居|長輩一個人住很擔心,爸媽一個人住,老人家獨居,阿嬤一個人住,獨居長輩怎麼照顧|生活
開頭=長輩一個人住，可以這樣讓大家安心：
步驟=約好每天固定的時間打電話或視訊；家裡做好防跌：夜燈、扶手、防滑墊，常用的東西放在好拿的地方；在明顯的地方貼緊急聯絡電話；可以考慮一鍵求救的裝置、跌倒偵測的手錶；請鄰居、里長幫忙留意，或讓長輩參加社區關懷據點的活動；需要照顧時可以打長照專線 1966
看法=讓長輩有朋友、有地方去，比一直擔心更能保護他
@長輩失眠|長輩失眠,老人家睡不著,爸媽晚上睡不著,阿公睡不好,長輩半夜一直醒來|生活
開頭=長輩睡不好，可以這樣改善：
步驟=白天多出門活動、曬太陽，晚上比較好睡；午睡不要超過 30 分鐘，下午以後不要喝茶和咖啡；晚餐後少喝水，減少半夜起來上廁所；每天固定時間睡覺、起床；房間保持安靜、暗一點、溫度舒適
提醒=不要自己買安眠藥吃，長輩比較容易頭暈跌倒；長期睡不好、心情低落，可以看醫生（家醫科、身心科）
@老大吃醋|二寶出生老大吃醋,老大吃弟弟的醋,有了二寶老大不開心,大寶吃醋,哥哥吃妹妹的醋|生活
開頭=二寶出生後老大吃醋，很常見，可以這樣做：
步驟=每天留一段只屬於老大的時間，就算只有十分鐘，讓他知道自己還是很重要；讓他參與照顧弟妹：拿尿布、唱歌給寶寶聽，稱讚他是好幫手；接住他的感受：「媽媽陪寶寶的時候你覺得被冷落，對不對」；老大變得愛撒嬌、要人餵、又尿床，是常見的退化，耐心陪他；不要拿兩個孩子比較
看法=老大需要的不是更多玩具，而是確定爸媽的愛沒有被分走
@小孩要買玩具|小孩一直要買玩具,孩子一直吵著買玩具,小孩在店裡哭著要玩具,小孩看到什麼都想買|生活
開頭=小孩一直吵著要買玩具，可以這樣處理：
步驟=出門前先約好：今天只是看看、或只能買一樣、多少錢以內；在店裡哭鬧時保持冷靜，說到做到，不要因為哭鬧就買，不然他會學到哭有用；可以拍照放進「願望清單」，等生日或節日再挑；大一點的孩子給零用錢，讓他自己存錢買
看法=接住他的失望：「好想要喔，我知道」，但規則不變
@小孩不想學才藝|小孩不想學才藝,孩子不想學鋼琴,小孩不想上才藝班,孩子學才藝半途而廢|生活
開頭=小孩不想學才藝了，可以這樣處理：
步驟=先問清楚原因：太難、太無聊、跟老師或同學處不來，還是太累、時間太多；剛開始的瓶頸期很常見，可以約定再試一段時間（例如到這期結束）再決定；讓他參與選擇自己有興趣的才藝；不要跟別人家的孩子比較
看法=學才藝是為了培養興趣，如果孩子很痛苦，換一個方向也沒關係
@參加婚禮注意|參加婚禮要注意什麼,喝喜酒要注意什麼,參加婚宴禮儀,參加婚禮的禮儀|生活
開頭=參加婚禮可以注意這些：
步驟=收到喜帖盡早回覆會不會出席、幾個人；穿整齊得體，避免全白（新娘的顏色）和全黑；紅包在收禮處交，信封寫上自己的名字，金額避開 4；準時到，入座後聽主持人的流程，新人敬酒時起身舉杯說句祝福；拍照不要擋到攝影師，不要喝太多
看法=不能出席的話，也可以託人帶紅包或送一份禮物和祝福
@探病|探病要帶什麼,去醫院探病要注意什麼,探病禮儀,去看病人要帶什麼|生活
開頭=去探病可以注意這些：
步驟=先問家屬方便的時間，看醫院的探病規定；自己感冒、不舒服就不要去；時間不要待太久，大約 15 到 30 分鐘，讓病人休息；可以帶好消化的水果、營養品、書或卡片，先問清楚病人能不能吃；避免帶花（有些病房不允許，也可能過敏）；說話溫和，多聽少問病情細節
看法=比起禮物，真心的關心和陪伴最重要
@拜年|過年要怎麼跟長輩拜年,拜年要說什麼,過年吉祥話,怎麼拜年,過年祝賀詞|生活
開頭=過年跟長輩拜年，可以這樣說：
步驟=見面先打招呼、說「新年快樂」，雙手作揖或微微鞠躬；常用的吉祥話：身體健康、萬事如意、平安喜樂、福壽安康（對長輩）、事業順利、心想事成；長輩給紅包時，雙手收下並說謝謝，不要當場拆開；也可以準備一點小禮物或幫忙家務
看法=對長輩說「祝您身體健康」最實在，最受歡迎
@請客點菜|請客吃飯要點多少菜,請客要點幾道菜,請客點菜怎麼點,宴客點幾道菜|生活
開頭=請客吃飯點菜，可以這樣抓：
步驟=常見的抓法是「人數加一」道菜，例如 4 個人點 5 道，再加一個湯；葷素搭配：有肉、有魚或海鮮、有青菜，再來一道豆腐或蛋類；問問客人有沒有不吃的東西（牛肉、海鮮、辣）；先點招牌菜，不夠再加點，比點太多浪費好
看法=不確定份量的話，問服務生一道菜大概夠幾個人吃
@餐廳訂位|餐廳訂位要注意什麼,怎麼訂餐廳,訂位要注意什麼,餐廳訂位禮儀|生活
開頭=餐廳訂位可以注意這些：
步驟=熱門的餐廳提早一兩週訂；說清楚日期、時間、人數，有小孩要不要兒童椅、有沒有人吃素或過敏；問清楚有沒有低消、服務費、用餐時間限制、要不要訂金；會晚到要先打電話說，不能去一定要取消
看法=臨時不去又不取消，餐廳會留空位等你，對店家影響很大
@被稱讚怎麼回|被稱讚的時候要怎麼回,別人稱讚我要怎麼回答,被誇獎怎麼回,被讚美要說什麼|生活
開頭=被稱讚的時候，可以這樣回：
步驟=最簡單也最好的是笑著說「謝謝！」，不用急著否認或貶低自己；可以多說一句感受：「謝謝，你這樣說我好開心」；如果是大家一起努力的成果，可以順便感謝別人：「謝謝，這是我們團隊一起做的」；也可以回問或回讚：「你也很厲害啊」，但不用硬擠
看法=大方接受稱讚，對方也會覺得說得很值得
@跟不熟的人打招呼|怎麼跟不熟的人打招呼,在電梯裡遇到主管要說什麼,遇到不熟的同事要說什麼,跟鄰居打招呼要說什麼,怎麼跟人寒暄|生活
開頭=遇到不熟的人，可以這樣打招呼：
步驟=微笑、點頭，說「早安」「午安」「您好」就很好；想多聊一兩句，可以聊天氣、最近的節日、手上的東西：「今天好熱喔」「週末有要去哪裡嗎」；在電梯遇到主管，打招呼後說一句近況或天氣就好，不用硬聊工作；對方回應冷淡也沒關係，禮貌到就好
看法=打招呼不用很會聊，有微笑和眼神就很加分
@被問薪水|別人問我薪水要不要說,被問薪水怎麼回答,親戚問薪水,同事問我薪水多少|生活
開頭=被別人問薪水，可以這樣回：
步驟=不想說是很正常的，薪水是私事；可以輕鬆地帶過：「還過得去啦」「夠生活」「跟業界差不多」；親戚追問的話，可以轉移話題：「最近在學理財，你有什麼建議嗎」；公司裡最好不要跟同事討論薪水，很多公司有規定，也容易造成誤會
看法=說不說是你的選擇，不用覺得不好意思
@傳訊息給長輩|傳訊息給長輩要注意什麼,傳LINE給長輩,跟長輩傳訊息,傳訊息給老闆要注意什麼|生活
開頭=傳訊息給長輩、主管，可以注意這些：
步驟=開頭先稱呼和問候：「王伯伯您好」；一則訊息把事情說清楚，不要分很多句連傳；用完整的句子，少用網路用語和太多貼圖；晚上太晚、太早不要傳，不急的事可以等白天；長輩眼睛不好、打字慢，重要的事打電話更好
看法=最後加一句「謝謝您」「辛苦了」，會讓訊息溫暖很多
@打電話的時間|晚上幾點打電話算不禮貌,打電話的禮貌時間,太晚打電話,幾點以後不要打電話|生活
開頭=打電話給別人，一般的禮貌時間：
步驟=平日大約早上 9 點以後、晚上 9 點以前比較適合；中午 12 點到 1 點半常在吃飯、午休，盡量避開；假日早上晚一點再打；不急的事可以先傳訊息問「方便講電話嗎」；工作上的電話盡量在上班時間打
看法=真的有急事、緊急狀況，就不用管時間
@借車注意|借別人的車要注意什麼,跟朋友借車,借車給別人要注意什麼,開別人的車要注意什麼|生活
開頭=借車開，可以注意這些：
步驟=先確認車主的保險有沒有涵蓋其他駕駛人，出事時理賠才不會有問題；開之前先繞車一圈、拍照，看有沒有原本的刮傷；問清楚油、電要加回多少，還車時加滿；遵守交通規則，罰單和違規是你要負責；還車時把車子整理乾淨，順便說聲謝謝或送個小禮
提醒=借車給別人的話，要確認對方有駕照，出事時車主也可能有責任
@大眾運輸講電話|在捷運上可以講電話嗎,搭公車可以講電話嗎,在高鐵上講電話,大眾運輸上講電話|生活
開頭=在捷運、公車、高鐵上可以講電話，但要注意禮貌：
步驟=小聲說、長話短說，重要的事等下車再講；高鐵、火車上比較安靜，最好到車廂連接處講；手機鈴聲調成震動；看影片、聽音樂要戴耳機，不要外放
看法=大家都在同一個空間，聲音比你以為的還大
@被插隊|排隊被插隊怎麼辦,排隊有人插隊,有人插隊要不要說,被插隊要怎麼講|生活
開頭=排隊被插隊，可以這樣處理：
步驟=先友善地提醒：「不好意思，我們在排隊，隊伍在後面喔」，很多人是沒注意到；對方不理的話，可以請店員、站務人員或工作人員處理；不要大聲爭吵或推擠，避免起衝突
看法=禮貌又堅定地說出來，通常就解決了
@鄰居送東西回禮|鄰居送東西要回禮嗎,鄰居送東西怎麼回禮,收到鄰居的禮物,鄰居送水果要回送嗎|生活
開頭=鄰居送東西，可以這樣回應：
步驟=先當面或傳訊息說謝謝，說說好不好吃、喜不喜歡；不用馬上回禮，下次有機會（出去玩帶伴手禮、過節）再回送一點心意就好；用鄰居送的碗盤裝來的，可以裝一點自己做的或買的東西還回去
看法=禮尚往來重要的是心意，不是價錢
@颱風天出門|颱風天要不要出門,颱風天可以出門嗎,颱風天出門要注意什麼,颱風天騎車|生活
開頭=颱風天盡量不要出門：
步驟=風雨大的時候，招牌、樹枝、鐵皮容易被吹落，騎機車特別危險；一定要出門的話，避開山區、河邊、海邊和地下道，走大路；穿顏色明亮的雨衣，不要撐傘騎車；隨時看氣象署的警報和停班停課的公告
提醒=颱風眼經過時風雨突然變小，不代表颱風走了，等警報解除再出門
@空污保護|空氣很差要怎麼保護自己,空氣品質差要怎麼辦,空汙嚴重要注意什麼|健康
開頭=空氣品質很差時，可以這樣保護自己：
步驟=先看環境部的空氣品質指標（AQI）或 App，紅色以上盡量待在室內；減少戶外運動，特別是小孩、長輩和有氣喘、心肺疾病的人；出門可以戴口罩，醫療口罩有幫助，N95 更好但戴久了會悶；在家關窗，有空氣清淨機可以開著；回家後洗臉、洗手、漱口
提醒=咳得很厲害、喘不過氣、胸悶，要去看醫生
@打雷用手機|打雷的時候可以用手機嗎,打雷可以講電話嗎,打雷可以用電腦嗎,打雷時能不能用手機|生活
開頭=打雷的時候用手機：
步驟=在室內用手機（沒有接充電線）基本上是安全的；比較要避免的是用插著電的東西：插著充電線的手機、有線電話、桌上型電腦，雷擊可能沿著電線傳進來；在戶外打雷時，最重要的是趕快進到建築物或車子裡，不要在空曠的地方、樹下講電話
看法=雷雨很大時，把貴重電器的插頭拔掉比較保險
@回應道歉|怎麼回覆別人的道歉,別人跟我道歉要怎麼回,收到道歉怎麼回答,朋友跟我道歉|生活
開頭=別人跟你道歉時，可以這樣回：
步驟=如果你願意原諒：「謝謝你跟我說，我知道了」「沒關係，下次我們再注意就好」；如果還在難過，可以誠實說：「謝謝你道歉，我還需要一點時間」；可以順便說出你希望以後怎麼做；不用勉強說「沒事」，接受道歉不代表不能有感受
看法=願意道歉的人也鼓起了勇氣，先謝謝他，關係比較容易修復
@地震時開車|地震的時候在開車怎麼辦,開車遇到地震,地震時在車上怎麼辦,騎車遇到地震|生活
開頭=開車時遇到地震，可以這樣做：
步驟=握緊方向盤，慢慢減速，打雙黃燈，不要急踩煞車；把車停在路邊安全的地方，避開橋樑、高架道路、隧道、電線桿、招牌和建築物旁邊；待在車裡，收聽廣播等地震停止；停下來後注意路面有沒有裂開、落石，再小心開；騎機車的話，停到空曠處，下車蹲低保護頭部
提醒=在高架橋或隧道裡的話，慢慢開出去再停
@運動後吃什麼|運動完要吃什麼,運動後吃什麼,健身完吃什麼,重訓完要吃什麼,跑完步吃什麼|健康
開頭=運動完可以這樣吃：
步驟=運動後 30 分鐘到 2 小時內，吃一點蛋白質加碳水化合物，幫助肌肉恢復；例子：一杯牛奶或豆漿配一根香蕉、茶葉蛋配地瓜、無糖優格配水果、一份雞胸肉便當；記得補水，流很多汗的話可以喝一點運動飲料或吃點鹹的；想減肥的人不用吃太多，正常吃下一餐就好
看法=運動完不吃東西不會比較瘦，反而容易餓到下一餐吃更多
@騎車屁股痛|騎腳踏車屁股好痛,騎腳踏車屁股痛,騎車坐墊好痛,自行車坐久屁股痛|健康
開頭=騎腳踏車屁股痛，可以這樣改善：
步驟=調整座墊高度：踩到最低點時膝蓋微彎，不要太高或太低；座墊的角度保持水平；穿有襯墊的車褲，或換一個比較寬、比較軟的座墊（座墊套）；騎一段時間就站起來踩一下，讓屁股休息；剛開始騎的人會痛，騎習慣後通常會改善
提醒=一直麻、一直痛或有傷口，先休息、去看醫生
@運動後頭暈|運動完頭暈,運動後頭暈,跑完步頭暈,運動完想吐,健身完頭暈|健康
開頭=運動完頭暈，可以先這樣處理：
步驟=馬上停下來，找地方坐下或躺下，把腳抬高；慢慢喝水，流很多汗的話補一點運動飲料；常見原因：空腹運動血糖太低、水喝太少、天氣太熱、突然停下來；下次運動前 1 到 2 小時吃點東西，運動中補水，結束時慢慢緩和下來再停
提醒=⚠️ 胸痛、喘不過氣、心跳很亂、昏倒，或休息後還是很暈，要馬上就醫
@游泳後頭髮乾|游泳完頭髮很乾,游泳頭髮變乾,游泳後頭髮毛躁,游泳池的水傷頭髮|健康
開頭=游泳後頭髮很乾，可以這樣保護：
步驟=下水前先用清水把頭髮沖濕，頭髮吸飽清水就比較不會吸進含氯的池水；戴泳帽；游完馬上用洗髮精把氯洗掉，再用潤髮乳或護髮；用吹風機時不要太熱，可以擦一點護髮油
看法=常游泳的人，每週做一次深層護髮會好很多
@跳繩減肥|跳繩可以減肥嗎,跳繩瘦身,跳繩一天要跳多久,跳繩會瘦嗎|健康
開頭=跳繩可以幫助減肥：
步驟=跳繩是消耗熱量很高的運動，跳 10 分鐘大約跟慢跑差不多；新手從每次 5 到 10 分鐘開始，跳一分鐘休息一下，慢慢增加到 20 到 30 分鐘；穿有緩衝的運動鞋，在木地板或軟墊上跳，膝蓋比較不會受傷；要瘦下來還是要搭配飲食控制
提醒=體重比較重、膝蓋或腳踝不好的人，先從快走、游泳開始比較安全
@瑜珈入門|瑜珈初學者要準備什麼,瑜珈新手,開始學瑜珈,瑜珈要準備什麼|健康
開頭=瑜珈新手可以這樣開始：
步驟=準備一張防滑的瑜珈墊、好活動的衣服，赤腳就好；先上入門課或跟著初學者影片，學會基本動作和呼吸；動作做到有一點拉扯感就好，不要勉強，每個人的柔軟度不一樣；飯後 1 到 2 小時再練，練完喝點水
看法=每週固定練兩三次，比偶爾練很久更有效
@跑步多久會瘦|跑步要跑多久才會瘦,跑步減肥要跑多久,跑多久可以減肥,慢跑會瘦嗎|健康
開頭=跑步想瘦，可以這樣安排：
步驟=每次持續跑 30 分鐘以上，每週 3 到 5 次，慢慢累積；新手從跑走交替開始，速度能邊跑邊說話就好；搭配飲食控制最重要，跑完一頓大吃很容易就吃回去了；加一點肌力訓練，基礎代謝會比較高
看法=體重下降通常要幾週到幾個月才看得出來，持續最重要
@流汗多正常嗎|運動流很多汗正常嗎,很容易流汗,流很多汗正常嗎,一動就流汗|健康
開頭=運動流很多汗，大多是正常的：
步驟=流汗是身體在散熱，天氣熱、運動強度高、體重比較重的人本來就流比較多；體能變好的人反而比較早開始流汗，散熱比較有效率；運動中和運動後記得補水，流很多汗的話補一點電解質
提醒=沒在運動、天氣也不熱卻常常大量流汗，或伴隨心悸、體重莫名下降、手抖，可以去看醫生
@被當掉|被當掉了怎麼辦,科目被當,大學被當,學分被當,這學期被當了,期末被當|生活
開頭=被當掉了，可以這樣處理：
步驟=先讓自己難過一下，被當不代表你不行，很多人都經歷過；查清楚被當的原因：缺考、作業沒交、分數差一點？差一點的可以禮貌地寫信問老師有沒有補救的機會（不要求情、不爭分數）；看是必修還是選修，必修要排重修，選修可以換一門；算一下會不會影響畢業學分，跟系辦或導師討論修課規劃；檢討這學期哪裡卡住，下次提早求助
看法=一科被當不會毀掉人生，重要的是下一學期怎麼調整
@番茄鐘|番茄鐘是什麼,番茄工作法,番茄鐘讀書法,什麼是番茄鐘,番茄鐘怎麼用|生活
開頭=番茄鐘（番茄工作法）是一種讓自己專心的時間管理方法：
步驟=設定 25 分鐘的計時器，這段時間只做一件事，不看手機；時間到休息 5 分鐘，起來走走、喝水；這樣算一個「番茄」，做完 4 個就休息長一點，15 到 30 分鐘；中途想到別的事，先記在紙上，等休息再處理
看法=名字來自發明人用的番茄造型廚房計時器；剛開始專注不了 25 分鐘，可以從 15 分鐘開始
@上課聽不懂|上課聽不懂怎麼辦,上課都聽不懂,老師上課講的聽不懂,上課跟不上|生活
開頭=上課聽不懂，可以這樣做：
步驟=上課前先把課本或講義翻一遍，知道今天要講什麼，聽起來會順很多；聽不懂的地方先在筆記上做記號，不要卡在那裡，繼續往下聽；下課當天就找老師、助教或同學問，越早問越好；回家用自己的話把重點寫一次，寫不出來的地方就是還不懂的；可以找網路上的教學影片換個方式聽
看法=聽不懂很正常，敢問的人進步最快
@考試作弊被抓|考試作弊被抓,作弊被抓到怎麼辦,考試被抓作弊,作弊被老師發現|生活
開頭=考試作弊被抓到，可以這樣面對：
步驟=先誠實面對，不要再編理由或否認，那會讓事情更嚴重；主動找老師談，承認錯誤、道歉，問清楚學校的處理方式；照規定接受處分，把它當成教訓；想想為什麼會想作弊：是準備不夠、壓力太大，還是怕被罵，找方法解決真正的問題；心裡很難受的話，可以找輔導室或信任的人聊聊
看法=犯錯不等於你是壞人，怎麼面對錯誤比較重要
@讀書聽音樂|讀書要不要聽音樂,讀書可以聽音樂嗎,邊讀書邊聽音樂,唸書聽音樂好嗎|生活
開頭=讀書要不要聽音樂，看讀的東西和你自己：
步驟=需要理解、背誦、寫作的時候，有歌詞的音樂容易讓人分心，最好安靜或只聽純音樂、白噪音；做比較機械的事（抄筆記、整理、算熟悉的題目）時，聽喜歡的音樂可以提振精神；音量開小一點；試試看兩種方式讀一樣久，比比看哪個效果好
看法=如果發現一直在切歌、跟著唱，就是該關掉的時候了
@背歷史|怎麼背歷史比較快,歷史要怎麼背,歷史背不起來,歷史年代怎麼背|生活
開頭=背歷史可以這樣做：
步驟=先抓大架構：朝代或時期的順序、每個時期的大事，畫成一條時間軸；記「因果」比記單一事件好背：為什麼發生、結果怎樣；把人物、事件串成故事，用自己的話講一遍給別人聽；年代可以用諧音或跟熟悉的事連結；考前用題目練習，看哪裡還不熟
看法=看一部相關的歷史劇或紀錄片，常常比死背更記得住
@找論文資料|論文要怎麼找資料,報告要怎麼找資料,怎麼找學術論文,寫論文找文獻|生活
開頭=寫報告、論文找資料，可以這樣找：
步驟=用 Google 學術（Google Scholar）搜尋關鍵字，看引用次數多的文章；台灣的論文可以到「臺灣博碩士論文知識加值系統」和華藝線上圖書館找；學校圖書館的資料庫很多可以免費用，連學校網路或用 VPN 登入；找到一篇好的論文，看它的參考文獻，可以順著找到更多資料；記下每份資料的出處，寫引用時比較方便
看法=先看摘要決定要不要讀全文，可以省很多時間
@引用資料|報告要怎麼引用資料,引用格式,參考文獻怎麼寫,APA格式怎麼寫|生活
開頭=報告引用別人的資料，可以這樣做：
步驟=直接照抄的句子要加引號，並寫出處；用自己的話改寫別人的觀點，也要註明出處；最後列「參考文獻」，寫作者、年份、標題、出處（期刊、網站、出版社）；照老師要求的格式寫，常見的是 APA 格式：作者（年份）。標題。出處；網路資料要寫網址和查閱日期
提醒=沒有註明出處就使用別人的文字，會被當成抄襲
@大學選課|大學選課要注意什麼,大學怎麼選課,選課要怎麼選,大一選課|生活
開頭=大學選課可以注意這些：
步驟=先看系上的必修和畢業學分規定，必修優先排；查課程大綱：上課內容、評分方式、作業份量；問學長姊或看選課評價，了解老師的教法；不要把課排得太滿，留一點時間給社團、打工和休息；注意加退選的時間，想換課要趕快
看法=選有興趣的通識課，常常會是大學最好的回憶
@出國交換|出國交換要準備什麼,大學出國交換,交換學生要準備什麼,申請交換學生|生活
開頭=想出國當交換學生，可以這樣準備：
步驟=先看學校國際處的交換名單、申請時間和條件（成績、語言檢定）；提早準備語言考試（托福、雅思或當地語言）；選學校時看課程能不能抵學分、生活費和住宿；錄取後辦護照、學生簽證、保險、住宿，算好生活費；出發前跟系上確認學分抵免的方式
看法=交換通常要提早一年準備，越早開始越從容
@壁癌|牆壁有壁癌,壁癌怎麼處理,牆壁起水泡掉粉,牆壁白白的粉,壁癌怎麼辦|生活
開頭=牆壁有壁癌，可以這樣處理：
步驟=壁癌是水氣從牆裡滲出來，把水泥裡的鹽分帶到表面，才會起泡、掉白粉；先找水從哪裡來：外牆裂縫、浴室或樓上漏水、水管滲水，不解決水源，刷幾次都會再長；小面積可以先把鬆掉的漆和白粉刮乾淨，等牆完全乾，再塗防水或抗壁癌的塗料，最後上漆；平常開除濕機，濕度維持 50% 到 60%
提醒=面積很大、一直反覆，或是樓上、外牆漏水，要請專業的抓漏師傅
@磁磚縫發黑|磁磚縫發黑,浴室磁磚縫發霉,磁磚縫黑黑的,磁磚縫隙怎麼清|生活
開頭=磁磚縫發黑，多半是發霉，可以這樣清：
步驟=戴手套、開窗通風；用稀釋的漂白水（約 1 比 10）或除霉劑，噴在磁磚縫上，蓋一張衛生紙讓它停留 10 到 20 分鐘，再用舊牙刷刷、清水沖；刷不掉的深色霉斑，可以把舊的填縫刮掉重新填矽利康或填縫劑；平常洗完澡用刮刀把水刮掉、開抽風機
提醒=漂白水不要跟其他清潔劑（尤其是酸性的）混在一起用，會產生有毒的氣體
@天花板水漬|天花板有水漬,天花板黃黃的一塊,天花板滲水,天花板有黃色的痕跡|生活
開頭=天花板出現水漬，可以這樣處理：
步驟=水漬代表上面有水滲下來：可能是樓上的浴室、廚房、水管漏水，或是頂樓、外牆防水壞了；先拍照記錄，看水漬會不會變大、變濕；住公寓的話，跟樓上住戶或管委會說，一起找原因；請抓漏師傅檢查，修好漏水的地方之後，再處理天花板的油漆
提醒=水漬靠近電燈、插座，先關掉那一區的電源，避免漏電
@窗戶玻璃破了|窗戶玻璃破了,玻璃破掉怎麼辦,窗戶破了,打破玻璃怎麼清|生活
開頭=窗戶玻璃破了，可以這樣處理：
步驟=先讓小孩和寵物離開，穿上鞋子、戴手套；大塊的碎片小心撿起來，小碎片用膠帶黏、或用濕紙巾擦，再用吸塵器吸一遍；碎玻璃用報紙包好、裝在紙箱裡，寫上「碎玻璃」再丟，免得清潔人員受傷；窗戶先用紙板或塑膠布封住擋風雨，再請玻璃行來量尺寸換新
看法=換玻璃時可以考慮強化玻璃或貼防爆膜，比較安全
@紗窗破洞|紗窗破洞,紗窗破了,紗窗有洞,紗網破掉,紗窗要怎麼補|生活
開頭=紗窗破洞，可以這樣處理：
步驟=小洞可以買紗窗修補貼（五金行、網路都有），剪成比洞大一點，兩面貼上壓緊；破很大或很舊了，可以拆下來整片換紗網：把壓條拆掉、換上新的紗網、再把壓條壓回去；不想自己換，可以請紗窗行到府換
看法=修補貼是最快的方法，蚊子馬上進不來
@窗簾清洗|窗簾要怎麼洗,窗簾怎麼清,窗簾可以丟洗衣機嗎,窗簾多久洗一次|生活
開頭=窗簾可以這樣洗：
步驟=先看窗簾上的洗標，有的只能乾洗；可以水洗的，拆下掛勾，放進洗衣袋，用冷水、溫和的洗劑和輕柔模式洗；不要用烘衣機，容易縮水變形；洗好後趁半濕直接掛回軌道上，靠重量自然拉平晾乾；平常可以用吸塵器的刷頭吸灰塵
看法=大約半年到一年洗一次，過敏體質的人可以洗勤一點
@門關不起來|門關不起來,門關不緊,門卡住關不起來,房門關不上,門要很用力才關得起來|生活
開頭=門關不起來，可以這樣檢查：
步驟=看門的上緣或側邊有沒有磨到門框：天氣潮濕時木門會膨脹，常常是這個原因；鉸鍊（合頁）的螺絲鬆了，門會往下垂，用螺絲起子鎖緊；門鎖的舌頭對不上門框的鎖扣片，可以把鎖扣片的位置稍微調整；舌頭卡卡的，噴一點潤滑油
提醒=門變形很嚴重、鎖壞了，就找鎖匠或木工師傅
@燈一直閃|燈一直閃,日光燈一直閃,燈泡閃爍,電燈一閃一閃,LED燈一直閃|生活
開頭=燈一直閃，可以這樣檢查：
步驟=先關掉開關，把燈泡轉緊一點，鬆了會接觸不良；日光燈管用很久了，兩端發黑、一直閃，多半是燈管或啟動器老化，換新的；LED 燈一直閃，可能是燈泡本身或驅動器壞了，換一顆試試；換了燈泡還是閃，或很多盞一起閃，可能是線路或開關的問題，要請水電師傅檢查
提醒=換燈泡前一定要關電、等燈泡冷卻
@插座沒電|插座沒電,插座插了沒反應,某個插座沒有電,插座不能用|生活
開頭=插座沒電，可以這樣檢查：
步驟=先插別的電器試試，確認是插座還是電器的問題；看電箱（配電箱）有沒有跳下來的開關，推回去；浴室、廚房的插座常有漏電斷路器，插座上或電箱裡有「測試／復歸」按鈕，按一下「復歸」；延長線的話，看延長線的開關或保險有沒有跳掉
提醒=插座有焦味、變色、冒火花，不要再用，請水電師傅來處理
@延長線很燙|延長線很燙,延長線發燙,延長線變熱,延長線插頭很燙|生活
開頭=延長線很燙，有火災的危險，要這樣處理：
步驟=先把插在上面的電器拔掉一些，特別是吹風機、電暖器、電鍋、微波爐這類耗電大的，不要同時插在同一條延長線上；看延長線上標的最大功率（例如 1650W），插的電器加起來不能超過；延長線不要捲成一團用、不要壓在家具或地毯下面；用很久、外皮破損、插孔鬆掉的延長線就換新，選有過載保護、有安全認證的
提醒=⚠️ 已經有焦味、變色、融化，馬上拔掉不要再用
@吸塵器吸力變弱|吸塵器吸力變弱,吸塵器不太吸,吸塵器吸不起來,吸塵器吸力變小|生活
開頭=吸塵器吸力變弱，可以這樣檢查：
步驟=倒掉集塵盒或換集塵袋，滿了吸力就會變弱；把濾網拆下來清灰塵（看說明書能不能水洗，洗完要完全乾才裝回去）；檢查吸管、刷頭有沒有被頭髮、紙屑卡住；無線吸塵器看電池有沒有充飽、用很久的電池會變弱
看法=每次用完就倒集塵盒，吸力會一直維持得比較好
@家裡霉味|家裡有霉味,房間有霉味,家裡有一股霉味,屋子裡有潮濕的味道|生活
開頭=家裡有霉味，可以這樣處理：
步驟=先找發霉的地方：牆角、衣櫃裡、床底下、窗簾、浴室；看得到的霉斑用稀釋的漂白水或除霉劑清掉；開除濕機，濕度維持在 50% 到 60%，天氣好的時候開窗通風；衣櫃、鞋櫃放除濕劑，衣服要乾透才收；可以放小蘇打粉或咖啡渣吸味
提醒=牆壁一直很潮、有壁癌或漏水，要先處理漏水的源頭
@地板刮痕|地板有刮痕,木地板刮傷,地板刮傷怎麼辦,地板被刮到|生活
開頭=地板有刮痕，可以這樣處理：
步驟=淺的刮痕：木地板可以用同色的木地板修補筆或蠟筆塗一塗，再用軟布擦；比較深的刮痕：用木頭填補劑填平，乾了再磨平、上色；預防：椅腳、桌腳貼防刮墊，搬家具用抬的不要拖，門口放地墊
看法=修補筆在五金行、網路都買得到，挑跟地板最接近的顏色
@冷氣遙控器沒反應|冷氣遙控器沒反應,冷氣遙控器壞了,遙控器按了沒反應,冷氣遙控器沒電,遙控器失靈|生活
開頭=冷氣遙控器按了沒反應，可以這樣試：
步驟=先換新的電池，最常見就是沒電；用手機的相機鏡頭對著遙控器前端按按鈕，螢幕上看得到閃光就是有在發射訊號；看看遙控器有沒有被設定成別的模式、或按到「鎖定」；把冷氣的插頭（或電源開關）關掉一分鐘再打開；室內機接收器的地方不要被東西擋住
看法=遙控器真的壞了，可以買原廠的或萬用冷氣遙控器，手機也有遙控 App（要有紅外線功能）
@除濕機滿水|除濕機一直滿水,除濕機水箱一直滿,除濕機很快就滿水,除濕機一直顯示滿水|生活
開頭=除濕機一直顯示滿水，可以這樣處理：
步驟=房間很潮濕時水本來就會很快滿，可以接一條排水管直接排到排水孔，就不用一直倒水；水箱沒滿卻顯示滿水，看看水箱有沒有放正、浮球有沒有卡住，把水箱拿出來擦乾淨重新裝；把門窗關好，除濕效果比較好，水也不會一直來
提醒=濾網也要定期清，不然除濕效果會變差
@白牆塗鴉|白牆被小孩畫,牆壁被畫,牆上的蠟筆怎麼擦,牆壁原子筆怎麼清|生活
開頭=白牆被小孩畫了，可以這樣清：
步驟=先在不明顯的地方試，免得把漆擦掉；鉛筆：用軟的橡皮擦輕輕擦；蠟筆：用吹風機稍微吹熱，再用乾布擦，或用一點牙膏輕輕擦；原子筆、簽字筆：用沾一點酒精的棉花輕拍，或用科技海綿輕擦；擦不掉的話，可以買小罐的同色油漆補漆
看法=給孩子一面可以畫的白板牆或大張的紙，他就比較不會畫在牆上
@蔬菜保存|蔬菜要怎麼保存比較久,青菜怎麼保存,蔬菜放冰箱怎麼放,青菜放冰箱會爛|做法
開頭=蔬菜可以這樣保存比較久：
步驟=買回來先不要洗，要煮的時候再洗；葉菜類用廚房紙巾包起來，裝進袋子或保鮮盒放冷藏，大約 3 到 5 天內吃完；根莖類（馬鈴薯、地瓜、洋蔥、南瓜）放在陰涼通風的地方，不用冰；菇類用紙袋裝冷藏，不要密封在塑膠袋裡；爛掉的葉子先挑掉，免得影響其他的
看法=葉菜類最不耐放，先吃葉菜，根莖類留到後面
@水果冰了比較甜|水果放冰箱會比較甜嗎,水果冰過比較甜,西瓜冰過比較甜嗎,冰的水果比較甜|做法
開頭=很多水果冰涼吃起來真的比較甜：
步驟=水果裡的果糖在低溫時，吃起來的甜度比較高，所以西瓜、荔枝、梨子、葡萄冰過常常覺得更甜；但香蕉、芒果、酪梨這類還沒熟的不要冰，放室溫熟了再冰；冰太久的水果香氣會變淡，吃之前拿出來放一下也不錯
看法=水果不會因為冰而真的變得更多糖，只是感覺不一樣
@吐司冷凍|吐司放冷凍可以放多久,麵包冷凍可以放多久,吐司冷凍怎麼吃,麵包可以冷凍嗎|做法
開頭=吐司、麵包放冷凍，大約可以放一個月：
步驟=買回來一兩天內吃不完，就分成一兩片一包，用保鮮膜或夾鏈袋包好冷凍，避免吸到冰箱的味道和變乾；要吃的時候不用退冰，直接放進烤麵包機或小烤箱烤；也可以放室溫 10 到 20 分鐘自然回軟
看法=放冷凍比冷藏好，冷藏反而會讓麵包變乾變硬
@生肉冷藏|生肉可以放冷藏幾天,生肉放冰箱可以放多久,豬肉放冷藏幾天,雞肉放冷藏可以放幾天,絞肉可以冰幾天|做法
開頭=生肉放冷藏，大概可以放這麼久：
步驟=絞肉、雞肉、內臟：1 到 2 天；大塊的豬肉、牛肉：3 到 5 天；買回來兩天內不會煮的，就分成一次份量冷凍；生肉放在冷藏室最下層，用盒子或袋子裝好，免得血水滴到其他食物；冷藏室溫度要在 7°C 以下
提醒=有酸臭味、變黏、顏色變灰綠，就不要吃了
@魚的保存|魚買回來要怎麼保存,魚要怎麼保存,魚可以冰幾天,鮮魚怎麼冰|做法
開頭=魚買回來，可以這樣保存：
步驟=最好買回來當天或隔天就吃；先把內臟、魚鱗、魚鰓處理乾淨，用清水沖洗、紙巾擦乾；用保鮮膜包好，放冷藏最冷的地方，1 到 2 天內吃完；吃不完就分成一餐的份量冷凍，大約 1 到 3 個月內吃完
看法=冷凍前把水分擦乾，比較不會結霜、肉質也比較好
@湯放幾天|煮好的湯可以放幾天,湯可以放多久,雞湯可以冰幾天,煮好的湯放冰箱可以幾天|做法
開頭=煮好的湯放冷藏，大約 3 到 4 天內喝完：
步驟=煮好後稍微放涼（不燙手）就分裝冷藏，不要整鍋放在室溫好幾個小時；每次喝多少就拿多少出來加熱，煮到滾再喝；喝不完很多，可以分裝冷凍，大約可以放 1 到 2 個月；海鮮湯、有放青菜的湯最好 1 到 2 天內喝完
提醒=有酸味、冒泡、變得黏稠，就不要喝了
@便當隔餐|便當隔餐還能吃嗎,便當放到晚上可以吃嗎,便當放室溫多久,中午的便當晚上吃|做法
開頭=便當要隔餐吃，要這樣注意：
步驟=買回來或做好後 2 小時內放進冰箱（天氣熱的話 1 小時內）；吃之前要徹底加熱到很燙；放在室溫超過 2 小時的便當，最好不要再吃；綠色葉菜隔餐顏色和味道會變差，最好當餐吃完；海鮮、蛋類、涼拌菜比較容易壞
看法=要帶隔餐便當的話，青菜選花椰菜、紅蘿蔔、高麗菜這類比較耐放的
@罐頭開封後|罐頭打開後可以放多久,罐頭開了要冰嗎,罐頭吃不完怎麼辦,開過的罐頭可以放多久|做法
開頭=罐頭打開後，可以這樣保存：
步驟=吃不完的不要留在原本的罐子裡，倒進乾淨的保鮮盒蓋好放冷藏；大部分大約 3 到 4 天內吃完；每次用乾淨的湯匙挖，不要用吃過的筷子；沒開的罐頭放陰涼處，注意有效期限
提醒=罐頭鼓起來、凹陷生鏽、打開有噴氣或怪味，就不要吃
@醬油放冰箱|醬油要放冰箱嗎,醬油開了要冰嗎,醬油可以放多久,調味料要放冰箱嗎|做法
開頭=醬油開封後，放冰箱比較好：
步驟=醬油開封後放冷藏，可以保持風味、比較不容易長白膜；放在陰涼的地方也可以，但要早一點用完，大約幾個月內；醬油膏、薄鹽醬油、蠔油、沙茶醬、番茄醬這類開封後最好都冰；瓶口用完擦乾淨、蓋緊
看法=買小瓶的比較能在新鮮的時候用完
@蜂蜜結晶|蜂蜜結晶了還能吃嗎,蜂蜜結晶,蜂蜜變白變硬,蜂蜜有顆粒|做法
開頭=蜂蜜結晶是正常的，還可以吃：
步驟=蜂蜜裡的葡萄糖在溫度低時會結晶，跟有沒有壞掉無關，很多天然蜂蜜都會；想讓它變回液體，把瓶子放進溫水裡（大約 40 到 50°C）慢慢攪拌，不要用滾水或微波加熱太久，會影響風味；平常放在室溫陰涼處，不用放冰箱，冰箱反而更容易結晶
提醒=1 歲以下的寶寶不能吃蜂蜜
@米的保存|米要怎麼保存,米怎麼放比較不會長蟲,米可以放多久,米長米蟲怎麼預防|做法
開頭=米可以這樣保存：
步驟=開封後倒進密封的米桶或保鮮盒，放在陰涼、乾燥、不會曬到太陽的地方；天氣熱、潮濕的時候，放冰箱冷藏最不容易長米蟲；不要一次買太多，大約一兩個月內吃完；新米和舊米不要混在一起
看法=發現有米蟲，可以把米攤開在陰涼處讓蟲跑掉，蟲很多或有霉味就丟掉
@咖啡豆保存|咖啡豆要放冰箱嗎,咖啡豆要怎麼保存,咖啡豆可以放多久,咖啡粉怎麼保存|做法
開頭=咖啡豆可以這樣保存：
步驟=裝在有單向排氣閥的袋子或密封罐裡，放在陰涼、避光的室溫地方；開封後大約 2 到 4 週內喝完風味最好；不建議放冷藏，冰箱裡濕氣和味道會被咖啡豆吸進去；買太多的話，可以分成一週的小包密封冷凍，拿出來先回到室溫再打開；磨成粉的咖啡香氣散得很快，要喝再磨最好
看法=一次買一兩週喝得完的量最新鮮
@麵粉長蟲|麵粉長蟲了,麵粉有蟲,麵粉裡面有小蟲,麵粉怎麼保存|做法
開頭=麵粉長蟲了，可以這樣處理：
步驟=蟲很多、有結塊或霉味，直接丟掉比較安全；放麵粉的櫃子要清乾淨，旁邊的穀類、乾貨也檢查一下有沒有一起長蟲；之後麵粉開封後裝進密封罐，放冰箱冷藏或冷凍最不容易長蟲；買小包裝，盡快用完
看法=麵粉裡的小蟲通常是從環境或包裝的縫隙跑進去的，密封是最有效的預防
@食物掉地上|食物不小心掉地上還能吃嗎,東西掉地上五秒內可以吃嗎,五秒原則,食物掉到地上能吃嗎|做法
開頭=食物掉到地上，「五秒原則」其實不可靠：
步驟=研究發現食物一碰到地面，細菌就會沾上去，濕的、黏的食物（西瓜、軟糖、有醬汁的）沾得更多更快；乾、硬的食物（餅乾）掉在很乾淨的地方，沾到的比較少，大人可以自己判斷；給小孩、長輩、孕婦吃的，掉地上就丟掉比較安全
看法=掉在外面的地上，不管幾秒都不要吃
@冰淇淋融化再冰|冰淇淋融化再冰可以嗎,冰淇淋退冰再冰回去,融化的冰淇淋可以吃嗎|做法
開頭=融化的冰淇淋，不建議再冰回去吃：
步驟=冰淇淋裡有牛奶和糖，融化後在室溫很容易長細菌；就算再冰起來，口感也會變得粗粗的、有冰晶；只是稍微軟掉、一直在冰箱裡（例如短暫停電），沒有放在外面，可以盡快吃完；在室溫放很久、整個融化了，就丟掉
看法=要吃多少挖多少，剩下的馬上放回冷凍庫
@雞肉熟度|雞肉要煮到幾分熟,雞肉可以吃半生嗎,雞肉沒熟可以吃嗎,雞肉要煮多久才熟|做法
開頭=雞肉一定要煮到全熟：
步驟=雞肉可能帶有沙門氏菌、曲狀桿菌，要煮到中心溫度 74°C 以上才安全；沒有溫度計的話，切開最厚的地方看：肉是白色的、沒有粉紅色，流出來的肉汁是清的；雞腿靠近骨頭的地方最容易沒熟，要特別注意
提醒=處理生雞肉的砧板、刀子和手要洗乾淨，不要再碰要生吃的東西
@豬肉熟度|豬肉可以吃半生的嗎,豬肉要煮到全熟嗎,豬肉沒熟可以吃嗎,豬排可以吃粉紅色的嗎|做法
開頭=豬肉要煮熟再吃：
步驟=豬肉可能有寄生蟲和細菌，不要吃生的或半生的；整塊豬排、里肌煮到中心大約 63°C 以上再靜置幾分鐘，切開中間微微的淡粉色是可以的；絞肉、香腸、肉丸要煮到全熟（約 71°C 以上），中間不能有粉紅色；不確定的話就煮到全熟
提醒=孕婦、小孩、長輩和免疫力比較差的人，豬肉一律全熟
@牛排生熟|牛排可以吃生的嗎,牛排三分熟安全嗎,牛肉可以吃生的嗎,漢堡肉可以吃半熟嗎|做法
開頭=牛排可以吃三分熟，但要分清楚：
步驟=整塊的牛排，細菌主要在表面，兩面煎熟、裡面三分或五分熟，一般是可以的；牛絞肉做的漢堡排、肉丸，細菌會被絞進裡面，一定要煮到全熟；選新鮮、來源可靠的牛肉，處理生肉的工具要分開
提醒=孕婦、小孩、長輩、免疫力比較差的人，牛肉也建議吃全熟
@海鮮新鮮|海鮮要怎麼看新不新鮮,怎麼挑新鮮的魚,魚新不新鮮怎麼看,蝦子新不新鮮,怎麼挑海鮮|做法
開頭=挑新鮮的海鮮，可以看這些：
步驟=魚：眼睛清亮、凸起，魚鰓鮮紅，魚身有光澤，按下去有彈性會回彈，沒有刺鼻的腥臭味；蝦：頭和身體連得緊，頭沒有變黑，殼有光澤、不黏；貝類（蛤蜊、牡蠣）：活的會閉緊，敲一下會合起來，打開的、不會動的不要買；冷凍海鮮：包裝裡不要有很多冰霜和血水
看法=買回來盡快煮，海鮮比肉更容易壞
@洗農藥|水果上的農藥要怎麼洗,蔬菜農藥怎麼洗,怎麼洗掉農藥,蔬菜要泡水嗎,青菜要怎麼洗|做法
開頭=蔬菜水果可以這樣洗，減少農藥殘留：
步驟=最有效的是用流動的清水沖洗；葉菜類先把根部切掉、葉子剝開，泡在清水裡 10 到 15 分鐘，再用流動的水一片一片沖洗；能削皮的水果（蘋果、梨子）削皮最保險；葡萄、小番茄這類，先泡水再一顆一顆沖；不需要用鹽水、蔬果清潔劑，清水就夠了
看法=洗好馬上煮或吃，不要洗完放很久
@宵夜不胖|宵夜吃什麼比較不會胖,很晚了肚子餓吃什麼,肚子餓但是很晚了吃什麼,半夜肚子餓吃什麼,宵夜吃什麼健康,晚上餓了吃什麼,減肥宵夜吃什麼|做法
開頭=真的餓了想吃宵夜，可以選這些：
步驟=份量小、清淡、有蛋白質的：無糖豆漿或牛奶、茶葉蛋、無糖優格、一小碗燕麥、一份水果（芭樂、蘋果）、一小把堅果；避開油炸、泡麵、鹹酥雞、含糖飲料；睡前 2 小時吃完比較好
看法=常常晚上很餓，可能是晚餐吃太少或太早，可以調整晚餐的份量
@手搖飲怎麼點|喝手搖飲要怎麼點比較健康,手搖飲怎麼點比較不胖,手搖飲健康點法,珍奶怎麼點比較健康|做法
開頭=手搖飲想喝得健康一點，可以這樣點：
步驟=甜度選無糖、一分或微糖，慢慢習慣；選純茶（綠茶、烏龍、紅茶）比奶茶好，奶類選鮮奶比奶精好；配料選仙草、愛玉、蘆薈，珍珠、布丁熱量比較高；點中杯就好；一週喝一兩杯當作小獎勵
看法=一杯全糖珍奶的熱量，差不多跟一個便當一樣
@早餐只喝咖啡|早餐只喝咖啡可以嗎,早上只喝咖啡不吃東西,早餐只喝拿鐵,早上只喝黑咖啡|做法
開頭=早餐只喝咖啡，偶爾可以，但不建議天天這樣：
步驟=空腹喝咖啡，有些人會胃不舒服、心悸、手抖；只有咖啡沒有蛋白質和澱粉，常常不到中午就很餓，午餐容易吃太多；可以簡單配一點：一顆蛋、一片全麥吐司、一杯無糖優格或一根香蕉；喝拿鐵的話至少有一些牛奶的營養
看法=咖啡放在早餐之後喝，對胃比較溫和
@狗吃巧克力|狗狗吃了巧克力怎麼辦,狗吃到巧克力,狗偷吃巧克力,狗吃巧克力會怎樣,貓吃到巧克力|生活
開頭=狗狗吃了巧克力，要盡快處理：
步驟=⚠️ 馬上打給獸醫院或直接帶去，說明吃了什麼巧克力（黑巧克力、烘焙用的最危險）、大概吃了多少、什麼時候吃的、狗狗的體重；把巧克力的包裝帶著；不要自己催吐，除非獸醫指示；注意症狀：嘔吐、拉肚子、一直喘、坐立不安、發抖、心跳很快，出現了更要立刻就醫
提醒=巧克力、葡萄、洋蔥、大蒜、木糖醇（口香糖）對狗都有毒，要放在牠拿不到的地方
@狗咳嗽|狗狗一直咳嗽,狗一直咳嗽,狗咳嗽怎麼辦,狗狗咳嗽像要吐|生活
開頭=狗狗一直咳嗽，要帶去看獸醫：
步驟=不要給狗吃人的咳嗽藥、感冒藥，很多對狗有毒；先觀察並記下來：咳了多久、乾咳還是有痰、什麼時候咳（運動、喝水、晚上）、有沒有發燒、流鼻水、食慾變差；可以錄一段咳嗽的影片給獸醫看；常見原因有犬窩咳（傳染性）、氣管塌陷（小型犬常見）、心臟病、異物
提醒=⚠️ 呼吸很喘、舌頭發紫、咳到昏倒或吐血，要馬上送急診
@狗不吃飯|狗狗不吃飯,狗不吃東西,狗狗食慾不好,狗狗都不吃飼料,狗挑食|生活
開頭=狗狗不吃飯，可以這樣判斷：
步驟=精神很好、只是不吃飼料，可能是挑食或零食吃太多：固定時間放飯 15 到 20 分鐘，不吃就收起來，不要一直換更好吃的；剛換環境、天氣熱也會吃少一點；超過一天完全不吃、或同時有嘔吐、拉肚子、沒精神、發燒，要帶去看獸醫
提醒=幼犬、老狗、小型犬不吃東西容易低血糖，更要早點看醫生
@狗一直喝水|狗狗一直喝水,狗喝很多水,狗狗喝水變多,貓一直喝水|生活
開頭=狗狗喝水突然變很多，要注意：
步驟=天氣熱、運動完、吃乾飼料，喝比較多水是正常的；但如果沒什麼原因，喝水和尿量都明顯變多，可能是腎臟病、糖尿病、子宮蓄膿（沒結紮的母狗）或荷爾蒙問題；可以量一下一天喝了多少水，帶去獸醫院驗血、驗尿
提醒=不要因為牠一直尿就限制喝水，先找出原因
@狗吃草|狗狗一直吃草,狗吃草正常嗎,狗為什麼吃草,狗吃草會吐|生活
開頭=狗狗吃草大多是正常的：
步驟=很多狗只是喜歡草的口感，或是想吃點纖維；有時候肚子不舒服會吃草然後吐出來；注意草地有沒有噴農藥、除草劑，也不要讓牠吃到有毒的植物；如果吃很多、一直吐、拉肚子或沒精神，要看獸醫
看法=想讓牠吃，可以在家種一盆小麥草給牠啃
@狗舔屁股|狗狗一直舔屁股,狗一直舔屁股,狗屁股在地上磨,狗一直磨屁股,擠肛門腺|生活
開頭=狗狗一直舔屁股、在地上磨屁股，常見原因是肛門腺：
步驟=狗的肛門兩側有肛門腺，分泌物塞住會癢、不舒服；可以請獸醫或美容師幫忙擠肛門腺，有些狗需要每個月擠一次；也可能是寄生蟲、皮膚過敏或拉肚子，記得定期驅蟲
提醒=屁股紅腫、有血或膿、狗狗很痛，可能是發炎或膿腫，要盡快看獸醫
@貓躲起來|貓咪一直躲起來,貓一直躲在床底下,貓躲著不出來,新來的貓一直躲|生活
開頭=貓咪一直躲起來，可以這樣看：
步驟=剛到新家、家裡有客人、搬家或裝潢，貓躲起來是正常的，給牠一個安靜的角落，放好水、食物和貓砂，讓牠自己慢慢出來；不要硬把牠拉出來；平常很黏人的貓突然一直躲，又不吃不喝、不上廁所、碰牠會叫，可能是身體不舒服
提醒=貓很會忍痛，突然變得很安靜、一直躲，要帶去看獸醫
@貓掉毛|貓咪一直掉毛,貓掉毛很嚴重,貓毛滿屋子,貓咪掉毛怎麼辦|生活
開頭=貓咪掉毛，可以這樣處理：
步驟=換毛季（春天、秋天）掉毛特別多是正常的；每天梳毛，可以把廢毛梳掉，也能減少吐毛球；家裡用滾筒黏毛器、吸塵器勤清；吃均衡的飼料、多喝水，毛會比較健康
提醒=掉到一塊一塊禿掉、皮膚紅、一直抓癢，可能是皮膚病或黴菌，要看獸醫
@新養貓準備|新養的貓要準備什麼,第一次養貓要準備什麼,養貓要準備什麼,接貓回家要準備什麼|生活
開頭=第一次養貓，可以先準備這些：
步驟=基本用品：飼料（先用牠原本在吃的）、水碗和食碗、貓砂盆和貓砂、外出籠、抓板、貓抓柱、逗貓棒；剛帶回家先放在一個安靜的小房間適應，有地方可以躲；一週內帶去獸醫院健康檢查、打疫苗、驅蟲，討論結紮的時間；家裡的窗戶、陽台裝好紗網，貓很容易從高處掉下去
看法=領養代替購買，收容所和中途之家有很多親人的貓在等家
@狗散步多久|狗狗散步要走多久,狗一天要散步幾次,狗要每天散步嗎,遛狗要多久|生活
開頭=狗狗散步，可以這樣安排：
步驟=大部分的狗每天至少要出門散步 1 到 2 次，每次 20 到 30 分鐘；精力旺盛的中大型犬（像柴犬、拉布拉多、邊境牧羊犬）可以走更久，加一點跑跳玩耍；幼犬、老狗、短鼻犬（法鬥、巴哥）要短一點、慢一點；夏天避開中午，地面太燙會燙傷腳掌
看法=散步不只是運動，讓牠到處聞，對狗的心情很重要
@狗怕洗澡|狗狗怕洗澡,狗很討厭洗澡,狗洗澡一直跑,狗洗澡會發抖|生活
開頭=狗狗怕洗澡，可以這樣慢慢讓牠習慣：
步驟=先讓牠在浴室玩、吃零食，對浴室有好印象；水溫調到溫溫的，先從腳開始沖，不要直接沖頭和臉；動作溫柔、快一點完成，邊洗邊稱讚、給零食；用不滑的止滑墊，站得穩比較不會怕；吹風機的聲音和熱風也要慢慢適應
看法=一般的狗大約 2 到 4 週洗一次就好，洗太勤皮膚反而會乾
@寵物保險|寵物要不要保險,寵物保險有用嗎,狗要買保險嗎,貓要不要買保險|生活
開頭=寵物要不要買保險，可以這樣想：
步驟=寵物看病沒有健保，開刀、住院一次可能好幾萬；寵物保險主要賠醫療費用，也常包含寵物咬傷別人的責任險；比較時看：每年保費、理賠上限、自付額、等待期、不保的項目（很多不保先天疾病、已經有的病、年紀太大）；年紀小、健康的時候保比較容易保、也比較便宜
看法=不買保險的話，可以每個月固定存一筆「寵物醫療基金」
@狗咬尾巴|狗狗一直咬尾巴,狗咬自己的尾巴,狗一直追尾巴,狗啃尾巴|生活
開頭=狗狗一直咬尾巴，可以這樣看：
步驟=偶爾追著尾巴玩是正常的；一直咬、咬到掉毛或流血，常見原因是跳蚤、皮膚過敏、肛門腺問題，或是太無聊、壓力大；先檢查尾巴和屁股附近的皮膚，定期除蚤；每天多帶牠散步、玩耍，給牠益智玩具
提醒=咬到受傷、停不下來，要帶去看獸醫
@寵物外出|寵物出門要怎麼帶,帶狗出門要帶什麼,帶貓出門,寵物外出注意什麼|生活
開頭=帶寵物出門，可以準備這些：
步驟=狗：牽繩一定要繫好，帶撿便便的袋子、水和水碗、一點零食；貓和小型犬：放在外出籠或提袋裡，籠子裡鋪一條有家裡味道的毛巾；長途出門帶尿布墊、濕紙巾、牠的飼料；搭大眾運輸要放在籠子裡、不能露頭；夏天不要把寵物留在車上，幾分鐘就可能中暑
看法=去陌生的地方，記得戴有聯絡電話的名牌，或確認有植入晶片
@狗暈車|狗狗暈車,狗坐車會吐,狗坐車流口水,狗暈車怎麼辦|生活
開頭=狗狗容易暈車，可以這樣幫牠：
步驟=出發前 2 到 3 小時不要餵太飽；讓牠待在固定的外出籠或戴安全帶，面向前方；車窗開一點小縫透氣，冷氣不要太熱；從短程開始練習，坐完車就去好玩的地方，讓牠對坐車有好印象；長途可以每 1 到 2 小時停下來讓牠走走
提醒=暈得很嚴重，可以問獸醫有沒有適合狗吃的暈車藥，不要給人吃的藥
@狗太胖|狗狗太胖了,狗太胖怎麼辦,狗狗要減肥,狗肥胖,貓太胖了|生活
開頭=狗狗太胖，可以這樣幫牠減重：
步驟=先請獸醫評估理想體重，算出一天該吃多少；飼料照份量用量杯量，不要憑感覺倒；零食減少，一天的零食不超過熱量的一成，可以用蔬菜（小黃瓜、高麗菜）代替；每天增加散步和玩耍的時間；家裡每個人都要說好，不要偷偷餵人吃的東西
看法=一個月減原本體重的 1% 到 2% 就好，不要減太快
@老貓照顧|貓咪老了要注意什麼,老貓要注意什麼,照顧老貓,貓咪幾歲算老|生活
開頭=貓咪大約 7 歲以後開始算中老年，可以多注意這些：
步驟=每半年到一年做一次健康檢查，驗血、驗尿，早點發現腎臟、甲狀腺、牙齒的問題；多讓牠喝水（濕食、流動飲水機）；換成適合老貓的飼料；貓砂盆換成邊緣比較低的，貓窩放在好上去的地方；注意體重、食慾、喝水量和上廁所的變化
提醒=老貓突然變瘦、喝水變多、尿變多、口臭、不愛動，要早點看獸醫
@烏龜曬太陽|烏龜要曬太陽嗎,烏龜要不要曬太陽,養烏龜要曬太陽嗎,烏龜曬燈|生活
開頭=烏龜要曬太陽（或曬燈）：
步驟=曬太陽可以幫助烏龜合成維生素 D3、吸收鈣質，殼才會長得健康；水龜要有一個可以爬上去曬乾身體的地方；在室內養的話，要準備 UVB 燈和保溫燈，每天照 8 到 12 小時；曬太陽時要有陰涼的地方讓牠躲，夏天不要曬太久
提醒=缺乏日照的烏龜容易軟殼、生病
@變得自律|怎麼變得更自律,怎麼變自律,沒有自制力,自律要怎麼培養,怎麼管好自己|生活
開頭=想變得更自律，可以這樣做：
步驟=目標定小、定具體：「每天讀書 20 分鐘」比「要用功」容易做到；把要做的事排進固定的時間和地點，變成習慣就不太需要意志力；減少誘惑：手機放遠一點、零食不要放在桌上；做到就記錄、打勾，看到連續的紀錄會更有動力；偶爾沒做到不要全盤放棄，隔天繼續就好
看法=自律不是天生的，是用小習慣一點一點累積出來的
@原諒自己|怎麼原諒自己,一直怪自己,原諒不了自己,做錯事一直自責,很自責怎麼辦|生活
開頭=想原諒自己，可以這樣慢慢來：
步驟=先承認發生了什麼、自己做錯了什麼，不逃避也不放大；想想當時你知道的、能做的有多少，用現在的眼光責怪過去的自己不公平；如果傷害了別人，能道歉、能彌補的就去做；問自己：如果是好朋友犯了一樣的錯，你會怎麼對他說？用同樣的話對自己說；把注意力放在以後可以怎麼做得更好
看法=原諒自己不是說錯的事沒關係，而是讓自己有機會變得更好
@找回動力|怎麼讓自己更有動力,沒有動力怎麼辦,做什麼都沒動力,提不起勁做事,怎麼找回動力|生活
開頭=沒有動力的時候，可以這樣讓自己動起來：
步驟=把事情切到很小：「先打開檔案寫一句」，開始了就比較容易繼續；先做 5 分鐘就好，5 分鐘後想停也沒關係；想想做這件事是為了什麼，寫下來貼在看得到的地方；做完一小步就給自己一點獎勵；睡不夠、太累也會沒動力，先把作息顧好
提醒=如果長時間對什麼都提不起勁、心情低落、睡不好，可能是太累或情緒生病了，可以找諮商師或身心科聊聊
@接納自己|怎麼跟自己和解,怎麼增加自我價值,覺得自己沒價值,怎麼喜歡自己,怎麼接受自己|生活
開頭=想跟自己和解、更喜歡自己，可以這樣練習：
步驟=每天寫下三件自己做到的小事，再小都算；注意心裡批評自己的聲音，試著換成你會對好朋友說的話；少跟別人比較，社群上看到的只是別人最好的一面；照顧好身體：睡飽、吃飯、動一動，心情會穩一點；接受自己有做不好的地方，每個人都是
看法=你的價值不需要靠表現證明，你本來就值得被好好對待
@改掉負面思考|怎麼改掉負面思考,一直負面思考,想法很負面,總是往壞處想,怎麼正面思考|生活
開頭=想改掉負面思考，可以這樣練習：
步驟=先察覺：發現自己又在想「一定會失敗」「大家都討厭我」時，停下來；問自己：有什麼證據？有沒有其他可能？最壞的情況真的會發生嗎？；把想法改成比較實際的版本：「這次可能不順利，但我可以準備」；每天記下一件好事或值得感謝的事；少看讓你焦慮的新聞和社群
提醒=負面想法多到影響生活、睡眠，或有不想活的念頭，請找專業的人幫忙，或打 1925 安心專線
@生活規律|怎麼讓生活更有規律,作息很亂,生活很不規律|生活
開頭=想讓生活更有規律，可以這樣做：
步驟=先固定起床時間，假日也差不多，晚上自然會比較早想睡；三餐盡量固定時間吃；每天安排幾個固定的「錨點」：早上散步、晚上洗澡、睡前看書；睡前一小時放下手機；一次調整一件事，不要一下子全部改
看法=規律的作息會讓心情和精神都比較穩定
@寫日記|怎麼開始寫日記,日記要寫什麼,寫日記的方法,不知道日記要寫什麼|生活
開頭=想開始寫日記，可以這樣做：
步驟=不用每天寫很多，三五行就好，重點是持續；不知道寫什麼，可以回答幾個問題：今天發生了什麼、我有什麼感覺、有什麼值得感謝的事、明天想做什麼；固定在睡前或早上寫；可以用本子、手機備忘錄或日記 App，選自己最順手的
看法=日記是寫給自己看的，不用寫得好，誠實就好
@維持友誼|怎麼和朋友維持關係,怎麼維持友誼,朋友越來越少,跟朋友漸行漸遠,長大後朋友變少|生活
開頭=想跟朋友維持關係，可以這樣做：
步驟=主動一點：偶爾傳個訊息、分享一張讓你想到他的照片或文章；記住對方的重要日子和近況，生日、換工作時說聲恭喜；定期約見面，就算只是吃個飯、散個步；對方需要幫忙時出現，好消息時真心替他開心
看法=長大後朋友少一點是正常的，留下來的關係更值得用心經營
@鞋子濕了|鞋子濕了怎麼快乾,鞋子濕了,鞋子淋濕了,鞋子泡水了,球鞋濕了怎麼辦,鞋子怎麼快乾,鞋子乾不了|生活
開頭=鞋子濕了，可以這樣讓它快點乾：
步驟=先把鞋墊和鞋帶拿出來分開晾；鞋子裡塞報紙或廚房紙巾吸水，濕了就換新的，前幾個小時多換幾次；放在通風的地方，用電風扇對著吹，或放在除濕機旁邊；可以用吹風機開冷風或低溫、離遠一點吹
提醒=不要直接放在暖爐旁、太陽下暴曬或用高溫烘，皮鞋和膠底容易變形、開膠；皮鞋乾了以後要上保養油
@玻璃杯卡住|玻璃杯卡在一起拿不出來,杯子卡在一起,兩個杯子卡住,杯子疊在一起拿不出來,玻璃杯疊在一起卡住|生活
開頭=兩個玻璃杯卡在一起，可以用熱脹冷縮分開：
步驟=在裡面那個杯子裡倒冷水或放冰塊；把外面那個杯子的下半部泡在溫熱水裡（不要用滾水）；等一兩分鐘，外杯受熱變大、內杯遇冷變小，再輕輕轉一轉拉開
提醒=不要硬拔或用力敲，玻璃可能裂開割傷手；拉的時候可以戴手套或墊一條毛巾
@保鮮膜黏住|保鮮膜一直黏在一起,保鮮膜找不到頭,保鮮膜撕不開,保鮮膜很難拉,保鮮膜黏成一團|生活
開頭=保鮮膜找不到頭或一直黏住，可以這樣做：
步驟=把整捲保鮮膜放進冰箱冷藏 10 到 20 分鐘，冷了比較不黏，比較好找頭和拉開；找頭時用一小段膠帶在捲筒上輕輕一黏，就能把邊緣拉起來；用完把邊緣固定在盒子的刀口附近，下次比較好拉
@筆電充不進電|筆電充不進電,筆電充不到電,筆電沒辦法充電,筆電插電沒反應,筆電插著電還是沒電,電腦充不進電,筆電充電沒反應|生活
開頭=筆電充不進電，可以照這個順序檢查：
步驟=確認插座有電、變壓器兩端（插座那頭和電腦那頭）都插緊，看變壓器或電腦的充電燈有沒有亮；換一個插座試，有延長線的話直接插牆壁；Type-C 充電的筆電，換另一個孔或用原廠充電器（功率不夠的充電器充不進去）；重新開機，Windows 可以到裝置管理員的「電池」把驅動程式解除安裝再重開；電池用很多年或已經膨脹，就要換電池
提醒=如果電池鼓起來、機殼被撐開，不要再充電，送修換電池
@手機訊號很差|手機訊號很差,手機訊號不好,手機收訊很差,手機收訊不好,手機沒訊號,手機收不到訊號,手機一直沒有訊號|生活
開頭=手機訊號不好，可以這樣試：
步驟=先開關一次飛航模式，或重新開機，讓手機重新找基地台；換個位置試試，靠窗、到室外或高一點的樓層，地下室和電梯本來訊號就差；拔出 SIM 卡擦一擦再裝回去；更新系統，或到設定裡「重置網路設定」（Wi-Fi 密碼要重新輸入）；在家裡收訊一直很差，可以打電話給電信公司，問有沒有室內訊號改善的方案，或開 Wi-Fi 通話
提醒=跟別人比較，同一個地方別人也沒訊號就是基地台的問題；只有你沒有，就可能是手機或 SIM 卡的問題
@幫狗狗刷牙|狗狗不肯刷牙,怎麼幫狗刷牙,狗狗刷牙,狗不讓我刷牙,狗狗討厭刷牙,狗要刷牙嗎|生活
開頭=狗狗不肯刷牙，可以慢慢讓牠習慣：
步驟=先讓牠習慣你摸嘴巴：每天摸一摸嘴邊、掀一下嘴唇，做到就給獎勵；再用手指沾寵物牙膏讓牠舔，讓牠喜歡這個味道；接著用指套牙刷輕輕刷外側的牙齒幾秒就停，慢慢加長時間；之後換成寵物牙刷，以每天刷、至少一週三次為目標
提醒=一定要用寵物專用牙膏，人的牙膏含木糖醇等成分，狗吃到很危險；牙結石很多、口臭很重或牙齦流血，要給獸醫檢查和洗牙
@多肉爛根|多肉植物爛根,多肉爛根,多肉爛掉了,多肉根爛了,多肉化水,多肉植物爛掉|生活
開頭=多肉爛根，可以這樣救：
步驟=把整棵拔出來，抖掉舊土，看看根和莖；用乾淨的剪刀把黑掉、軟爛的部分全部剪掉，剪到切面是乾淨的綠色或白色；放在陰涼通風的地方晾幾天，等傷口乾了；換新的、排水好的多肉專用土，種下後先不要澆水，大約一週再少量澆
提醒=爛根多半是水太多、土太濕或盆子不透水；以後等土完全乾了再澆，用有洞的盆子；如果整棵都爛了，可以剪下還健康的葉子或頂端重新扦插
