開頭=下雨天騎機車，可以這樣準備：
步驟=準備兩件式雨衣（比一件式安全，不會被風吹起來捲進輪子）和鞋套；安全帽用有面罩的，面罩可以噴防霧劑；車速放慢，煞車提早、輕輕按，前後一起用；避開人孔蓋、斑馬線、油漬和積水，這些地方特別滑；開大燈，讓別人看得到你
提醒=雨太大、看不清楚的時候，先找安全的地方停下來等一下；輪胎紋路太淺的話雨天特別容易打滑，要記得換
@洗蔬菜|蔬菜怎麼洗比較乾淨,青菜怎麼洗,蔬菜怎麼洗,怎麼洗菜,洗菜的方法|做法
開頭=蔬菜可以這樣洗，比較能洗掉髒污和殘留農藥：
步驟=先把外層的葉子和根部切掉，葉菜一片一片剝開；先泡在清水裡幾分鐘，讓泥沙鬆開；再用小水流沖洗 2 到 3 分鐘，邊沖邊用手搓；花椰菜切成小朵再泡再沖；要削皮的（紅蘿蔔、馬鈴薯）先洗再削皮
提醒=用流動的清水沖最重要，不需要加鹽或清潔劑；洗好再切，切了再洗營養容易流失
