開頭=眼睛看太久很痠，可以這樣讓它休息：
步驟=用「20-20-20」：每看 20 分鐘，看 6 公尺（20 英尺）外的地方 20 秒；多眨眼，專心看螢幕時眨眼會變少，眼睛容易乾；用溫毛巾熱敷眼睛 5 到 10 分鐘；螢幕亮度調到跟環境差不多，不要在全黑的房間看手機；螢幕離眼睛遠一點，手機大約 30 公分以上
提醒=如果視力變模糊、看東西有重影、眼睛很痛或一直紅，要去眼科檢查
