開頭=想查自己的勞保紀錄，可以這樣做：
步驟=上勞保局網站的「e化服務系統」，選個人查詢，用自然人憑證或健保卡（要先註冊）登入，可以看投保紀錄、年資和投保薪資；也可以下載勞保局的手機 App 查詢；不方便上網的話，帶身分證到勞保局各地辦事處臨櫃查；也可以打勞保局的電話詢問
提醒=發現老闆用比較低的薪水幫你投保（高薪低報），可以向勞保局反映
@怎麼截圖|怎麼截圖,截圖怎麼截,怎麼螢幕截圖,手機怎麼截圖,要怎麼截圖,截圖要按哪裡|生活
開頭=截圖的方法（看你用哪一種）：
步驟=iPhone 有 Face ID 的：同時按「側邊按鈕」和「音量加」；iPhone 有 Home 鍵的：同時按「Home 鍵」和「側邊（或上方）按鈕」；Android 手機：大多是同時按「電源鍵」和「音量減」，有些可以三指往下滑；Windows 電腦：按「Windows + Shift + S」選範圍截圖；Mac：按「Command + Shift + 4」選範圍，「Command + Shift + 3」截整個螢幕
提醒=截下來的圖在相簿（手機）或剪貼簿、桌面、「截圖」資料夾（電腦）
@包裹沒到|包裹一直沒到,包裹還沒到,網購東西一直沒到,包裹不見了,東西寄了還沒收到,包裹延遲,網購的東西還沒到|生活
開頭=包裹一直沒到，可以這樣處理：
步驟=先用訂單或寄件單上的「貨運單號」到物流公司網站或 App 查目前在哪裡；看看是不是被放在管理室、超商或寄回去了，超商取貨要注意取件期限；顯示「已送達」卻沒收到，先問家人、管理員、鄰居；聯絡賣家或購物平台的客服，請他們跟物流公司追蹤，網購平台通常有「未收到商品」可以申請退款；物流一直沒動靜，直接打物流公司的客服電話
提醒=還沒確認收到商品之前，先不要按「完成訂單」或給評價
@擦傷|擦傷怎麼辦,破皮怎麼辦,膝蓋破皮,跌倒破皮,跌倒擦傷,手肘破皮,傷口破皮,擦傷要擦什麼,騎車跌倒破皮,騎車跌倒擦傷|健康
開頭=擦傷破皮可以這樣處理：
步驟=先用乾淨的清水或生理食鹽水把傷口沖乾淨，把砂石沖掉；用乾淨的紗布輕輕壓住止血；傷口周圍可以用優碘消毒，再用清水或食鹽水沖掉（不要直接一直塗在傷口上）；貼人工皮或蓋上紗布，保持濕潤比較快好、比較不會留疤；每天看看傷口，紗布髒了或濕了就換
提醒=傷口很深、一直流血、裡面有沙子弄不出來、被生鏽的東西弄傷，或是紅腫熱痛、流膿、發燒，要去看醫生；很久沒打破傷風疫苗的話也可以問醫生
@電腦沒聲音|電腦沒聲音,電腦突然沒聲音,電腦沒有聲音,筆電沒聲音,筆電突然沒聲音,電腦喇叭沒聲音,電腦聲音不見了|生活
開頭=電腦突然沒聲音，可以照這個順序檢查：
步驟=先看右下角（Mac 是右上角）的喇叭圖示，是不是靜音或音量被調到 0；看看輸出裝置是不是選錯了，例如還選著已經拔掉的耳機、藍牙耳機或螢幕，換回「喇叭」；耳機拔掉再插一次，或把藍牙關掉試試；重新開機；Windows 可以在喇叭圖示按右鍵用「疑難排解」，或到裝置管理員更新、重新安裝音效驅動程式
提醒=只有某個網頁或 App 沒聲音，看看是不是那個分頁或 App 自己被靜音了
