類型=長篇小說
地區=西方
年代=1818 年
簡介=常被認為是第一部科幻小說
故事=年輕科學家法蘭肯斯坦用屍體拼湊出一個生命，卻因為它太醜而拋棄它。怪物渴望被愛，處處被排斥，於是向創造者復仇，殺了他的親人
結局=法蘭肯斯坦追怪物到北極而死，怪物在他的遺體旁悲傷，說要結束自己的生命，消失在冰原
主題=科學的責任、被拋棄與孤獨、誰才是怪物
看法=很多人以為「科學怪人」是怪物的名字，其實是科學家的名字——真正的怪物是不負責任的那個人
@金銀島|金銀島|作品
作者=英國的史蒂文生
類型=冒險小說
地區=西方
年代=1883 年
