結局=吉姆機智地奪回船，大家在島上找到寶藏回到英國，西佛帶著一小袋金幣逃走
主題=冒險、貪婪、善惡難分
看法=西佛是壞人，但壞得很有魅力，這是它比一般冒險故事好看的地方
@福爾摩斯|福爾摩斯探案,夏洛克·福爾摩斯,福爾摩斯探案集|作品
作者=英國的柯南·道爾
