結局=作者曾在〈最後一案〉讓福爾摩斯和莫里亞蒂一起墜下瀑布，讀者抗議後又讓他回來，最後退休去養蜂
主題=理性與觀察、正義
看法=福爾摩斯教人的是一種習慣：別只是看，要觀察
@紅與黑|紅與黑|作品
