結局=家人一個個離散，女兒羅撒香的孩子死產，最後她把乳汁餵給一個快餓死的陌生男人
主題=貧窮與尊嚴、資本的剝削、人與人之間的互助
看法=最後那一幕很震撼：什麼都沒有的人，還是願意把僅有的分給別人
@金閣寺|金閣寺|作品
作者=日本的三島由紀夫
類型=長篇小說
地區=日本
年代=1956 年
簡介=根據 1950 年京都金閣寺被僧人縱火燒毀的真實事件改寫
故事=口吃、自卑的年輕僧人溝口從小被父親說金閣寺是世上最美的東西，他對金閣的美又崇拜又痛苦，覺得這份美把自己和人生隔開了
結局=他最後放火燒了金閣寺，本來想一起死，卻逃出來決定活下去
主題=美與毀滅、自卑、孤獨
看法=它把一個人被「美」壓得喘不過氣的心理寫得很深
@雪國|雪國|作品
作者=日本的川端康成
類型=中篇小說
地區=日本
年代=1937 年到 1948 年
簡介=川端康成的代表作，他是第一位得到諾貝爾文學獎的日本作家
故事=東京的有錢閒人島村三次到雪國的溫泉小鎮，和藝伎駒子、少女葉子之間有一段淡淡又哀傷的關係；開頭「穿過縣界長長的隧道，便是雪國」非常有名
結局=村裡的倉庫失火，葉子從二樓墜落，駒子抱著她，島村仰望銀河
主題=徒勞的美、孤獨、無常
看法=它不靠情節，靠畫面和氣氛，讀起來像一幅冷冷的雪景
@快樂王子|快樂王子|作品
作者=愛爾蘭的王爾德
類型=童話
地區=西方
年代=1888 年
簡介=王爾德最有名的童話
故事=城市裡有一座鍍金、鑲寶石的快樂王子雕像，他看見城裡窮人的苦難，請一隻要飛去南方過冬的燕子，把他身上的寶石和金箔一片片送給窮人
結局=燕子凍死在雕像腳下，失去光彩的雕像被熔掉，只剩一顆破掉的鉛心；上帝說這座城裡最珍貴的兩樣東西，就是鉛心和死去的燕子
主題=犧牲與善良、貧富不均、真正的美
看法=小時候讀是童話，長大再讀會發現它其實很心酸
@被討厭的勇氣|被討厭的勇氣|作品
作者=日本的岸見一郎和古賀史健
類型=心理學書（對話形式）
地區=日本
年代=2013 年
簡介=用哲學家和青年對話的方式，介紹阿德勒心理學的暢銷書
故事=一個對人生很不滿的青年去找哲學家辯論，哲學家用五個晚上告訴他：人不是被過去決定的、所有煩惱都來自人際關係、要「課題分離」，不用活在別人的期待裡
結局=青年最後接受了「勇氣」的觀點，決定要為自己而活
主題=課題分離、不追求認同、幸福就是對別人有貢獻的感覺
看法=「被討厭的勇氣」不是叫你去惹人厭，而是不要為了討好所有人而活
@原子習慣|原子習慣|作品
作者=美國的詹姆斯·克利爾
類型=自我成長書
地區=西方
年代=2018 年
簡介=談怎麼建立好習慣、戒掉壞習慣的暢銷書
故事=核心觀念是每天進步 1%，一年後會變成 37 倍；提出習慣的四個法則：讓提示顯而易見、讓習慣有吸引力、讓行動輕而易舉、讓獎賞令人滿足；還有「身分認同」——先想成為什麼樣的人
結局=是工具書，沒有故事結局
主題=微小的改變累積成巨大的成果、系統比目標重要
看法=最實用的一句：不要訂目標，要設計系統
@嫌疑犯X的獻身|嫌疑人X的獻身|作品
作者=日本的東野圭吾
類型=推理小說
地區=日本
年代=2005 年
簡介=東野圭吾的代表作，得到直木獎，改編成電影
故事=單親媽媽靖子失手殺死糾纏不清的前夫，住在隔壁的天才數學老師石神主動幫她掩蓋，設計出完美的不在場證明；物理學家湯川學是石神的大學同學，慢慢看穿了真相
結局=石神為了保護靖子，自首說是自己殺的，甚至另外殺了一個流浪漢來佈局；靖子知道後崩潰，也去自首了
主題=純粹的愛與犧牲、天才的孤獨
看法=推理很精彩，但最後讓人難過的是石神的那份愛
@失落的一角|失落的一角|作品
作者=美國的謝爾·希爾弗斯坦
類型=繪本
地區=西方
年代=1976 年
簡介=用簡單線條畫成的哲理繪本
故事=一個缺了一角的圓，一邊唱歌一邊滾，到處尋找自己失落的那一角；途中找到幾塊不合適的，最後終於找到剛好的
結局=補齊之後它滾得太快，沒辦法停下來唱歌、看花、跟蟲子說話，於是它把那一角輕輕放下，又繼續慢慢滾、慢慢找
主題=不完美、追尋與滿足
看法=有時候缺的那一角，才讓你看得見路邊的風景
@孤獨六講|孤獨六講|作品
作者=台灣的蔣勳
類型=散文
地區=台灣
年代=2007 年
簡介=蔣勳談孤獨的六篇演講整理成的書
故事=從情慾孤獨、語言孤獨、革命孤獨、思維孤獨、倫理孤獨、暴力孤獨六個面向，談孤獨不是寂寞，而是了解自己的開始
結局=是散文集，沒有故事結局
主題=孤獨是生命的本質、和自己相處
看法=它讓很多人第一次覺得，孤獨不一定是壞事
@心流|心流,快樂，從心開始|作品
作者=美國的契克森米哈伊（匈牙利裔心理學家）
類型=心理學書
地區=西方
年代=1990 年
簡介=提出「心流」概念的經典心理學書
故事=作者研究很多人最快樂的時刻，發現是全神貫注做一件有挑戰、又剛好做得到的事時，會忘了時間、忘了自己，這種狀態叫「心流」
結局=是心理學書，沒有故事結局
主題=專注、挑戰和能力剛好平衡、從做事中得到快樂
看法=打遊戲、運動、畫畫時那種忘了時間的感覺，就是心流
@傷心咖啡店之歌|傷心咖啡店之歌|作品
作者=台灣的朱少麟
類型=長篇小說
地區=台灣
年代=1996 年
簡介=九〇年代台灣最暢銷的小說之一，寫一群年輕人追尋自由和人生意義
故事=都市上班族馬蒂厭倦了循規蹈矩的生活，離開工作和婚姻，走進台北一家叫「傷心咖啡店」的小店，認識了一群各有傷痕的年輕人，和他們討論自由、愛和生命的意義；她後來獨自去了馬達加斯加
結局=馬蒂在異鄉經歷了很多，最後在大自然裡結束了生命的旅程
主題=自由、孤獨、人生的意義、對體制的反叛
看法=很多人在二十幾歲讀到它，第一次認真問自己：我到底想怎麼活
@恐懼與戰慄|恐懼與顫慄|作品
作者=丹麥哲學家齊克果
類型=哲學著作
地區=西方
年代=1843 年
簡介=存在主義先驅齊克果的代表作之一
故事=以《聖經》裡亞伯拉罕聽從上帝要獻上兒子以撒的故事為中心，討論信仰為什麼是一種超越理性和道德的「信心的跳躍」
結局=是哲學著作，沒有故事結局
主題=信仰、倫理與信仰的衝突、個人的抉擇與焦慮
看法=它問了一個很難的問題：如果信仰要你做違背道德的事，你怎麼辦
@憂鬱的熱帶|憂鬱的熱帶|作品
