故事=記錄他 1930 年代在巴西內陸和幾個原住民部落相處的經歷，也反省西方文明怎麼看待和破壞其他文化
結局=是遊記和思考，沒有故事結局
主題=文化的多樣性、對西方中心的反省、旅行的意義
看法=開頭第一句「我討厭旅行和探險家」很有名，因為他想說的遠不只是旅行
@悲傷逆流成河|悲傷逆流成河|作品
作者=中國的郭敬明
類型=長篇小說
地區=中國
年代=2007 年
簡介=寫校園霸凌和青春傷痛的小說，後來改編成電影
故事=上海弄堂裡長大的高中女生易遙，家境貧窮、母親不被鄰居尊重，在學校被同學霸凌、被謠言傷害；只有鄰居男孩齊銘對她好，但大人和流言讓一切越來越糟
結局=易遙在絕望中跳河自殺
主題=校園霸凌、流言的傷害、青春的孤獨
看法=它讓很多讀者第一次正視：旁觀和流言，也是一種傷害
@解憂雜貨店|解憂雜貨店|作品
作者=日本的東野圭吾
類型=長篇小說
地區=日本
