結局=他們發現所有的事都跟同一間孤兒院有關，也和自己有關；最後收到一封空白信的回信，決定重新面對人生
主題=迷惘與選擇、善意的連結、人生的地圖是白紙
看法=它說：煩惱的人其實心裡已經有答案，只是需要有人推一把
