@AI會不會取代人類||看法
問=^(你覺得)?(AI|ai|人工智慧|機器人)(會|將會|以後會|會不會)(取代|統治|消滅|毀滅)(人類|人|世界)(嗎)?$
問=^(AI|ai|人工智慧)(危險|可怕)(嗎)?$
問=^(AI|ai|人工智慧)會不會取代人類$
答=我的看法：AI 會取代很多「工作內容」，但不會取代「人」。重複、有固定規則的事（整理資料、寫制式文件、翻譯初稿）會越來越多交給 AI；但決定什麼重要、為別人負責、跟人建立信任、在不確定時做選擇——這些還是人比較擅長，也應該由人來做。比較實際的問題是：會用 AI 的人，會取代不會用的人。所以與其害怕，不如把它當成工具學起來。
