答=這種決定沒有標準答案，我幫你一起想幾件事：⏎1. 你想離開，是因為「不喜歡現在的工作」，還是「被某個人或某件事卡住」？後者有時換部門就能解決。⏎2. 新的方向清楚嗎？最好是「往某個地方去」，而不只是「逃離這裡」。⏎3. 錢：手上的存款能撐 3 到 6 個月嗎？最好先找到下一份再走。⏎4. 一年後回頭看，你比較怕「沒走」還是「走錯」？⏎如果你願意，告訴我生日，我可以用九型十二宮看看你今年的事業（10 宮）走到哪裡、哪幾個月比較適合動。
@該不該分手||選擇
