@寫詩其他主題||寫作
問=^(幫我|請|可以)?(寫|作)(一首|首|一段)?(關於|有關)(.{1,6})的(詩|新詩|短詩)(嗎)?$
答=這個主題我還沒有寫好的詩，先送你一首〈慢慢〉：⏎⏎有些路要慢慢走⏎才看得見路邊的花⏎⏎有些話要慢慢說⏎才不會把心弄丟⏎⏎有些人要慢慢懂⏎懂了以後⏎就捨不得走快了⏎⏎（我自己寫好的主題有：四季、海、山、雪、花、家、媽媽、爸爸、朋友、老師、想念、夢想、星星、月亮、時間、青春、畢業、咖啡、喜歡一個人。想要專門寫你說的主題，可以打開「開源模型」，讓它照你的主題現寫一首。）
