@睡不好||關心
問=^我(最近|這幾天|每天|常常)?(都|一直|老是)?(睡不好|睡不著|失眠|睡不飽|很難睡著|半夜會醒)$
答=睡不好真的很折磨，白天整個人都沒力氣。最近是有什麼事放在心上，還是作息亂掉了？⏎可以先試試：每天固定時間起床、睡前一小時放下手機、下午之後不喝咖啡和茶。想知道更多好睡的方法，問我「睡不著怎麼辦」。如果已經好幾週都這樣，可以去看身心科或睡眠門診。
@嫉妒||關心
問=^我(好|很|有點|超|真的)?(嫉妒|羨慕|眼紅)(我的|我)?(朋友|同學|同事|姐姐|妹妹|哥哥|弟弟|別人|他|她|他們)?$
答=會羨慕、會嫉妒很正常，那代表對方擁有的東西，剛好是你很在乎、也想要的。⏎與其責怪自己心胸不夠大，不如把它當成線索：你最羨慕的是哪一點？那可能就是你接下來想努力的方向。⏎另外也記得，我們常常拿自己的「幕後」去比別人的「精華片段」，別人光鮮的那一面不是全部。
@事情做不完||關心
問=^(因為|就是|我)?(的)?(工作|事情|作業|報告|功課|事)(好多|太多|超多)?(都|一直|永遠)?(做不完|寫不完|忙不完|弄不完)(了)?$
問=^(工作|事情|作業)(好|太|超)多$
答=事情堆成山的時候，最累的常常不是做，是「想到還有好多沒做」。可以試試這樣：⏎1. 先把所有事寫下來，腦袋會輕鬆一點。⏎2. 挑出今天「一定要完成」的一到三件，其他的明天再說。⏎3. 從最小、最快能完成的開始，做完一件會比較有動力。⏎4. 真的做不完，早一點跟主管或老師說，比最後才說好得多。⏎你已經很努力了，記得中間也要休息一下。
@不想上學||關心
問=^我(真的)?(好|很|超)?不想(上學|去學校|上課|讀書|念書)$
答=會不想去學校，通常背後有原因：是太累了、功課壓力大、跟同學處不好，還是在學校遇到不開心的事？可以跟我說說看。⏎如果是在學校被欺負，不要一個人承受，一定要跟爸媽或老師說；台灣也可以打 1953 反霸凌專線。
