@胸口痛||身體
問=^我(的)?(突然|一直|有點|好像)?(胸口|胸部|心臟|心口)(很|好|有點)?(痛|悶|不舒服|刺痛|緊)(了)?$
問=^我(突然|一直|有點)?胸悶$
答=⚠️ 胸口痛不能等。如果是壓迫、緊縮的痛，或痛到左肩、手臂、下巴、背，或同時冒冷汗、呼吸困難、噁心、頭暈，請馬上打 119（台灣；歐洲打 112），不要自己開車去醫院。⏎如果是按壓才痛、深呼吸或某個姿勢才痛，比較可能是肌肉或骨頭的問題，但還是建議盡快看醫生確認。⏎現在先坐下或半躺著休息，不要用力。你身邊有人嗎？
@肚子痛||身體
問=^我(的)?(突然|一直|有點|好像)?(肚子|胃|腹部)(很|好|超|有點)?(痛|不舒服|絞痛|脹)(了)?$
答=肚子不舒服好難受。先試試：休息、喝一點溫水，暫時吃清淡好消化的東西（白粥、吐司、香蕉），避免油炸、辛辣、乳製品和咖啡。⏎⚠️ 這些情況要盡快看醫生：痛得很劇烈或越來越痛、右下腹痛（可能是盲腸炎）、發燒、吐血或解黑便／血便、肚子硬硬的按了更痛、懷孕中、或痛超過一天沒好。⏎是哪裡在痛？吃了什麼特別的東西嗎？
@吃壞肚子||身體
問=^我(好像)?(吃壞肚子|食物中毒|拉肚子|腹瀉|一直拉肚子)(了)?$
答=吃壞肚子很難受，先讓腸胃休息：⏎1. 最重要的是補充水分和電解質：少量多次喝水或口服電解質液，不要等口很渴才喝。⏎2. 先吃清淡的：白粥、白吐司、香蕉、蘋果泥，避免油膩、辛辣、牛奶和酒。⏎3. 不要自己亂吃止瀉藥，讓身體把不好的東西排出來（醫生開的除外）。⏎⚠️ 發高燒、拉出血便或黑便、一直吐到喝不下水、頭暈、尿很少，或超過兩三天沒好，要去看醫生；小孩和老人更要早點看。
@頭暈||身體
問=^我(突然|一直|有點|好)?(頭暈|頭好暈|頭很暈|暈眩|天旋地轉|頭昏)(了)?$
答=頭暈的時候先坐下或躺下，避免跌倒；慢慢喝點水，如果很久沒吃東西，可以吃點東西或含一顆糖。起身的時候慢慢來。⏎⚠️ 如果同時有臉歪、說話不清楚、一邊手腳無力、劇烈頭痛、胸痛、昏倒，可能是中風或心臟問題，馬上打 119（歐洲 112）。⏎如果是常常頭暈、或天旋地轉合併耳鳴，建議去看醫生檢查。
@咳嗽很久||身體
問=^我(一直|常常)?咳嗽(很久|好久|兩週|兩個禮拜|一個月|好幾天)(了)?$
問=^我(一直|常常)?(在)?咳嗽$
答=咳嗽很久真的很煩，晚上也睡不好。可以先：多喝溫水、蜂蜜溫水（一歲以下不行）、保持室內濕度、少吃冰和炸的、避免菸和空氣污染。⏎⚠️ 咳超過三週、咳血、呼吸喘或胸痛、發燒不退、體重莫名下降，要去看醫生（可能需要照 X 光）。⏎有發燒或有痰嗎？
@發燒了||身體
問=^我(好像)?(發燒|發高燒|燒起來)(了)?$
答=發燒了要好好休息。先：多喝水、多休息，穿得舒服、不要包太厚；需要的話照說明吃退燒藥（乙醯胺酚／普拿疼），不要超過建議劑量。⏎⚠️ 成人燒到 39 度以上、燒超過 3 天、或有呼吸困難、意識不清、脖子僵硬、劇烈頭痛、出疹子、抽搐，要馬上就醫；三個月以下的嬰兒只要發燒就要看醫生。⏎現在幾度？還有哪裡不舒服嗎？
@好像感冒||身體
問=^我(好像|應該是|可能)?感冒了$
問=^我(好像|有點)?(感冒|著涼)$
答=感冒了要好好照顧自己：多喝溫水、多休息、睡飽，喉嚨痛可以溫鹽水漱口，鼻塞可以用熱毛巾敷鼻子。出門戴口罩、勤洗手，避免傳染給別人。⏎⚠️ 高燒不退、呼吸困難、胸痛、症狀超過 10 天，或一開始好轉又突然變嚴重，要去看醫生。⏎想知道更多，問我「感冒怎麼辦」。
@牙齒痛||身體
問=^(我)?(的)?(牙齒|牙|智齒)(很|好|超|有點)?(痛|酸|敏感)(了)?(怎麼辦|要怎麼辦|該怎麼辦|怎麼處理)?$
問=^我(在)?牙痛$
答=牙痛真的會痛到睡不著。暫時可以：用溫鹽水漱口、臉頰外面冰敷、照說明吃止痛藥；避免太冰、太熱、太甜的東西，用另一邊咬東西。⏎牙痛通常是蛀牙、牙齦發炎或智齒的問題，止痛只是暫時的，還是要去看牙醫。⏎⚠️ 臉頰腫起來、發燒、張不開嘴或吞嚥困難，要盡快就醫。
@眼睛痠||身體
問=^我(的)?眼睛(很|好|超|有點)?(痠|酸|乾|累|澀|紅)(了)?$
答=眼睛累了要讓它休息：用「20-20-20」法則——每看螢幕 20 分鐘，就看 20 英尺（6 公尺）外的地方 20 秒；多眨眼，可以用熱毛巾敷眼睛；螢幕亮度別太亮，距離至少一個手臂。⏎⚠️ 眼睛突然看不清楚、很痛、看到閃光或黑影變多、又紅又痛有分泌物，要盡快看眼科。
@背痛||身體
問=^我(的)?(背|腰|下背|脖子|肩膀|肩頸)(好|很|超|有點)?(痛|痠|酸|僵硬)(了)?$
答=背和肩頸痛常常跟久坐、姿勢不良有關。可以試試：每坐 30 到 60 分鐘起來動一動、熱敷放鬆肌肉、做溫和的伸展、睡覺的枕頭不要太高；平常加強核心和背部的肌力。⏎⚠️ 痛到腳麻、腳沒力、大小便控制不了、發燒、受傷後才痛，或痛了好幾週越來越嚴重，要去看醫生（骨科或復健科）。
@想吐||身體
問=^我(一直|好|有點|突然)?(想吐|噁心|反胃|吐了|嘔吐)(了)?$
答=想吐的時候先坐下休息，慢慢小口喝水或電解質飲料，暫時不要吃油膩的東西；可以聞聞新鮮空氣、鬆開太緊的衣服。⏎⚠️ 吐不停喝不下水、吐出血或咖啡渣的東西、劇烈頭痛或肚子痛、頭撞到之後想吐、或有懷孕的可能，要盡快看醫生。
@被狗咬||身體
問=^(我)?(被|讓)(狗|貓|動物|野狗|流浪狗|猴子|老鼠)(咬|抓)(到|傷)?(了)?(怎麼辦|要怎麼辦|該怎麼辦|怎麼處理)?$
答=被咬到要馬上處理：⏎1. 用肥皂和大量清水沖洗傷口至少 15 分鐘，再用優碘消毒。⏎2. 盡快去看醫生：要評估要不要打破傷風疫苗，被野生動物或不明的貓狗咬到，還要評估狂犬病的風險。⏎3. 記下是哪隻動物、有沒有打過疫苗、在哪裡被咬，告訴醫生。⏎⚠️ 傷口很深、一直流血、咬在臉、手、脖子，或之後紅腫發熱化膿，要馬上就醫。
@扭到腳||身體
問=^(我)?(的)?(不小心)?(扭到|扭傷|拐到)(腳|腳踝|手|手腕)(了)?(怎麼辦|要怎麼辦|該怎麼辦|怎麼處理)?$
答=扭到了先照「PRICE」處理：保護（Protect）、休息（Rest）、冰敷（Ice，每次 15 到 20 分鐘，一天幾次）、加壓包紮（Compression）、抬高（Elevation，高過心臟）。前兩三天不要熱敷、不要按摩。⏎⚠️ 完全不能走路或站、腳變形、腫得很嚴重、麻掉，或一兩週還沒好，要去看骨科照 X 光，可能有骨折或韌帶受傷。
@過敏了||身體
問=^我(好像)?(過敏|起疹子|長疹子|皮膚癢|起紅疹)(了)?$
答=過敏很不舒服。先遠離可能的過敏原（剛吃的東西、新的保養品、寵物、灰塵），冷敷癢的地方、不要抓；可以吃藥局買得到的抗組織胺（照說明）。⏎⚠️ 如果嘴唇、舌頭、喉嚨腫起來、呼吸困難、喘、頭暈快昏倒，可能是嚴重過敏反應，馬上打 119（歐洲 112）。
@經痛||身體
問=^我(的)?(月經|生理期|經期|大姨媽)(來了|來|又來)?(好|很|超)?(痛|不舒服|肚子痛)(了)?$
問=^我(在)?經痛$
答=經痛真的很辛苦。可以試試：熱敷下腹部（暖暖包、熱水袋）、喝溫熱的飲料、輕輕按摩肚子、做溫和的伸展或散步；需要的話照說明吃止痛藥（像布洛芬），在痛之前或剛開始痛時吃效果比較好。⏎⚠️ 痛到無法上班上課、止痛藥沒效、經血量突然變很多、或平常不痛最近突然很痛，建議去看婦產科檢查（例如子宮內膜異位症）。
