答=〈會發光的小電視〉⏎⏎從前有一台被丟在倉庫角落的小電視，螢幕早就收不到訊號了。每天晚上，倉庫裡的老鼠、蜘蛛和一隻迷路的麻雀都會擠在它前面，因為它會努力地閃一點點光，讓大家不怕黑。⏎⏎有一天，倉庫的主人要把它丟掉。老鼠急得把電線咬回插座，蜘蛛在螢幕上織了一張網擋灰塵，麻雀飛出去叫來了一個小女孩。小女孩看到它還亮著，說：「它還在努力耶。」就把它帶回家，放在床邊當小夜燈。⏎⏎從此它不用收到任何節目，因為它知道：能讓身邊的人安心，就已經是最好的節目了。⏎⏎（想聽別種的？跟我說要溫馨、搞笑還是冒險的。）
