@九型十二宮介紹||命理說明
問=^(什麼是|何謂|請問)?(九型十二宮)(是什麼|是什麼意思|怎麼算|怎麼算的|是怎麼算的|的原理|的算法|在算什麼)?(呢|啊)?$
問=^你(都|是)?(怎麼|如何|用什麼)(算命|算運勢|看命盤|看運勢)(的)?(呢|啊)?$
答=九型十二宮是我主要用的命理系統，算法是固定的，同一個生日每次算出來都一樣：⏎1. 把你的生日化成三柱、相加得到靈數，決定你的九型人格和命宮。⏎2. 從命宮逆排出十二宮，每一宮管一個人生方面：自我、物質（錢）、交流、家庭、桃花（戀愛）、勞碌、他人（伴侶）、偏財（身體、別人的錢）、愉悅（好運、機會）、事業、朋友、沉迷（內心深處）。⏎3. 每一宮判讀成「好、正、壞」，再看「起因」來自哪一宮，說明事情從哪裡來、會在哪裡呈現。⏎4. 看時間：十年的大運、流年、流月，還有每天白天的日宮、晚上的夜宮。⏎⏎我也會參考八字、紫微斗數和西方星盤。把它當成認識自己、整理想法的參考就好，想看你的，問我「我的命盤」或「今天運勢」。
@命理準嗎||命理說明
問=^(這|那|你算的|你說的|這個|剛剛那個|剛剛的|運勢|算命|命理)?(準嗎|準不準|會準嗎|真的準嗎|可信嗎|靈不靈|靈嗎|可以信嗎|有科學根據嗎|有根據嗎)(啊|呢)?$
問=^(紫微斗數|紫微|八字|星座|塔羅|塔羅牌|算命|命理|九型十二宮|易經|占卜|風水|生肖|星盤)(準嗎|準不準|可信嗎|有科學根據嗎|是真的嗎|靈嗎|靈不靈|可以信嗎|有用嗎)(啊|呢)?$
答=說實話：目前沒有科學證據能證明命理可以預測未來。我的算法是固定的，同一個生日每次算出來都一樣，你可以對照最近的生活，看看哪些說中了、哪些沒有。⏎⏎我比較建議把它當成一面鏡子：提醒你留意哪個方面、幫你整理想法；真正決定結果的，還是你的選擇和努力。
