@五行||命理說明
問=^(五行|金木水火土)(呢|啊)?$
答=五行是中國古代用來說明萬物變化的五種元素：木、火、土、金、水。它們之間有「相生」：木生火、火生土、土生金、金生水、水生木；也有「相剋」：木剋土、土剋水、水剋火、火剋金、金剋木。⏎⏎八字、中醫、風水都會用五行來分析；想知道你的八字五行，告訴我生日後問我「我的八字五行缺什麼」。
